WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[55774] = { title = "WANTED: Inquisitor Ithriza", description = "Wanted for attacks against the Alliance!\n\nInquisitor Ithriza is responsible for leading several raids and ambushes against our soldiers.\n\nLast seen near the vicinity of this command poster.\n\nExtreme caution advised!\n\nUpon completion of the mission, report to Lieutenant Hawkins for commendation.", objectives = "Retrieve the head of Inquisitor Ithriza.", progress = "Have anything to report?", completion = "Well done, <class>. Inquisitor Ithriza was a formidable foe and a high-ranking commander among the naga." }
WordHunterWoW_QuestEN[55775] = { title = "WANTED: Haggronar", description = "Wanted for attacks against the Alliance!\n\nHaggronar is responsible for the gruesome deaths of several of our finest soldiers. Extreme caution advised!\n\nUpon completion of the mission, report to Lieutenant Hawkins for commendation.", objectives = "Retrieve the head of Haggronar.", progress = "Have anything to report?", completion = "Well done, <class>. Haggronar has been terrorizing our soldiers since the day we arrived on Nazjatar." }
WordHunterWoW_QuestEN[55776] = { title = "WANTED: Emorneth", description = "Wanted for attacks against the Alliance!\n\nEmorneth is responsible for the gruesome deaths of several of our best soldiers. Extreme caution advised!\n\nUpon completion of the mission, report to Lieutenant Hawkins for commendation.", objectives = "Slay Emorneth.", completion = "Well done, <class>. Emorneth has been terrorizing our soldiers since the day we arrived on Nazjatar." }
WordHunterWoW_QuestEN[55777] = { title = "WANTED: Braxicus", description = "Wanted for attacks against the Alliance!\n\nBraxicus is responsible for the gruesome deaths of several of our finest soldiers.\n\nLast seen near the vicinity of this command poster.\n\nExtreme caution advised!\n\nUpon completion of the mission, report to Lieutenant Hawkins for commendation.", objectives = "Retrieve Braxicus' giant claw.", progress = "Have anything to report?", completion = "Well done, <class>. Braxicus has been terrorizing our soldiers since the day we arrived on Nazjatar." }
WordHunterWoW_QuestEN[55778] = { title = "Visions of Danger", description = "{name}, Spiritwalker Ussoh has revealed a disturbing vision to me regarding Baine Bloodhoof.\n\nHe has asked that you speak with him as soon as you can.\n\nReturn to me after. We will have much to discuss.", objectives = "Speak with Spiritwalker Ussoh.", completion = "Sylvanas will execute Baine Bloodhoof soon... unless we act." }
WordHunterWoW_QuestEN[55779] = { title = "Stay of Execution", description = "Come. It is time to save a friend.", objectives = "Complete the \"Stay of Execution\" Scenario.", completion = "Thank the Sunwell you were able to save Baine's life, <name>. Thank you.\n\nAnd Jaina Proudmoore came to his aid as well. Interesting..." }
WordHunterWoW_QuestEN[55780] = { title = "Old Allies", description = "Sylvanas was my Ranger-General. I have respected her for millennia. Making this choice is something I have been wrestling with for some time. Baine's death will tear the Horde apart. The Tauren will not stand for it and if they leave, I know they will not be the last.\n\nWe must save Baine. Not just for his life, but for the Horde. I can only hope once the time pressure is gone we may be able to reason with her but... \n\nI have contacted allies who will help. Meet them in the Cleft of Shadows.", objectives = "Meet with allies in the Cleft of Shadows.", completion = "It is good to see you again, <name>. Quickly, Baine does not have much time." }
WordHunterWoW_QuestEN[55781] = { title = "Old Allies", description = "Sylvanas Windrunner was once my ranger-general. Now she is my warchief. Through peacetime and war, I followed her orders.\n\nUntil now.\n\nBaine is a noble soul. His execution would drive a blade into the very heart of the Horde.\n\nWe must save him, {name}. It is the only way to preserve who we are. What we stand for.  \n\nI have reached out to allies who will help you. But in siding with them, you will put your own life in peril.\n\nIf you feel as I do, then meet them in the Cleft of Shadows. Good luck.", objectives = "Meet with allies in the Cleft of Shadows in Orgrimmar.", progress = "Once again, we face dark times, <name>.", completion = "Your aid is welcome, <class>.\n\nBaine has little time left." }
WordHunterWoW_QuestEN[55782] = { title = "Stay of Execution", description = "Baine's time is short. We must act now.", objectives = "Complete the \"Stay of Execution\" Scenario.", completion = "A pity Bloodhoof and all the rest survived.\n\nOur Warchief has anticipated this outcome, however." }
WordHunterWoW_QuestEN[55783] = { title = "Stay of Execution", description = "When I was younger, Baine Bloodhoof and I began exchanging letters. Through our unlikely friendship, I learned that there was nobility in the Horde.\n\nHe proved that by defying Sylvanas when she planned to strip the free will from Derek Proudmoore. That act of nobility will cost him his life... unless we intervene.\n\nIf there is to be peace in Azeroth, our hope depends upon good people doing the right thing. People like Baine. People like you.\n\nPlease, go with Jaina. Save my friend and see him home.", objectives = "Complete the \"Stay of Execution\" Scenario.", completion = "Thank you for helping us rescue Baine.\n\nIt was the right thing to do." }
WordHunterWoW_QuestEN[55784] = { title = "Payment in Kind", description = "{name}, King Anduin has requested our presence in Stormwind.\n\nWe've sent him reports on our situation here in Nazjatar, and he understands the severity of the threat we're facing. For him to pull both of us back from the front lines, it must be a matter of grave importance.\n\nI will meet you in Stormwind Keep.", objectives = "Meet with Anduin Wrynn in Stormwind Keep.", progress = "Thank you for coming, <name>.", completion = "We may be at war with the Horde, but that did not stop Baine from doing the right thing.\n\nWe can do no less for him." }
WordHunterWoW_QuestEN[55785] = { title = "Requisition: More Starfish", description = "Our forward scouts have been using starfish scales as camouflage. The trouble is that the scales deteriorate too quickly. We are going to need more scales if we want to keep tabs on naga movements.\n\nIf you happen upon any Angel Scale Starfish, please deliver them to the quartermaster as soon as possible.", objectives = "Collect 5 Angel Scale Starfish.", completion = "Thank you for your contribution." }
WordHunterWoW_QuestEN[55786] = { title = "Requisition: More Seaweed", description = "We have so many wounded and we are dangerously low on seaweed bandages. If you find Sticky Seaweed, please give it to the quartermaster.", objectives = "Collect 5 Sticky Seaweed.", completion = "Thank you for your contribution." }
WordHunterWoW_QuestEN[55787] = { title = "Requisition: More Kelp Buds", description = "We need rations for our forces. While kelp buds do not have the same delicious taste as other options, it is nutritious and plentiful near any kelp forests. This makes it our first choice for making rations.\n\nIf you happen to find any around Nazjatar, please leave your stores with the quartermaster. The ones freshly fallen from kelp are best.", objectives = "Collect 5 Fallen Kelp Buds.", completion = "Thank you for your contribution." }
WordHunterWoW_QuestEN[55788] = { title = "Requisition: More Pearls", description = "<This letter bears the seal of the quartermaster.>\n\nSupplies needed!\n\nWe are dangerously low on pearls. Anyone carrying Luminous Pearls, please leave your stores with the quartermaster.", objectives = "" }
WordHunterWoW_QuestEN[55789] = { title = "Requisition: More Carp", description = "Our local sea life is in danger! If you spot a fish out of water, please return it to the nearest lake, stream, or river. Conservation is everyone's responsibility!", objectives = "Return 5 Struggling Carps to water.", completion = "Thank you for your contribution." }
WordHunterWoW_QuestEN[55790] = { title = "Requisition: More Deepcoral Buds", description = "Many species feed on the deepcoral buds from the tall columns that grow in the east. Fathom rays feed on these buds especially. We use the buds as lures for fathom rays to use as mounts. But with our stores so low, we will not be able to provide the air support we need across Nazjatar.\n\nIf you could gather more Deepcoral Buds and return them to the quartermaster, you will surely be rewarded.", objectives = "Collect 5 Deepcoral Buds.", completion = "Thank you for your contribution." }
WordHunterWoW_QuestEN[55791] = { title = "Requisition: More Spiral Leaf", description = "We are dangerously low on our medicine stores. If you find any Spiral Leaf, please leave your stores with the quartermaster.\n\nI should warn you, Spiral Leaf is immensely poisonous. Make sure to handle it with care. Some symptoms of spiral leaf poisoning include bouts of rage, immense bursts of strength, and murderous impulses. If you are exposed, find some naga and use your murderous energy for good.", objectives = "Collect 5 Poisonous Spiral Leaf.", completion = "Thank you for your contribution." }
WordHunterWoW_QuestEN[55792] = { title = "Requisition: More Cone Shells", description = "If we are going to arm ourselves against the naga, we will need far more supplies and armaments. Cone Shells make most of our armor and weapons. It's light, it's strong, and it's plentiful in this region. However, our supplies are running short and our forces need support.\n\nIf you find yourself carrying Impregnable Cone Shells, please leave your stores with the quartermaster.", objectives = "Collect 5 Impregnable Cone Shell.", completion = "Thank you for your contribution." }
WordHunterWoW_QuestEN[55793] = { title = "Requisition: More Flotsam", description = "I have seen piles of flotsam in the sands to the west. If you could go out and scrounge anything useful from the debris, it could prove useful. Beware, that area is a hydra breeding ground and they have been growing more aggressive since the water receded.\n\nOnce you've gathered some supplies, return to the quartermaster for your reward.", objectives = "Collect 5 Piles of Flotsam.", completion = "Thank you for your contribution." }
WordHunterWoW_QuestEN[55794] = { title = "Reclamation Rig", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[55795] = { title = "Mountain On the Move", description = "I have seen such fervor only once before.\n\nIn times of peril, Torcali may call upon her children to defend her and those she looks after.\n\nIt is likely she called your beast away. Go to her and see how you can help.", objectives = "Speak to Torcali.", completion = "<Torcali's voice enters your mind.>\n\nI have called and you have come once again, <name>. We have little time to waste." }
WordHunterWoW_QuestEN[55796] = { title = "Heresy at the Crossroad", description = "<Torcali's voice enters your mind.>\n\nMy followers undertook a pilgrimage to a place called the Antul'Mita Plateau. It is regarded as the crossroads of Zandalar among my faithful and is the site of a Greater Wayshrine.\n\nI sense some great peril has fallen upon them.\n\nI have sent my children and my champion, Jo'nok, to their aid. Your charge is among them. Go to her and ensure that my acolytes reach the shrine safely.\n\nLet nothing stand in your way.", objectives = "Meet Jo'nok at the Antul'Mita Plateau in Nazmir.", completion = "She is ready. You are ready. This one thinks dey have made a mistake in challenging us." }
WordHunterWoW_QuestEN[55797] = { title = "The Direhorn Mother's Fury", description = "This one protects de faithful who still seek de shrine.\n\nYou will take your companion and show them de fury of a mother direhorn.\n\nTrust in your young friend. She has always known how to fight.\n\nOpen de way. Slay de heretics that defile our loa's shrine.", objectives = "Clear a path to the Greater Wayshrine in the Antul'Mita Plateau.", progress = "A direhorn is gentle until it is provoked. Their mistake.", completion = "It is a joy to behold her strength, <name>. Our faith is rewarded." }
WordHunterWoW_QuestEN[55798] = { title = "Wander Not Alone", description = "She is here. I can feel her eyes upon us.\n\nMy loa is generous. She will reward you for de service you have given her.\n\nGreat Wanderer guide your path, {name}.", objectives = "Speak to Torcali.", completion = "<Torcali's voice enters your mind.>\n\nTime and time again I have called upon you. Time and time again you have answered.\n\nThe little one tells me she will follow you wherever it is that you wish to go. After all that you have done for my faithful and my young, this is my gift to you.\n\nFrom this day until the end of your days, you will wander not alone.\n\n<Torcali gently touches her great snout to your head.>\n\nThank you and farewell, <name>." }
WordHunterWoW_QuestEN[55799] = { title = "The Tide Turns", description = "The time to strike is now. We must take the Tidestone of Golganneth and the Javelin of Suramar is our best chance of piercing the barrier around it.\n\nEvery minute we wait is another minute when the sea can come crashing down on us. What forces we have will be arrayed below, just outside their encampment.\n\nWe will need your strength in addition to the Javelin, {name}. We do not have enough forces to take it on our own.", objectives = "Assault the naga camp and seize control of the Tidestone of Golganneth.", completion = "Quickly, the Tidestone!" }
WordHunterWoW_QuestEN[55801] = { title = "Requisition: We Need It All", description = "We are dangerously low on all of our supplies. Please, you must go out and collect as much as you can.\n\nPlease return with any resources you find to the quartermaster!", objectives = "Collect resources from around Nazjatar.", completion = "Thank you for your contribution." }
WordHunterWoW_QuestEN[55802] = { title = "Requisition: Lots of Seaweed", description = "Supplies needed!\n\nWe are dangerously low on seaweed bandages. Anyone carrying Sticky Seaweed, please leave your stores with the quartermaster.", objectives = "" }
WordHunterWoW_QuestEN[55803] = { title = "Requisition: Lots of Kelp Buds", description = "Supplies needed!\n\nWe need rations for our forces. While kelp buds do not have the same delicious taste as other options, it is nutritious and plentiful near any kelp forests. This makes it our first choice for making rations.\n\nIf you happen to find any around Nazjatar, please leave your stores with the quartermaster. The ones freshly fallen from kelp are best.", objectives = "" }
