WordHunterWoW_QuestEN[55835] = { title = "Bounty: More Elementals", description = "<This letter bears the seal of the quartermaster.>\n\nThe elemental population is disrupting endeavors within Nazjatar. Kill on sight.\n\nReport to the quartermaster to claim your reward.", objectives = "" }
WordHunterWoW_QuestEN[55836] = { title = "Bounty: Elite Naga Forces", description = "Strike at the elite naga forces within Nazjatar. Once we remove some of their leadership, our people will be able to move about more freely.\n\nReport to the quartermaster to claim your reward.", objectives = "Kill 5 elite naga.", progress = "I know it is dirty work, but someone must do it.", completion = "This will ease our efforts in Nazjatar." }
WordHunterWoW_QuestEN[55837] = { title = "Bounty: Dangerous Creatures", description = "There are creatures in Nazjatar that are far more dangerous than their peers. I leave it to you to find them and defeat them.\n\nWhen you've done your part, report to the quartermaster to claim your reward.", objectives = "Kill 1 rare creature in Nazjatar.", progress = "I know it is dirty work, but someone must do it.", completion = "This will ease our efforts in Nazjatar." }
WordHunterWoW_QuestEN[55838] = { title = "Bounty: Lots of Hydras", description = "The hydra population is disrupting endeavors within Nazjatar. Kill on sight.\n\nReport to the quartermaster to claim your reward.", objectives = "" }
