WordHunterWoW_QuestEN[55844] = { title = "Bounty: Lots of Elementals", description = "The elemental population is disrupting endeavors within Nazjatar. Kill on sight.\n\nReport to the quartermaster to claim your reward.", objectives = "" }
WordHunterWoW_QuestEN[55845] = { title = "Plans of Attack", description = "<The attack plans are written on the parchment in fluorescent squid-ink and bound together with Azshara's seal.>\n\nOrders from our queen:\n\nQueen Azshara has commanded that all naga forces prepare for a full assault upon the Alliance invaders in our land. Details for the attack have been distributed to your various unit commanders.\n\nThe Alliance shall tremble at the might of our queen!", objectives = "Collect 8 Assault Plans.", progress = "What news do you bring from the front?", completion = "Excellent work, <class>. You've done the Alliance a great service. With these plans in hand, we will be able to prepare our defenses in advance of the attack." }
WordHunterWoW_QuestEN[55846] = { title = "Forbidden Rituals", description = "The naga use dark, forbidden rituals to subjugate the elements to their will.\n\nBut such rituals threaten to destroy the elemental balance that binds this world together. The rituals must be stopped. \n\nFortunately, the rituals the naga use are too elaborate to commit to memory. The ritual instructions are contained within ancient texts.\n\nIf we destroy the ancient tomes that contain the rituals, the knowledge will be lost to the naga forever.\n\nRetrieve the tomes and I will see that they are destroyed", objectives = "Collect 8 Tomes of Binding.", progress = "Do you have the tomes?", completion = "I will see to it that the tomes of binding are destroyed at once. May Neptulon guide your journey, <class>." }
WordHunterWoW_QuestEN[55849] = { title = "Reclamation Rig", description = "", objectives = "" }
WordHunterWoW_QuestEN[55851] = { title = "Essential Empowerment", description = "Champion, excitin' news!\n\nI know yer busy dealin' with the naga threat right now, but we need ye to come back tae the Chamber of Heart! MOTHER's finally finished her calculations and she's got an idea of what tae do next!\n\nHurry back tae Silithus as quick as ye can. Azeroth needs ye!", objectives = "Meet Magni in the repaired Chamber of Heart in Silithus.", progress = "There ye are! Chamber's lookin' better, eh?", completion = "Welcome back, champion! We've got loads tae do now that MOTHER's finished her calculatin'.\n\nLet's get started, eh?" }
WordHunterWoW_QuestEN[55860] = { title = "Sea Slug Liquidation", description = "My brief studies have shown that the refinement process creates a byproduct that is invisible to the naked eye, but is easily seen with refracted bioluminescent light. \n\nThe sea floor is littered with creatures that produce just what we need to track down this weapons cache.", objectives = "Collect 8 Bioluminescent Ooze from Luminescent Sea Slugs within Bloodfin Village.", progress = "Do you have the ooze?", completion = "The substance is stickier than expected, but should still work." }
WordHunterWoW_QuestEN[55861] = { title = "Let the Residue Lead You", description = "I have fashioned a device that will emit bioluminescent light when toggled on, allowing you to see any Azerite residue that lingers. \n\nIt should give you a clear trail to the weapons cache. \n\nGood luck, {name}.", objectives = "Follow the residue trail to locate the Azerite Weapons Cache.", completion = "<Although tightly sealed, the radiating energy and weight suggest that the crate contains Azerite weapons.>" }
WordHunterWoW_QuestEN[55862] = { title = "Insight into Our Enemies", description = "There's no telling what awaits us within this land. We cannot press forward without first knowing exactly what we're up against. \n\nAlthough our new allies have suffered greatly at the hands of the naga, their hardships will not be in vain. \n\nThe kelfin should have invaluable knowledge of Azshara's forces. \n\nWith their help, we might be able to learn more about how our enemies operate.\n\nSpeak with Neri and see what insight she can provide.", objectives = "Speak to Neri to learn more about the naga within Nazjatar.", completion = "You want some insight into the naga?\n\nI can tell you what I know, but the kelfin who are still being held captive can give you a firsthand account." }
WordHunterWoW_QuestEN[55863] = { title = "Deteriorating Knowledge", description = "The kelfin are no strangers to Azshara's cruelty. \n\nShe commands creatures of darkness that entrap my kind and warp their minds. They eat away at their memories until nothing's left but an empty husk. \n\nIf you can get to them soon, perhaps they'll still be in a state worth saving.", objectives = "Rescue Fenn, Kono, and Esma from the clutches of mind-leeching Zoatroids.", completion = "I thought I'd die in that cave. Sometimes, I wished it. \n\nThank you for getting me out of there, <name>." }
WordHunterWoW_QuestEN[55864] = { title = "The Price is Death", description = "We've long believed that the ocean is big enough for all that wish to call it home. \n\nUnfortunately, the naga don't see it that way. \n\nThey kill and capture our kind without remorse, and it's about time they paid the price.", objectives = "Kill 10 naga within Zanj'ir wash and the Deepsea Slave Pens.", completion = "If they're dead, they can't hurt me anymore. \n\nIf I keep telling myself that, soon enough I'll believe it, right?" }
WordHunterWoW_QuestEN[55865] = { title = "What We Know of the Naga", description = "It feels good to be me again. I have you to thank for that.\n\nMy head still hurts from the zoatroid's influence, but I think the others are worse off.\n\nPut some of this salve on their wounds, and I'll do my best to tell you what I know about the naga.", objectives = "Tend to the Kelfin's wounds and hear what Fenn has to say about the naga.", progress = "You're interrupting.", completion = "Whatever is hidden within the stronghold needs to be destroyed." }
WordHunterWoW_QuestEN[55866] = { title = "Scouting Undercover", description = "Entering the stronghold alone would be a death wish.\n\nThe Zanj'ir slaughter outsiders on sight. \n\nThe only way to get in without being killed is to appear to be under the effects of a zoatroid. \n\nEven then, the mind-shackled are put to work. \n\nYou must obey all commands, or they will know your mind is still your own. \n\nOnce the Zanj'ir believe you are mind-shackled, it should be easier to navigate their domain and uncover their secret.", objectives = "Scout Zanj'ir Terrace while pretending to be mind-shackled.", completion = "What use are you to us if you're not working?" }
WordHunterWoW_QuestEN[55867] = { title = "Coveted Crystals", description = "Locating the weapons cache shouldn't be a problem once we have the proper tools. A little light and a lot of bioluminescent fluid is all we need!\n\nIt all seems rather simple, doesn't it? But the key is in the Deepsea Crystal used to refract the light. \n\nI am told that the Bloodfin tribe covets these crystals, so it shouldn't be too much trouble to get your hands on one.", objectives = "Collect a Deepsea Crystal from Hoarder Moarrgl.", progress = "Have you found the crystal?", completion = "The clarity on this gem is rather remarkable, wouldn't you say? I think it'll do nicely." }
WordHunterWoW_QuestEN[55868] = { title = "Let the Residue Lead You", description = "I've fashioned a device that will emit bioluminescent light when toggled on, allowing you to see any Azerite residue that lingers. \n\nIt should give you a clear trail to the weapons cache. \n\nGood luck, {name}.", objectives = "Follow the residue trail to locate the Azerite Weapons Cache.", completion = "<Although tightly sealed, the radiating energy and weight suggest that the crate contains Azerite weapons.>" }
WordHunterWoW_QuestEN[55869] = { title = "Clearing Out the Cache", description = "<While inspecting the crate, a commotion can be heard within the cavern. A familiar voice, shouting orders.>", objectives = "Deal with Priscilla Ashvane and her minions.", completion = "It seems Azshara's influence reaches even further than we thought. \n\nAshvane may have escaped, but at least we have secured the weapons." }
WordHunterWoW_QuestEN[55870] = { title = "Sea Slug Liquidation", description = "The Azerite refinement process creates a byproduct that is invisible to the naked eye, but is easily seen with refracted bioluminescent light. \n\nThe sea floor is littered with creatures that produce just what we need to track down this weapons cache.", objectives = "Collect 8 Bioluminescent Ooze from Luminescent Sea Slugs within Bloodfin Village.", progress = "Do you have the ooze?", completion = "It's stickier than expected, but should still work." }
WordHunterWoW_QuestEN[55871] = { title = "Gather Friends", description = "Outside is dangerous.\n\nIt is safe in the Kelfin Pocket. \n\nWe find the lost crabs, and slugs, and other friends.\n\nHere they get a new name and a new home. \n\nFind friends like these, and bring them home.", objectives = "Collect Sandclaw Crabs and Muck Creepers for Narm.", progress = "Did you bring us friends?", completion = "They are already my friends. Now they are safe.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[55872] = { title = "Where They Hide", description = "Those sneaky snakes have started to send assassins.\n\nThey hide nearby and kill those they cannot take away to the slave pens.\n\nEven the sponges want to be rid of them! \n\nThe spores will reveal the naga treachery... and then you can go ahead and kill them. \n\nWe must keep our people safe!", objectives = "Use the Fresh Sponge to reveal and kill 5 Zanj'ir Assassins.", progress = "Did you find them all?", completion = "Ha! They hate those things.\n\nNicely destroyed." }
WordHunterWoW_QuestEN[55873] = { title = "Kill the Kritch", description = "Mrgglrr! Mrlg rmglr grlmrrgrr, grmm mrgl grrmrrgllrr. \n\n<Rlgmrr jumps around anxiously and points toward the cave.>\n\nGrrmrlgr mrg lrglgllmrrglm mlr mrlglmrgm mrl Kriiitchrglgr.\n\n<He makes a scary face and pinching motions with his hands.>\n\nMrglrmgr lrg, mrgglmmmr! Mrlg grrrrml lrg.", objectives = "Kill the Kritch.", progress = "Mrgglrmr grm?", completion = "Llrmmrgl! Mrgggl mrgl!\n\n<Rlgmrr laughs.>" }
WordHunterWoW_QuestEN[55874] = { title = "Plug the Geysers", description = "We're getting a geyser hit any minute now.\n\nThe effects of the Tidestone are far-reaching.\n\nWe have to do what we can to prevent any further destruction.\n\nUse this sealant to stall off the next round of eruptions!", objectives = "Seal all of the unstable geysers.", progress = "Did you take care of all of them?", completion = "Did it get you once? I feel like it got you.\n\nHappens to the best of us! Great work." }
WordHunterWoW_QuestEN[55875] = { title = "Plug the Geysers", description = "Just keep watching this spot... any second now...\n\nOnce those geysers start firing, get in there and seal them up.\n\nThe more they shake, the more everything breaks apart!\n\nWe have to keep these things under control.", objectives = "Seal all of the unstable geysers.", progress = "Is it all sealed up?", completion = "Good work!\n\nI was hoping for a little help from the Reefwalkers, but we take what we can get!" }
WordHunterWoW_QuestEN[55876] = { title = "Plug the Geysers", description = "Earthquakes! Snakes! Water coming from every direction.\n\nWhat is going on around here?\n\nNeri said to plug some holes in the defenses - didn't think she'd mean it literally.\n\nTake some of this goo, next eruption, stick it in the hole.", objectives = "Seal all of the unstable geysers.", progress = "Goop them all up?", completion = "Yeah! That was some surftastic heroing!" }
WordHunterWoW_QuestEN[55877] = { title = "Plug the Geysers", description = "We have been keeping an eye out for these unstable geysers.\n\nSince the water went away, the ocean has been trying to find a way back in.\n\nIf we let it burst up just anywhere, we could all be doomed!\n\nHelp me plug these up!\n\nBe careful, though, I found out the hard way they have a bit of a kick.", objectives = "Seal all of the unstable geysers.", progress = "Did you prevent the disaster?", completion = "The ocean's own luck was with us! Well done, <race>." }
WordHunterWoW_QuestEN[55878] = { title = "Plug the Geysers", description = "Have you heard about the geysers? \n\nAll over the newly exposed areas, water trying to fill where it was pulled away.\n\nThe ocean, she is angry. I don't think she likes Azshara either.\n\nWe will keep filling this in until we can find a permanent fix.", objectives = "Seal all of the unstable geysers.", progress = "Get them stopped up for now?", completion = "Thank you, friend.\n\nI have a feeling that won't hold for long." }
WordHunterWoW_QuestEN[55879] = { title = "Ride of the Scientifically Enhanced Boar", description = "We don't know how long the re-sizing will last, so let's get moving.\n\nYou're going to ride this giant boar and mow down the army of undead between us and Wrathion.\n\nThe large ones are pulsing with shadow magic. If you kill them, I bet it they'll take out any enemies near them.\n\nLet's hope Wrathion is willing to help us find Kalecgos.", objectives = "Ride the Giant Boar to destroy the undead army.", progress = "Please... help! I won't last much longer!", completion = "Thank you, stranger. I thought I was going to be punished for failing to save my friends.\n\nI'm relieved that I was mistaken." }
WordHunterWoW_QuestEN[55880] = { title = "Redistribution of Power", description = "Welcome back, dear test subject.\n\nToday's experiment is...\n\n<Pristy flips through some papers and smiles.>\n\n...My pet project, the NRG-100!\n\nI am quite pleased with the potential improvements I've made to efficiency, potency, and destructivity.\n\nAnd the only thing I had to sacrifice was stability!\n\nWhen you're ready to proceed, strap on the NRG-100.", objectives = "Use the NRG-100 to charge 6 energy cells.", progress = "Let's experiment!", completion = "Wondrous experimentation, dear test subject!\n\nI'll make further modifications to the NRG-100 based on these results. It will be ready for our follow-up test in a few days." }
WordHunterWoW_QuestEN[55881] = { title = "Purge the Totems", description = "The harpies' totems are scattered throughout the area.\n\nHarpies are known for using their magic to corrupt those nearby. Even now, I can hear foul whispers in the air...\n\nWe must destroy these totems before any of us are tainted by their dark magic!", objectives = "Set fire to 5 Harpy Totems.", progress = "The totems are not particularly powerful. A simple light and tinder should do.", completion = "The foul magic in this area is dissipating. I think we're safe for now." }
WordHunterWoW_QuestEN[55882] = { title = "Message to Base", description = "We did it! We're one step closer to getting off this island.\n\nLet's get back to camp and inform the captain of our success.", objectives = "Return to the Alliance Camp and speak with Captain Garrick.", completion = "I'm relieved you rescued Meredy. That's one more life saved and one fewer sacrificed.\n\nAnd I'm glad to see you helped Henry get back to his old self.\n\nWe'll work with Meredy to figure out a plan of action." }
WordHunterWoW_QuestEN[55883] = { title = "To Soar Like a Ray", description = "I like to find the eggs of the fathom rays before they hatch so we can form a bond with them.\n\nAt least, when we can't swim, we can fly!\n\nBring me a few more eggs to start a new thing - we'll call them Rayriders!", objectives = "Bring back 7 fathom ray eggs.", progress = "Did you find many eggs?", completion = "Ah! Perfect! Soon we will feel the wind!" }
WordHunterWoW_QuestEN[55884] = { title = "Infestation of Madness", description = "", objectives = "" }
WordHunterWoW_QuestEN[55885] = { title = "Rico's Rescue", description = "Some of our Roughriders are missing, I tried to find them, but got pinned down here by the bugs! \n\nI could really use your help, {name}. See if you can save my missing troopers.", objectives = "Rescue Trooper Levy, Katrin, and Bybee.", completion = "Rico put in a good word for you. Could mean a promotion sometime." }
WordHunterWoW_QuestEN[55886] = { title = "The Zanj'ir Brutalizer", description = "", objectives = "" }
WordHunterWoW_QuestEN[55887] = { title = "Champion Alzana, Arrow of Thunder", description = "", objectives = "" }
WordHunterWoW_QuestEN[55888] = { title = "Champion Qalina, Spear of Ice", description = "", objectives = "" }
WordHunterWoW_QuestEN[55889] = { title = "Champion Kyx'zhul the Deepspeaker", description = "", objectives = "" }
WordHunterWoW_QuestEN[55890] = { title = "Champion Vyz'olgo the Mind-Taker", description = "", objectives = "" }
WordHunterWoW_QuestEN[55891] = { title = "Champion Aldrantiss, Defender of Her Kingdom", description = "", objectives = "" }
WordHunterWoW_QuestEN[55892] = { title = "Champion Eldanar, Shield of Her Glory", description = "", objectives = "" }
WordHunterWoW_QuestEN[55893] = { title = "Azanz, the Slitherblade", description = "", objectives = "" }
WordHunterWoW_QuestEN[55894] = { title = "Zoko, Her Iron Defender", description = "", objectives = "" }
WordHunterWoW_QuestEN[55895] = { title = "Frozen Winds of Zhiela", description = "", objectives = "" }
WordHunterWoW_QuestEN[55896] = { title = "Undana, Chilling Assassin", description = "", objectives = "" }
WordHunterWoW_QuestEN[55897] = { title = "Szun, Breaker of Slaves", description = "", objectives = "" }
WordHunterWoW_QuestEN[55898] = { title = "Tempest-Speaker Shalan'ali", description = "", objectives = "" }
WordHunterWoW_QuestEN[55899] = { title = "Starseeker of the Shirakess", description = "", objectives = "" }
WordHunterWoW_QuestEN[55900] = { title = "Kassar, Wielder of Dark Blades", description = "", objectives = "" }
WordHunterWoW_QuestEN[55901] = { title = "Rustbolt Rebellion", description = "Aid the Rustbolt resistance.You will receive:", objectives = "Aid the Rustbolt resistance." }
WordHunterWoW_QuestEN[55905] = { title = "Abduction Reduction", description = "We got actual ABDUCTIONS happenin' here, {name}!\n\nHonest to gold, flying robots are swoopin' into town and snatchin' up people like it's closin' time at Gallywix's buffet!\n\nLucky for the Rustbolt Resistance, Gazlowe called in me and my explosives to save the day.\n\nYou wanna pitch in? Take one of my rocket launchers and blast those containment crates outta the sky.\n\nWhatever they've got trapped inside will come tumblin' down real fast, so you gotta run underneath and catch 'em.", objectives = "Free 6 captured Mechagnomes and catch them before they hit the ground.", completion = "Nice shootin' out there!\n\nAnd, hey, don't worry if you \"accidentally\" missed a Mechagnome or two... I did too!\n\n<Penny winks at you.>" }
WordHunterWoW_QuestEN[55937] = { title = "Clearing Out the Cache", description = "<While inspecting the crate, a commotion can be heard within the cavern. A familiar voice, shouting orders.>", objectives = "Deal with Priscilla Ashvane and her minions.", completion = "It seems Azshara's influence reaches even further than we thought. \n\nAshvane may have escaped, but at least we have secured the weapons." }
WordHunterWoW_QuestEN[55965] = { title = "Westward Bound", description = "Captain Garrick wants us tae search west o' camp fer any other members of the expedition.\n\nAlaria and I will go on ahead. Meet us tae the west and we'll see what we can find.", objectives = "Meet Bjorn Stouthands west of the Alliance Camp.", completion = "A giant pit of spiders right on our doorstep! Aren't we the lucky ones?" }
WordHunterWoW_QuestEN[55967] = { title = "Sating Snapdragons", description = "It's time for the snapdragons to feed, but it's a job best left to someone a little more expendable. \n\nThe beasts will eat anything, including your arm if you don't move it away quickly enough. \n\nLuckily for you, they've developed a taste for Chitterspine Roe.", objectives = "Collect Chitterspine Roe and feed it to Savage Snapdragons.", completion = "I'm surprised they didn't make a meal out of you." }
WordHunterWoW_QuestEN[55970] = { title = "Attrition", description = "", objectives = "" }
WordHunterWoW_QuestEN[55973] = { title = "Deepcoil Experiments", description = "", objectives = "" }
WordHunterWoW_QuestEN[55976] = { title = "Supplies From the Waveblade Ankoan", description = "The Waveblade Ankoan appreciate all the aid you've provided.\n\nPlease take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.", objectives = "Speak with Speaker Utia in Mezzamere for your reward.", completion = "Thanks to your efforts against the naga, our clan has been able to secure additional resources from the battlefield.  Please accept this gift of supplies, <name>. \n\nThe more you continue to dominate the battlefield the more resources we can spare." }
WordHunterWoW_QuestEN[55979] = { title = "Iteration is Key", description = "You've been holding out on me!\n\nHere I was, thinking that we're friends now and yet you neglected to tell me about your magnificient wrench!\n\n<Christy inspects it closely.>\n\nWell, not too magnificient... I recognize the Ub3r-Spanner from its blueprints, but whoever built this lacks a certain level of craftsmanship.\n\nI will upgrade it for you. Bring me the Overcharged Mecha-core from a mechanocrawler.\n\nNo excuses. I will fix your mistakes.", objectives = "Collect an Overcharged Mecha-core from the Overcharged Mechanocrawler.", progress = "Imagine crafting an Ub3r-Spanner without an overcharged mecha-core... Ha!", completion = "This will only take a minute. Keep a close eye on what I do, and you will learn a thing or ten." }
WordHunterWoW_QuestEN[55980] = { title = "Turn the Scale", description = "I have been trying to gather some of the scales from the young hydra nearby. \n\nTheir flexibility and strength makes them incredibly versatile.\n\nWith all the cranky old hydra tromping around, I don't stand much of a chance. \n\nCan you gather some up for me?", objectives = "Collect 20 Hydra Scales from nearby hydra.", progress = "Do you have enough?", completion = "You aren't as slow as I thought you'd be, with those land foots." }
WordHunterWoW_QuestEN[55981] = { title = "Right Beneath Their Eyes", description = "We need to get inside Darkmaul Citadel, rescue the captain of the expedition, and stop the ogre behind all of this.\n\nMeredy is going to cast an illusion to make you look like an ogre, and you're going to take us all in as \"prisoners.\"\n\nI'll be hiding my efforts to suppress the shadow magic in the meantime.\n\nSpeak with Meredy when you're ready for her to cast the spell.\n\nHer illusion spell should be temporary, as long as she casts it in the proper way.", objectives = "Have Meredy transform you into an ogre, then scout the nearby ogre citadel.", completion = "We're close to stopping all of this. We just need to push a little further." }
WordHunterWoW_QuestEN[55982] = { title = "The Lords of Water", description = "", objectives = "" }
WordHunterWoW_QuestEN[55983] = { title = "A Safer Place", description = "<The murloc seems to be in rough shape. Perhaps it would be safer with your allies in Mezzamere.>", objectives = "Escort Mrrl back to Mezzamere.", completion = "<Mrrl seems at home in his new spot and his family has also taken up refuge here. It is unlikely you will be able to remove this new murloc infestation.>" }
WordHunterWoW_QuestEN[55984] = { title = "A Good Offense", description = "Korl was told to watch the naga, so watching the naga I am.\n\nThey're bad, friend, you know... just... terrible, horrible, bad monsters. \n\nI don't think I can just watch any more.\n\nThey say the best defense is.. something...\n\nHelp me teach them being being bad gets you smashed!", objectives = "Kill 50 naga.", progress = "Did you have fun?", completion = "This was my best day. Thank you, friend." }
WordHunterWoW_QuestEN[55985] = { title = "Extra Shiny", description = "In the pools below are some small, lovely pearls. \n\nThey were tossed in during some Azsh'ari ritual. \n\nDo they mean something? I have no idea. But I would like to have some of them. \n\nBe a lovely heavyfoot and go grab some for me, please!", objectives = "Collect 10 Imbued Pearls.", progress = "Did you find all of the pearls?", completion = "I can feel them glowing! They tingle through my hand and into the ocean floor.\n\nVery lovely." }
WordHunterWoW_QuestEN[55986] = { title = "Break a Few Eggs", description = "This chamber is lovely and terrifying. \n\nWhat is born here will ruin the lives of so many. \n\nWe cannot hurt the pods, but we can destroy the eggs of the serpents that guard them.\n\nTake out the eggs, every little bit helps.\n\nPoor eggs...", objectives = "Destroy 10 Deepcoil Eggs.", progress = "Did you destroy the eggs?", completion = "The fewer creepy flying snakes we have guarding the naga, the better." }
WordHunterWoW_QuestEN[55988] = { title = "Like Ogres to the Slaughter", description = "This is bad, {name}. Captain Kelra is bound by magic, the ogres are preparing to attack our friends, and the ritual is almost complete!\n\nI have to stay calm. We can't give up now, right?\n\nThis may sound risky, but we need to take the fight to the ogres.\n\nWe're behind enemy lines, so we'll be able to get the jump on them and draw their focus away from the camp.\n\nTake down any ogres that you can. That should keep them away from our friends.", objectives = "Slay 8 ogres within Darkmaul Citadel.", progress = "You need to slay the ogres so they don't go after our friends back at the camp.", completion = "This should buy us enough time to stop the ritual!" }
WordHunterWoW_QuestEN[55989] = { title = "Catapult Destruction", description = "Did you notice the catapults on our way up? It appears the ogres plan to attack our allies below.\n\nLindie anticipated something like this and provided several bombs to handle siege weapons.\n\nJust don't shake them too hard.", objectives = "Blow up 4 catapults within Darkmaul Citadel.", progress = "Don't worry about the bombs. They'll blow up those catapults just fine.", completion = "Great work! I'll have tae tell Lindie that his bombs worked perfectly." }
WordHunterWoW_QuestEN[55990] = { title = "Controlling their Stones", description = "Captain Kelra won't last much longer. We need to acquire the ward stones to break the ritual before it kills her.\n\nI'll continue weakening the main ritual. Get those ward stones from the ogre lieutenants nearby.", objectives = "Recover the Ward Stones from Jugnug, Wug, and Grunk, then use them to free Captain Kelra.", progress = "So, these were the stones used to bind me? The ogres clearly were concerned about you thwarting their plans.", completion = "Thank you for saving me, but we have no time to lose. The ogres will not stop until they have raised the dragon!" }
WordHunterWoW_QuestEN[55991] = { title = "An End to Beginnings", description = "You've done fine work within Exile's Reach, recruit. You should continue on to the Dragon Isles.\n\nI'm afraid I must change my plans and go back to Stormwind. I need to find out how the ogres found such powerful shadow magic.\n\nI'm sure we'll meet again. I can tell you've got many adventures ahead of you.", objectives = "Speak with Kalecgos to travel to the Dragon Isles.", completion = "It's good to be back in Stormwind. \n\nI must report our mission's success to the king, but I have an idea for what you can do in the meantime..." }
WordHunterWoW_QuestEN[55992] = { title = "Dungeon: Darkmaul Citadel", description = "You've slown down Gor'groth's efforts to control Kalecgos atop the citadel, but the ritual itself needs to be thwarted.\n\nYou must storm the citadel and stop him from completing the ritual. His dark magic is an affront to the Light.\n\nWe will need all the help we can get. Gor'groth's most elite lieutenants await within the citadel.", objectives = "Complete the dungeon, \"Darkmaul Citadel\".", progress = "You must go and slay Gor'groth before it is too late!", completion = "It seems things are finally looking up for us. I think it's time we returned to Stormwind." }
WordHunterWoW_QuestEN[55993] = { title = "A Little Edge", description = "In the darkest cavern. Below the naga city. You will find them.\n\nCreepy little crabs with sharp and pointy spines. \n\nI think we can find a way to use them. Projectiles didn't work so well in water, but now...\n\nHarvest some for us!\n\nBe careful, some of them are much sneakier than they have any right to be.", objectives = "Collect 12 Chitterspine Spines.", progress = "Did you gather the spines?", completion = "Ouch! These might just do the trick!" }
WordHunterWoW_QuestEN[55994] = { title = "Do Not Drink", description = "These troggs watch everything we do.  \n\nThey see us pouring oil into various machines, so now they're stealing the oil and drinking it. I think they believe it's going to turn them into machines!\n\nWe need that oil back, before they drink it all!", objectives = "Recover 12 containers of Stolen Oil.", progress = "Get that oil back quick!", completion = "Ya done good work." }
WordHunterWoW_QuestEN[55995] = { title = "We Can Fix It", description = "<This drill rig looks capable of breaking through the nearby debris, but is clearly broken.\n\nIf you can collect the parts required, Prince Erazmin should be able to show you how to repair it.>", objectives = "Collect 40 Spare Parts and 1 Energy Cell from enemies in Junkwatt Depot.", progress = "Us mechagnomes are always building something. Mechagon is littered with broken or half-completed construction projects.", completion = "Do these small parts appear insignificant to you?\n\nUse your imagination. Find their purpose. Give them value." }
WordHunterWoW_QuestEN[55997] = { title = "Hungry Hungry Hydras", description = "", objectives = "" }
WordHunterWoW_QuestEN[56000] = { title = "We've Got Crabs!", description = "{name}, you're just in time. Everything's ready for the crab hunt!\n\nOkay, okay... I know what you're thinking. A founding member of D.E.H.T.A. that condones hunting?\n\nI'm going to level with you, {name}. I've got a bar full of hungry murlocs that only eat three things: crabs, fish, and people.\n\nIf that's not reason enough, crabs are overpopulated in this region and they're decimating the local grub worm population!\n\nHow many innocent grub worms need to die before we do something, {name}?", objectives = "Collect 12 Crackleclaw Crabs.", progress = "How many innocent grub worms need to die before we do something, <name>?", completion = "That's quite the case of crabs you've got there, <name>. Well done! Please set it down behind the bar and I'll take care of the rest." }
WordHunterWoW_QuestEN[56001] = { title = "Drunk Angry Murlocs", description = "Those no-good Bloodfins ran off with all of the beer!\n\nI've been experimenting with brews that only use ingredients native to Nazjatar, but it's still a work in progress. For now, I must rely on whatever I can scrounge up from the shipwreck.\n\nMy supply of beer was already limited, but now it's all gone thanks to those thieving Bloodfin murlocs! We're going to have some very angry customers here if we don't get it back.\n\nPlease recover the stolen lager from Bloodfin Village before it's too late!", objectives = "Collect 12 Ocean \"Infused\" Lagers.", progress = "Those no-good Bloodfins ran off with all of the beer!", completion = "Good work, <name>! You've recovered pretty much all of the stolen beer. Those Bloodfins are more trouble than they're worth!" }
WordHunterWoW_QuestEN[56002] = { title = "Mgglurky's Mugglrgl", description = "My cook, Mgglurky, lost his mugglrgl and he's refusing to work until he gets it back.\n\nI've got a bar full of hungry murlocs and nothing to feed them until Mgglurky starts cooking. If Mgglurky doesn't find his mugglrgl soon, we're going to have a riot on our hands!\n\nI don't know about you, but I definitely don't want to be the main course tonight.\n\nThere were some Bloodfins lurking around earlier. Search Bloodfin Village for the mugglrgl and bring it back to me once you find it.", objectives = "Retrieve Mgglurky's Mugglrgl from Bloodfin Village.", progress = "If Mgglurky doesn't find his mugglrgl soon, we're going to have a riot on our hands!", completion = "You've found it! So this is a mugglrgl? For some reason I thought it would be bigger. Mgglurky will be happy you returned it!" }
