WordHunterWoW_QuestEN[56030] = { title = "The Warchief's Order", description = "Champion, the Dark Lady summons you. The time has come to set her plan into motion.\n\nOur warships are ready to embark. The key to victory over the Alliance is within our grasp.\n\nMeet me in Zuldazar, aboard the Banshee's Wail. What we do next... we do for the Horde.", objectives = "Meet with Nathanos Blightcaller on The Banshee's Wail.", completion = "Ah, the final member of our crew has arrived." }
WordHunterWoW_QuestEN[56031] = { title = "The Wolf's Offensive", description = "Champion, Spymaster Shaw reports that the remains of the Horde fleet is preparing to depart.\n\nThey will be easy pickings for our superior forces. Let us seize this opportunity to eliminate their threat once and for all!\n\nPreparations are underway to set sail. Come to Boralus Harbor and meet with me upon the Wind's Redemption with all haste!", objectives = "Meet with Genn Greymane on the Wind's Redemption.", completion = "You're just in time, <name>. \nSpymaster Shaw was just informing me of some new intelligence we've recently learned about the Horde fleet." }
WordHunterWoW_QuestEN[56032] = { title = "Dirty Dozen", description = "", objectives = "" }
WordHunterWoW_QuestEN[56034] = { title = "Re-sizing the Situation", description = "The Re-Sizer v9.0.1 barely works on inanimate objects. I have no idea what it will do to organic matter!\n\nBut if we do nothing, Wrathion will die!\n\nDesperate times call for massively experimental science, {name}.\n\nTake the Re-Sizer v9.0.1. I'll follow you around and calibrate it.\n\nWe're going to whip up a giant boar!", objectives = "Use the Re-Sizer v9.0.1 on 3 Wandering Boars.", progress = "Be careful where you point the Re-Sizer v9.0.1. Make sure you're only using it on the boars in the immediate area.", completion = "I never thought I'd be so relieved to be face to face with a giant, scientifically enhanced boar.\n\nLet's go save my son." }
WordHunterWoW_QuestEN[56035] = { title = "Most Delicious Clams", description = "This pool is filled with creepy fish. \n\nIt is also the home of some of the most delicious clams you will ever eat. Fresh water somehow mixes into the ocean water in this one part of Nazjatar, and that gives the meat a totally new flavor.\n\nEvery now and then, we come down here and collect them for our friends in Newhome.\n\nWe could sure use some help with all these extra mouths to feed!", objectives = "Collect 10 Neptulian Clams.", progress = "Did you find enough?", completion = "Everyone is going to be so happy!\n\nThank you!" }
WordHunterWoW_QuestEN[56036] = { title = "A Steamy Situation", description = "", objectives = "" }
WordHunterWoW_QuestEN[56037] = { title = "Stealing the Naga's Secrets", description = "<Upon closer inspection, it becomes clear that the blades have been forged from Azerite. \n\nWeapons of this power should never be in the hands of the naga.>", objectives = "Steal the Azerite weaponry and fight your way out of Zanj'ir Terrace!", progress = "I recognize the craftsmanship. This is Priscilla Ashvane's work.  \n\nShe must have taught the naga how to forge Azerite weaponry, but why?", completion = "We cannot expect to succeed in any battle where our enemies are using Azerite weaponry. \n\nNo, we must find a way to even the playing field." }
WordHunterWoW_QuestEN[56038] = { title = "Working with Purpose", description = "It seems the Shirakess are never satisfied with the number of pearls we source for them. They're always demanding more. \n\nBefore you came along, it was my job to crawl around the cavern, cracking open clams. \n\nSo you see, you have some purpose, other than being a mindless sack of flesh.", objectives = "Collect 6 Iridescent Pearls from Chittershell Clams.", progress = "Do you have them all?", completion = "Eager to please, aren't you?" }
WordHunterWoW_QuestEN[56039] = { title = "We Can't Have Dull Weapons", description = "For a squid head, you sure are making my life easier. \n\nI guess you get to live long enough to complete another task. \n\nOur new weapons are forged from some foreign material that I don't quite trust. \n\nYou won't catch me sharpening any blades, but the work still needs to get done. \n\nGet to it!", objectives = "Find the special weaponry within Zanj'ir Terrace.", completion = "<The weapons on the rack radiate with a familiar energy.>" }
WordHunterWoW_QuestEN[56041] = { title = "Give 'Em Shell", description = "", objectives = "" }
WordHunterWoW_QuestEN[56042] = { title = "Blingtron 7000", description = "", objectives = "OUTPUT: Please accept this GIFT. \n\nADMINISTER GIFT DISTRIBUTION PROTOCOL." }
WordHunterWoW_QuestEN[56043] = { title = "Send the Fleet", description = "This war has cost us dearly, but victory will soon be in our grasp.\n\nWhat remains of the Horde fleet has departed Zuldazar and our spies say that the Banshee Queen's hand sails at their helm.\n\nThis is our chance, {name}! With one strike we can eliminate what remains of their fleet and rid Azeroth of Blightcaller's filth once and for all!\n\nThe fleet is preparing to depart, report to the Harbormaster when you are ready to set sail.", objectives = "Speak to Harbormaster Cyrus Crestfall to set sail.", completion = "Never could I have expected this..." }
WordHunterWoW_QuestEN[56044] = { title = "Send the Fleet", description = "The Warchief has entrusted me with a mission of the highest priority, {name}.\n\nThe mission will succeed, of this there is no question, but to ensure that any obstacles I encounter are dealt with swiftly I once again have need of your particular skills.\n\nThe Zandalari have offered us use of their ships for this endeavor. Clear out whatever affairs you have remaining and report to Captain Rez'okun when you are ready to set sail.", objectives = "Speak to Captain Rez'okun to set sail.", completion = "An unexpected development, but it changes nothing.\n\nWe have our orders to carry out, <name>." }
WordHunterWoW_QuestEN[56045] = { title = "Stealing the Naga's Secrets", description = "<Upon closer inspection, it becomes clear that the blades have been forged from Azerite. \n\nWeapons of this power should never be in the hands of the naga.>", objectives = "Steal the Azerite weaponry and fight your way out of Zanj'ir Terrace!", progress = "I recognize the craftsmanship. This is Priscilla Ashvane's work.  \n\nShe must have taught the naga how to forge Azerite weaponry, but why?", completion = "We cannot expect to succeed in any battle where our enemies are using Azerite weaponry. \n\nNo, we must find a way to even the playing field." }
WordHunterWoW_QuestEN[56046] = { title = "Working with Purpose", description = "It seems the Shirakess are never satisfied with the number of pearls we source for them. They're always demanding more. \n\nBefore you came along, it was my job to crawl around the cavern, cracking open clams. \n\nSo you see, you have some purpose, other than being a mindless sack of flesh.", objectives = "Collect 6 Iridescent Pearls from Chittershell Clams.", progress = "Do you have them all?", completion = "Eager to please, aren't you?" }
WordHunterWoW_QuestEN[56047] = { title = "We Can't Have Dull Weapons", description = "For a squid head, you sure are making my life easier. \n\nI guess you get to live long enough to complete another task. \n\nOur new weapons are forged from some foreign material that I don't quite trust. \n\nYou won't catch me sharpening any blades, but the work still needs to get done. \n\nGet to it!", objectives = "Find the special weaponry within Zanj'ir Terrace.", completion = "<The weapons on the rack radiate with a familiar energy.>" }
WordHunterWoW_QuestEN[56048] = { title = "The Drowned Oracles", description = "", objectives = "" }
WordHunterWoW_QuestEN[56049] = { title = "Deck 'Em", description = "That ooze seems really hungry!\n\nHe ate my backpack, compass, pickaxe, and my hearthstone cards.\n\nGet my cards back!", objectives = "Recover Adalin's Hearthstone Cards.", progress = "I'm not leaving till I get my cards back!", completion = "Thank you! I'll grab my cards here, and meet you back in town!" }
WordHunterWoW_QuestEN[56050] = { title = "PvP Event: Battle for Nazjatar", description = "", objectives = "" }
WordHunterWoW_QuestEN[56053] = { title = "The Final Act", description = "Those of us with enough mechanization survived, but it didn't matter. Bondo Bigblock sold us out. In exchange for full mechanization, he built giant bots and attacked Rustbolt. \n\nHe will continue to act against us, till those few of us left are dead. \n\nWe must remove this threat immediately.", objectives = "Kill Bondo Bigblock.", progress = "Will you help me deal with this threat?", completion = "We can start to rebuild now." }
WordHunterWoW_QuestEN[56056] = { title = "Terror of the Depths", description = "", objectives = "" }
WordHunterWoW_QuestEN[56057] = { title = "The Soulbinder", description = "", objectives = "" }
WordHunterWoW_QuestEN[56063] = { title = "Dark Tides", description = "A Tidemistress leads the naga in this area.\n\nShe is performing some damnable ritual outside, demanding sacrifices of our soldiers.\n\nStop her before more of our own meet a cruel fate.", objectives = "Slay Tidemistress Ethendriss.", completion = "With her death, the ritual is over. But there is not time for celebration." }
WordHunterWoW_QuestEN[56064] = { title = "Assault: The Black Empire", description = "I cannot believe my eyes. The Black Empire is materializing right here in the Vale!\n\nWe must spring to action!", objectives = "Drive back the N'Zoth Assault in the Vale of Eternal Blossoms.", completion = "Thank goodness you arrived when you did! I still cannot believe that N'Zoth would strike at my very doorstep.\n\nThe pandaren will recount this tale for countless generations." }
WordHunterWoW_QuestEN[56070] = { title = "Vengeance for the Venthyr", description = "Lord Denathrius has fallen under the sway of the Jailer. His betrayal of our people shall not stand.\n\nWe will show the Jailer that the venthyr are not to be underestimated... nor are you, Maw Walker. Slay his sub-lords. Let him know that he is now being hunted.", objectives = "Defeat the Jailer's lieutenants on floors 5 and 10 of the Jailer's Tower." }
WordHunterWoW_QuestEN[56071] = { title = "De-Synced Vibro Blade", description = "The wildly shaking blade reminds you of the blades the Rustbolt defenders use. No doubt someone will be able to fix it up.", objectives = "Give the De-Synced Vibro Blade to Ricket in Rustbolt." }
WordHunterWoW_QuestEN[56072] = { title = "De-Synced Vibro Blade", description = "The wildly shaking blade reminds you of the blades the Rustbolt defenders use. No doubt someone will be able to fix it up.", objectives = "Give the De-Synced Vibro Blade to Sapphronetta Flivvers in Rustbolt.\n\nProvided item:" }
WordHunterWoW_QuestEN[56074] = { title = "Void Conduit", description = "", objectives = "" }
WordHunterWoW_QuestEN[56075] = { title = "Stolen Power", description = "From the void these naga pull their strength. \n\nEach scroll they record, shared knowledge -- that knowledge is power.\n\nIt stands to reason, if we take away their knowledge, we steal their power.\n\nMy logic may be flawed, but let's do it anyway!", objectives = "Collect 8 Scrolls of Shirakess.", progress = "Did you get all of the scrolls?", completion = "Take away a little magic, get a little weaker.\n\nIf nothing else, we will win this war through erosion." }
WordHunterWoW_QuestEN[56076] = { title = "Abyssal Ritual", description = "", objectives = "" }
WordHunterWoW_QuestEN[56078] = { title = "Time to Krill", description = "", objectives = "" }
WordHunterWoW_QuestEN[56080] = { title = "March of the Murlocs", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[56081] = { title = "Octo-Grab", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[56082] = { title = "Bot Rampage", description = "Those bots have been attacking us from the moment we landed. We've got to hold this beach!\n\nMy expedition guards could use your help, {name}. Lend a hand, destroy bots on the beach and in the nearby woodlands.", objectives = "15 attacking bots slain.", progress = "The expedition guards could use your help!", completion = "They're still attacking, but we can handle it from here." }
WordHunterWoW_QuestEN[56083] = { title = "Unsafe Work Conditions", description = "Those rampaging bots ain't lettin' up!\n\nWe're payin' good money for the best and brightest goblins on the planet, and I ain't gonna let some malfunctionin' machinery take 'em outta the shift schedule.\n\nThis is textbook unsafe working conditions, and the Greasemonkey Union reps are givin' me an earful for it. Protect the workers!", objectives = "15 attacking bots slain.", progress = "The greasemonkeys could use your help!", completion = "Ya done good work for a <race>." }
WordHunterWoW_QuestEN[56086] = { title = "Blueprint: Holographic Digitalization Relay", description = "<This blueprint details how to build what appears to be some form of holographic teleporter.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "Upload the blueprint to Pascal-K1N6's database.\n\nProvided item:", completion = "Have you recovered a new blueprint, my fleshy friend?\n\nI will add it to my database posthaste." }
WordHunterWoW_QuestEN[56087] = { title = "Blueprint: Experimental Adventurer Augment", description = "<This blueprint details how to build what appears to be some form of ring... or maybe it's a trinket?\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "Upload the blueprint to Pascal-K1N6's database.\n\nProvided item:", completion = "Have you recovered a new blueprint, my fleshy friend?\n\nI will add it to my database posthaste." }
WordHunterWoW_QuestEN[56090] = { title = "Stormstout Holdout", description = "", objectives = "" }
WordHunterWoW_QuestEN[56091] = { title = "Usurper's Scent Gland", description = "When a new queen is born and old enough to start proliferating her own hive, she will leave the nest. Her scent will attract some of the hive to fly with her to their new home. This one likely never got the chance to do so, thanks to you.\n\nThe Hivemother will be interested in this item.", objectives = "Take the Usurper's Scent Gland to the Honeyback Hivemother for a reward.\n\nProvided item:", completion = "<The Hivemother quickly devours the scent gland and wiggles at you.>" }
WordHunterWoW_QuestEN[56092] = { title = "Hivethief's Jelly Stash", description = "This ettin was a well known and oft dreaded face among the bees of the Honeyback hive. Their jelly stores will benefit from his demise.\n\nThe Hivemother will be interested in this item.", objectives = "Take the Hivethief's Jelly Stash to the Honeyback Hivemother for a reward.\n\nProvided item:", completion = "<The Hivemother buzzes animatedly.>\n\nBzzz! Bzzz!" }
WordHunterWoW_QuestEN[56095] = { title = "Legacy of Nar'anan", description = "Hey there, {race}. Mind helping me out?\n\nYou see, I found these pylons here and it seems they contain memories from a notable Highborne who lived here long ago.\n\nI can't get any closer to the rest of em' because of the snapdragons. Especially the terrormaws...\n\nCan you go and activate the pylons for me? We Tortollans love old things, and this is a potential goldmine!\n\nOh, and be sure to write down what you see!", objectives = "Activate the Memory Pylons in Nar'anan and witness what happened.", completion = "Let me see what you got. \n\n<Collector Kojo reads your notes... slowly>\n\nI think we may have just found the origin of Snapdragons! Let's see what else we can learn." }
WordHunterWoW_QuestEN[56097] = { title = "Grime-Coated Disc", description = "<Look for someone that can help recover the data trapped on this grime-coated disc.>", objectives = "" }
WordHunterWoW_QuestEN[56098] = { title = "Defensive in Death", description = "<Having handled zin'anthid for a while now, you pluck one of its tentacles from the main body. As you do, the tentacle retracts, spiraling in on itself preventing you from getting to the blooms that reside along it. Perhaps Instructor Ulooaka will have more insight on how to keep this herb from defending itself.>", objectives = "Ask Instructor Ulooaka about the tentacles of the Zin'anthid.\n\nProvided item:", completion = "Zin'anthids are no mere plant, <name>. They are living beings and as such, know when a predator is trying to harvest them. And yes, even in death they defend themselves.\nIf you wish to harvest all they have to offer, you must lure them into a false sense of security. Here, let me show you a technique I know." }
WordHunterWoW_QuestEN[56099] = { title = "Font of Corruption", description = "", objectives = "" }
WordHunterWoW_QuestEN[56103] = { title = "Ounces of Osmenite", description = "<Picking away at the ore, you pick up some shards that have fallen to the ground. There ought to be a way to mine these deposits without wasting any of it. Perhaps Instructor Ulooaka knows of still a better way to mine this ore.>", objectives = "Ask Instructor Ulooaka about the Osmenite Shards.\n\nProvided item:", completion = "Ah yes, that's due to the fragile nature of the ore. You need to adjust your style a bit.\n\nInstead of heavy, powerful swings, try picking away at the edge of where the ore meets the rock.\n\nLike peeling the skin off a fruit. Here, let me show you what I mean..." }
WordHunterWoW_QuestEN[56104] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[56107] = { title = "One of the Hive", description = "[PH]", objectives = "[PH]" }
WordHunterWoW_QuestEN[56108] = { title = "Leaving the Hive", description = "<The enormous bee twitches its antennae toward you. It swings its abdomen toward the cave exit.>\n\nBarry might know what's going on.", objectives = "Speak to Barry in the Honeyback Hatchery.", completion = "<It wriggles eagerly in its new harness.>\n\nBzzz!" }
WordHunterWoW_QuestEN[56109] = { title = "Defender of the Hive", description = "[PH]", objectives = "[PH]" }
WordHunterWoW_QuestEN[56110] = { title = "A Defender Emerges", description = "[PH]", objectives = "[PH]" }
WordHunterWoW_QuestEN[56111] = { title = "The Usurper", description = "[PH]", objectives = "[PH]" }
WordHunterWoW_QuestEN[56112] = { title = "A Royal Awakening", description = "[PH]", objectives = "[PH]" }
WordHunterWoW_QuestEN[56113] = { title = "Tracking Quest", description = "[PH] I saw some bees tussling over a much larger jelly deposit. It's probably worth bringing one to the Hivemother and seeing what happens.", objectives = "Acquire 1 Rich Jelly and return it to the Hivemother.[PH] I saw some bees tussling over a much larger jelly deposit. It's probably worth bringing one to the Hivemother and seeing what happens." }
WordHunterWoW_QuestEN[56116] = { title = "Even More Recycling", description = "", objectives = "<WARNING 3.6.4 - Y: Keep all appendages clear of doors or risk irreversible limb recyclerization.>", progress = "<WARNING 3.6.4 - Y: Keep all appendages clear of doors or risk irreversible limb recyclerization.>", completion = "You deposit the bundle of parts into the Recyclerizer DX-82.  The doors close and the machine surges to life, a slight buzzing sound begins emanating from within. The sound increases in frequency, the slight buzz giving way to a high-pitched whirring. The machine shakes violently, seemingly ready to explode..." }
WordHunterWoW_QuestEN[56117] = { title = "Recyclable Parts", description = "<This bundle of recycling could be valuable. The gnomes in the area appear to be dropping their scrap into some nearby contraptions.>", objectives = "Collect 1 Bundle of Recyclable Parts", progress = "<WARNING 3.6.4 - Y: Keep all appendages clear of doors or risk irreversible limb recyclerization.>", completion = "You deposit the bundle of parts into the Recyclerizer DX-82.  The doors close and the machine surges to life, a slight buzzing sound begins emanating from within. The sound increases in frequency, the slight buzz giving way to a high-pitched whirring. The machine shakes violently, seemingly ready to explode..." }
WordHunterWoW_QuestEN[56118] = { title = "Snap Back", description = "I have a favor to ask of you, if you would be so kind.\n\nScrollsage Nola gave me this scroll to protect me on my adventures here in Nazjatar. She is a kind soul, but her scroll-work isn't always the most...accurate.\n\nYou look like a brave adventurer who's seen a thing or two. Could you test out the scroll for me? While you're there you may as well cull their numbers a tad.", objectives = "Use the Scroll of Busting Power on Snapdragon Terrormaws and slay snapdragons in Nar'anan.", completion = "Wow! That powerful huh? \n\nI will be sure to keep this with me then!" }
WordHunterWoW_QuestEN[56119] = { title = "The Waveblade Ankoan", description = "Assist the Ankoan in Nazjatar by completing 4 world quests.", objectives = "Complete any 4 world quests in Nazjatar.", progress = "Return to me when you have finished aiding the Ankoan, <name>.", completion = "May Neptulon shower you with his blessings, friend." }
WordHunterWoW_QuestEN[56120] = { title = "The Unshackled", description = "Assist the Unshackled in Nazjatar by completing 4 world quests.", objectives = "Complete any 4 world quests in Nazjatar.", progress = "Return to me when you have finished aiding us, <name>.", completion = "You've really made a difference out there! \n\nThank you, friend." }
WordHunterWoW_QuestEN[56121] = { title = "Jumping Jellies", description = "", objectives = "" }
WordHunterWoW_QuestEN[56126] = { title = "Seams to be a Problem", description = "<Picking away at the ore, you notice that much of it seems to turn to dust and fall to the floor at your feet. Enough even, that had it held its shape, would be enough to craft something with.\n\nIt may be worth talking to Instructor Ulooaka to see if there's a way to prevent this loss from happening.>", objectives = "Ask Instructor Ulooaka about the Osmenite Dust.\n\nProvided item:", completion = "The seams that osmenite flows through are structurally different than that of their mere deposits.\n\nIf you want to harvest the full amount of osmenite from a seam, you'll have to ignore the ore all together and go for the rock surrounding it.\n\nIt's a bit counter to how you normally mine, but trust me, you'll be pleasantly surprised with the results." }
WordHunterWoW_QuestEN[56128] = { title = "Drowning the Horde", description = "We must strike now before the Horde have a chance to gain a secure foothold. Attack their champions and knock them on their heels.", objectives = "Kill 25 Horde players in Nazjatar while in War Mode.", completion = "If we keep up the pressure there is no way the Horde will succeed." }
WordHunterWoW_QuestEN[56129] = { title = "Heroic: Battle for Stromgarde", description = "", objectives = "" }
WordHunterWoW_QuestEN[56131] = { title = "Security First", description = "Many dangerous creatures and allies of my father still seek to destroy us.\n\nHelp secure this island, seek out and and eliminate five of our most powerful enemies.You will receive:", objectives = "Defeat Rare enemies on the island of Mechagon." }
WordHunterWoW_QuestEN[56136] = { title = "Heroic Warfront: The Battle for Stromgarde", description = "If the Horde thinks it can assault Stromgarde, it is sorely mistaken! We will not let Arathi fall!\n\nPrepare yourself for battle.", objectives = "Defeat the Horde at the Battle for Stromgarde.", completion = "Well fought, <name>, though I'm afraid it may be premature to let our guard down just yet. I am sure our enemy will not sit idly while we rebuild Stromgarde." }
WordHunterWoW_QuestEN[56137] = { title = "Heroic Warfront: The Battle for Stromgarde", description = "Our enemies are relentless in their quest to seize Arathi for themselves. We will never allow it to fall into their hands! We must stop them before the keep is rebuilt!\n\nTake up arms. The Alliance is upon us.", objectives = "Defeat the Alliance at the Battle for Stromgarde.", completion = "A battle well fought, <name>. You have once again proven yourself a great warrior of the Horde." }
WordHunterWoW_QuestEN[56138] = { title = "Holographic Entity Materalizer", description = "Alright! Let's try this puppy out. Just insert that cleaned up data disc I gave ya into my Experimental Holographic Entity Materializer over there and we'll fire 'er up!", objectives = "" }
WordHunterWoW_QuestEN[56139] = { title = "Junkyard Treasures", description = "Everyone here needs to work hard to find resources for our cause. \n\nLocate and open ten mechanized chests on the island.You will receive:", objectives = "" }
WordHunterWoW_QuestEN[56141] = { title = "Security First", description = "Many dangerous creatures and allies of my father still seek to destroy us.\n\nHelp secure this island, seek out and and eliminate five of our most powerful enemies.You will receive:", objectives = "Defeat Rare enemies on the island of Mechagon." }
WordHunterWoW_QuestEN[56142] = { title = "Adapt, Improve, Overcome!", description = "Izira Gearsworn is still alive, she is Rustbolt's strongest fighter, but her legs are broken. If we're going to survive I need parts to repair and upgrade her.\n\nThere are machines all over with parts we can salvage. With some perseverance we should be able to fix Izira's legs.\n\nHelp me obtain the following parts.", objectives = "20 Pristine Hound Bolts, 4 Steel Tibia XS, and 2 Machined Heel Nut.", progress = "We need to start searching!", completion = "These are in excellent shape!" }
WordHunterWoW_QuestEN[56143] = { title = "The Fate of Professor Elryna", description = "From the looks of it, Elryna's story should have a very interesting end. This pylon here has been acting up, but I think I know why!\n\nThese things use memory cores, little crystals found within the center of the orb. I bet there's one in that old magi tower. \n\nThere's a snapdragon that's bigger than the terrormaws in there so here, keep the scroll for now. It should help in your fight. She's a big one!", objectives = "Defeat the Snapdragon Matriarch, collect the Memory Core, and activate the Memory Pylon to witness the fate of Professor Elryna.", progress = "What happened that fateful day?", completion = "So. She was betrayed by that general?\n\nHe probably proceeded to take all the credit himself. \n\nShame. But at least now we have the knowledge! Thank you, <name>." }
WordHunterWoW_QuestEN[56144] = { title = "Old Nasha's Paw", description = "The old bear's paw is sticky with honey. She likely ransacked a number of hives before you stopped her.\n\nThe Hivemother will be interested in this item.", objectives = "Take Old Nasha's paw to the Honeyback Hivemother for a reward.\n\nProvided item:", completion = "<The Hivemother hums contentedly.>\n\nBzzz." }
WordHunterWoW_QuestEN[56145] = { title = "Blueprint: Advanced Adventurer Augment", description = "<This blueprint details how to condense even more power into a ring or trinket!\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "Upload the blueprint to Pascal-K1N6's database.\n\nProvided item:", completion = "Have you recovered a new blueprint, my fleshy friend?\n\nI will add it to my database posthaste." }
WordHunterWoW_QuestEN[56146] = { title = "Making Kelpberry Wine", description = "<This is an empty kelpberry juice cask.\n\nThere is someone nearby that may appreciate a refill.>", objectives = "Deliver Kelpberry Wine to Maedin in Maedin's Challenge.", progress = "Did you bring me something?", completion = "Oh, you know exactly what this ol' girl likes!" }
WordHunterWoW_QuestEN[56148] = { title = "Call to Arms: Nazjatar", description = "Our objectives in Nazjatar are being interrupted by the influx of Alliance scum.\n\nClear as many of them out of the area that you find, then report back.", objectives = "Slay Alliance within Nazjatar.", completion = "Good work, <class>." }
WordHunterWoW_QuestEN[56149] = { title = "Feed Them All", description = "I am grateful for the help that your Alliance has given my people, but we are desperately short on food and supplies.\n\nIf we do not gather enough supplies to take care of both the Alliance and my clan, we will run out of food within the week.\n\nThankfully, there appears to be an abundance of fathom rays in the area, but I will need help hunting them in order to gather enough food for our camp.\n\nTake this fathom hook and use it to pull down the fathom rays from above.", objectives = "Collect 10 Fathom Flesh.", progress = "Have you returned from the hunt?", completion = "You have brought back a hefty supply of fathom meat. I will make sure that it gets hauled back to camp. Thank you for your service, <class>." }
WordHunterWoW_QuestEN[56150] = { title = "Kill the Kritch", description = "Mrgglrr! Mrlg rmglr grlmrrgrr, grmm mrgl grrmrrgllrr. \n\n<Rlgmrr jumps around anxiously and points toward the cave.>\n\nGrrmrlgr mrg lrglgllmrrglm mlr mrlglmrgm mrl Kriiitchrglgr.\n\n<He makes a scary face and pinching motions with his hands.>\n\nMrglrmgr lrg, mrgglmmmr! Mrlg grrrrml lrg.", objectives = "Kill the Kritch.", progress = "Mrgglrmr grm?", completion = "Llrmmrgl! Mrgggl mrgl!\n\n<Rlgmrr laughs.>" }
WordHunterWoW_QuestEN[56151] = { title = "Poen's Favorite Dish", description = "Poen is always helping us take care of every rescue we find.\n\nCan you collect some meat from the eels south of here?\n\nI like to make his favorite dish every now and then, to repay him.\n\nIt also has a great effect on the ones recovering. \n\nThe power of deliciousness, I tell you!", objectives = "Collect 15 Fresh Unagi.", progress = "Did you get enough meat?", completion = "This really is a special treat for all of us.\n\nThank you!" }
WordHunterWoW_QuestEN[56152] = { title = "Turn the Scale", description = "I am in need of your help, {class}. I have been hunting the nearby hydras for their scales, but my weapon was broken in the melee.\n\nThe scales of the hydra make durable and resilient armor for our warriors. Our clan requires the scales to craft and repair our armor.\n\nIf we do not resupply soon, we will be ill-equipped in our fight against the naga.", objectives = "Collect 20 Hydra Scales.", progress = "Have you completed the hunt?", completion = "Thank you, <class>. These scales will help us greatly in our war against the naga." }
WordHunterWoW_QuestEN[56153] = { title = "Most Delicious Clams", description = "Neptulian clams are an important part of the ankoan diet.\n\nMany forget how important proper nutrition is during a time of war. A warrior can be armed with the finest weapons and training, but if she is not healthy and well-nourished she will be ineffective in battle.\n\nNow that Mezzamere is home to your Alliance, we must work hard to gather enough food to feed our soldiers.\n\nGather as many Neptulian clams as you can find and I will see that they make it back to camp safely.", objectives = "Collect 10 Neptulian Clams.", progress = "Have you gathered the Neptulian clams?", completion = "These will serve us well.\n\nThank you, <class>." }
WordHunterWoW_QuestEN[56154] = { title = "Where They Hide", description = "The naga are sending assassins to eliminate our forces.\n\nThey hide nearby and murder those they cannot steal away to the slave pens.\n\nTake this special sea sponge with you. The spores will reveal the naga in all their treachery.\n\nOnce revealed, slay the assassins before they can flee for reinforcements.\n\nAzshara will fall!", objectives = "Use the Fresh Sponge to reveal and kill 5 Zanj'ir Assassins.", progress = "Have the naga assassins been eliminated?", completion = "Well done, <class>. The road is now much safer to travel." }
WordHunterWoW_QuestEN[56155] = { title = "Plug the Geysers", description = "The geysers are dangerously unstable and will be erupting any moment now.\n\nI fear that Azshara's misuse of the Tidestone is causing irreparable damage to the elements within Nazjatar.\n\nWe have to do what we can to prevent any further destruction.\n\nTake this sealant and use it to stave off the next round of eruptions. In the meantime, I will do what I can to stabilize the elements.", objectives = "Seal 5 Unstable Geysers and slay the Disturbed Algan.", progress = "Were you able to prevent the geysers from erupting further?", completion = "Good work, <name>. Thanks to your help sealing the geysers, I've been able to stabilize the elements and redirect the pressure to a safer location." }
WordHunterWoW_QuestEN[56156] = { title = "A Tempered Blade", description = "These blades that I wield are newly forged. The time has come to temper them in the blood of my enemies.\n\nI have heard that you are skilled in the ways of battle. I too am proficient in the business of death and I would be honored to fight at your side.\n\nAccompany me, {class}, and together we will spill the blood of our enemies.", objectives = "Slay 15 naga with Bladesman Inowari.", progress = "A blade is not worthy of a warrior until it is tempered in the blood of the enemy.", completion = "It was an honor to fight by your side, <name>. If you should have need of me in the future, you need only ask." }
WordHunterWoW_QuestEN[56157] = { title = "Plug the Geysers", description = "There are several geysers nearby that will be erupting soon.\n\nUnfortunately, the elements in this area are not stable enough to handle the force of the eruptions.\n\nI need someone to plug the geysers while I use the elements to redirect the pressure to a safer area of Nazjatar.\n\nTake this sealant and use it to plug the geysers while I work to restore the elemental balance.", objectives = "Seal 5 Unstable Geysers and slay the Disturbed Algan.", completion = "Good work, <name>. Thanks to your help sealing the geysers, I've been able to stabilize the elements and redirect the pressure to a safer location." }
WordHunterWoW_QuestEN[56158] = { title = "Plug the Geysers", description = "The elements are becoming increasingly unstable due to Azshara's abuse of the Tidestone.\n\nGeysers will be erupting nearby at any moment. Each eruption threatens to destroy the delicate balance of life on the surface.\n\nTake this sealant and use it to plug the geysers while I work to restore the elemental balance and redistribute the explosive underground pressure to a safer location.", objectives = "Seal 7 Unstable Geysers.", completion = "Good work, <name>. Thanks to your help sealing the geysers, I've been able to stabilize the elements and redirect the pressure to a safer location." }
WordHunterWoW_QuestEN[56159] = { title = "Plug the Geysers", description = "The geysers are dangerously unstable and will be erupting any moment now.\n\nI fear that Azshara's misuse of the Tidestone is causing irreparable damage to the elements within Nazjatar.\n\nWe have to do what we can to prevent any further destruction.\n\nTake this sealant and use it to stave off the next round of eruptions. In the meantime, I will do what I can to stabilize the elements.", objectives = "Seal 7 Unstable Geysers.", progress = "Were you able to prevent the geysers from erupting further?", completion = "Good work, <name>. Thanks to your help sealing the geysers, I've been able to stabilize the elements and redirect the pressure to a safer location." }
WordHunterWoW_QuestEN[56160] = { title = "Plug the Geysers", description = "There are several geysers nearby that will be erupting soon.\n\nUnfortunately, the elements in this area are not stable enough to handle the force of the eruptions.\n\nI need someone to plug the geysers while I use the elements to redirect the pressure to a safer area of Nazjatar.\n\nTake this sealant and use it to plug the geysers while I work to restore the elemental balance.", objectives = "Seal 6 Unstable Geysers.", progress = "Have the geysers been sealed?", completion = "Good work, <name>. Thanks to your help sealing the geysers, I've been able to stabilize the elements and redirect the pressure to a safer location." }
WordHunterWoW_QuestEN[56161] = { title = "Back Out to Sea", description = "Now that things're under control here, I'm sure they could use your help back in Nazjatar!\n\nWhy don't ye head back out tae sea, err, or under the sea, tae lend a hand with the new folk there?", objectives = "Return to Newhome in Nazjatar.", completion = "Welcome back. There's work to do." }
WordHunterWoW_QuestEN[56162] = { title = "Back Out to Sea", description = "Now that things're under control here, I'm sure they could use your help back in Nazjatar!\n\nWhy don't ye head back out tae sea, err, or under the sea, tae lend a hand with the new folk there?", objectives = "Return to Mezzamere in Nazjatar.", completion = "Thank you for returning to assist us. There's more to be done." }
WordHunterWoW_QuestEN[56163] = { title = "Bound Elemental", description = "", objectives = "" }
WordHunterWoW_QuestEN[56164] = { title = "Desperate Need", description = "Our injured are in desperate need of bandages and medicines. Ask Speaker Utia for more medical supplies. \n\nUtia is our quartermaster and will certainly have the items we need.", objectives = "" }
WordHunterWoW_QuestEN[56165] = { title = "Blueprint: Extraordinary Adventurer Augment", description = "<This blueprint details how to condense an extraordinary amount of power into a ring or trinket!\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "Upload the blueprint to Pascal-K1N6's database.\n\nProvided item:", completion = "Have you recovered a new blueprint, my fleshy friend?\n\nI will add it to my database posthaste." }
WordHunterWoW_QuestEN[56166] = { title = "The Needs of the People", description = "There are others in the camp that may be in need of aid. Ask around and see if there are any duties that you could take up.\n\nBe sure to report what you find to Speaker Utia.", objectives = "Speak to people in Mezzamere about things they need." }
WordHunterWoW_QuestEN[56167] = { title = "Investigating the Highlands", description = "When I first sensed these essences, I did not anticipate the importance of the role they would play. It is only a matter of time before all of the dragonflights are brought into the fold.\n\nThough I have reached out to the other Aspects, I have yet to hear from Alexstrasza. It is odd that she would be silent while these powers manifest.\n\nShe was last seen in the Vermillion Redoubt in Twilight Highlands.\n\nI fear she may be in trouble. We must hurry.", objectives = "Meet Kalecgos in the Twilight Highlands.", completion = "It is far worse than expected. We tried to reach the Redoubt, but did not even make it to the ridge.\n\nSomething is watching the skies and preventing us from reaching Alexstrasza." }
WordHunterWoW_QuestEN[56168] = { title = "Factory Refurbished", description = "I need you to get us a Recycled Crawler Manifold.\n\nYou should be able to get one up at Junkwatt Depot if you recycle parts found there.", objectives = "Recycled Crawler Manifold obtained.", progress = "Head up to the Junkwatt Depot and get working!", completion = "Nice work, this is just what I needed." }
WordHunterWoW_QuestEN[56170] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[56171] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[56172] = { title = "Other Interests", description = "Madam Goya is interested in many unusual items other than just rare metals.\n\nKeep your eyes out for these particular items during your travels in Nazjatar.\n\nDeliver them to me and Madam Goya will consider you for special access.", objectives = "Deliver 5 Curious Murloc Horn to Steelsage Gao.", progress = "Have you found these items.", completion = "Excellent work, we shall speak again." }
WordHunterWoW_QuestEN[56173] = { title = "Other Interests", description = "Madam Goya is interested in many unusual items other than just rare metals.\n\nKeep your eyes out for these particular items during your travels in Nazjatar. \n\nDeliver them to me and Madam Goya will consider you for special access.", objectives = "Deliver 5 Unidentified Mass to Steelsage Gao.", progress = "Have you found these items.", completion = "Excellent work, we shall speak again." }
WordHunterWoW_QuestEN[56174] = { title = "Other Interests", description = "Madam Goya is interested in many unusual items other than just rare metals.\n\nKeep your eyes out for these particular items during your travels in Nazjatar. \n\nDeliver them to me and Madam Goya will consider you for special access.", objectives = "Deliver 5 Disintegrating Sand Sculpture to Steelsage Gao.", progress = "Have you found these items.", completion = "Excellent work, we shall speak again." }
WordHunterWoW_QuestEN[56175] = { title = "Emission Free", description = "We're going to need a few Empty Energy Cells to fill out the battery pack on the mount control assembly. \n\nSee if you can find me these.", objectives = "Collect 20 Empty Energy Cells", progress = "We need to fix this battery pack.", completion = "Nice work, this will help a lot." }
WordHunterWoW_QuestEN[56176] = { title = "Desperate Need", description = "Our injured are in desperate need of bandages and medicines. Ask Atolia Seapearl for more medical supplies. \n\nAtolia is our quartermaster and will certainly have the items we need.", objectives = "" }
WordHunterWoW_QuestEN[56177] = { title = "Void Conduit", description = "", objectives = "" }
WordHunterWoW_QuestEN[56178] = { title = "Void Conduit", description = "", objectives = "" }
WordHunterWoW_QuestEN[56179] = { title = "The Needs of the People", description = "There are others in the camp that may be in need of aid. Ask around and see if there are any duties that you could take up.\n\nBe sure to report what you find to Atolia.", objectives = "" }
WordHunterWoW_QuestEN[56180] = { title = "Bound Elemental", description = "", objectives = "" }
WordHunterWoW_QuestEN[56181] = { title = "This One's on Me", description = "I'm sure you agree that Pascal-K1N6 is the greatest invention you've ever seen!\n\nIf you're not convinced yet, try to push him to his limits. I don't mind!\n\nBring him more resources and blueprints -- he'll craft anything you need!", objectives = "Craft $1oa Junkyard Tinkering items with Pascal-K1N6.", completion = "You've done good work around town, <name>. A real asset to the resistance.\n\nI've also seen you admiring my blowtorch... Quite the creation, isn't it?\n\nTell you what, I'll unlock the blueprint for the Scrapmaster Blowtorch on Pascal-K1N6 for you.\n\nNo need to thank me. Excellence should be rewarded." }
WordHunterWoW_QuestEN[56184] = { title = "Pirates, Sea Monsters, Robots", description = "I finally found it! This is the resting place of my father, after his crew mutinied and left him here to die.\n\nI've scouted the island, and found the locations of three chests that contain mementoes of my father. \n\nDo this for me and my family. Recover my father's sword, clothing, and bones from the three chests I've marked.", objectives = "Recover DeMeza's father's Sword, Clothing and Bones.", progress = "Help my recover the remains of my father.", completion = "I can never thank you enough, so I won't." }
WordHunterWoW_QuestEN[56185] = { title = "Whispers of N'Zoth", description = "Are you curious how I came to be here, in the Chamber of Heart? \n\nOf course I arrived of my own volition, but there was quite a search for me, for a time.\n\nKalecgos remembers how it went. Speak to him, if you wish to relive the details of how I thwarted discovery by both Speaker and Old God.", objectives = "Speak to Kalecgos in the Chamber of Heart.", completion = "I knew that N'Zoth was powerful, but to reach Ebonhorn within the safety of the Chamber... \n\nWe have to do something about this. None of us are safe." }
WordHunterWoW_QuestEN[56186] = { title = "Spies to the Left and Right", description = "Ebonhorn cannot resist the whispers for long. The dark forces that once corrupted the black dragonflight seek to overwhelm the world once again.\n\nWe need a way to fight back. While I am loathe to mention him, I do know of someone who has been studying the Old Gods in order to better combat their insidious power: Wrathion.\n\nThe Black Prince has associates in Pandaria, in the Tavern of the Mists at the Veiled Stair. I suggest you begin your search there.\n\nPlease hurry, {name}.", objectives = "Seek out Wrathion at the Tavern in the Mists.", progress = "The Black Prince isn't here. But we might be able to help you find him.", completion = "Good work getting rid of those spies.\n\nThings have been quiet here for a long time. And now, suddenly, all eyes are on us. So to speak.\n\nThe Black Prince is notoriously secretive about his plans. I'm not in the habit of reading other people's journals, but I'm guessing he expected you to feel differently about it." }
WordHunterWoW_QuestEN[56187] = { title = "Black Winged Shadow", description = "Obviously, the Black Prince isn't here. Trust me when I say he's not an easy one to find.\n\nIf I were you, I'd make my way to Blackrock Mountain. There's a terrace carved into its slopes, where Nefarian once made his lair.\n\nWrathion has been monitoring that place for a long time. Even if he's not there himself, you might find someone who knows where to look.\n\nAnd {class}... it's clear you're not the only one searching for him. Watch your back.", objectives = "Seek out Wrathion outside the entrance to Blackwing Descent.", progress = "My head is still spinning... they showed me... such terrible... tempting things...", completion = "Thank you. They... forced their way into my mind. I couldn't stop them from finding what they sought.\n\nThe Black Prince meant for you to have those pages. He was certain that you would need the knowledge within them." }
WordHunterWoW_QuestEN[56188] = { title = "To the Catacombs!", description = "I held out as long as I could, but... the whispers were too strong.\n\nYou must hurry to Karazhan. The Black Prince said he intended to study the artifacts stored within its catacombs.\n\nPlease, do not allow my failure to bring about his doom!", objectives = "Seek out Wrathion outside the Karazhan Catacombs.", progress = "<It seems the lookout gave his life in service to the Black Prince.>", completion = "<The lookout put up a fierce fight before he died.\n\nYou have found more pages from Wrathion's journal on his body. Perhaps the Black Prince himself is not far.>" }
WordHunterWoW_QuestEN[56189] = { title = "On the Trail of the Black Prince", description = "<It looks like a fight took place here. N'Zoth's agents must have already entered the catacombs beneath Karazhan.\n\nThe dead lookout still has a set of keys on him. Perhaps they will unlock the door.\n\nWith any luck, you can find Wrathion before N'Zoth's agents and gain something that can help Ebonhorn.>", objectives = "Enter the Karazhan Catacombs and search for a cure for Ebonhorn.", progress = "<The note appears to have been left behind in a hurry, and deliberately placed where you would find it.>", completion = "The note reads:\n\n\"<name>. If you are reading this note, then I assume that Ebyssian has fallen prey to the whispers of the Old Gods. Fortunately, I have prepared a method to save him.\n\nYou will find a potion with the properties you seek sitting next to this note. Bring it to my brother and it will clear his mind of N'Zoth's influence.\n\nI will thank you for your efforts in person, soon enough.\"" }
WordHunterWoW_QuestEN[56190] = { title = "Save Ebonhorn", description = "<The potion appears to be powerful and chaotic. It changes color seemingly at random.\n\nThis must be the concoction Wrathion wrote about in his journal. Just standing near it grants you a sense of peace and clarity.\n\nYou may not have found the Black Prince himself, but perhaps what he left behind for you can help Ebonhorn.>", objectives = "Return to the Chamber of Heart and treat Ebonhorn with the Potion of Mental Clarity.", completion = "My mind is finally my own again. Whatever Wrathion brewed into that potion has quieted the whispers.\n\nBut I take it you did not find the Black Prince himself." }
WordHunterWoW_QuestEN[56191] = { title = "Blueprint: TK32[DNT]", description = "<This blueprint details how to build what appears to be TK.[DNT]\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>You will learn:", objectives = "Upload the blueprint to Pascal-K1N6's database.\n\nProvided item:" }
