WordHunterWoW_QuestEN[56205] = { title = "Just Ptrust Me On This", description = "Ahhh, it is good to see you, {name}.\n\nHow is de defective one? Still pleased to be at your side?\n\nI have given this some thought. Fear may still be what holds your not-so-little one back, but your love is what enables him to thrive without his wings. Perhaps that love will be what restores him to de skies.\n\nI am asking you to trust me. I wish to try something.\n\nIf I am correct then de two of you will find yourselves airborne as nature intended!", objectives = "Place your faith in Pa'ku and Kua'fon.", completion = "What did I tell you, child?\n\nAll he needed was de right motivation. Haha!" }
WordHunterWoW_QuestEN[56206] = { title = "Heroic: Battle for Stromgarde", description = "", objectives = "" }
WordHunterWoW_QuestEN[56209] = { title = "The Halls of Origination", description = "It looks like the Halls of Origination have been claimed by a group o' tol'vir calling themselves the Amathet. I don't know much about them other than they're new in town and not the friendliest of types.\n\nWe'll need tae get in there and re-activate the forge, or else Azeroth will be done for!", objectives = "Defeat the Amathet forces and reactivate the forge in the Halls of Origination.", progress = "Azeroth's gonna be done for if we dun get this thing back online!", completion = "We got the forge back, but not before N'Zoth was able tae cripple her systems. \n\nI'm afraid our work is far from done." }
WordHunterWoW_QuestEN[56210] = { title = "Scrying Stones", description = "I have a gift for you, {name}. \n\nIt's a stone unlike anything you've seen before. To the uninformed, it may seem to be a simple rock, but it's far more precious than that. \n\nThis is a scrying stone. It reveals objects that have been hidden by magic. When near an anomaly, the runes etched within will begin to glow. \n\nUse the stone to reveal treasure hidden away by ancient magic.", objectives = "Find treasures hidden away by magic within Nazjatar.", completion = "See, I wasn't lying. The scrying stones are extraordinary!" }
WordHunterWoW_QuestEN[56211] = { title = "Scrying Stones", description = "I have a gift for you, {name}. \n\nThis stone is unlike anything you may have seen before. To the uninformed, it appears to be a simple rock, but it is far more precious than that.\n\nThis is a scrying stone. It reveals objects that have been hidden by magic. When near an anomaly, the runes etched within will begin to glow. \n\nUse the stone to reveal treasure hidden away by ancient magic.", objectives = "Find treasures hidden away by magic within Nazjatar.", progress = "Have you found any treasure?", completion = "As you are now aware, these stones are quite extraordinary." }
WordHunterWoW_QuestEN[56214] = { title = "Good Girl", description = "I have learned so much by your side, I can't believe how many naga we've taken down!\n\nWhen you first arrived, I was skeptical that you'd make a difference. We've been down here, fighting, for so long. I had almost lost hope.\n\nBut now, we see a way out of the darkness of the depths, finally!\n \nI took in a snapdragon pup when we formed Newhome, been training her ever since. I think... I think I'd like you to have her.\n\nShe'll make a great mount... and loyal friend.", objectives = "Accept a gift from your companion.I have learned so much by your side, I can't believe how many naga we've taken down!\n\nWhen you first arrived, I was skeptical that you'd make a difference. We've been down here, fighting, for so long. I had almost lost hope.\n\nBut now, we see a way out of the darkness of the depths, finally!\n \nI took in a snapdragon pup when we formed Newhome, been training her ever since. I think... I think I'd like you to have her.\n\nShe'll make a great mount... and loyal friend.", completion = "Take good care of her, ok? She means a lot to me. \n\nShe likes fathom ray eggs best, so remember that.\n\nGoodbye, little one! Neri loves you!" }
WordHunterWoW_QuestEN[56215] = { title = "Glittering Shell", description = "Hi, friend. I just wanted you to know that traveling with you has been the best ever!\n\nI never thought I could learn so much about fighting, but now I feel like I can actually hold my own.\n\nI will protect all of the wee ones that can't protect themselves!\n\n<Poen produces a crab from somewhere, it has a bright shell.>\n\nLike this little one. I found him a while back, while we were out. He looked so scared.\n\nHey, why don't you take him?", objectives = "Accept a gift from your companion.Hi, friend. I just wanted you to know that traveling with you has been the best ever!\n\nI never thought I could learn so much about fighting, but now I feel like I can actually hold my own.\n\nI will protect all of the wee ones that can't protect themselves!\n\n<Poen produces a crab from somewhere, it has a bright shell.>\n\nLike this little one. I found him a while back, while we were out. He looked so scared.\n\nHey, why don't you take him?", completion = "I've never seen one with a shell this brightly-colored, must make him a target.\n\nWithout you, we could have both been doomed.\n\nHere, take him, it's because of you that we're all a lot safer now.\n\nI have more friends to protect!" }
WordHunterWoW_QuestEN[56216] = { title = "Last Heirloom", description = "We have encountered many foes together, and emerged victorious every time. I have you to thank for our safety this day, and my prowess in combat.\n\nI will be honest with you, friend. I did not think I would live this long.\n\nMy people had families, once. Traditions. We would carve symbols into our talismans and pass them down from generation to generation of deep sea hunters. Charms for luck, or prowess, each family had their own.\n\nThis is mine. I have none to pass it on to. I would like you to have it", objectives = "Accept a gift from your companion.We have encountered many foes together, and emerged victorious every time. I have you to thank for our safety this day, and my prowess in combat.\n\nI will be honest with you, friend. I did not think I would live this long.\n\nMy people had families, once. Traditions. We would carve symbols into our talismans and pass them down from generation to generation of deep sea hunters. Charms for luck, or prowess, each family had their own.\n\nThis is mine. I have none to pass it on to. I would like you to have it", completion = "This charm is one of luck, it was passed down through many years of my people.\n\nIt has brought me little luck, until now, until it brought you to me.\n\nIt is only fitting that you take it from here." }
WordHunterWoW_QuestEN[56217] = { title = "Wild Tame", description = "In our time together, I have learned much. Both about my own abilities, and about your people. \n\nYou are selfless in the face of challenge, much like our own. I consider us kin.\n\nFor some time, I have been training a snapdragon I found as a pup. He is a worthy mount, and I have been waiting for a worthy hunter to ride him. I believe I have found that hunter.\n\nHere, he is yours.", objectives = "Accept a gift from your companion.In our time together, I have learned much. Both about my own abilities, and about your people. \n\nYou are selfless in the face of challenge, much like our own. I consider us kin.\n\nFor some time, I have been training a snapdragon I found as a pup. He is a worthy mount, and I have been waiting for a worthy hunter to ride him. I believe I have found that hunter.\n\nHere, he is yours.", completion = "Take care when feeding him, the poison is no less lethal to a friend." }
WordHunterWoW_QuestEN[56218] = { title = "Beauty in the Deeps", description = "We have slain many enemies, spilled much blood on the sand. My skills have improved tenfold fighting at your side.\n\nYet let us not forget that once, this was a place of peace. Once, my people walked amongst the caverns and reefs undisturbed.\n\nThere is beauty, here, in the depths, all around us. Take a moment, sit, and enjoy your serene surroundings. Look here, a crab with a shell of brilliant colors.\n\nYou see? There is beauty here, even now.", objectives = "Accept a gift from your companion.We have slain many enemies, spilled much blood on the sand. My skills have improved tenfold fighting at your side.\n\nYet let us not forget that once, this was a place of peace. Once, my people walked amongst the caverns and reefs undisturbed.\n\nThere is beauty, here, in the depths, all around us. Take a moment, sit, and enjoy your serene surroundings. Look here, a crab with a shell of brilliant colors.\n\nYou see? There is beauty here, even now.", completion = "Take this crab, may it be a symbol of the beauty that once reigned in this place.\n\nWith your help, it will again." }
WordHunterWoW_QuestEN[56219] = { title = "Tome of Tears", description = "We've been fighting side by side for a while now. I didn't think an old salt like me could get any better at killing naga, but here we are.\n\nI have something to show you...\n\n<Vim produces a book from his pack.>\n\nWorst thing we can do is forget.\n\nSo many names I've written in this book, each and every one of them an Unshackled. All of them gone, now.\n\nI will never forget their names.\n\nI want you to have it. Tell people. Tell them who they were, and what we have done here.", objectives = "Accept a gift from your companion.We've been fighting side by side for a while now. I didn't think an old salt like me could get any better at killing naga, but here we are.\n\nI have something to show you...\n\n<Vim produces a book from his pack.>\n\nWorst thing we can do is forget.\n\nSo many names I've written in this book, each and every one of them an Unshackled. All of them gone, now.\n\nI will never forget their names.\n\nI want you to have it. Tell people. Tell them who they were, and what we have done here.", completion = "This book contains the names of brave creatures of all kinds that helped us, fought for us, and died for us.\n\nHelp me remember them." }
WordHunterWoW_QuestEN[56222] = { title = "WANTED: Lady Naz'jess", description = "Wanted for attacks against the people of Nazjatar. \n\nLady Naz'jess has been driving the weapon masters to create crueler devices.\n\nLast seen skulking about Zanj'ir Terrace. She is vicious, proceed with caution.\n\nUpon completion of the mission, report to Seacaller Unow for commendation.", objectives = "Retrieve the head of Lady Naz'jess.", progress = "Has her command come to an end?", completion = "Well done, <class>. Lady Naz'jess had become a thorn in the side of the people here." }
WordHunterWoW_QuestEN[56223] = { title = "WANTED: Commander Sarj'eth", description = "Wanted for attacks against the people of Nazjatar. \n\nCommander Sarj'eth has attempted to enslave many Horde survivors.\n\nHe commands slavers in Zanj'ir Terrace. Extreme caution advised!\n\nUpon completion of the mission, report to Seacaller Unow for commendation.", objectives = "Retrieve the head of Commander Sarj'eth.", progress = "Did the brave commander reach the end of his days?", completion = "Sarj'eth was a high-ranking commander among the naga. \n\nThese people will sleep better, knowing he is gone." }
WordHunterWoW_QuestEN[56224] = { title = "WANTED: Lord Ha'kass", description = "Wanted for attacks against the people of Nazjatar. \n\nLord Ha'kass has attempted to enslave many Horde survivors.\n\nHe commands slavers in Zanj'ir Wash. Extreme caution advised!\n\nUpon completion of the mission, report to Seacaller Unow for commendation.", objectives = "Retrieve the head of Lord Ha'kass.", progress = "Was the villain found?", completion = "Filth like him does not deserve to keep their head.\n\nYou just made the world a little bit better." }
WordHunterWoW_QuestEN[56225] = { title = "WANTED: Lady Narjiss", description = "Wanted for attacks against the Horde!\n\nLady Narjiss is responsible for leading several raids and ambushes against our soldiers.\n\nLast seen on the outskirts of Zanj'ir Terrace. Extreme caution advised!\n\nUpon completion of the mission, report to Seacaller Unow for commendation.", objectives = "Retrieve the head of Lady Narjiss.", progress = "Did you silence her?", completion = "Lady Narjiss brought with her a darkness. The world feels a little lighter now." }
WordHunterWoW_QuestEN[56226] = { title = "WANTED: Gler'thogg", description = "Gler'thogg is responsible for the death and torture of many of the Unshackled. \n\nThey have shared with us their pain. Bring back his eye.\n\nHe dwells in the Deepcoil Tunnels. Extreme caution advised!\n\nUpon completion of the mission, report to Seacaller Unow for commendation.", objectives = "Retrieve the Eye of Gler'thogg.", progress = "Is this your first enucleation?", completion = "That tentacled terror will torture them no more." }
WordHunterWoW_QuestEN[56227] = { title = "WANTED: Inquisitor Ithriza", description = "Wanted for attacks against the Horde!\n\nInquisitor Ithriza is responsible for leading several raids and ambushes against our soldiers.\n\nLast seen in the vicinity of Dragon's Teeth Basin. Extreme caution advised!\n\nUpon completion of the mission, report to Seacaller Unow for commendation.", objectives = "Retrieve the head of Inquisitor Ithriza.", progress = "Did you knock him down a peg?", completion = "One tormentor down, so many to go." }
WordHunterWoW_QuestEN[56231] = { title = "Reinforced Cache", description = "The heavily reinforced chest is of naga construction and appears to be reinforced with a heavy-duty lock of some kind.\n\nReinforcement aside, the cache still requires a key to unlock.\n\nThe key is most likely being held by one of the nearby naga commanders.", objectives = "Locate the key to the Naga Cache.", progress = "The chest is locked and requires a key.", completion = "As you turn the key you can hear the heavy latches of the chest snap open with considerable force..." }
WordHunterWoW_QuestEN[56232] = { title = "Void Cache", description = "The heavily reinforced chest is of naga construction and appears to be reinforced with a magical lock of some kind.\n\nMagical reinforcement aside, the cache still requires a key to unlock.\n\nThe key is most likely being held by one of the nearby naga commanders.", objectives = "Locate the key to the Naga Cache.", progress = "The chest is locked and requires a key.", completion = "The magical barrier dissipates as you insert the key..." }
WordHunterWoW_QuestEN[56233] = { title = "Arcane Cache", description = "The heavily reinforced chest is of naga construction and appears to be reinforced with a magical lock of some kind.\n\nMagical reinforcement aside, the cache still requires a key to unlock.\n\nThe key is most likely being held by one of the nearby naga commanders.", objectives = "Locate the key to the Naga Cache.", progress = "The chest is locked and requires a key.", completion = "The magical barrier dissipates as you insert the key..." }
WordHunterWoW_QuestEN[56234] = { title = "Friends In Need", description = "I doubt that will be the last we've seen of Priscilla, but at least she is no longer one of our immediate concerns.\n\nWe must think carefully before making our next move. In the meantime we should continue to build upon our relationship with our new allies, the Ankoan. Work with them to secure the area and hone their skills, we're not out of the woods yet.\n\nI fear the biggest battle is still to come. Let's show them that together we can take on Azshara's forces and succeed!", objectives = "Support your allies in Nazjatar by gaining 3000 experience combined between Farseer Ori, Hunter Akana, and Bladesman Inowari.", completion = "Good work, while you were gone Shandris and I have been talking and I think she's found a promising lead for us to focus our efforts." }
WordHunterWoW_QuestEN[56235] = { title = "Down Into Nazjatar", description = "We have much to do {name}. However our troops are weary and need rest. Decisions made when tired are often the wrong ones.\n\nThese \"Unshackled\" have offered to aid us with what forces they have. If we hope to survive down here against Azshara's forces, we will need to support our new allies.\n\nJoin one of their hunters and aid them in their tasks, we will remain here and discuss our next move.", objectives = "Support your allies in Nazjatar by getting one to rank 3.", completion = "Excellent work. Your efforts have helped us rebuild our supplies and gained our friends some much-needed combat experience.\n\nThey have entrusted us with this item, which appears to be quite magical. I cannot harness the power, but perhaps your Heart of Azeroth can. Take it, may it do us some good in this strange place." }
WordHunterWoW_QuestEN[56236] = { title = "Down But Not Out", description = "Ashvane won't trouble us for now, but our situation remains perilous.\n\nI must consider our next move, {name}. In the meantime we should continue to build upon our relationship with our new allies, the Unshackled. Test them in combat, train them while you can, we will need their aid in the battles to come.\n\nWe will show them that through unity there are no obstacles that can stand in our way.", objectives = "Support your allies in Nazjatar by gaining 2400 experience combined between Vim Brineheart, Poen Gillbrack, and Neri Sharpfin.", completion = "Good work, while you were gone I was able to make some progress in locating our next objective." }
WordHunterWoW_QuestEN[56239] = { title = "Strange Silver Knife", description = "<This silver knife is small and lightly decorated, you found it inside of a chest. \n\nIt was more likely used for eating or preparing food than combat. What would the naga need with such a thing?\n\nOne of the Ankoan may know more...>", objectives = "Ask the Ankoan about the knife.\n\nProvided item:", completion = "What do you have there?\n\nAh, yes, you found this within one of the chests? We have found similar things inside of them -- finery, decorative platters, and the like. Perhaps they do not belong to the naga? It is a mystery." }
WordHunterWoW_QuestEN[56240] = { title = "Strange Silver Knife", description = "<This silver knife is small and lightly decorated, you found it inside of a chest. \n\nIt was more likely used for eating or preparing food than combat. What would the naga need with such a thing?\n\nOne of the Unshackled may know more...>", objectives = "Ask the Unshackled about the knife.\n\nProvided item:", completion = "Ay, what's that? \n\nAh yeah, lots of nice things to be found in those chests out there. Don't seem to be naga things, mind you, and that's kind of strange. Someone else left those here.\n\nHappy to take that off of your hands, though." }
WordHunterWoW_QuestEN[56241] = { title = "Preserved Clues", description = "We have found similar chests, as you describe. We believe they were left behind by one that came before the naga.\n\nSome are even locked by odd arcane runes, the naga seem most interested in those.\n\nI know little about them, save that we find them most often in the city ruins.\n\nIf you seek to decipher their history, I would begin there.", objectives = "Search in Zin-Azshari for information about the strange arcane chests.", completion = "<A simple tome with a small series of runes inscribed along the spine, it appears remarkably well-maintained amongst the ruins. \n\nUpon further inspection, it appears to be a diary of one of the citizens of the city. No doubt the magic that preserves it was intended to allot for the lengthy lifetimes of the elves.>" }
WordHunterWoW_QuestEN[56242] = { title = "Preserved Clues", description = "If you find anything else in those chests that you don't need, you feel free to bring it on over my way.\n\nFound a few of them myself. Don't look like they belong to the naga, probably someone that lived in the city.\n\nSome are locked tight by arcane magic, seen the naga taking those back with them. Probably got the good stuff in there.\n\nI don't know much more than that. If you want a history lesson, I'd snoop around the city ruins.", objectives = "Search in Zin-Azshari for information about the strange arcane chests.", completion = "<A simple tome with a small series of runes inscribed along the spine, it appears remarkably well-maintained amongst the ruins. \n\nUpon further inspection, it appears to be a diary of one of the citizens of the city. No doubt the magic that preserves it was intended to allot for the lengthy lifetimes of the elves.>" }
WordHunterWoW_QuestEN[56243] = { title = "Diaries of the Dead", description = "<The enchantments preserving this journal are intact, but fading. It appears to be the diary of a citizen of the city. You turn to a random page...>\n\nThen he had the audacity to enter our summoning circle and demand we evict his study space at once. Who willingly steps into the chaos of a summoning ritual? He is mad. We call him that now -- Mad Mardivas.\n\nOf course, he was bitten on the leg by a lesser summon, and...\n\n<It continues -- not useful, but you surmise there may be more such tomes.>", objectives = "Search Zin-Azshari in Nazjatar for additional diaries.", progress = "<A preserved tome.>", completion = "<You see a glowing lock, and Mardivas' journal is next to it. You glance at the final pages.>\n\nThe rune locks have been stabilized, and organized in such a way that only one with my level of logical acumen would be able to decipher.\n\nOh, to see the faces of the would-be thieves, thwarted! \n\nYes, yes, yes that is it! I shall work on a ward that allows me to view the thieves in the act! Genius, genius, I am.\n\nI simply need a bit more time..." }
WordHunterWoW_QuestEN[56244] = { title = "Diaries of the Dead", description = "<The enchantments preserving this journal are intact, but fading. It appears to be the diary of a citizen of the city. You turn to a random page...>\n\nThen he had the audacity to enter our summoning circle and demand we evict his study space at once. Who willingly steps into the chaos of a summoning ritual? He is mad. We call him that now -- Mad Mardivas.\n\nOf course, he was bitten on the leg by a lesser summon, and...\n\n<It continues -- not useful, but you surmise there may be more such tomes.>", objectives = "Search Zin-Azshari in Nazjatar for additional diaries.", progress = "<A preserved tome.>", completion = "<You see a glowing lock, and Mardivas' journal is next to it. You glance at the final pages.>\n\nThe rune locks have been stabilized, and organized in such a way that only one with my level of logical acumen would be able to decipher.\n\nOh, to see the faces of the would-be thieves, thwarted! \n\nYes, yes, yes that is it! I shall work on a ward that allows me to view the thieves in the act! Genius, genius, I am.\n\nI simply need a bit more time..." }
WordHunterWoW_QuestEN[56245] = { title = "Enchanted Lock", description = "<The lock appears to be secured by a magical mechanism.\n\nIt is clearly one of Mardivas', and from what you can surmise from reading the journals, it is likely locked via an arcane puzzle.\n\nYou look around the room, and see something odd in the water.>", objectives = "Solve Mardivas' arcane puzzle to unlock the enchanted lock.", progress = "<The lock hums.>", completion = "<With the puzzle complete, the lock springs open with a satisfying click.\n\nIt seems that Mardivas' devised a series of similar such puzzles with which to secure his belongings.>" }
WordHunterWoW_QuestEN[56246] = { title = "Enchanted Lock", description = "<The lock appears to be secured by a magical mechanism.\n\nIt is clearly one of Mardivas', and from what you can surmise from reading the journals, it is likely locked via an arcane puzzle.\n\nYou look around the room, and see something odd in the water.>", objectives = "Solve Mardivas' arcane puzzle to unlock the enchanted lock.", progress = "<The lock hums.>", completion = "<With the puzzle complete, the lock springs open with a satisfying click.\n\nIt seems that Mardivas' devised a series of similar such puzzles with which to secure his belongings.>" }
WordHunterWoW_QuestEN[56247] = { title = "Treasure Tale", description = "<You discovered the history of Mardivas, a sorcerer that once lived in the city and the crafter of the arcane chests scattered around Nazjatar.\n\nFrom the sounds of it, he was not well-liked, which worked out for him, as he did not much like others.\n\nYou also found and unlocked one of his \"unsolvable\" arcane locks. This knowledge may prove useful on your journey.\n\nArtisan Itanu will surely enjoy hearing the end of this tale.>", objectives = "Return to Artisan Itanu in Nazjatar.", completion = "Ah, how nice to see a proper end to the tale, thank you.\n\nI had always wondered why one would lock up one's dinnerware. If one does not much like or trust others, it becomes more obvious.\n\nDespite all of his efforts, they will end up in your hands, in the end. How droll." }
WordHunterWoW_QuestEN[56248] = { title = "Treasure Tale", description = "<You discovered the history of Mardivas, a sorcerer that once lived in the city and the crafter of the arcane chests scattered around Nazjatar.\n\nFrom the sounds of it, he was not well-liked, which worked out for him, as he did not much like others.\n\nYou also found and unlocked one of his \"unsolvable\" arcane locks. This knowledge may prove useful on your journey.\n\nFinder Palta will surely enjoy hearing the end of this tale.>", objectives = "Return to Finder Palta in Newhome in Nazjatar.", completion = "Hey, thanks for letting me know. Always wondered what was going on with those chests. \n\nNot that I mind free treasures, mind you. All for them.\n\nI'm sure it'd just steam his clams to know that you're going to end up with all of his stuff, ha!" }
WordHunterWoW_QuestEN[56249] = { title = "I Am the Trashmaster", description = "Whatcha got there, richmon? \n\nHa! You think you be de Trashmasta? You be talkin' to de God of Garbage! De Ruler of Rubbish! Master of all things Discarded an' Unwanted!\n\nSo you not be wantin' that ol' trashy cloak, eh? Jani got somethin' better. \n\nYou just give dat ol' thing to me, an Jani will be takin' care o' you...", objectives = "Give Jani the Trashmaster's Mantle.", completion = "Hek hek hek. Thanks for de trade, richmon.\n\nI not be wantin' this thing. It be too stuffy, too high-an-mighty. Not worthy of Jani! But you can have it.\n\nNow be gone. I got offerins' to sort." }
WordHunterWoW_QuestEN[56250] = { title = "I Am the Trashmaster", description = "Whatcha got there, richmon? \n\nHa! You think you be de Trashmasta? You be talkin' to de God of Garbage! De Ruler of Rubbish! Master of all things Discarded an' Unwanted!\n\nSo you not be wantin' that ol' trashy cloak, eh? Jani got somethin' better. \n\nYou just give dat ol' thing to me, an Jani will be takin' care o' you...", objectives = "Give Jani the Trashmaster's Mantle.", completion = "Hek hek hek. Thanks for de trade, richmon.\n\nI not be wantin' this thing. It be too stuffy, too high-an-mighty. Not worthy of Jani! But you can have it.\n\nNow be gone. I got offerins' to sort." }
WordHunterWoW_QuestEN[56256] = { title = "The Battle of Alterac", description = "The Explorers' League believes there are artifacts in Alterac Valley, but the Frostwolf orcs won't let us explore.  We can't allow the Horde to stop our scholarly pursuits!  Defeat the Frostwolf general, Drek'Thar.  With him dead, the orcs will lose their edge.\n\nDrek'Thar is in Frostwolf Keep, in the south of Alterac Valley.  Vanquish him, and then return to me.", objectives = "Enter Alterac Valley, defeat the Horde general Drek'thar.", completion = "Well done, <name>!  With the Horde's nose bloodied after the death of their general, we'll have the breathing room we need to explore!" }
WordHunterWoW_QuestEN[56257] = { title = "The Battle for Alterac", description = "The Stormpike dwarves and their allies have invaded Alterac Valley, and we must drive them out!  To win the battle for Alterac, we must defeat their general, Vanndar Stormpike!\n\nYou will find Vanndar in Dun Baldar, in the north of Alterac Valley.\n\nDestroy him, {name}, and then return to me.", objectives = "Enter Alterac Valley and defeat the dwarven general, Vanndar Stormpike.", completion = "Well done, <name>!  Stormpikes have no hope in this foolish invasion.\n\nHah!  So far, all they've done is get their general killed!" }
WordHunterWoW_QuestEN[56258] = { title = "Ivus the Forest Lord", description = "The Frostwolf Clan is protected by a taint of elemental energy. Their shaman meddle in powers that will surely destroy us all if left unchecked.\n\nThe damage has grown too great for the Circle to control! Ivus must be called to our aid.\n\nThe Frostwolf soldiers carry elemental charms called storm crystals. We can use the charms to conjure Ivus. Venture forth and claim the crystals, {name}!", objectives = "Slay Horde and loot a Storm Crystal and return it to Archdruid Renferal in Alterac Valley.", progress = "Have you brought us some crystals, <name>?", completion = "Well done, <name>. I will use the power of this charm to augment the magic that has already been gathered. When enough power has been amassed, I shall focus the collected energies and call upon the Forest Lord to aid our cause." }
WordHunterWoW_QuestEN[56259] = { title = "Lokholar the Ice Lord", description = "I come from Thunder Bluff, {race}. Cairne himself has seen to it that I assist the Frostwolf Clan in these dire times.\n\nBut let us not waste any more time. You must strike down our enemies and bring to me their blood. Once enough blood has been gathered, the ritual of summoning may begin.\n\nVictory will be assured when the elemental lord is loosed upon the Stormpike army.", objectives = "Slay Alliance and loot Stormpike Blood and return it to Primalist Thurloga within Frostwolf Village in Alterac Valley.", progress = "Have you come with an offering?", completion = "The blood of our enemies has been shed. I shall mix this blood with the rest that has been gathered. Once the offering is complete, the Ice Lord shall show these Stormpike dogs the full wrath of the Frostwolf Clan!" }
WordHunterWoW_QuestEN[56260] = { title = "Unlocking the Power", description = "There's somethin' special waitin' fer ye back in the Chamber of Heart, champion.\n\nI won't spoil it, but ye best get back there as quick as ye can.", objectives = "Return to the Chamber of Heart.", completion = "Have we got somethin' fer ye, champion! Yer gonna love this." }
WordHunterWoW_QuestEN[56261] = { title = "Return to the Heart", description = "Greetings, Champion of Azeroth.\n\nMOTHER's been monitorin' yer progress with the Heart of Azeroth, and is mighty pleased with the work you've done tae make it stronger.\n\nAt least, we think she's pleased. It's difficult tae tell at times.\n\nRegardless, come back tae the Chamber of Heart when ye've got a chance. There's more that needs doin'.", objectives = "Return to the Chamber of Heart.", completion = "The Heart o' Azeroth feels stronger than ever. I wonder what amazing powers might be locked within!" }
WordHunterWoW_QuestEN[56262] = { title = "Back to the Chamber", description = "The Heart o' Azeroth is gettin' stronger every day, and it's makin' a difference.\n\nMake yer way tae the Chamber o' Heart, champion. Yer talents are needed.", objectives = "Return to the Chamber of Heart.", completion = "The Heart o' Azeroth never ceases tae amaze me. Well done, champion!" }
WordHunterWoW_QuestEN[56263] = { title = "Unlocking the Power", description = "There's somethin' special waitin' fer ye back in the Chamber of Heart, champion.\n\nI won't spoil it, but ye best get back there as quick as ye can.", objectives = "Return to the Chamber of Heart.", completion = "Have we got somethin' fer ye, champion! Yer gonna love this." }
WordHunterWoW_QuestEN[56264] = { title = "We've Got Crabs!", description = "{name}, you're just in time. Everything's ready for the crab hunt!\n\nOkay, okay... I know what you're thinking. A founding member of D.E.H.T.A. that condones hunting?\n\nI'm going to level with you, {name}. I've got a bar full of hungry murlocs that only eat three things: crabs, fish, and people.\n\nIf that's not reason enough, crabs are overpopulated in this region and they're decimating the local grub worm population!\n\nHow many innocent grub worms need to die before we do something, {name}?", objectives = "Collect 12 Crackleclaw Crabs.", progress = "How many innocent grub worms need to die before we do something, <name>?", completion = "That's quite the case of crabs you've got there, <name>. Well done! Please set it down behind the bar and I'll take care of the rest." }
WordHunterWoW_QuestEN[56265] = { title = "Drunk Angry Murlocs", description = "Those no-good Bloodfins ran off with all of the beer!\n\nI've been experimenting with brews that only use ingredients native to Nazjatar, but it's still a work in progress. For now, I must rely on whatever I can scrounge up from the shipwreck.\n\nMy supply of beer was already limited, but now it's all gone thanks to those thieving Bloodfin murlocs! We're going to have some very angry customers here if we don't get it back.\n\nPlease recover the stolen lager from Bloodfin Village before it's too late!", objectives = "Collect 12 Ocean \"Infused\" Lagers.", progress = "Please tell me you found the beer.", completion = "Good work, <name>! You've recovered pretty much all of the stolen beer. Those Bloodfins are more trouble than they're worth!" }
WordHunterWoW_QuestEN[56266] = { title = "Mgglurky's Mugglrgl", description = "My cook, Mgglurky, lost his mugglrgl and he's refusing to work until he gets it back.\n\nI've got a bar full of hungry murlocs and nothing to feed them until Mgglurky starts cooking. If Mgglurky doesn't find his mugglrgl soon, we're going to have a riot on our hands!\n\nI don't know about you, but I definitely don't want to be the main course tonight.\n\nThere were some Bloodfins lurking around earlier. Search Bloodfin Village for the mugglrgl and bring it back to me once you find it.", objectives = "Retrieve Mgglurky's Mugglrgl from Bloodfin Village.", progress = "If Mgglurky doesn't find his mugglrgl soon, we're going to have a riot on our hands!", completion = "You've found it! So this is a mugglrgl? For some reason I thought it would be bigger. Mgglurky will be happy you returned it!" }
WordHunterWoW_QuestEN[56267] = { title = "Whispers of N'Zoth", description = "Are you curious how I came to be here, in the Chamber of Heart? \n\nOf course I arrived of my own volition, but there was quite a search for me, for a time.\n\nKalecgos remembers how it went. Speak to him, if you wish to relive the details of how I thwarted discovery by both Speaker and Old God.", objectives = "Speak to Kalecgos in the Chamber of Heart.", completion = "I knew that N'Zoth was powerful, but to reach Ebonhorn in the safety of the Chamber... \n\nWe have to do something about this. None of us are safe." }
WordHunterWoW_QuestEN[56301] = { title = "Go For The Gold", description = "I've heard lot's of stories about dead fathers, mothers, and family treasures. Don't believe any of it. We're all here to get any pirate gold, before these mecha-fools get it first! \n\nIf there's gold to be had here, it's in that fat chest the murlocs are guarding.\n\nKill their chief, empty out the chest, and we'll split it fifty-fifty, since I'm telling ya about it.", objectives = "Recover the Murloc Treasure Bag.", progress = "Go get the gold!", completion = "Nice working with ya, here's your share!" }
WordHunterWoW_QuestEN[56304] = { title = "The High Life", description = "You there, I require some help.\n\nEveryone where I once called home lost their lives to the flood. I still don't know what became of my father, Corin. \n\nIt pains me to return to the estates, and there are vengeful spirits who haunt the once pristine grounds. Will you help me find out what happened to my father?", objectives = "Accompany Kelya Moonfall into the Highborne Estates to search for the spirit of her father.", completion = "<name>, Corin is being tormented by that naga shadowcaster. \n\nWe have to do something!" }
WordHunterWoW_QuestEN[56305] = { title = "Let's Fish!", description = "We may need the help of some friends to land this fish!\n\nUse the Hundred-Fathom Lure when you're ready to start.", objectives = "Catch and kill the Deepwater Maw.", progress = "Let's fish!", completion = "This will make a great fish story!" }
WordHunterWoW_QuestEN[56306] = { title = "The Family Jewels", description = "Darn pirates stole my jewels... err, I mean my sister's... uh, mom's jewelry. Yeah, that's the story!\n\nPoint is, they stole it, and it's all out there strewn around in the mud, and treasure chests. Maybe on a few of the robots and murlocs.\n\nMy mom's not greedy, she just wants a few of the necklaces with gold and lots of diamonds. I'd pay ya for those.", objectives = "Recover 75 Family Jewels", progress = "Go steal those jewels back for my brother!", completion = "All these jewels for me!" }
WordHunterWoW_QuestEN[56308] = { title = "Assault: Aqir Unearthed", description = "Our position is being overrun. The aqir are surging in greater numbers than I've ever seen!\n\nI'm not sure how long we'll be able to hold the line. We need you to drive them back!", objectives = "Drive back the Aqir Assault in Uldum.", progress = "Our men can only hold out so long.", completion = "You have saved our camp, and quite possibly our people.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[56309] = { title = "City of Drowned Friends", description = "Champion, I have a personal favor to ask of you that I do not feel I can ask of any of my sentinels.\n\nThis... this is not on behalf of the Alliance, or the war, or even our battle against Azshara. This is a favor for me.\n\nWhen I was a little girl, my city was attacked by the Legion. Many of the survivors fled here only to drown or worse. I must know their fate.\n\nWill you help me search for signs?", objectives = "Help Shandris Feathermoon search the Drowned Market.", completion = "He... he may be here. Janius... no." }
WordHunterWoW_QuestEN[56310] = { title = "City of Drowned Friends", description = "Champion, I have a personal favor to ask of you. This is not on behalf of the Horde or the war effort.\n\nIt has been over ten thousand years since I last walked these streets. I knew many of these people, even trained some of them.\n\nWill you walk with me as I learn their fates? The road is dangerous, and I do not trust myself to maintain calm as I try to resurface old grief.", objectives = "Help First Arcanist Thalyssra search the Drowned Market.", completion = "Sivara. Oh Sivara. She was the finest pupil I ever taught. I must find her and ensure she is not locked in eternal torment like these others." }
WordHunterWoW_QuestEN[56311] = { title = "The Ever Drowning", description = "Stay close, Champion. I have some magical items that might help us defend briefly against magic attacks, but Azshara was the greatest mage our kind has ever known.\n\nI do not feel confident that these trinkets will hold back her power for long, or even be usable afterward.\n\nSpeak with me when you are ready.", objectives = "Escort Shandris Feathermoon through the Drowned Market.", completion = "The flood has stopped for now. That is good because I do not think I have enough charge left in these items to shield us from another wave like that." }
WordHunterWoW_QuestEN[56312] = { title = "The Ever Drowning", description = "Queen Azshara has her eye on us now. We must proceed with caution.\n\nI do not know what she may try but stay close to me. Whatever this threat is we must pass through it if we are to find Sivara.\n\nSpeak with me when you are ready to proceed.", objectives = "Escort First Arcanist Thalyssra through the Drowned Market.", completion = "The flood has stopped for now. That is good because my power is nearly drained." }
WordHunterWoW_QuestEN[56313] = { title = "The Warbringer", description = "We are standing in the center of some very powerful magics. An echo of something Azshara did long ago.\n\nIf you are feeling brave enough to commune with this echo, I will stand guard as you do.", objectives = "Commune with the Memory of the Pact.", progress = "Be ready for anything.", completion = "We long suspected Azshara's choice. The question becomes, why is she showing us this? What game is she playing this time?" }
WordHunterWoW_QuestEN[56314] = { title = "The Warbringer", description = "We are standing in the center of some very powerful magics. An echo of something Azshara did long ago.\n\nIf you are feeling brave enough to commune with this echo, I will stand guard as you do.", objectives = "Commune with the Memory of the Pact.", progress = "Be ready for anything.", completion = "We long suspected Azshara's choice. The question becomes, why is she showing us this? What game is she playing this time?" }
WordHunterWoW_QuestEN[56315] = { title = "They Made Their Choice", description = "It wasn't enough for Azshara to break the world. She had to doom the rest of our people here as well!\n\nThose who didn't choose to become naga were stuck in this horrifying half death, left to haunt these drowned ruins. \n\nI am almost afraid of what we will find if we do find my friend.\n\nWait, did you hear something?", objectives = "Aid Shandris Feathermoon.", progress = "Thrice damned Azshara. Her evil knows no bounds.", completion = "I cannot thank you enough for helping me say farewell to my friend, <name>. I am in your debt." }
WordHunterWoW_QuestEN[56316] = { title = "They Made Their Choice", description = "It wasn't enough for Azshara to break the world. She had to doom the rest of our people here as well!\n\nThose who didn't choose to become naga were stuck in this horrifying half death, left to haunt these drowned ruins. \n\nI am almost afraid to find Sivara.\n\nWait, did you hear something?", objectives = "Aid First Arcanist Thalyssra.", progress = "Thrice damned Azshara. Her evil knows no bounds.", completion = "Sivara could have defeated us at any time. Why are they toying with us? \n\nAt any rate, champion, again I find myself in your debt. Thank you for helping me, even if the answers we found were more horrifying than I could have anticipated." }
WordHunterWoW_QuestEN[56319] = { title = "The Quickcharge Contract", description = "Wondrous news, dear test subject!\n\nMy dear brother and I have restored 65% of the functionality of our research laboratory.\n\nWe are hoping to resume our regular research schedule shortly, but require a fresh batch of brave test subjects to help us push the laws of nature and science to their limits!\n\nIf you're interested, you'll just need to agree to our standard verbal contract first...", objectives = "Agree to the Quickcharge Contract.", progress = "How can I help you, dear test subject?", completion = "Welcome to the Quickcharge team, dear test subject.\n\nWhat a wondrous day this is!" }
WordHunterWoW_QuestEN[56320] = { title = "Your First Charge is Free!", description = "Do you feel the energy rippling through the ground here, my dear test subject?\n\n<Flip inhales deeply.>\n\nWithout that constant bristle of electricity, nothing of any meaning would exist.\n\nMy dear sister and I have tapped into a high-voltage power line buried here, but the real juice is over in Bondo's Yard. He selfishly hoards access to the heftiest power line in Mechagon!\n\nIf you want to recharge your empty energy cells, you're going to have to get access to the Charging Station from Flux.", objectives = "Gain access to the Charging Station in Bondo's Yard, then use it to charge an Empty Energy Cell.", completion = "Flux is rude, crude, and I suspect more than a little unglued.\n\nBe careful with that wondrous energy cell. Those little packs of power are worth their weight in gold out here in Mechagon!" }
WordHunterWoW_QuestEN[56321] = { title = "Saving Corin", description = "My father is being tortured by that naga!\n\n{name}, I need you to help me save him. We can't let his spirit be a slave to the naga. \n\nHurry, if we don't act now he will end up like the rest of them!", objectives = "Defeat Shadowcaster Vixtris.", completion = "Thank you, <name>. My father and I are eternally grateful for what you did." }
WordHunterWoW_QuestEN[56322] = { title = "Contained Alemental", description = "<As the brew is returned to its natural, dormant form, a strange keg appears.\n\nPerhaps Brewmaster Tsing knows more about such a strange occurrence.>", objectives = "Talk to Brewmaster Tsing in the Brewfest grounds.", completion = "Everything has a spirit to it. From the clouds in the sky to the worms in the ground, life is woven through the entire world.\n\nBrew is no different. Created with such love, such care... it only requires a spark to spring to life in front of our very eyes." }
WordHunterWoW_QuestEN[56324] = { title = "Your First Charge Ain't Free!", description = "You lookin' to charge some energy cells off of our tower of power?\n\nI ain't surprised - everyone is.\n\nAnd everyone PAYS. You got that or I got ta say it again?\n\n<Flux spits behind her.>\n\nI can tell you're a first-timer. Bondo's got a special deal for you flashfoots.\n\nSmall access fee, one charge only.\n\nDeal? You ain't gettin' any other offers.", objectives = "Pay Flux's access fee, then use the Charging Station to charge an Empty Energy Cell.", progress = "You lookin' to charge some energy cells off of our tower of power?\n\nI ain't surprised - everyone is.\n\nAnd everyone PAYS. You got that or I got ta say it again?\n\n<Flux spits over her shoulder.>\n\nI can tell you're a first-timer. Bondo's got a special deal for you flashfoots.\n\nSmall access fee, one charge only.\n\nYou ain't gettin' any other offers.", completion = "You're authorized for one charge.\n\nHold up your empty energy cell to the Charging Station to proceed.\n\nNo double-charging. I've got my eyes on you." }
WordHunterWoW_QuestEN[56325] = { title = "Changing Tides", description = "We are out of time. We must gain control the Tidestone of Golganneth and the Javelin is our best shot at piercing the barrier surrounding it.\n\nThe guardian is formidable, but must be defeated if we are to take the fight to Azshara. What forces we have will be arrayed below, just outside their encampment.\n\nI would trust you with the Javelin of Suramar, {name}. We will need your strength in the coming battle.", objectives = "Assault the naga camp and seize control of the Tidestone of Golganneth.", progress = "If we do not take the Tidestone, we are finished.", completion = "Quickly, the Tidestone!" }
WordHunterWoW_QuestEN[56326] = { title = "Ravenous Rescue", description = "A conspiracy of ravens is preying on citizens of Rustbolt! It's most unacceptable! \n\nPrince Erazmin has asked me to rescue as many citizens as I can, but I could use your help. I've tracked the ravens to this hill. We blast the ravens out of the sky, and you rescue the mechagnomes.\n\nUse my marker gun if you need help bringing the ravens down.", objectives = "Rescue 8 injured mechagnomes.", progress = "Let's get to it!", completion = "You've lived up to your reputation." }
WordHunterWoW_QuestEN[56327] = { title = "Chopped Bots", description = "Chopping up bots is my business. Any bots you bring to my scrapper will be broken up into useful parts. It's a win for both of us!\n\nUse the Bot-Energizer to bring me dead bots, and we'll break them into spare parts.", objectives = "12 Re-animated bots delivered to Bolten Springspark.", progress = "Re-animate dead bots and bring them to me!", completion = "I love those spare parts! You're can grind up bots here anytime you want!" }
WordHunterWoW_QuestEN[56328] = { title = "Do Not Drink", description = "These troggs watch everything we do.  \n\nThey see us pouring oil into various machines, so now they're stealing the oil and drinking it. I think they believe it's going to turn them into machines!\n\nWe need that oil back, before they drink it all!", objectives = "Recover 12 containers of Stolen Oil.", progress = "Get that oil back quick!", completion = "Ya done good work." }
WordHunterWoW_QuestEN[56334] = { title = "Bots Gone Wild", description = "It's loose up there!\n\nI told them not to do it, but they didn't listen. Now it's gone out of control and killed everyone up there. It's an experimental Whirlbot. They never should have built it!\n\nYou need to stop it before it comes down here looking for more victims!\n\nKill the Whirling Zap-O-Matic.", objectives = "Whirling Zap-O-Matic slain", progress = "You need to stop it.", completion = "You performed better than those that build the bot." }
WordHunterWoW_QuestEN[56335] = { title = "Wanna Charge? Gotta Pay!", description = "You lookin' to charge some energy cells off of our tower of power?\n\nI ain't surprised - everyone is.\n\nAnd everyone PAYS. You got that or I got ta say it again?\n\n<Flux spits behind her.>\n\nI can tell you're a first-timer. Bondo's got a special deal for you flashfoots.\n\nSmall access fee, one charge only.\n\nDeal? You ain't gettin' any other offers.", objectives = "Pay Flux's access fee, then use the Charging Station to charge an Empty Energy Cell.", progress = "You lookin' to charge some energy cells off our tower of power?\n\nSave your sob stories. Everyone pays.\n\n<Flux spits over her shoulder.>\n\nNo exceptions.", completion = "Limited access granted.\n\nCharge whatever you want. Don't break anything.\n\n<Flux spits over her shoulder.>\n\nMost importantly, mind your own damn business." }
WordHunterWoW_QuestEN[56336] = { title = "Uncovering the Artifact Fragments", description = "The Artifact Fragments seem to come from any creature we've found in the outskirts of Ashran. Go out and kill any you find and bring at least fifty to Ecilam the Mage near the campfire in Stormshield Stronghold.", objectives = "Ecilam in Stormshield Stronghold wants you to go kill creatures in the outskirts of Ashran outside of the main road and bring back 50 Artifact Fragments.", progress = "Are those Artifact Fragments, I see?", completion = "Good work. If you happen to find anymore Artifact Fragments, bring them to me or the others in need of them to contribute to the war effort." }
WordHunterWoW_QuestEN[56337] = { title = "Uncovering the Artifact Fragments", description = "The Artifact Fragments seem to come from any creature we've found in the outskirts of Ashran.\n\nGo out and kill any you find and bring at least fifty Artifact Fragments to Fura the Mage in Warspear Outpost.", objectives = "Fura in Warspear Outpost wants you to go kill creatures in the outskirts of Ashran outside of the main road and bring back 50 Artifact Fragments.", progress = "Are those Artifact Fragments, I see?", completion = "Good work. If you happen to find anymore Artifact Fragments, bring them to me or the others in need of them to contribute to the war effort." }
WordHunterWoW_QuestEN[56338] = { title = "Volrath Must Die", description = "The Horde are getting in our way of completing our mission here in Ashran. Their leader is High Warlord Volrath. He must be put down.\n\nPush forth through the center road, enter Warspear and slay Volrath.", objectives = "Slay High Warlord Volrath found in the Horde base Warspear within Ashran.", completion = "Well done. That will give the Horde something to think about next time they decide to test us here in Ashran." }
WordHunterWoW_QuestEN[56339] = { title = "Tremblade Must Die", description = "This battle in Ashran has waged on long enough. It appears they're being led by Grand Marshal Tremblade. If she falls, the Alliance will crumble.\n\nPush forward through the center road, make your way into their keep and take down Tremblade.\n\nFor the Horde!", objectives = "Slay Grand Marshal Tremblade found in the Alliance base Stormshield Keep within Ashran.", completion = "That's what I like to see, good work <class>." }
WordHunterWoW_QuestEN[56341] = { title = "Direbrew Cog", description = "<Direbrew's Dark Iron have fled, leaving behind a small piece of one of their mole machines.\n\nPerhaps your Dark Iron allies would be interested in hearing of your victory.>", objectives = "Talk to Verra Fireblood in the Brewfest grounds.", completion = "<Verra spits on the cog.>\n\nThat Direbrew is a piece o' work. He's been a contrarian since before we even joined the Alliance. I'm not surprised he's still attackin'. \n\nAll he thinks about is brew and causin' chaos! Not to say that I don' love those things too, but there are other things in life!\n\nThanks for takin' care o' him." }
WordHunterWoW_QuestEN[56344] = { title = "To Darkmaul Citadel", description = "We've rescued everyone except for the expedition's captain. Lindie's Scout-o-Matic spotted her just outside Darkmaul Citadel.\n\nMeredy has come up with an... interesting plan to rescue the captain. It may be our only chance.\n\nCome. We'll convene in the shadow of Darkmaul Citadel, and there we will begin our rescue mission.", objectives = "Meet Lady Jaina Proudmoore outside of Darkmaul Citadel.", completion = "All right, <name>. I hope you're a good actor, because you're about to play to a very tough crowd." }
WordHunterWoW_QuestEN[56346] = { title = "Ancient Technology", description = "<Given the experience you've had with the naga and the power they wield, you wonder if using their own power against them might not garner you a powerful advantage.\n\nPerhaps Instructor Ulooaka back at Mezzamere could help you repair this core and put it to use against the naga invasion.>", objectives = "Bring the Broken Power Core to Instructor Ulooaka in Mezzamere.\n\nProvided item:", completion = "What's this you've brought me?\n\n<Instructor Ulooaka looks over the broken power core and arcs an eyebrow. You ask him if he thinks it could be used against the naga.>\n\nActually, I believe it could. But probably not in the way you think." }
WordHunterWoW_QuestEN[56347] = { title = "An Abyssal Opportunity", description = "I believe, {name}, we can use this thing to make our armor stronger. By redirecting its power, we can take the strength of our crafts to a new level.\n\nBut we're getting ahead of ourselves. The first thing we need to do is repair this device.\n\nIt'll require some powerful materials to fix it, and those are usually carried by the stronger creatures of this region.\n\nHowever, Artisan Okata is great at collecting materials like the ones we need. I'd check with him to see what he's got.", objectives = "Acquire 15 Abyssal Shards from Artisan Okata.", progress = "How goes the hunt for the materials?", completion = "This should be plenty, <name>. I'll get started on repairing it right away." }
WordHunterWoW_QuestEN[56348] = { title = "The Eternal Palace: We Can Make It Stronger...", description = "Now that it's functioning, it occurred to me while repairing it that it has the capability to output even more energy.\n\nOf course that will require stronger materials to upgrade and the only place I can think of is in the Eternal Palace.\n\nAzshara's army and even herself carry items of extraordinary power. If you could bring some of those back, I could at the very least test my theory and see if it's viable.", objectives = "Collect 20 Eternal Ornaments from the most powerful creatures of the Eternal Palace.", progress = "How goes the search for those items?", completion = "Yes, these will do nicely. Good work, <name>.\n\nI'll get started right away on upgrading the core." }
WordHunterWoW_QuestEN[56349] = { title = "The Eternal Palace: Pushing the Limits", description = "Now that we know how to increase the potency of this tool, I think we can push its capabilities even further.\n\nBring me back more of those ornaments. LOTS of them.\n\nLet's see just how far we can make this go.", objectives = "Collect 200 Eternal Ornaments from the most powerful creatures of the Eternal Palace.", progress = "Any luck on retrieving more of those ornaments?", completion = "Wow, that's...a lot!\n\nAlright, let's see what this thing can do." }
WordHunterWoW_QuestEN[56350] = { title = "Scouting the Palace", description = "We cannot hide here forever, {name}. Azshara must be dealt with.\n\nIt would be an act of folly to assault her palace without knowing what defenses she has in place. I dispatched a scouting team while you were gone, but they have not reported back.\n\nI'm getting concerned, {name}. Let me know when you're ready and I'll perform a ritual to see what has happened to our scouts.", objectives = "Speak with Lady Jaina Proudmoore to observe the scouting party.", progress = "Are you ready?", completion = "The Tidestone! Of course..." }
WordHunterWoW_QuestEN[56351] = { title = "The Eternal Palace: Pushing the Limits", description = "Now that we know how to increase the potency of this thing, I think we can push its capabilities even further.\n\nBring me back more of those ornaments. LOTS of them.\n\nLet's see just how far we can make this go.", objectives = "Collect 200 Eternal Ornaments from the most powerful creatures of the Eternal Palace.", progress = "Any luck on retrieving more of those ornaments?", completion = "Wow, that's...a lot!\n\nAlright, let's see what this thing can do." }
WordHunterWoW_QuestEN[56352] = { title = "The Eternal Palace: We Can Make It Stronger...", description = "Now that it's functioning, it occurred to me while repairing it that it has the capability to output even more energy.\n\nOf course that'll require stronger materials to upgrade and the only place I can think of is in the Eternal Palace.\n\nAzshara's army and even herself carry items of extraordinary power. If you could bring some of those back, I could at the very least test my theory and see if it's viable.", objectives = "Collect 20 Eternal Ornaments from the most powerful creatures of the Eternal Palace.", progress = "How goes the search for those items?", completion = "Yes, these'll do nicely. Good work, <name>.\n\nI'll get started right away on upgrading the core." }
WordHunterWoW_QuestEN[56353] = { title = "An Abyssal Opportunity", description = "I believe, {name}, we can use this thing to make our armor stronger. By redirecting its power, we can take the strength of our crafts to a new level.\n\nBut we're getting ahead of ourselves. The first thing we need to do is repair this device.\n\nIt'll require some powerful materials to fix it, and those are usually carried by the stronger creatures of this region.\n\nHowever, Finder Pruc is great at collecting materials like the ones we need. I'd check with him to see what he's got.", objectives = "Acquire 15 Abyssal Shards from Finder Pruc.", progress = "How goes the hunt for the materials?", completion = "This should be plenty, <name>. I'll get started on repairing it right away." }
WordHunterWoW_QuestEN[56354] = { title = "Ancient Technology", description = "<Given the experience you've had with the naga and the power they wield, you wonder if using their own power against them might not garner you a powerful advantage.\n\nPerhaps Rolm back at Newhome could help you repair this core and put it to use against the naga invasion.>", objectives = "Bring the Broken Power Core to Rolm in Newhome.\n\nProvided item:", completion = "What's this ya brought me?\n\n<Rolm looks over the broken power core and arcs an eyebrow. You ask him if he thinks it could be used against the naga.>\n\nActually, I believe it could. But probably not in the way ya think." }
WordHunterWoW_QuestEN[56355] = { title = "Battle Tested", description = "A weapon like this could really turn the tide against King Mechagons Troops. Let's go see how their gear matches up against our new toy.\n\nTake out King Mechagon's Sentries wherever you can find them", objectives = "Eliminate 10 Upgraded, Anodized, or Corroded Sentry wherever you find them.", progress = "Go kill something!", completion = "This is what I like to see!" }
WordHunterWoW_QuestEN[56356] = { title = "The Eternal Palace: Queen's Gambit", description = "The way is clear. The palace awaits, {name}.\n\nWithin the Vainglorious holds court with an old god. Defeating her will be no small feat. \n\nMake no mistake, Azshara is one of the most powerful sorceresses alive. We cannot underestimate her power or her planning, for she has had thousands of years to prepare for us. Nevertheless, she must be defeated.\n\nWe are ready when you are. Shall we finally accept her invitation?", objectives = "Defeat Queen Azshara in the Eternal Palace.", progress = "We cannot rest easy knowing that she still holds power here.", completion = "This is only the beginning...." }
WordHunterWoW_QuestEN[56358] = { title = "The Eternal Palace: Queen's Gambit", description = "We have opened the way to the palace. We must end this.\n\nQueen Azshara is the most powerful sorceress in existence. She mastered magics thousands of years before our archmagi were even born.\n\nStill, we must prevail. If not, she and her dark patron will remake all of Azeroth to their desires.\n\nChampion, we must defeat Azshara. Are you with us?", objectives = "Defeat Queen Azshara in the Eternal Palace.", progress = "Such power, brought to ruin....", completion = "She is gone, but this is far from over." }
WordHunterWoW_QuestEN[56361] = { title = "Rustbolt Requisitions: Tidespray Linen", description = "I've received an urgent request from Tinkmaster Overspark.\n\nThese supplies are needed!", objectives = "Bring 20 Storm Silver Ore to Gila Crosswire.", progress = "I've received an urgent request from Tinkmaster Overspark.\n\nThese supplies are needed!", completion = "Thank you, <name>. Your contribution has been logged in our records for posterity to appreciate!" }
WordHunterWoW_QuestEN[56362] = { title = "Rustbolt Requisitions: Tidespray Linen", description = "Gazlowe's orders are in: He wants these supplies ASAP.\n\nYa got the goods?", objectives = "Bring 20 Storm Silver Ore to Skaggit.", progress = "Gazlowe's orders are in: He wants these supplies ASAP.\n\nYa got the goods?", completion = "Thanks for pitchin' in.\n\nI'll make sure Gazlowe and Prince Erazmin know these came from you." }
WordHunterWoW_QuestEN[56363] = { title = "Rustbolt Requisitions: Frenzied Fangtooth", description = "I've received an urgent request from Tinkmaster Overspark.\n\nThese supplies are needed!", objectives = "Bring 20 Storm Silver Ore to Gila Crosswire.", progress = "I've received an urgent request from Tinkmaster Overspark.\n\nThese supplies are needed!", completion = "Thank you, <name>. Your contribution has been logged in our records for posterity to appreciate!" }
WordHunterWoW_QuestEN[56364] = { title = "Rustbolt Requisitions: Frenzied Fangtooth", description = "Gazlowe's orders are in: He wants these supplies ASAP.\n\nYa got the goods?", objectives = "Bring 20 Storm Silver Ore to Skaggit.", progress = "Gazlowe's orders are in: He wants these supplies ASAP.\n\nYa got the goods?", completion = "Thanks for pitchin' in.\n\nI'll make sure Gazlowe and Prince Erazmin know these came from you." }
WordHunterWoW_QuestEN[56365] = { title = "Be Kind, Rewind", description = "You exist here due to a time anomaly, but you must return to your own time and help us there.\n\nThe Visual Holo Sphere from the Vaultbot nearby contains the data necessary to defeat King Mechagon before he can use the Mechoriginator.\n\nDeliver the Visual Holo Sphere to me in your reality. With luck I will be able to rewind history and prevent this existence from ever happening.", objectives = "Deliver the Visual Holo Sphere to Izira Geasworn in Rustbolt.", progress = "You will have to return to your time period.", completion = "Let's hope that you bringing me this, is not what triggers that alternate reality." }
WordHunterWoW_QuestEN[56370] = { title = "Break a Few Eggs", description = "The naga are using these caverns as a hatchery for their deadly deepcoil serpents.\n\nThese deepcoil serpents are especially dangerous because they have been infused with dark void magic.\n\nWe must put a stop to this operation before it is too late. The naga forces are already quite powerful. I do not wish to imagine what would happen if Azshara also had an army of these deepcoil serpents as well.\n\nOur only hope is to destroy the deepcoil eggs before they hatch.", objectives = "Destroy 10 Deepcoil Eggs.", progress = "Have you destroyed the deepcoil eggs?", completion = "You have done well, <name>. We cannot allow the naga to amass an army of these mutated deepcoil serpents. We will need to keep a close eye on this place..." }
WordHunterWoW_QuestEN[56371] = { title = "Young Twilight Scale", description = "<A partially-grown scale from a young twilight whelp.\n\nMore and more twilight dragons are appearing once again. This seems suspicious.\n\nYou should show the scale to Eryna above Grim Batol in the Wetlands, perhaps she has seen something recently.>", objectives = "Show the scale to Eryna above Grim Batol in the Wetlands.\n\nProvided item:", completion = "Welcome, I see you noticed the whelps. They appeared recently, along with more members of the flight coming and going from the citadel. \n\nI have indeed been observing strange happenings down below.\n\nI sense a great power has manifested. Something awakened in the depths, perhaps? One thing is certain -- the flight is mobilizing at someone's command.\n\nI will continue to relay all I find to my flight and your Speaker, thank you for your assistance." }
WordHunterWoW_QuestEN[56372] = { title = "Hozen Totem", description = "<The hozen have been successfully chased away, and Brewfest saved once again.\n\nThe question asks itself, though: How did hozen get to Dun Morogh? Perhaps you should ask somebody who has experience in navigation and travel.>", objectives = "Talk to Arcti in the Brewfest grounds.", completion = "Just because I arrived to Azeroth on a ship that flew through the stars doesn't mean that I know how... navigation works.\n\nI've never even seen a hozen, let alone one with wings!\n\nPerhaps they held hands as they flew through the sky? Your guess is as good as mine." }
WordHunterWoW_QuestEN[56373] = { title = "A Gulper Ate the Rolly", description = "The bubble-eyed rolly used to be plentiful in the nearby pond. Last week they all started to vanish!\n\nA large water elemental has been swallowing all the fish! They are still alive, just swimming around inside the elemental now.\n\nI need you to kill that elemental, and catch three bubbly-eyed rollies so I can examine their condition.", objectives = "Kill the Rolly Gulper and catch 3 Bubble-eyed Rolly.", progress = "Did you kill that elemental?", completion = "You saved a lot of Rollys today!" }
WordHunterWoW_QuestEN[56374] = { title = "A Titanic Problem", description = "We've no time tae waste. \n\nWithout the Forge of Origination, Azeroth is left vulnerable tae N'Zoth's corruption. Not tae mention it holds a weapon capable of wipin' out all life on Azeroth!\n\nWe'll need tae head over tae the forge right away. MOTHER can hold down the fort here.\n\nHurry on, I'll meet ye there.", objectives = "Meet Magni Bronzebeard at the Halls of Origination in Uldum.", completion = "Ye got here just in time, <name>.\n\nThis whole place is overrun!" }
WordHunterWoW_QuestEN[56375] = { title = "To Ramkahen", description = "It looks like we're gonna have tae wait a spell while MOTHER figures out what tae do with the forge.  In the meantime we'll want tae try to make sure nobody tries tae do any more damage here.\n\nYe should check in on the tol'vir in Ramkahen. I know ye've helped them in the past, so they might be able tae help us keep the forge out o' the wrong hands.", objectives = "Meet King Phaoris in Ramkahen.", completion = "Welcome to Uldum, <class>. \n\nI wish we could have offered you a warmer welcome, but I'm afraid my people find themselves once again in a dire situation." }
WordHunterWoW_QuestEN[56376] = { title = "Surfacing Threats", description = "The tol'vir take the protection of the titans' constructs here in Uldum as a sacred duty. However, our numbers have dwindled, and we face greater threats with each day.\n\nEven with the strength of our new allies, we will only be able to hold these enemies back for so long.  Should any of them surge in power, they may still be able to overwhelm us and endanger the forge. This is where your assistance is needed.\n\nSpeak to High Commander Kamses to assess our current situation.", objectives = "Complete an Assault in Uldum.", completion = "The threat has abated... for now.\n\nOur scouts will continue to monitor enemy movements. With any luck we should be able to keep them at bay before they can make a move on the forge.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[56377] = { title = "Forging Onward", description = "Thanks fer helpin' me back there at the forge. It's vexin' that N'Zoth was able to infiltrate it so quickly, but at least we arrived in time tae keep it from bein' completely wrecked!\n\nNow comes the task of gettin' her back tae a hundred percent. MOTHER has been workin' on a solution, and we think we've got a plan.", objectives = "Return to Magni Bronzebeard at the Chamber of Heart and learn about the fate of the Forge of Origination.", progress = "Aye?", completion = "It looks like we're in for quite an adventure, champion!" }
WordHunterWoW_QuestEN[56378] = { title = "The Missing Crew", description = "I can't believe it. Almost the entire fleet.. lost! \n\nWe need to have ships out there on missions supporting our efforts, but how am I supposed to do that now?\n\nIf we are going to recover from this, I'm going to need my top people. I know the chances are low, but I need you to get out there and try to find them. Alive if possible.", objectives = "Find and rescue the missing crew members.", completion = "Well, I suppose that's better than nothing. Let's get to work." }
WordHunterWoW_QuestEN[56379] = { title = "The Missing Crew", description = "I can't believe it. Almost the entire fleet... lost! \n\nWe need to have ships out there on missions supporting our efforts, but how am I supposed to do that now?\n\nIf we are going to recover from this, I'm going to need my top people. I know the chances are low, but I need you to get out there and try to find them. Alive if possible.", objectives = "Find and rescue the missing crew members.", completion = "Well, I suppose that's better than nothing. Let's get to work." }
WordHunterWoW_QuestEN[56380] = { title = "Grounded", description = "One of King Mechagon's older Aerial units is having mechanical problems and is grounded nearby. \n\nThey're trying to get it repaired, so we need to act fast while it's vulnerable.\n\nDestroy the Aerial Patroller XZ-2 before they can get it repaired.", objectives = "Destroy the Aerial Patroller XZ-2", progress = "Did you kill the Aerial Patroller XZ-2?", completion = "That's one less threat to our forces!" }
