WordHunterWoW_QuestEN[56401] = { title = "A Bolt from the Blue", description = "You have done much to empower the Heart of Azeroth, and I am proud that the dragonflights have lent their strength to your cause.\n\nIt is now time for the blue dragonflight to do the same.\n\nWhen I first learned of the essences, I knew that some remnant of my dragonflight's power must be out there, coalescing where we were once strong.\n\nThat is exactly what I have found. The Kirin Tor have isolated its signature at the Nexus, but only the wielder of the Heart of Azeroth can claim it.", objectives = "Meet Kalecgos at the Nexus and claim the Charged Scale of the Blue Aspect.", progress = "The power of the Heart of Azeroth never ceases to amaze me.", completion = "We entrust you with this power, champion, because we believe that you will be the one to save Azeroth.\n\nWield it well." }
WordHunterWoW_QuestEN[56402] = { title = "Wastewander Coins", description = "It may be too late for some of our fallen brothers and sisters, but it is not too late to give solace to their families.\n\nEvery Wastewander carries with them a unique coin, signifying their status as a member of our group.\n\nIf you find any of these coins, please bring them to me and I will make sure they are properly returned to their next of kin.", objectives = "Collect 6 Wastewander Coins.", progress = "Do you have coins to return?", completion = "Thank you, <name>. I will see to it that these make it into the right hands." }
WordHunterWoW_QuestEN[56405] = { title = "Cogfrenzy's Construction Frenzy", description = "You Rustbolt resisters inspire me. Tinkering, building, exploring.\n\nLetting your imagination run wild and then chasing after it, wherever it leads, with reckless abandon!\n\n<Walton releases a deep sigh.>\n\nI miss those days. I hope, someday, my conscience will allow me to stay on the surface with you all permanently...\n\nBefore I return to Mechagon, we must build something incredible.\n\nWaren and I have identified a large number of extra construction project sites for today. \n\nBuild with boldness!", objectives = "Help build construction projects.", progress = "Even the greatest builders are eventually forgotten, but their creations are not.", completion = "Clever craftsmanship, <name>.\n\nContinue practicing your construction and you'll replace me as Chief Architect in no time. Ha!" }
WordHunterWoW_QuestEN[56406] = { title = "Activate Water Object", description = "", objectives = "" }
WordHunterWoW_QuestEN[56410] = { title = "Discs of Norgannon", description = "King Mechagon unit in possession of Norgannon disk. Data is corrupted, possession of such data is dangerous.\n\nPlease aid in the recovery of Corrupted Disk Fragments that have been discarded via Mechagon waste systems. \n\nDeliver recovered Corrupted Disc Fragment to Data Analyzer R33-DR for purging.", objectives = "Recover Corrupted Disc Fragment", progress = "Recover Corrupted Disc Fragment.", completion = "This data fragment is now safely eliminated. \n\nIf you locate additional Discs, deliver them to me immediately." }
