WordHunterWoW_QuestEN[56419] = { title = "The Doppel Gang", description = "", objectives = "" }
WordHunterWoW_QuestEN[56421] = { title = "Cracked Numeric Cylinder", description = "<R33-DR is looking for this item.>", objectives = "Deliver the item to R33-DR.", progress = "Deliver the item to R33-DR.", completion = "Data successfully purged." }
WordHunterWoW_QuestEN[56422] = { title = "On Ghostly Wings", description = "We will meet you back where our journey began, {name}. \n\nCorin and I have been separated for many years. We have so much to catch up on. \n\nAs a token of our gratitude we will remain in the area to help you in your travels through this cursed land.", objectives = "Return to Kelya Moonfall in Zin-Azshari.", completion = "Thank you, <name>.\n\nBecause of your efforts, we have some the peace of mind that was long lost.\n\nMy father and I are at your service." }
WordHunterWoW_QuestEN[56423] = { title = "Large Storage Fragment", description = "<R33-DR is looking for this item.>", objectives = "Deliver the item to R33-DR.", progress = "Deliver the item to R33-DR.", completion = "Data successfully purged." }
WordHunterWoW_QuestEN[56424] = { title = "Rust Covered Disc", description = "<R33-DR is looking for this item.>", objectives = "Deliver the item to R33-DR.", progress = "Deliver the item to R33-DR.", completion = "Data successfully purged." }
WordHunterWoW_QuestEN[56425] = { title = "Scorched Data Disc", description = "<R33-DR is looking for this item.>", objectives = "Deliver the item to R33-DR.", progress = "Deliver the item to R33-DR.", completion = "Data successfully purged." }
WordHunterWoW_QuestEN[56429] = { title = "Up Against It", description = "I don't like the sound of that... It sounds like an army!\n\nWe need to investigate.\n\nTry not to draw too much attention as we take a look. If there's an army down there, we'll need to move quickly to find refuge.", objectives = "Move deeper into Nazjatar with Lor'themar and Thalyssra.", progress = "These naga move with a single purpose!", completion = "These naga wear out their welcome quickly." }
WordHunterWoW_QuestEN[56430] = { title = "Defensive in Death", description = "<Having handled zin'anthid for a while now, you pluck one of its tentacles from the main body. As you do, the tentacle retracts, spiraling in on itself preventing you from getting to the blooms that reside along it. Perhaps Rolm will have more insight on how to keep this herb from defending itself.>", objectives = "Ask Rolm about the tentacles of the Zin'anthid.\n\nProvided item:", completion = "Zin'anthids are no mere plant, <name>. They are living beings and as such, know when a predator is trying to harvest them. And yes, even in death they defend themselves.\nIf you wish to harvest all they have to offer, you must lure them into a false sense of security. Here, let me show you a technique I know." }
WordHunterWoW_QuestEN[56431] = { title = "Ounces of Osmenite", description = "<Picking away at the ore, you pick up some shards that have fallen to the ground. There ought to be a way to mine these deposits without wasting any of it. Perhaps Rolm knows of still a better way to mine this ore.>", objectives = "Ask Rolm about the Osmenite Shards.\n\nProvided item:", completion = "Ah yes, that's due to the fragile nature of the ore. You need to adjust your style a bit.\n\nInstead of heavy, powerful swings, try picking away at the edge of where the ore meets the rock.\n\nLike peeling the skin off a fruit. Here, let me show you what I mean..." }
WordHunterWoW_QuestEN[56432] = { title = "Seams to be a Problem", description = "<Picking away at the ore, you notice that much of it seems to turn to dust and fall to the floor at your feet. Enough even, that had it held its shape, would be enough to craft something with.\n\nIt may be worth talking to Rolm to see if there's a way to prevent this loss from happening.>", objectives = "Ask Rolm about the Osmenite Dust.\n\nProvided item:", completion = "The seams that osmenite flows through are structurally different than that of their mere deposits.\n\nIf you want to harvest the full amount of osmenite from a seam, you'll have to ignore the ore all together and go for the rock surrounding it.\n\nIt's a bit counter to how you normally mine, but trust me, you'll be pleasantly surprised with the results." }
WordHunterWoW_QuestEN[56433] = { title = "Drowning the Alliance", description = "The Alliance continue to pursue us, they will not disrupt our plans any further. Drive their champions into a watery grave.", objectives = "Kill 25 Alliance players in Nazjatar while in War Mode.", completion = "There is no way the Alliance will defeat us, even here." }
WordHunterWoW_QuestEN[56434] = { title = "WANTED: Junkbrat and Roadtrogg", description = "Responsible for a spree of mayhem and chaos throughout the Heaps, resulting in the theft of energy cells, spare parts, and the consumption of Improbable Mechano-Chicken Wings without payment.\n\nSpecial caution around Roadtrogg, who has demonstrated a violent attitude towards living things.\n\nElimination of these two felons is of the highest priority.", objectives = "Eliminate Junkbrat and Roadtrogg.", completion = "It's about time we saw the last of those two!" }
WordHunterWoW_QuestEN[56436] = { title = "Small Skull", description = "<Inside of the gelatinous remains of the slime you find a small skeleton.\n\nSomeone in Rustbolt might be missing. \n\nYou pick up the skull, it might still be able to be identified.>", objectives = "Show the Small Skull to Vera Lonelycog in Rustbolt on Mechagon Island.\n\nProvided item:", completion = "Another one? Don't worry, there's no tragedy behind this skull. It's not real.\n\nWhen we first started finding the skeletons, we feared the worst. Our children getting lost in the wastes and devoured!\n\nBut no, the kids are safe.\n\nIt's him, he's tormenting us. King Mechagon. Heard he has some new technology, calling it \"thrice die mentioned smithing.\" Lets him make whatever he wants.\n\nAnd he chooses to make fake baby skeletons.\n\n<Vera shakes her head.>\n\nJust toss it in the grinder with the rest." }
WordHunterWoW_QuestEN[56437] = { title = "Rusty Tube", description = "<The malfunctioning junkbot is now a mere heap of metal, its signature tube poking out of the remains.\n\nYou remove the tube. The citizens of Rustbolt seem to trade in junk, maybe someone will want it.>", objectives = "Show the Rusty Tube to Vera Lonelycog in Rustbolt on Mechagon Island.\n\nProvided item:", completion = "A tube? A rusty tube. Aw, you shouldn't have!\n\n<Vera laughs and then looks closer at the tube.>\n\nHold a moment, an 18 unit tube? You're telling me the circumference of this tube is 18 standard units. That's what I'm seeing here with my unit gauge.\n\nHoly manufactured light, that is just perfect for my hair dryer.\n\nYou're the best! Well, best tube-finder, at least." }
WordHunterWoW_QuestEN[56438] = { title = "Flashing Siren", description = "<Despite the robot being destroyed, the siren continues flashing.\n\nClearly this was a key sentry of King Mechagon. The citizens of Rustbolt will want to know of its demise.>", objectives = "Show the Flashing Siren to Vera Lonelycog in Rustbolt on Mechagon Island.\n\nProvided item:", completion = "Gold trim on the base. This must be from that golden robot patrolling the city outskirts?\n\nNice hit, that thing has been a pain in our side for as long as I can remember.\n\nNot because it actually catches us--it's terrible at that.\n\nNo, the thing wanders into the city in the middle of the night, and looks in our rooms! Just imagine -- you're sound asleep, then the room is lit up bright red, and there's a robot just standing there, looking at you.\n\nIt wanders away eventually, but wow, how rude!" }
WordHunterWoW_QuestEN[56439] = { title = "Mechanical Egg Sac", description = "<You find a mechanical egg sac inside of the defunct spiderbot.\n\nThis doesn't make any sense, robots don't reproduce this way.\n\nOr do they?\n\nSomeone in Rustbolt might have the answers.>", objectives = "Show the Mechanical Egg Sac to Vera Lonelycog in Rustbolt on Mechagon Island.\n\nProvided item:", completion = "Well that's creepy.\n\nMaybe King Mechagon thought we'd be scared of mechanical creatures that could reproduce.\n\nI could see him doing something like that. Reveals his own fears more than ours.\n\nOr maybe the mechanical spiders are... evolving.\n\nCan programs do that?\n\n...\n\nAm I a program?\n\n<Vera sits down to think.>" }
WordHunterWoW_QuestEN[56440] = { title = "Can of Critter Spray", description = "<Inside the wreckage of the robot, you find a sealed can of anti-critter spray.\n\nDestroying all life, down to the rats, seems cruel but on par for King Mechagon.\n\nSomeone in Rustbolt might be able to provide additional insight.>", objectives = "Show the Can of Critter Spray to Vera Lonelycog in Rustbolt on Mechagon Island.\n\nProvided item:", completion = "Oh, yeah, you didn't hear? Proclamation 7: King Mechagon outlawed non-mechanicals smaller than a baby.\n\nHe thought that was so important that it was his SEVENTH proclamation ever made.\n\n<Vera shakes her head.>\n\nThe king hated bugs, rats, anything uninvited that always finds its way into a city. So, he made them illegal. \n\nHe arrested rabbits, squirrels, even fish. Held tiny trials, sentenced them to mechanization, or death, or exile.\n\nHe made those flying robots to deal with any that remained." }
WordHunterWoW_QuestEN[56441] = { title = "Cluckbox", description = "<In the sparking, smoldering wreckage of Unit 35, you find a small, black cube.\n\nIt looks to be made of a metallic substance and appears unharmed.\n\nLooking closely, you see a single word imprinted in the metal -- \"Cluckbox.\"\n\nThis particular mechanical fowl was operating quite strangely. Someone in Rustbolt will probably want to investigate.>", objectives = "Show the Cluckbox to Vera Lonelycog in Rustbolt on Mechagon Island.\n\nProvided item:", completion = "Is that the cluckbox from that rust-blooded Unit 35? I hate that thing!\n\n<Vera grabs the box from you and throws it to the ground. She stomps on it a few times, then once more for good measure.>\n\nSomeone programmed that thing to wake up the island at dawn every morning! Who does that?\n\n<Vera glares in the direction of the city.>\n\nIf you see that thing show up again, smash it good for me." }
WordHunterWoW_QuestEN[56442] = { title = "Broken Unit 6", description = "<Unit 6 sits here, nonfunctional following your attack.\n\nThere is something different and unsettling about this mechanical frog. It appeared to be mimicking frog behavior, but in a way that seemed wrong somehow.\n\nNone of the other mechanical frogs in the area behave similarly.\n\nInstead of taking back only part of the unit for inspection, you pocket the entire frog. It's pretty small, after all.>", objectives = "Show the Broken Unit 6 to Vera Lonelycog in Rustbolt on Mechagon Island.\n\nProvided item:", completion = "Is that one of the mechanical critters? Ah, one of the dark metal ones.\n\nI've never seen one up close. I kept my distance because they never felt... right to me.\n\nNo one in Rustbolt knows where they came from. Perhaps King Mechagon sent them to watch the other critters as they mechanized? He would be the type to want to watch their suffering.\n\nMost think they're here to spy on us. You shouldn't have brought the whole thing back to the town. Just grab an eye, or a liver, next time." }
WordHunterWoW_QuestEN[56443] = { title = "Mechanical Eye", description = "<As the mechanical body of Unit 17 crumples into a heap, one eye lights up.\n\nYou hear a popping noise, and the eye flies from the head, aided by a small explosion.\n\nYou pick up the eye and notice it twitch a few times, then power down.\n\nThe citizens of Rustbolt seem to like junk, maybe they'll be interested in this.>", objectives = "Show the Mechanical Eye to Vera Lonelycog in Rustbolt on Mechagon Island.\n\nProvided item:", completion = "You retrieved this from a mechanical marmot? It must have been that one with the smoke-colored metal.\n\nDid I ever tell you my story about that sinister Unit 17?\n\nSo there I was, browsing the scrap heap for junk, like you do. Suddenly, it's right in front of me -- Unit 17. \n\nI froze. Did it see me? What would it do? I took one step backwards, it twitched, I yelped.\n\nThen it blared at me in a tone I will never forget.\n\n\"Error 74.\"\n\nI ran back as fast as my legs could take me.\n\n<Vera shudders.>" }
WordHunterWoW_QuestEN[56444] = { title = "Wiggletail's Poking Fork", description = "<The tenacious tine of the vanquished prince.\n\nIt does not thrum with any power whatsoever. In fact, it appears quite plain, and a bit rusted.\n\nYou pocket it anyway. Perhaps Artisan Itanu would be interested?>", objectives = "Show Wiggletail's Poking Fork to Artisan Itanu in Mezzamere in Nazjatar.\n\nProvided item:", completion = "Ah hello again, have you more treasures from the deep?\n\nOh, an eating instrument. You will have to convince me of its value here, friend.\n\nIt came from a small naga? Hm, yes. I have seen one such as you describe. \n\nI have thought many long hours about where it may have come from. \n\nI have concluded that it is best not to think on it.\n\nI will gladly take this fork from you to aid in removing the barnacles from my home, though." }
WordHunterWoW_QuestEN[56445] = { title = "Wiggletail's Poking Fork", description = "<The tenacious tine of the vanquished prince.\n\nIt does not thrum with any power whatsoever. In fact, it appears quite plain, and a bit rusted.\n\nYou pocket it anyway. Perhaps Finder Palta would be interested?>", objectives = "Show Wiggletail's Poking Fork to Finder Palta in Newhome in Nazjatar.\n\nProvided item:", completion = "Oh hey, how's it going? Got anything to sell? Or buy?\n\nA fork? You brought me a fork? \n\nIt came from a tiny naga? Oh, yeah, I've seen that one. We talk about it all the time! What even is that thing?\n\nIs it a baby naga? Or maybe just a vision from the deeps? Where did it come from?\n\nI have no answers for you, friend. But I'll take that fork -- it's almost dinner time.\n\nThink I'll have the fish." }
WordHunterWoW_QuestEN[56446] = { title = "Leathery Venom Gland", description = "<You pry a leathery gland from the snapdragon corpse. Drops of venom spill from an opening on one end and sizzle as they touch the ground, leaving small holes behind.\n\nThis toxin appears to be very potent. It would be best to bring it back to Mezzamere.>", objectives = "Show the Leathery Venom Gland to Artisan Itanu in Mezzamere in Nazjatar.\n\nProvided item:", completion = "Friend, let me take that from you, it is best not to handle the venom for too long.\n\nThe naga tame the snapdragon with ease, but we have more difficulty. They seem to have a natural affinity for them. I envy them somewhat, the creatures are both vicious and loyal.\n\nThe venom they spit is deadly. I have only known one to truly master it, a naga commander. We believe she feeds on the substance to give herself immunity. I do not know how this is possible, she must be a terror in combat." }
WordHunterWoW_QuestEN[56447] = { title = "Half-Digested Deepcoral Pod", description = "<Upon inspection of this oddly-aggressive fathom ray, you find several halfway-digested pods.\n\nYou've seen similar pods on the coral of this region, it appears to be one of the foods of the fathom rays.\n\nThis may explain their strange ability to fly.\n\nArtisan Itanu might know more.>", objectives = "Show the Half-Digested Deepcoral Pod to Artisan Itanu in Mezzamere in Nazjatar.\n\nProvided item:", completion = "Hello again, have you come to trade?\n\nAh yes, the coral produces such pods. The fathom rays have a liking for them, we can sometimes lure one into a trap with them, to tame or consume.\n\nThe pods are filled with a gas of some sort, I have never ventured to breathe it myself, but I surmise this diet now keeps the rays aloft.\n\nThe creatures of the deeps have not seen the air before, yet I could not have foreseen such an outcome. It is fascinating." }
WordHunterWoW_QuestEN[56448] = { title = "Molted Spineshell", description = "<The molted shell of a defeated spine crab, a vicious species of crab first encountered in Nazjatar.\n\nThe spines that stick out from it are quite sharp.\n\nArtisan Itanu may have some use for this.>", objectives = "Show the Molted Spineshell to Artisan Itanu in Mezzamere in Nazjatar.\n\nProvided item:", completion = "That is quite a pretty shell, we find them around when the spine crabs molt.\n\nSpine crabs lurk in the deep trenches, waiting on large fish to spear and devour. The beasts of our waters are not as kind as yours.\n\nThe shells themselves are not useful to us -- they become flimsy and brittle over time.\n\nOnce, the children would fill them with sand and hang them on the coral as decorations.\n\nThat was long ago.\n\n<Itanu tosses the shell into the sand with a deep sigh.>" }
WordHunterWoW_QuestEN[56449] = { title = "Pearlescent Shell", description = "<A large, hardened shell of a vanquished hermit crab.\n\nThe shell itself was much larger than the crab, and shines in different colors when you look at it at different angles.\n\nSurely someone back at Mezzamere would be interested in this beautiful shell.>", objectives = "Show the Pearlescent Shell to Artisan Itanu in Mezzamere in Nazjatar.\n\nProvided item:", completion = "Ah, a hermit crab shell. The crabs here are not easy to hunt, nor are they worthwhile. The size of the crab is so small, barely makes for a single meal.\n\nThe shells themselves are quite useful. We use them in making spear tips, shields, even cookware and pots. They are quite versatile and do not lose their durability with time.\n\nI shall add this one to the supplies, with our thanks." }
WordHunterWoW_QuestEN[56450] = { title = "Eel Jelly", description = "<You examine the corpse of the abyssal eel, only to find it bathed in a strange slime.\n\nThe slime coats your hands and arms, and seems quite difficult to remove.\n\nOne of your deep sea allies may know more about it.>", objectives = "Show the Eel Jelly to Artisan Itanu in Mezzamere in Nazjatar.\n\nProvided item:", completion = "Eel jelly? What have you gotten yourself into? Eels, I would guess.\n\nHere, let me remove it from you. We have many uses for it, if you can believe it. Few other things can make things slick, here beneath the waves. You may find it useful as well.\n\n<Itanu rubs some jelly on your arms and legs.>\n\nYou will slide between coral like the tides now, friend." }
WordHunterWoW_QuestEN[56451] = { title = "Mottled Hydra Scale", description = "<The scale of a recently-defeated hydra hatchling, it appears to be a mixture of several colors.\n\nThere appears to be a battle for dominance between the hydra of the region, one of your new allies may know more.>", objectives = "Show the Mottled Hydra Scale to Artisan Itanu in Mezzamere in Nazjatar.\n\nProvided item:", completion = "Ah, a hydra scale, we do have a fair bit of them around here.\n\nThey have three matriarchs leading their packs. Each one has attempted to gain dominance over the area for years, yet they always fail.\n\nThe naga amuse themselves by sending slaves into the area to be devoured.\n\nThey are friends of none, we had best leave them be." }
WordHunterWoW_QuestEN[56452] = { title = "Strange Organ", description = "<You find a strange organ in the corpse of the mindbender. Upon picking it up, your head begins to throb.\n\nThe octopus-like creatures have long been one of Azeroth's mysteries, this organ may shed some light on them.\n\nSomeone in Mezzamere may know more.>", objectives = "Show the Strange Organ to Artisan Itanu in Mezzamere in Nazjatar.\n\nProvided item:", completion = "The organ from a mind-squid, yes, I am familiar with them.\n\nThe children of Ozumat flood the deeps, too numerous to count. \n\nThey attack our thoughts with the aid of this organ. It makes a sound that speaks directly to the mind.\n\nLet me show you.\n\n<Itanu pushes on the organ, and your mind is assailed by a deafening psychic scream.>\n\nThe very creature itself seems built to harass the mind, and service the old ones.\n\nI will dispose of this now, away from the camp." }
WordHunterWoW_QuestEN[56453] = { title = "Overgrown Stone", description = "<A stone taken from the earthy elemental you recently defeated, covered in kelp and various other underwater plants.\n\nYou have not seen many such creatures in the deeps. Perhaps there is a story to them.\n\nOne of your new undersea allies may know more.>", objectives = "Show the Overgrown Stone to Artisan Itanu in Mezzamere in Nazjatar.\n\nProvided item:", completion = "Oh hello, what have you there?\n\nA fragment from a kelp-covered elemental? Most fortuitous. Such stones can be used to enhance the growth of most sorts of plants that we know of.\n\nAt times, I use them to grow healing wraps for us, when I can find them. The elementals themselves are quite rare.\n\nI thank you for this donation." }
WordHunterWoW_QuestEN[56454] = { title = "Crackling Mandible", description = "<The mandible of a tidal guardian, still crackling with electricity.\n\nOne of your new allies might have a use for this.>", objectives = "Show the Crackling Mandible to Artisan Itanu in Mezzamere in Nazjatar.\n\nProvided item:", completion = "Oh, let me handle that with care, I do not want another shock.\n\nYou have met the tidal guardians, then? They have lived in the naga caves for as long as I can recall, serving their masters faithfully. I have not seen one while hunting in the wild in my lifetime.\n\nWe can make many things with their mandibles, from spearheads to electrified traps. I will put this to good use." }
WordHunterWoW_QuestEN[56455] = { title = "Frenzy Fang", description = "<You remove a fully-grown fang from the fallen frenzy.\n\nYou have heard of some seafaring groups that made weapons or decorations out of fangs found in the deeps, perhaps your new allies could find use for this?>", objectives = "Show the Frenzy Fang to Artisan Itanu in Mezzamere in Nazjatar.\n\nProvided item:", completion = "<Itanu holds the tooth between his fingers.>\n\nThe frenzies serve none but themselves.\n\nYou do not know of them.\n\n<Itanu looks at the open sky.>\n\nThey cannot come here, now. Once they were a force that even the naga feared. Even their most powerful champions feared them.\n\nWhat little light we would have would be doused, when the frenzies would come. Their numbers would blot out the sun. Their teeth would find all unhidden flesh.\n\nYou will never know the terror of the deeps, dry one." }
WordHunterWoW_QuestEN[56456] = { title = "Opaline Conch", description = "<The conch slumps following your assault -- the battle appears to be over.\n\nIt doesn't move. You bend over and pick it up, instinctively turning it over, wary of any attack.\n\nIt appears to be dead, but intact. You consider bringing the entire conch back to your allies in Mezzamere.>", objectives = "Show the Opaline Conch to Artisan Itanu in Mezzamere in Nazjatar.\n\nProvided item:", completion = "Ah, a great find.\n\n<Itanu takes the conch from you and flips it over. Before you can see it, he has a small knife in hand. The conch is quickly speared, the slug within removed.>\n\nMost delightful! It would ruin it to touch fire. This... is a delicacy. It must be savored.\n\n<Itanu closes his eyes and breathes deeply, then devours the snail in a single gulp.>\n\nHm, mm. Slimy, oddly rough on the insides. \n\nMagnificent." }
WordHunterWoW_QuestEN[56457] = { title = "Leathery Venom Gland", description = "<You pry a leathery gland from the snapdragon corpse. Drops of venom spill from an opening on one end and sizzle as they touch the ground, leaving small holes behind.\n\nThis toxin appears to be very potent. It would be best to bring it back to Newhome.>", objectives = "Show the Leathery Venom Gland to Finder Palta in Newhome in Nazjatar.\n\nProvided item:", completion = "Is that a venom gland in your pocket or... why is that in your pocket? You know how potent those things are, right?\n\nYeah, the snapdragons have been a pain in our side for a long time. The naga can easily sway them with their mind-bending tricks, or even just meat, they're not very smart creatures. A few good meals and they're as good as tamed.\n\nI've heard of a naga commander that can handle the venom in combat. Rumor has it she even eats the stuff. \n\nHope I never meet her!" }
WordHunterWoW_QuestEN[56458] = { title = "Opaline Conch", description = "<The conch slumps following your assault -- the battle appears to be over.\n\nIt doesn't move. You bend over and pick it up, instinctively turning it over, wary of any attack.\n\nIt appears to be dead, but intact. You consider bringing the entire conch back to your allies in Newhome.>", objectives = "Show the Opaline Conch to Finder Palta in Newhome in Nazjatar.\n\nProvided item:", completion = "Oh, hey, that's a giant conch, right? Let me see that.\n\n<Palta flips the conch over and pulls the innards out by the antennae.>\n\nThat's the stuff. Look at it! Full-slime, all scales, this one is going to be great.\n\nI'll prepare this for the meal tonight, that should lift some spirits. Nothing like a slice of spireshell to remind you of home.\n\nThanks for bringing this.\n\n<Palta nods at you.>" }
WordHunterWoW_QuestEN[56459] = { title = "Half-Digested Deepcoral Pod", description = "<Upon inspection of this oddly-aggressive fathom ray, you find several halfway-digested pods.\n\nYou've seen similar pods on the coral of this region, it appears to be one of the foods of the fathom rays.\n\nThis may explain their strange ability to fly.\n\nFinder Palta might know more.>", objectives = "Show the Half-Digested Deepcoral Pod to Finder Palta in Newhome in Nazjatar.\n\nProvided item:", completion = "Hey, you're back! What's that? Something you ate?\n\nOh, yeah, the fathom rays love these pods. They grow on the coral around the area, seem to be filled with gas.\n\nI always thought it was just air but it appears it's lighter than air, I can fill a fishskin with what's in a pod and it floats above water!\n\nMust help them survive in the deeps, somehow. Not sure how that works, life is a mystery, you know?" }
WordHunterWoW_QuestEN[56460] = { title = "Molted Spineshell", description = "<The molted shell of a defeated spine crab, a vicious species of crab first encountered in Nazjatar.\n\nThe spines that stick out from it are quite sharp.\n\nFinder Palta may have some use for this.>", objectives = "Show the Molted Spineshell to Finder Palta in Newhome in Nazjatar.\n\nProvided item:", completion = "A spine crab shell? We find them around, though I try to stay away from the dark places myself.\n\nThat's where they live, you see? The spine crabs lurk in the darkness, waiting for fish to spear. Once I saw a group of them skewer a whale shark! \n\nWhen they devour prey, they make a chittering noise -- I hate it.\n\nThe shells themselves aren't very useful -- they get brittle and shatter easily.\n\nWatch!\n\n<Palta flings the shell against a nearby rock, shattering it to pieces.>\n\nWoo-ha!" }
WordHunterWoW_QuestEN[56461] = { title = "Pearlescent Shell", description = "<A large, hardened shell of a vanquished hermit crab.\n\nThe shell itself was much larger than the crab, and shines in different colors when you look at it at different angles.\n\nSurely someone back at Newhome would be interested in this beautiful shell.>", objectives = "Show the Pearlescent Shell to Finder Palta in Newhome in Nazjatar.\n\nProvided item:", completion = "That's a big shell! Like the sheen on it, too. Really catches the light, especially now that we can see the sun directly.\n\nYou know what I haven't made in a while? With all this fighting and barely surviving? Jewelry. I miss it! We used to find all kinds of things to wear dropped by your ships.\n\n<Palta smashes the shell into many pieces and holds two irregular shards up to her ears.>\n\nWell, how do I look?\n\n<Do you answer?>" }
WordHunterWoW_QuestEN[56462] = { title = "Eel Jelly", description = "<You examine the corpse of the abyssal eel, only to find it bathed in a strange slime.\n\nThe slime coats your hands and arms, and seems quite difficult to remove.\n\nOne of your deep sea allies may know more about it.>", objectives = "Show the Eel Jelly to Finder Palta in Newhome in Nazjatar.\n\nProvided item:", completion = "You are really covered in slime, there. Mind if I take some?\n\nEel jelly is incredibly useful to us. Not a whole lot of things can be used to make things slippery underwater, you know. Eel jelly is just great at it.\n\nHere, let me show you.\n\n<Palta rubs some jelly on your arms and legs.>\n\nYour skin is looking better already! Slimier. Much better." }
WordHunterWoW_QuestEN[56463] = { title = "Mottled Hydra Scale", description = "<The scale of a recently-defeated hydra hatchling, it appears to be a mixture of several colors.\n\nThere appears to be a battle for dominance between the hydra of the region, one of your new allies may know more.>", objectives = "Show the Mottled Hydra Scale to Finder Palta in Newhome in Nazjatar.\n\nProvided item:", completion = "You'd like to know a little about the hydra of the area? Not much to tell, truth be told.\n\nThere are three matriarchs, they've been battling for dominance of the area for generations.\n\nSometimes, the naga throw slaves to them, for their amusement.\n\nThey don't serve anyone, just themselves. The depths aren't aligned against you, newcomer. They're just... hostile to outsiders." }
WordHunterWoW_QuestEN[56464] = { title = "Strange Organ", description = "<You find a strange organ in the corpse of the mindbender. Upon picking it up, your head begins to throb.\n\nThe octopus-like creatures have long been one of Azeroth's mysteries, this organ may shed some light on them.\n\nSomeone in Newhome may know more.>", objectives = "Show the Strange Organ to Finder Palta in Newhome in Nazjatar.\n\nProvided item:", completion = "Mindbender brain-organ? Great, thanks, I have a use for this.\n\nThey use this organ to attack our thoughts. Or, at least, it's a part of the process.\n\nHere, watch.\n\n<Palta points the organ at you and pokes it. You hear a deafening psychic scream in your mind.>\n\nIt's like they were made just to service the Old Gods and drive people insane.\n\nAnyway, thanks. I'm going to save this for when my friend comes over to talk about her gardening." }
WordHunterWoW_QuestEN[56465] = { title = "Overgrown Stone", description = "<A stone taken from the earthy elemental you recently defeated, covered in kelp and various other underwater plants.\n\nYou have not seen many such creatures in the deeps. Perhaps there is a story to them.\n\nOne of your new undersea allies may know more.>", objectives = "Show the Overgrown Stone to Finder Palta in Newhome in Nazjatar.\n\nProvided item:", completion = "Hey, what's that? Really fuzzy rock you've got there.\n\nIt's from one of those earthy elementals? Oh, neat, yeah I can use that. Things grow on them like crazy, I just need to plant it in the garden and the next crop will be great.\n\nNot sure where the elementals came from. We don't see many of them around, they're quite rare.\n\nAnyway, thanks! Think I'm going to make my own kelp garden with this one." }
WordHunterWoW_QuestEN[56466] = { title = "Crackling Mandible", description = "<The mandible of a tidal guardian, still crackling with electricity.\n\nOne of your new allies might have a use for this.>", objectives = "Show the Crackling Mandible to Finder Palta in Newhome in Nazjatar.\n\nProvided item:", completion = "Yowch! You've got to warn a person before you hand them something electric! You picked this up from a tidal guardian?\n\nThe tidal guardians have guarded the naga domain for as long as I can remember. It seems like they have always been intertwined, I can't recall ever having seen one in the wild.\n\nThey're really quite beautiful when they're swimming, mesmerizing even.\n\nAnyway, I use these things to make drinks. You mix some kelpflower wine with a bit of ground mandible, really gives it a kick!" }
WordHunterWoW_QuestEN[56467] = { title = "Frenzy Fang", description = "<You remove a fully-grown fang from the fallen frenzy.\n\nYou have heard of some seafaring groups that made weapons or decorations out of fangs found in the deeps, perhaps your new allies could find a use for this?>", objectives = "Show the Frenzy Fang to Finder Palta in Newhome in Nazjatar.\n\nProvided item:", completion = "<Palta pokes the tip of the fang.>\n\nFrenzy fang, huh? Those things... we don't joke about them.\n\n<Palta looks up at the open air.>\n\nYou're lucky, they can't come here anymore.\n\nI remember, one time, we had gone out looking for supplies. I was the only one to make it back. I can still hear the screams of the devoured. They came out of nowhere, by the hundreds. It was all clouds of red.\n\nThe deep places of the world are dangerous, friend. Avoid them if you can." }
WordHunterWoW_QuestEN[56469] = { title = "Pirates? I Hate Those Guys!", description = "<An old pirate hat. Seems out of place on this island, perhaps Reno Jackson will know what to make of it>", objectives = "Deliver the old pirate hat to Reno Jackson.\n\nProvided item:", completion = "I suspected pirate activity here! All these strange items we're finding are their plundered loot." }
WordHunterWoW_QuestEN[56470] = { title = "Give A Dog A Bone", description = "Louison lent me Dog Bone to help uncover some marrowgrubs, but I'm busy here with the stoves. Could you be a dear and go hunting for me?\n\nDog Bone loves to pounce on the smaller nibblers and makes a lot of noise doing it. That'll scare the larger marrowgrubs into making a run for it. That's when you'll need to make your move.\n\nJust use this bone to lure Dog Bone near the nibblers. Oh, and don't forget to harvest the flesh from the marrowgrubs! That's what you're really after.", objectives = "Collect 12 Marrowgrub Flesh from Giant Marrowgrubs.", progress = "Did you collect the meat?", completion = "Wonderful! This will make something tasty!" }
WordHunterWoW_QuestEN[56471] = { title = "Unprofitable Ventures", description = "This land is already a monumental disaster, but it could get worse!\n\nThe Venture Company is here, and will exploit this land for every ounce of profit they can make. We must make their venture here unprofitable, so they will leave.\n\nDestroy the three expensive security units with them, and they may leave for more profitable ventures.", objectives = "Destroy Pummeller Red, Pummeller Orange, and Pummeller Grey", completion = "This certainly hurts their profits. Now we see if they leave!" }
WordHunterWoW_QuestEN[56472] = { title = "The Uldum Accord", description = "You seek assistance defending the Forge of Origination? It would seem that our goals align.\n\nThe Halls of Origination are but a small portion of the forge's true scope. Any threat to Uldum would be a potential threat to the forge, and Uldum has found itself with many new enemies of late.\n\nWe were about to convene the High Council when these Wastewanders arrived unannounced. Perhaps you could join us in learning about these threats?", objectives = "Learn about the threats facing Uldum in Ramkahen.", progress = "We should learn all we can about the threats facing Uldum before we proceed.", completion = "Our accord with the Wastewanders and the Explorer's League will aid us in defending Uldum. \n\nYet even with our combined strength, we may not be able to hold these enemies at bay without your help." }
WordHunterWoW_QuestEN[56473] = { title = "Envenomed Spider Fang", description = "Even wary bees have been known to fall prey to these enormous spiders. They lie in wait near flowerbeds and ambush them while they collect their harvest. Thanks to you, they have one less spider to worry about.\n\nThe Hivemother will be interested in this item.", objectives = "Take the Envenomed Spider Fang to the Honeyback Hivemother for a reward.\n\nProvided item:", completion = "<The Hivemother buzzes at you.>\n\nBzzzzzz!" }
WordHunterWoW_QuestEN[56474] = { title = "Hivekiller Stinger", description = "Wasps are a bee's natural enemy, and none are more deadly than this highly specialized killer. It will terrorize the hive no longer, thanks to you.\n\nThe Hivemother will be interested in this item.", objectives = "Take the Hivekiller Stinger to the Honeyback Hivemother for a reward.\n\nProvided item:", completion = "<The Hivemother buzzes animatedly at the sight of the stinger.>\n\nBzzzz!" }
WordHunterWoW_QuestEN[56475] = { title = "Spiral Yeti Horn", description = "All manner of creatures are attracted to the sweet smell of fresh honey, but relatively few are willing to withstand the painful and often deadly stings of the largest of bees. This yeti, however, has been a persistent thorn in the hive's side, until now.\n\nThe Hivemother will be interested in this item.", objectives = "Take the Spiral Yeti Horn to the Honeyback Hivemother for a reward.\n\nProvided item:", completion = "<The Hivemother buzzes animatedly at the sight of the horn.>\n\nBzzz! Bzzzz!" }
WordHunterWoW_QuestEN[56489] = { title = "Restless Dead", description = "Rumors are spreading of some new evil business happening in Stratholme of all places. We need you to head to Eastern Plaguelands and put an end to any new evil threats that may have taken residence there.\n\nWe have received contact from a member of the Argent Crusade who has offered their assistance to get you into Stratholme and find the source of this new evil.", objectives = "Find Sean Wilkers outside of the service entrance of Stratholme in Eastern Plaguelands.", completion = "Dead things in Stratholme isn't really a surprise anymore, but there's some new evil lurking within that we haven't seen before. \n\nOnly the most courageous and strong willed should enter." }
WordHunterWoW_QuestEN[56490] = { title = "Restless Dead", description = "Rumors are spreading of some new evil business happening in Stratholme of all places. We need you to head to Eastern Plaguelands and put an end to any new evil threats that may have taken residence there.\n\nWe have received contact from a member of the Argent Crusade who has offered their assistance to get you into Stratholme and find the source of this new evil.", objectives = "Find Sean Wilkers outside of the service entrance of Stratholme in Eastern Plaguelands.", completion = "Dead things in Stratholme isn't really a surprise anymore, but there's some new evil lurking within that we haven't seen before. \n\nOnly the most courageous and strong willed should enter." }
WordHunterWoW_QuestEN[56491] = { title = "Tiny Terrors of Stratholme", description = "Scourge activity inside of Stratholme has increased dramatically in the recent days. The air is thick with the stink of necromancy, and there are screams and shrieks coming from within these walls that will send chills down your spine for weeks to come.\n\nI haven't ventured in there yet myself, but there is definitely some new evil stirring from within. I have the keys to this entrance, and can bring you in there to see for yourself.\n\nLet me know when you are ready.", objectives = "Defeat Blackmane.", progress = "I can open these gates and bring us in, but it will be up to you to get out safely.", completion = "They did what to Blackmane!? Who are these people? Infusing a beast with strange necromancy powers certainly sounds like an escalation of events compared to what they have done previously. What can they possibly be doing with all of this stuff they are taking? It sounds like a showdown is imminent." }
WordHunterWoW_QuestEN[56492] = { title = "Pet Battle Challenge: Stratholme", description = "The evil presence has returned to Stratholme yet again. That's the problem with necromancy and scourge, they keep reanimating themselves and coming right back!\n\nI can bring us in there again, but I suspect all of those evil forces have returned. Are you sure you want to go back in there? That place gives me the creeps. If you really want to head back in there, I will let you back in.", objectives = "Defeat Blackmane.", progress = "I can open this service entrance, but it is up to you to safely get out of Stratholme.", completion = "They did what to Blackmane!? Who are these people? Infusing a beast with strange necromancy powers certainly sounds like an escalation of events compared to what they have done previously. What can they possibly be doing with all of this stuff they are taking? It sounds like a showdown is imminent." }
WordHunterWoW_QuestEN[56493] = { title = "A Direct Approach", description = "Maokka has such a gentle heart. He is so good with the little ones, always playing games and telling stories.\n\nWe do however really dislike these Venture Co. individuals, so I suggest a more direct approach.\n\nTry killing them all.", objectives = "Eliminate 12 Venture Co. employees", completion = "You've sent them a message they won't forget." }
WordHunterWoW_QuestEN[56494] = { title = "The Eve of Battle", description = "{name}. The time has come.\n\nWe may have defeated Azshara, but we still have to deal with Sylvanas. Though our position is not ideal, we have mobilized our available forces and stand ready to finish this war.\n\nKing Wrynn wanted me to brief you on the situation before we join him. There have been some... interesting developments.", objectives = "Speak with Mathias Shaw.", completion = "Thank you for responding with haste." }
WordHunterWoW_QuestEN[56495] = { title = "They Move Against Us", description = "The Dark Lady requests your presence in Orgrimmar, {name}. \n\nIt seems the rats have finally come out of hiding. Which will make it all the easier to exterminate them.\n\nDo not delay. We have waited for this moment long enough.", objectives = "Meet with Sylvanas in Orgrimmar.", progress = "The pathetic fools.", completion = "These traitors will be dealt with. No more leniency. No more weakness." }
WordHunterWoW_QuestEN[56496] = { title = "The Eve of Battle", description = "{name}, we must speak of the Horde... and the warchief.\n\nThe war has proven costly, and the battle against Azshara drained what little resources we had left. The Horde is divided once more and the Alliance fares little better than we do. \n\nSylvanas is now in a position to destroy everyone she considers an enemy. That means us, as well.\n\nI had hoped that my old friend would see reason, but now...\n\nHigh Overlord Saurfang is rallying those of us who remain--including some unlikely allies.", objectives = "Speak with Lor'themar.", completion = "We have much to do, <name>. The Banshee moves swiftly." }
WordHunterWoW_QuestEN[56499] = { title = "Storming the Battlefields", description = "We cannot afford to let up on any front, continue to press the war.", objectives = "Win a PVP Island Expedition, Normal Battleground and Epic Battleground.", completion = "If we keep up the pressure there is no way the Horde will succeed." }
WordHunterWoW_QuestEN[56500] = { title = "Storming the Battlefields", description = "We cannot afford to let up on any front, continue to press the war.", objectives = "Win a PVP Island Expedition, Normal Battleground and Epic Battleground.", completion = "If we keep up the pressure there is no way the Alliance will succeed." }
WordHunterWoW_QuestEN[56501] = { title = "Taking The Air Out", description = "<This box of rockets could just be used to take out the Venture Co. Balloons. That would really motivate Venture Co. to go somewhere else.>", objectives = "Eliminate 5 Venture Co. Transports", completion = "You are a generous one. You did far more than I asked." }
WordHunterWoW_QuestEN[56504] = { title = "Wrathion's Journal", description = "The whispers ceased as soon as I drank the potion. Thank you, {name}.\n\nStill, it is gravely concerning that N'Zoth's influence could reach me even within the Chamber of Heart. If Wrathion has found a way to resist the power of the Old Gods, then we can use it to reinforce the Chamber's defenses.\n\nPerhaps MOTHER can glean more information from Wrathion's journal.", objectives = "Deliver Wrathion's incomplete journal to MOTHER.", progress = "Awaiting information interface.", completion = "Information from journal pages committed to memory. Formulating fortification schematics for Chamber of Heart.\n\nAll data recorded and catalogued. Physical transcription no longer required." }
WordHunterWoW_QuestEN[56508] = { title = "Waste Not", description = "<There's a variety of parts around this area that might be useful to Rustbolt. You should collect them before Venture Co takes them.>", objectives = "Collect 20 Useful Bits and Pieces", progress = "Grab what things you can!", completion = "These parts will make someone a nice upgrade!" }
WordHunterWoW_QuestEN[56515] = { title = "Vinyl: Gnomeregan Forever", description = "<This pressed vinyl is surprisingly still intact. Its label says it contains the recording of a song called \"Gnomeregan Forever.\"\n\nYou should be able to install this vinyl into the gramophone back in Rustbolt.>", objectives = "Install the vinyl into the Rustbolt Gramophone.\n\nProvided item:", completion = "<The vinyl slides neatly into the gramophone's vinyl carousel. The titleboard updates automatically.>" }
WordHunterWoW_QuestEN[56516] = { title = "Vinyl: Mimiron's Brainstorm", description = "<This pressed vinyl is surprisingly still intact. Its label says it contains the recording of a song called \"Mimiron's Brainstorm.\"\n\nYou should be able to install this vinyl into the gramophone back in Rustbolt.>", objectives = "Install the vinyl into the Rustbolt Gramophone.\n\nProvided item:", completion = "<The vinyl slides neatly into the gramophone's vinyl carousel. The titleboard updates automatically.>" }
WordHunterWoW_QuestEN[56517] = { title = "Vinyl: Battle of Gnomeregan", description = "<This pressed vinyl is surprisingly still intact. Its label says it contains the recording of a song called \"Battle of Gnomeragan.\"\n\nYou should be able to install this vinyl into the gramophone back in Rustbolt.>", objectives = "Install the vinyl into the Rustbolt Gramophone.\n\nProvided item:", completion = "<The vinyl slides neatly into the gramophone's vinyl carousel. The titleboard updates automatically.>" }
WordHunterWoW_QuestEN[56518] = { title = "Vinyl: Depths of Ulduar", description = "<This pressed vinyl is surprisingly still intact. Its label says it contains the recording of a song called \"Depths of Ulduar.\"\n\nYou should be able to install this vinyl into the gramophone back in Rustbolt.>", objectives = "Install the vinyl into the Rustbolt Gramophone.\n\nProvided item:", completion = "<The vinyl slides neatly into the gramophone's vinyl carousel. The titleboard updates automatically.>" }
WordHunterWoW_QuestEN[56519] = { title = "Vinyl: Triumph of Gnomeregan", description = "<This pressed vinyl is surprisingly still intact. Its label says it contains the recording of a song called \"Triumph of Gnomeregan.\"\n\nYou should be able to install this vinyl into the gramophone back in Rustbolt.>", objectives = "Install the vinyl into the Rustbolt Gramophone.\n\nProvided item:", completion = "<The vinyl slides neatly into the gramophone's vinyl carousel. The titleboard updates automatically.>" }
WordHunterWoW_QuestEN[56523] = { title = "My Chickens are Not for Eating!", description = "If you've spent any time with that arrogant nitwit, Overspark, you know why I'm here.\n\nTo silence his boasting and finally prove that my inventions are better!\n\nI've released countless mechanical chickens across this island to analyze the technology here, adopt it, and evolve their own circuitry. One of them will become my ultimate battle chicken!\n\nBut those idiot troggs think my chickens are edible and keep bashing them.\n\nProtect them, so my techno-evolutionary experiment can run its course.", objectives = "Collect 20 Mechanical Giblets and repair the OOX-Bomber/MG.", progress = "Imagine being so dumb that you try to eat a mechanical chicken...", completion = "Superlative intervention, <name>!\n\nNow, we sit back and let the robots evolve themselves through natural selection... with no negative side effects whatsoever." }
WordHunterWoW_QuestEN[56532] = { title = "Nuke 'Em Norbit", description = "These motospiders continue to multiply unchecked. If we don't slow them down they'll overrun Rustbolt soon.\n\nI've modified Norbit here with adequate firepower to take the spiders head on!\n\nWould you pilot Norbit and destroy the Reinforced Sparkweave Eggs?", objectives = "Eliminate the 5 Reinforced Sparkweave Eggs", progress = "Norbit needs a skilled pilot!", completion = "Mission accomplished!" }
WordHunterWoW_QuestEN[56533] = { title = "Worldvein Rumors", description = "Gather intelligence to assist SI:7 in identifying the location of the Fluctuating Worldvein.", objectives = "Collect 3 Worldvein Intelligence Reports.", progress = "Have you gathered enough intelligence?", completion = "This is exactly the intelligence Mathias Shaw wanted me to watch out for, I will pass it over to him immediately. I am sure he will have a Mission waiting for you." }
WordHunterWoW_QuestEN[56534] = { title = "Worldvein Rumors", description = "Gather more intelligence to assist your followers in tracking down the location of the Fluctuating Worldvein.", objectives = "Collect 3 Worldvein Intelligence Reports.", progress = "Have you gathered enough intelligence?", completion = "Nathanos Blightcaller was looking for just this type of intelligence. I will send a runner immediately to the flagship. I am sure he will have a follow up mission for you when you arrive." }
WordHunterWoW_QuestEN[56536] = { title = "It's Never Easy", description = "The last I heard, Mogu'shan Vaults was still abandoned. \n\nWe shouldn't have too tough of a time reachin' the engine, since we've already defeated the mogu guardians in that place.\n\nWell, what are ye waitin' for? Let's get that engine turned on!", objectives = "Meet Magni Bronzebeard outside Mogu'shan Vaults in Kun-Lai Summit.", progress = "It's never easy, is it?", completion = "That amber barrier looks nigh impassable.\n\nIt looks like we've hit a dead end..." }
WordHunterWoW_QuestEN[56537] = { title = "The Mysterious Sigil", description = "<The slain mogu clutches a sigil in his hand -- a symbol of the mysterious clan he belongs to.\n\nPerhaps if you could track down his clan, they may know more about the mantid's invasion of Mogu'shan Vaults and how they can be overcome.\n\nLorewalker Cho is well known as font of lore for Pandaria. He may be able to track down the origins of the mogu's sigil.>", objectives = "Bring the Mysterious Mogu Sigil to Lorewalker Cho at the Seat of Knowledge in Vale of Eternal Blossoms.", completion = "So Mogu'shan Vaults has been taken by the mantid? A strange turn, indeed, though hardly surprising. \n\nSeeking the help of the mogu to reclaim it though, that is unexpected. Last I heard, they weren't precisely on speaking terms." }
WordHunterWoW_QuestEN[56538] = { title = "Clans of the Mogu", description = "You say a mogu asked for your help? This is quite uncharacteristic. \n\nI'd be happy to help you uncover the origins of this sigil. To be honest, the prospect of a mogu clan that isn't openly hostile interests me greatly. Just think of the possibilities!\n\nLet's get down to business. We'll need to consult the volumes on the various mogu clans in the vale to narrow it down.", objectives = "Help Lorewalker Cho discover the origin of the Mysterious Mogu Sigil at the Seat of Knowledge.", progress = "Why are you talking to me? The knowledge you seek is in the tomes.", completion = "If the mogu are once again following Ra-den it could mean an end to their days of war.\n\nThis is very exciting!" }
WordHunterWoW_QuestEN[56539] = { title = "Finding the Rajani", description = "Now that we have an idea of who we're looking for, the next question is, where can we find them?\n\nWith the constant infighting of the mogu, it is likely that each clan would keep tabs on the whereabouts of their competitors. If we can find such information, it may just lead us to the Rajani.\n\nSeek out the champions of the mogu. They would be the most likely to carry reports on their enemies' whereabouts.", objectives = "Collect a Mogu Scouting Report from mogu in the Vale of Eternal Blossoms.", progress = "Have you found a scouting report?", completion = "Excellent. Not only might this lead us to the Rajani, but it will prove valuable to the Golden Lotus's defense efforts.\n\nThis is valuable information, indeed!" }
WordHunterWoW_QuestEN[56540] = { title = "Proof of Tenacity", description = "If the Highkeeper is so convinced that we don't stand a chance against our enemies, perhaps a show of force would sway him.\n\nI am not sure how you would manage, but if you could bring proof of a victory against those who threaten the Vale, it may convince him that action should be taken.", objectives = "Obtain a Conqueror's Trophy from the commander of an Assault in the Vale of Eternal Blossoms.", progress = "What is it this time?", completion = "So, you managed to defeat one of the Vale's would-be conquerors? A notable feat, but Azeroth's enemies are innumerable.\n\nThe Burning Legion, the Old Gods, the Void... sooner or later the scales will tip against this world.\n\n...but I have been mistaken before." }
WordHunterWoW_QuestEN[56541] = { title = "The Engine of Nalak'sha", description = "Your kind have proved me wrong in the past, so I will give you a chance to do so again.\n\nThe titan structure which houses the Engine of Nalak'sha spans the entirety of Pandaria. There are more ways to reach it than just the Mogu'shan Vaults.\n\nThere are many such routes, but the closest would be through Mogu'shan Palace. The chambers beneath the palace are interconnected with the vaults. \n\nSeek your fate there, champion.", objectives = "Follow the secret passage within Mogu'shan Palace and re-activate the Engine of Nalak'sha.", progress = "Your courage is impressive. I only hope it is not wasted.", completion = "You have done a great thing for the Rajani today, champion.\n\nI hope the Engine of Nalak'sha provided the power you seek." }
WordHunterWoW_QuestEN[56542] = { title = "Restored Hope", description = "Your persistence fills me with hope for this world. \n\nLet us return to your \"Chamber of Heart.\" As the caretaker of the Forge of Origination, I believe I can help your efforts to restore it.\n\nSpeak to me when you are ready, and I will bring us there.", objectives = "Speak with Ra-den to return to the Chamber of Heart.", completion = "Not only have we managed tae restore power tae the Forge of Origination, but we even brought back the Titan keeper that originally installed it!\n\nBut believe it or not, that's not the end o' the good news!" }
WordHunterWoW_QuestEN[56550] = { title = "Corpse Cleanup", description = "Our friends continue to fall as these terrible insects pour of their nests and attack our camps.\n\nIt's a terrible job to ask of anyone, but we have to dispose of the corpses as quickly as possible.\n\nWe can't allow our dead to be used as fertilizer for growing their disgusting eggs.", objectives = "Burn 8 Egg-bearing corpses.", progress = "We need to complete this task quickly and without delay.", completion = "I hope this will help keep the growth of their numbers at bay." }
WordHunterWoW_QuestEN[56552] = { title = "Off-the-Books Brawlin'", description = "Gazlowe hired you for protection too? I guess it's true that he only hires the best, eh? Ha!\n\nPay's great, but the rules are dung: no fightin' in town, no exceptions. Bah!\n\n<Usha takes a big gulp of her drink.>\n\nThat tiny tender prince won't give us his tech unless he thinks we're good little angels... Ha!\n\nBut Gazlowe didn't say nothin' about fightin' outside of town.\n\nI got my own squad on the outskirts, ready to brawl with Grumbol's guzzlers if they show their bearded faces.\n\nYou want in?", objectives = "Brawl with Grumbol Grimhammer's forces on Mechagon.", completion = "Ha ha ha! Look at Grumbol's stupid face!\n\nHe can't believe it! Ha ha ha! Pathetic!" }
WordHunterWoW_QuestEN[56557] = { title = "A Little Side Action", description = "There are only two things more fun than fighting, and the first is talking trash!\n\n<Usha shouts an insult at Grumbol Grimhammer.>\n\nThat boar-beard runt over there's been a thorn in my backside since Alterac... Can't seem to shake him.\n\nWe got a bet going about who's the best fighter on the island.\n\nYou want to help me win this wager?", objectives = "Slay 5 Alliance players in Mechagon.", completion = "Ha! Looks like I owe you another drink." }
WordHunterWoW_QuestEN[56558] = { title = "Off-the-Books Brawlin'", description = "*buuuurrp* Arrrright, listen 'ere. We got ourselves a bit o' a predicament.\n\nBesides this dump's ale tastin' like oil, that pigheaded Usha here been sayin' some unfortunate stuff about our troops.\n\nUnfortunate FOR HER, 'cuz now *uuuuurp* gonna needya ta rough up any Horde swine ya end up runnin' into out there.\n\nLoosely speakin' we ain't supposed to be brawlin' out 'ere, so this ain't a formal order or nothin'...", objectives = "Brawl with Usha Eyegouge's forces on Mechagon.", completion = "Couldn't be more proud of ya me lad! 'Ere's a little somethin' fer yer trouble." }
WordHunterWoW_QuestEN[56559] = { title = "A Little Side Action", description = "'Ey, {name}, I could be usin' yer talents fer a little bet I got goin' on with Usha.\n\nI'm wagerin' you can beat up five 'o her pals around the island before her dog can beat up five o' ours.\n\nYe up fer it me lad? 'O course ya are, ahahaha!", objectives = "Slay 5 Horde players in Mechagon.", completion = "I knew ye wouldn't be lettin' me down!" }
WordHunterWoW_QuestEN[56560] = { title = "A Curious Discovery", description = "<This crystal shines with a mesmerizing light that you find difficult to avert your gaze from.\n\nPerhaps the Unshackled would be able to tell you more about it.>", objectives = "Bring the Enchanting Crystal to Narv in Newhome.\n\nProvided item:", completion = "I've seen these crystals in a couple of places, often with a weird looking slime nearby. There has to be some sort of link but I've yet to discover it. \n\nAt any rate the only use of these crystals I've found is to get tiny creatures to follow me around for a while.\n\nSorry, that doesn't help you much but you can have your crystal back. Let me know if you figure anything else out." }
WordHunterWoW_QuestEN[56561] = { title = "A Curious Discovery", description = "<This crystal shines with a mesmerizing light that you find difficult to avert your gaze from.\n\nPerhaps the Ankoan would be able to tell you more about it.>", objectives = "Bring the Enchanting Crystal to Instructor Okanu in Mezzamere.\n\nProvided item:", completion = "I've seen these crystals in a couple of places, often with a strange slime nearby. Clearly there is a link between the two but I have yet to discover it. \n\nAt any rate, the only use of these crystals I have found is to hypnotize tiny creatures for a while.\n\nSorry, that does not help you much but you can have your crystal back. Let me know if you figure anything else out." }
WordHunterWoW_QuestEN[56562] = { title = "The Problem with Shrinkage", description = "<Having skinned countless creatures, you can't help but notice how much usable leather is lost when the skin is dried and tanned. The Ankoan seem to have mastered using the material, perhaps Instructor Ulooaka could share some of his insights.>", objectives = "Ask Instructor Ulooaka about the shriveled leather hide.\n\nProvided item:", completion = "Apologies. We are so used to working with these materials, I forgot to explain how to prevent that. These beasts are usually underwater all the time, and the air dries them unevenly. When you skin the beast, roll the skin as you harvest it. This will rehydrate it enough to prevent waste." }
WordHunterWoW_QuestEN[56563] = { title = "The Problem with Shrinkage", description = "<Having skinned countless creatures, you can't help but notice how much usable leather is lost when the skin is dried and tanned. The Unshackled seem to have a solid understanding of using the material, perhaps Rolm could share some of his insights.>", objectives = "Ask Rolm about the shriveled leather hide.\n\nProvided item:", completion = "Ah, yeah, sorry about that. We are so used to working with these materials, I forgot to explain how to prevent that. See, these beasts are usually underwater all the time, and the air dries them unevenly. When you skin the beast, roll the skin as you harvest it. That'll rehydrate it enough to prevent waste." }
WordHunterWoW_QuestEN[56565] = { title = "Hanging by a Thread", description = "<As you peel the hide from the creature's body, you notice numerous scales break off the skin, tearing holes that render portions of the hide useless. The Ankoan seem to have mastered using the material, perhaps Instructor Ulooaka could share some of his insights.>", objectives = "Ask Instructor Ulooaka about the deteriorating cragscales.\n\nProvided item:", completion = "I have seen this many times. The scales of these beasts are not just part of the skin, but connected by tough muscle and sinew. This allows the creature to move through the crushing depths easier. When you are ready to remove the hide, do it in two passes. The first to cut these sinuous fibers, the second to flay it. You will find more of the hide will be usable." }
WordHunterWoW_QuestEN[56566] = { title = "Hanging by a Thread", description = "<As you peel the hide from the creature's body, you notice numerous scales break off the skin, tearing holes that render portions of the hide useless. The Unshackled seem to have mastered using the material, perhaps Rolm could share some of his insights.>", objectives = "Ask Rolm about the deteriorating cragscales.\n\nProvided item:", completion = "I've seen THIS before. See, the scales of these beasts are not just part of the skin, but are connected with muscle and sinew. This allows the creature to move through the crushing depths easier. When you are ready to remove the hide, do it in two passes. The first to free the scales, the second to actually skin it. That way more of the hide will be usable." }
WordHunterWoW_QuestEN[56570] = { title = "Work Order: Greater Flask of the Currents", description = "", objectives = "Are you here to deliver supplies?", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, friend. We needed these flasks badly." }
WordHunterWoW_QuestEN[56572] = { title = "Toys Like Us", description = "I must share the wonders of this place with all of Azeroth in a way that will entertain young and old alike. I will use the technology here to create a new line of toys unlike anything seen before!\n\nMy Quasi-Faceted scanner can help construct perfect replicas of things here on the island. \n\nI just need a helpful individual such as yourself to scan a few things around this area.", objectives = "Quasi-Facet scan creatures in Mechagon", completion = "The first batch of toys is all ready to go!" }
WordHunterWoW_QuestEN[56573] = { title = "Certified Pre-Owned", description = "First, let me say that you will ALWAYS be our favorite test subject.\n\nBut our experiments require far more sacrifice than a single test subject can offer. And, from time to time, some of those test subjects require new limbs.\n\nMy dear brother and I have a nascent concept for expanding the average lifespan of mechanical appendages. But we've run out of components to experiment on.\n\nSalvage some appendages from the heap outside town so we can continue our experiments.", objectives = "Collect 15 Salvaged Mechagnome Appendages.", progress = "Don't worry about any malfunctioning or missing parts. Gill will help us repair whatever you find.", completion = "Wondrous! This should last us...\n\n<Pristy counts the appendages and scribbles in her notebook.>\n\n...at least 3 hours. Wow, we're really churning through these appendages!" }
WordHunterWoW_QuestEN[56574] = { title = "Reflections in Amber", description = "<A viscous dark ooze drips from this large chunk of amber. Attempting to wipe it off is futile, as the ooze is seemingly created by the amber itself.\n\nAs you hold it, unintelligible whispers fill the back of your mind.\n\nThe Shado-Pan will surely want to examine it.>", objectives = "Bring the Ooze-Covered Amber to the Shado-Pan at the Serpent's Spine.", completion = "What is it you have there, <name>?" }
WordHunterWoW_QuestEN[56575] = { title = "Once More Into Kor'vess", description = "You found this on a member of the swarm? It seeps with corruption... and with power. We could be faced with a serious threat if the rest of the mantid's amber is similarly corrupted.\n\nFar to the west in the Dread Wastes lies Kor'vess, a large kypari tree that provides the swarm with most of its amber. From there, we can determine just how much of their stores have been infused with the energy of the Old Gods.\n\nI will meet you closer to the tree.", objectives = "Investigate Kor'vess.", completion = "The mantid appear to be corrupting the entire tree. It is worse than I thought." }
WordHunterWoW_QuestEN[56576] = { title = "Aqir Extermination", description = "There are too many of these things flyin' around for us to make a clean getaway. \n\nWe're liable to get swarmed the second we start up them plane engines!\n\nThese bugs are going straight back into the ground... one way or another. May as well expedite the process, know what I mean?", objectives = "Kill 10 Aqir Impalers.", completion = "That should help keep the runway clear for a bit!" }
WordHunterWoW_QuestEN[56577] = { title = "Crippling the Hive", description = "The mantid here are working feverishly to harvest amber from the tree.\n\nPerhaps killing a pawful of them will slow their efforts.", objectives = "Kill 12 Kor'thik mantid in Kor'vess.", completion = "While it is not a permanent solution, this should buy us some time." }
WordHunterWoW_QuestEN[56578] = { title = "Rotten at the Roots", description = "Underneath Kypari Kor is a large chamber where the mantid tend to the tree. That must be where the source of the corruption lies.\n\nWe need to get into that chamber and stop them. N'Zoth must not be allowed to empower the swarm.", objectives = "Stop the source of the corruption within the Morrowchamber.", completion = "Faceless ones? The kypari trees are sacred to the mantid... but I suppose their devotion to the Old Gods is greater." }
WordHunterWoW_QuestEN[56580] = { title = "Amber Secrets", description = "The Morrowchamber houses a small section of the Zara'thik, mantid under immediate directive of the new empress. Some of them may have been given pieces of amber like the one you found.\n\nThe Shado-Pan would be interested in any extra pieces we can acquire.", objectives = "Collect 8 pieces of Corrupted Amber.", progress = "We always feared this day would come...", completion = "More of this corrupted amber. I need to bring this back to the garrison." }
WordHunterWoW_QuestEN[56616] = { title = "Old Faces, New Problems", description = "One of N'Zoth's minions appears to have taken note of our presence.\n\nShall we pay them a visit?", objectives = "Kill Watcher Vl'thax.", progress = "Is it done?", completion = "Another agent of N'Zoth. It seems the mantid have earned his favor." }
WordHunterWoW_QuestEN[56617] = { title = "A Unified Swarm", description = "It seemed as though the mantid had been producing the corrupted amber for some time before our... intervention. It stands to reason that they are keeping a stockpile of it somewhere.\n\nThe Shado-Pan's scouts have been reporting an increased presence of the swarm's warriors in Klaxxi'vess. I would wager that they are guarding the corrupted amber.\n\nMeet me there. If we have a chance to destroy that amber, then we need to take it.", objectives = "Infiltrate Klaxxi'vess.", completion = "If the entire swarm were empowered by that corrupted amber, N'Zoth would have an unstoppable army under his command." }
WordHunterWoW_QuestEN[56621] = { title = "Real Ultimate Power", description = "When I say that power is life, I'm not speaking figuratively, my dear test subject.\n\nProperly harnessed, power can create life itself--or at least a close enough facsimile for our purposes.\n\nThere is a massive reserve of discarded technology lurking deep in the mucky depths of the Outflow. As usual, Mechagon's trash is our treasure.\n\nI've finally perfected my device that will animate the sludge to bring that technology up to the surface for you.\n\nAll you have to do is pop 'em and grab the tech!", objectives = "Collect 15 discarded technologies from techno-animated sludge.", progress = "Please thoroughly document any adverse side effects you experience while using the Spark-7143.", completion = "Glorious recovery!\n\nAnd you say that the Spark-7143 did NOT cause an extreme burning sensation in your gut?\n\n<Flip makes a quick note and smiles.>\n\nWondrous indeed!" }
WordHunterWoW_QuestEN[56622] = { title = "Ashran Dominance", description = "The Alliance refuse to back down in Ashran. Teach them that the Horde will not stand aside while they plunder the power of the ancient ogre empire to use for their own schemes.", objectives = "Defeat the Alliance at all event locations in Ashran and kill Grand Marshal Tremblade." }
WordHunterWoW_QuestEN[56623] = { title = "Ashran Dominance", description = "As we feared the Horde are trying to consolidate their position here on the island by looting it, just like we feared. Get out there and show them the Alliance won't put up with their aggression.", objectives = "Defeat the Horde at all event locations in Ashran and kill High Warlord Volrath." }
WordHunterWoW_QuestEN[56640] = { title = "Fortunate Souls", description = "You and I survived the attack and have thus far evaded capture by the enemy.\n\nNot all were as fortunate.\n\nThere are many of our allies now under the control of the naga. We must free them before they are killed or suffer an even worse fate.", objectives = "Rescue 7 captive soldiers in Spears of Azshara.", progress = "We are outnumbered, but we are not outclassed.", completion = "Our army was devastated, but we will rebuild." }
WordHunterWoW_QuestEN[56641] = { title = "Disruption of Power", description = "The naga are tapping into some latent power, infusing the energy into some manner of device.\n\nI do not know what purpose they have for this power, but it is surely in our interest to destroy the objects before they can be used against us.", objectives = "Destroy 5 Ley Line Accumulators in Spears of Azshara.", progress = "Can you feel the magic in this place?", completion = "At times it is satisfying to break another's toys." }
WordHunterWoW_QuestEN[56642] = { title = "Dark Tides", description = "A tidemistress leads some nefarious ritual above a pool.\n\nDo not look in the pool when we approach it, or you will be rewarded with a view of our drowned allies.\n\nWe must put a stop to this ritual. The tidemistress is key.", objectives = "Slay Tidemistress Ethendriss.", progress = "We must not underestimate this tidemistress.", completion = "The ritual ceased as soon as we killed the tidemistress." }
WordHunterWoW_QuestEN[56643] = { title = "In Deep", description = "By now, King Greymane and Lady Proudmoore should be in the cave at which we are to meet.\n\nLet's not keep them waiting.", objectives = "Meet Jaina and Genn in the cave within Spears of Azshara.", completion = "I already tire of this place." }
WordHunterWoW_QuestEN[56644] = { title = "Up Against It", description = "We must move quickly if we are to find safety for our people.\n\nThis cave is barely defensible, and much of our army is in an even more precarious position.\n\nLet's search deeper.", objectives = "Move deeper into Nazjatar with Jaina and Genn.", completion = "We have been watching you. Your people seem quite capable." }
WordHunterWoW_QuestEN[56645] = { title = "Heart of the Swarm", description = "We need to know what we're up against. Before we return to the Serpent's Spine, we should take the opportunity to scout the swarm.\n\nI will fly us over the Heart of Fear. We should be able to survey Empress Shek'zara's forces from above. Then we can determine the extent to which N'Zoth has bolstered their ranks with his own.", objectives = "Fly with Taoshi on the Shado-Pan Kite.", completion = "A close call. Thank you, <name>." }
WordHunterWoW_QuestEN[56647] = { title = "The Mantid Threat", description = "The mantid have been corrupting their kypari trees to imbue their amber with power from N'Zoth. The swarm is enough of a menace on its own. N'Zoth could transform them into something even more dire.\n\nThe Shado-Pan need to hear about this. I suggest you bring this information to your other allies as well.", objectives = "Return to Stormspeaker Qian at the Silent Sanctuary.", completion = "That the mantid would give their own kypari trees over to corruption speaks volumes of their loyalty to N'Zoth.\n\nThank you for bringing this to my attention." }
WordHunterWoW_QuestEN[56648] = { title = "Call to Arms: Nazjatar", description = "Our mission in Nazjatar is being compromised by the Horde incursion. \n\nGet into Nazjatar and take out as many as you can.", objectives = "Slay Horde within Nazjatar.", completion = "Good work, <class>." }
WordHunterWoW_QuestEN[56649] = { title = "Call to Arms: Mechagon", description = "Our mission in Mechagon is being compromised by the Horde incursion. \n\nGet into Mechagon and take out as many as you can.", objectives = "Slay Horde within Mechagon.", completion = "Good work, <class>." }
WordHunterWoW_QuestEN[56650] = { title = "Call to Arms: Mechagon", description = "Our objectives in Mechagon are being interrupted by the influx of Alliance scum.\n\nClear as many of them out of the area that you find, then report back.", objectives = "Slay Alliance within Mechagon.", completion = "Good work, <class>." }
WordHunterWoW_QuestEN[56714] = { title = "Contained Alemental", description = "<As the brew is returned to its natural, dormant form, a strange keg appears.\n\nPerhaps Brewmaster Tao knows more about such a strange occurrence.>", objectives = "Talk to Brewmaster Tao in the Brewfest grounds.", completion = "Everything has a spirit to it. From the clouds in the sky to the worms in the ground, life is woven through the entire world.\n\nBrew is no different. Created with such love, such care... it only requires a spark to spring to life in front of our very eyes." }
WordHunterWoW_QuestEN[56715] = { title = "Hozen Totem", description = "<The hozen have been successfully chased away, and Brewfest saved once again.\n\nThe question asks itself, though: How did hozen get to Durotar? Perhaps somebody in the Brewfest grounds has experience with them.>", objectives = "Talk to Zenda in the Brewfest grounds.", completion = "<Zenda spits on the hozen totem.>\n\nDo not be fooled by deir appearance. Dese hozen are ruthless. Some chased my brother out of his own bar in Zuldazar and took it over as deir own!\n\nI have seen dese winged ones, and dey are unwelcome wherever dey go." }
WordHunterWoW_QuestEN[56716] = { title = "Direbrew Cog", description = "<Direbrew's Dark Iron have fled, leaving behind a small piece of one of their mole machines.\n\nYou know they have attacked Brewfest before. Perhaps one of the goblins would be interested in hearing of your victory.>", objectives = "Talk to Blix Fixwidget in the Brewfest grounds.", completion = "So Direbrew still ain't giving up, is he?\n\nWell, thanks for taking care of his lackeys again. Thanks to you, I still have business! Take these tokens as a reward... but be sure to come back and spend them later!" }
WordHunterWoW_QuestEN[56719] = { title = "This Ain't Mine", description = "Your arrival is timely, {name}. Sylvanas's loyalists have collapsed part of the canyon path to Orgrimmar. \n\nWe are cut off from our vanguard and I fear that they will be destroyed if we cannot reinforce them quickly. Our forces are few in number. We cannot afford to leave them stranded for long.\n\nTinkmaster Overspark and Gazlowe believe they have a solution. Hurry and aid them however you can.", objectives = "Clear the pass of boulders, mines, and other obstructions between Razor Hill and Orgrimmar.", progress = "Thank the Light you were able to open the pass.", completion = "We may have rejoined the vanguard, but Sylvanas's forces have been harrying our front line." }
WordHunterWoW_QuestEN[56739] = { title = "The Power of Worship", description = "I was once like them, stuck in a loop and waiting for Azshara to come and save me. Our spirits are locked to this place.\n\nThere are naga in the other parts of these ruins. They have these magical orbs... I think they are using us to fuel their arcane experiments. They draw power from our spirits and our worship of Azshara. This keeps us weakened and unable to break free.\n\nDestroy the orbs. Breaking the connection will allow us to gain strength and move on.", objectives = "Destroy 3 Arcane Energy Transmuters.", progress = "Have you found them all?", completion = "Without the draw of energy, I believe that the other spirits will eventually be able to break out of their loop. They will be able to move on." }
WordHunterWoW_QuestEN[56740] = { title = "S.P.A.R.E. Crates", description = "I'm sure you agree that Pascal-K1N6 is the greatest invention you've ever seen!\n\nIf you're not convinced yet, try to push him to his limits. I don't mind!\n\nBring him more resources and blueprints -- he'll craft anything you need!", objectives = "Craft $1oa Junkyard Tinkering items with Pascal-K1N6.", completion = "Look at all those spare parts you've got in those bags! You're starting to look like a real junkyard tinkerer.\n\nLet me give you a tip, though. Only amateurs carry 'em around all helter skelter like that.\n\nReal experts keep 'em organized efficiently, so we can carry more.\n\nHere, I'll show you how." }
WordHunterWoW_QuestEN[56741] = { title = "The Spear of Destiny", description = "The Javelins are some of the most powerful magical creations of Suramar, before the Sundering. This is just what we need to bring down the wards on the protector and the Tidestone.\n\nWe must hurry back to Mezzamere, Lady Proudmoore needs to know of our success.\n\nThis will change the entire course of our campaign here in Nazjatar, {name}.", objectives = "Return to Jaina Proudmoore in Mezzamere.", completion = "This is an amazing find, <name>. With this, we can assault the guardian of the Tidestone, and secure it." }
WordHunterWoW_QuestEN[56746] = { title = "Our Direct Line", description = "I'm sure you agree that Pascal-K1N6 is the greatest invention you've ever seen!\n\nIf you're not convinced yet, try to push him to his limits. I don't mind!\n\nBring him more resources and blueprints -- he'll craft anything you need!", objectives = "Craft $1oa Junkyard Tinkering items with Pascal-K1N6.\n\nProvided item:", completion = "Madam Goya wishes to convey her appreciation for your continued support of her operations.\n\nShe's asked me to entrust you with the blueprints for our encrypted communication network, so you can always stay in touch.\n\nDo not share this with anyone, <name>.\n\nWe'll be watching." }
WordHunterWoW_QuestEN[56747] = { title = "Rustbolt Requisitions: Akunda's Bite", description = "I've received an urgent request from Tinkmaster Overspark.\n\nThese supplies are needed!", objectives = "Bring 20 Storm Silver Ore to Gila Crosswire.", progress = "I've received an urgent request from Tinkmaster Overspark.\n\nThese supplies are needed!", completion = "Thank you, <name>. Your contribution has been logged in our records for posterity to appreciate!" }
WordHunterWoW_QuestEN[56748] = { title = "Brewfest Chowdown", description = "Mok-rah, {class}! I hope you came with an empty stomach!\n\nBack on Draenor, we often held eating contests at our festivals as a form of celebration. When we were put in charge of Brewfest, we could think of nothing better to add to the event!\n\nTake a seat and show us what you can eat. If you want more details before jumping in, just ask!", objectives = "Participate in the Brewfest Chowdown.", progress = "Eat a sausage, drink some brew, then eat some more!", completion = "Well eaten! Every time you win, you'll receive a token as a reward. Once you collect five, come back to me and I can award you with a beautiful trophy!" }
WordHunterWoW_QuestEN[56749] = { title = "Rustbolt Requisitions: Akunda's Bite", description = "Gazlowe's orders are in: He wants these supplies ASAP.\n\nYa got the goods?", objectives = "Bring 20 Storm Silver Ore to Skaggit.", progress = "Gazlowe's orders are in: He wants these supplies ASAP.\n\nYa got the goods?", completion = "Thanks for pitchin' in.\n\nI'll make sure Gazlowe and Prince Erazmin know these came from you." }
