WordHunterWoW_QuestEN[56756] = { title = "My Punkin, the Action Figure", description = "Heya, {name}.\n\n<Grizzek leans in close and whispers.>\n\nI'm workin' on a surprise for Saffy. Hopin' you can help me out.\n\nI overheard her beggin' Jepetto Joybuzz to make her into one of his fancy new action figures.\n\nThat ol' jerk told her no. Can you believe it? My Punkin!\n\nWell, we don't need him. I reverse engineered a few of his toys and found out what makes them tick.\n\nI got a blueprint ready to go. We can make Saffy's action figure ourselves and surprise her with it!", objectives = "Craft the Sapphronetta Flivvers Action Figure at Pascal-K1N6.", progress = "You've got the spark of discovery in your eyes!", completion = "<Sapphronetta's eyes light up as you hand her the action figure of herself.>" }
WordHunterWoW_QuestEN[56757] = { title = "Rustbolt Requisitions: Winter's Kiss", description = "I've received an urgent request from Tinkmaster Overspark.\n\nThese supplies are needed!", objectives = "Bring 20 Storm Silver Ore to Gila Crosswire.", progress = "I've received an urgent request from Tinkmaster Overspark.\n\nThese supplies are needed!", completion = "Thank you, <name>. Your contribution has been logged in our records for posterity to appreciate!" }
