WordHunterWoW_QuestEN[56771] = { title = "Time-Lost Warriors", description = "According to the scouting report ye found, the Rajani are holed up in the Silent Sanctuary, overlooking Mistfall Village. \n\nThey are described in the report as seclusive and dangerous, so we'd had best take caution when approaching them.\n\nI'll meet ye there.", objectives = "Meet with the Rajani at the Silent Sanctuary.", progress = "What is it, outsider?", completion = "It is of no use. The great Highkeeper is convinced of our fate.\n\nIt will take more than words to move him." }
