WordHunterWoW_QuestEN[56775] = { title = "Warming Up", description = "Prepare yourself, {name}. We're nearing the island where the previous expedition was lost.\n\nWarm up on these combat dummies. We need everyone ready for whatever we find on that island.", objectives = "Warm up by fighting a Combat Dummy.", progress = "Don't be shy. Just walk up to the target dummies, select them, and use your main attack.", completion = "Good, looks like you've kept up your <class> training during our voyage.\n\nI'm concerned about the sudden turn in weather. Spar with Private Cole while I speak with the ship's crew.\n\nCole's report will determine where we'll place you on our initial expedition team." }
WordHunterWoW_QuestEN[56777] = { title = "A Gift From The Clan", description = "Speaker Utia has requested that I direct you back to Mezzamere when you have a chance, {name}.\n\nOur clan has prepared a gift for you to show our appreciation for the courage and valor you have shown in battle against the naga.\n\nI am sure that you will find the gift of supplies to be a valuable addition to your arsenal as you continue your campaign against Azshara.", objectives = "Meet with Speaker Utia.", completion = "You have brought honor to our clan, <name>. Please accept these additional supplies along with our thanks." }
WordHunterWoW_QuestEN[56778] = { title = "A Glint in the Darkness", description = "There are many treasures hidden throughout Nazjatar.\n\nRecently, I spotted an object glinting from within a cave not far from here. It appeared to be some sort of lockbox.\n\nI suggest we head back and investigate. There may be valuable items inside that will help us in our battle against the naga.", objectives = "Loot the Lambent Lockbox." }
WordHunterWoW_QuestEN[56779] = { title = "A Valorous Reward", description = "Your deeds on the battlefield have brought honor upon your Alliance, {class}.\n\nSpeaker Utia has requested your presence in Mezzamere to accept a reward on behalf of our clan.\n\nYou should return to Mezzamere at your soonest convenience.\n\nIt is an honor to fight at your side.", objectives = "Meet with Speaker Utia.", completion = "Please accept this gift of supplies. May it serve you well." }
WordHunterWoW_QuestEN[56780] = { title = "Hidden, But Dangerous", description = "The naga have hidden many useful treasures throughout Nazjatar.\n\nI have heard tell that there is a treasure hoard not far from here. It will be dangerous, but it may be worth investigating.\n\nThere may be untold valuables inside the cache that could aid us in our fight against the naga.", objectives = "Loot the Mystic Chest." }
WordHunterWoW_QuestEN[56781] = { title = "Treasure In The Deep", description = "There are many treasures to be found throughout the naga stronghold of Nazjatar.\n\nSome time ago, I noticed a mysterious looking chest. The area was heavily fortified with naga troops, so whatever it contains must be valuable.\n\nWe should go back and investigate the chest. Whatever is inside is better used in our hands than the hands of the enemy.", objectives = "Loot the Mysterious Cache." }
WordHunterWoW_QuestEN[56782] = { title = "The Speaker's Gift", description = "Speaker Utia has requested your presence in Mezzamere, {name}.\n\nI believe that the Speaker has prepared a collection of items to aid you in your journey.\n\nYou should return to Mezzamere at your soonest convenience and accept the Speaker's gift.", objectives = "Meet with Speaker Utia.", completion = "Please accept this gift on behalf of our clan. May it serve you well." }
WordHunterWoW_QuestEN[56783] = { title = "The Lambent Lockbox", description = "There are many treasures to find throughout these ancient ruins.\n\nSometime ago, I noticed a strange looking chest in a cave not far from here.\n\nThere may be valuable items inside that can help us in our fight against Queen Azshara.\n\nWe should go back and investigate the chest.", objectives = "Loot the Lambent Lockbox." }
WordHunterWoW_QuestEN[56784] = { title = "Helpful Provisions", description = "Speaker Utia is awaiting your return to Mezzamere.\n\nThe Speaker has bundled together some helpful provisions to aid you in your journey.\n\nPlease accept this gift with the thanks of our clan.", objectives = "Meet with Speaker Utia.", completion = "Please accept this gift of supplies. May you be well-equipped in your battles against the naga." }
WordHunterWoW_QuestEN[56785] = { title = "The Mystic Chest", description = "We have uncovered many rare treasures while exploring Nazjatar. I believe that I have found yet another cache of valuable artifacts to retrieve.\n\nSome time ago, I noticed a strangely glowing object in the distance. I believe that it may have been a treasure chest.\n\nWe should go and investigate the object. If it is a treasure chest, its contents may prove valuable in our quest to defeat the naga!", objectives = "Loot the Mystic Chest." }
WordHunterWoW_QuestEN[56786] = { title = "Naga Treasure", description = "The naga have stashed away the spoils of their wars throughout Nazjatar.\n\nEarlier while we were adventuring, I noticed a mysterious looking cache. The chest is located deep within naga territory, so I imagine that whatever is inside is most likely extremely valuable.\n\nWe should retrieve the contents of the cache. Whatever is inside is better used in our hands than the hands of the enemy.", objectives = "Loot the Mysterious Cache." }
WordHunterWoW_QuestEN[56787] = { title = "Additional Supplies", description = "Speaker Utia has asked me to send you back to Mezzamere when you have a moment, {name}.\n\nThe Speaker has some additional supplies that might aid you in your fight against the naga.\n\nPlease return to Mezzamere at your soonest convenience and accept the Speaker's gift with the thanks of our entire clan.", objectives = "Meet with Speaker Utia.", completion = "May these additional supplies aid you in your journey, <name>." }
WordHunterWoW_QuestEN[56788] = { title = "Reclaimed Treasure", description = "The naga have filled Nazjatar with the ill-gotten spoils of war. We should reclaim whatever we come across in our effort to put an end to their tyranny once and for all.\n\nI noticed a strange looking chest in a cave nearby. It appeared to be of naga make.\n\nWe should claim the contents of the cache. There may be valuable items inside that will help us in our battle against the naga.", objectives = "Loot the Lambent Lockbox." }
WordHunterWoW_QuestEN[56789] = { title = "A Gift of Supplies", description = "Speaker Utia has asked that I send you back to Mezzamere at your soonest convenience.\n\nThe Speaker has gathered together a gift of supplies to further aid you in your fight against the naga.\n\nYou should return to Mezzamere at your soonest convenience. Please accept this gift with the thanks of our clan.", objectives = "Meet with Speaker Utia.", completion = "Please accept this gift of supplies. May it serve you well." }
WordHunterWoW_QuestEN[56790] = { title = "Treasure To Find", description = "The naga have stashed away treasures all over Nazjatar.\n\nNot long ago, I noticed an ornately crafted treasure chest hidden in plain view. The area is heavily fortified, but such minor inconveniences have not stopped us yet.\n\nWe should head back there and liberate the contents of the cache.", objectives = "Loot the Mystic Chest." }
WordHunterWoW_QuestEN[56791] = { title = "Mysterious Treasure", description = "We have located many treasure hoards while exploring Nazjatar. I believe that I have found yet another cache for us to liberate.\n\nSome time ago, I noticed a mysterious looking chest. It is held in an extremely dangerous area, so whatever it contains must be valuable.\n\nWe should embark on a mission to liberate the contents of the cache. Whatever is inside is better used in our hands than the hands of the enemy.", objectives = "Loot the Mysterious Cache." }
