WordHunterWoW_QuestEN[56803] = { title = "Just A Friend", description = "Look, mudfoot, I need to make sure a slight current isn't going to knock you over.\n\nI asked Atolia to see if she could pull together some things to make you a little less useless here.\n\nAfter what I saw in that last fight, we should probably head back sooner rather than later.", objectives = "Visit Atolia Seapearl in Newhome.", completion = "As an observation, that you're still putting up with that grump is laudable.\n\nI will see what else I can find, in case you guys are still working together later.\n\nI'm rooting for you." }
WordHunterWoW_QuestEN[56804] = { title = "With Friends Like You, Who Needs Anemones?", description = "I sometimes amuse myself with excursions into Zanj'ir Terrace, where the naga tough guys hang out.\n\nI grab things that could be useful and stash them somewhere I can pick them up later.\n\nI haven't been down there in a while. \n\nI could have something in there you may find useful.", objectives = "See what is in Vim's Cache.I sometimes amuse myself with excursions into Zanj'ir Terrace, where the naga tough guys hang out.\n\nI grab things that could be useful and stash them somewhere I can pick them up later.\n\nI haven't been down there in a while. \n\nI could have something in there you may find useful.", completion = "<The movement of the tentacles provides a lovely breeze in this muggy terrace.>" }
WordHunterWoW_QuestEN[56805] = { title = "That's What Friends Are For", description = "Hmm. I am not admitting to anything, but there is a very small chance that I could have possibly, but not definitely, been mistaken about your whole... thing.\n\nOn the off chance we were still tolerating each other, Atolia mentioned she had another delivery for you.\n\nWe should swing through Newhome.", objectives = "Visit Atolia Seapearl in Newhome.", completion = "We Unshackled help each other. \n\nThis has helped us grow. This has kept us strong... maybe not charming, but strong.\n\nVim is a good friend, especially once you get past his crustacean act." }
WordHunterWoW_QuestEN[56806] = { title = "Friends Through Eternity", description = "You may have noticed by now that me and the sea giants get along great.\n\nThey mostly just want to be left alone. They want to laugh, and they want to tell you stories that make no sense.\n\nA simple life.\n\nWe do share one interest, aside from killing naga, that is sampling interesting brews. \n\nMaedin recently brought in a lovely new keg, I hid it away. When it is ready to be opened, that round will be on me!\n\nCome, take a look!", objectives = "Visit Vim's Round.You may have noticed by now that me and the sea giants get along great.\n\nThey mostly just want to be left alone. They want to laugh, and they want to tell you stories that make no sense.\n\nA simple life.\n\nWe do share one interest, aside from killing naga, that is sampling interesting brews. \n\nMaedin recently brought in a lovely new keg, I hid it away. When it is ready to be opened, that round will be on me!\n\nCome, take a look!", completion = "<There is a message carved into the wood.\n\n\"The best brews are the ones shared with friends.\">" }
WordHunterWoW_QuestEN[56807] = { title = "Real Friends Help Hide Bodies", description = "Bodies... treasures... \n\nI've seen it all, but it was a long time before I found someone worth calling friend.\n\nI am glad I added you to that list.\n\nSo, back to those friends... I have one more place I would like you to see.", objectives = "Find Gorm's Lantern.Bodies... treasures... \n\nI've seen it all, but it was a long time before I found someone worth calling friend.\n\nI am glad I added you to that list.\n\nSo, back to those friends... I have one more place I would like you to see.", completion = "<A plaque reads:\n\nWho you meet on your journey, makes the trip worth taking.\n\nGorm was a good fighter.>" }
WordHunterWoW_QuestEN[56808] = { title = "We're Going To Be Friends", description = "It is going to be fun getting to know you. You're not half bad!\n\nWe kinda got a little gift for you, to welcome you to the neighborhood.\n\nI hope Atolia was able to put together something neat, she didn't have much time.", objectives = "Visit Atolia Seapearl, in Newhome, for your gift.", completion = "Seems like you're fitting in well here. Keep it up, young one!" }
WordHunterWoW_QuestEN[56809] = { title = "Super Friends", description = "You are a super trooper duper friend!\n\nThere is a place I go to visit some of my smaller buddies. I keep some neat things I find in a bag there.\n\nWould you like to see it? \n\nWhat am I asking? Of course you would, let's go!", objectives = "See what's in Poen's Bag.You are a super trooper duper friend!\n\nThere is a place I go to visit some of my smaller buddies. I keep some neat things I find in a bag there.\n\nWould you like to see it? \n\nWhat am I asking? Of course you would, let's go!", completion = "<There is a note inside the bag that reads, \"Remember, Poen, every day is a chance to find the silver lining.\" - Poen>" }
WordHunterWoW_QuestEN[56810] = { title = "A Friend Indeed", description = "My friend, every day with you is a new adventure. \n\nI am sorry your ships crashed, but I am so happy we met!\n\nI heard a rumor, that Atolia found some more goods!\n\nWe should swing by and see what she has this time!", objectives = "Visit Atolia Seapearl, in Newhome, for your gift.", completion = "I haven't seen Poen this happy in such a long time.\n\nYou deserve this and more!" }
WordHunterWoW_QuestEN[56811] = { title = "You've Got A Friend In Me", description = "There are a few spots I enjoy checking out with my friends. \n\nI actually found this amazing... well, I don't know what it is.\n\nThink you could check it out with me?", objectives = "Examine Poen's Hidey Hole.There are a few spots I enjoy checking out with my friends. \n\nI actually found this amazing... well, I don't know what it is.\n\nThink you could check it out with me?", completion = "<It is apparent Poen is a bit of a practical joker.>" }
WordHunterWoW_QuestEN[56812] = { title = "Friendship Is Magic", description = "Every day with you, I feel like I am a better kelfin than I was the day before.\n\nYou have no idea how much that means to me.\n\nI felt like I wanted to do more, be more... help more.\n\nNow, I'm starting to be a real contributing member of the Unshackled.\n\nIt's all thanks to you.", objectives = "Seek out Poen's Wonder.Every day with you, I feel like I am a better kelfin than I was the day before.\n\nYou have no idea how much that means to me.\n\nI felt like I wanted to do more, be more... help more.\n\nNow, I'm starting to be a real contributing member of the Unshackled.\n\nIt's all thanks to you.", completion = "<The motion is quite relaxing.>" }
WordHunterWoW_QuestEN[56813] = { title = "An Unexpected Friend", description = "Oh, {name}, I nearly forgot!\n\nTo help you with your mission here in Nazjatar, Atolia and I put together some items you may need.\n\nWe should swing by and grab them when we have the time!", objectives = "Visit Atolia Seapearl, in Newhome, for your gift.", completion = "Welcome to our lovely, and yet terrifying, little neighborhood. \n\nIf you survive, I may be able to pull together a few more items for you!" }
WordHunterWoW_QuestEN[56814] = { title = "Anytime You Need A Friend", description = "You're not that bad for a... what was it? {race}?\n\nI like when I am reminded to look past appearances. Ha!\n\nBut, really, speaking of hiding things in plain sight, I put some things in a naga crate. It is close to one of their camps in the Spears of Azshara, so they will never suspect it belongs to me!\n\nLet's go see if it is still there.", objectives = "Find Neri's Ruse.You're not that bad for a... what was it? <race>?\n\nI like when I am reminded to look past appearances. Ha!\n\nBut, really, speaking of hiding things in plain sight, I put some things in a naga crate. It is close to one of their camps in the Spears of Azshara, so they will never suspect it belongs to me!\n\nLet's go see if it is still there.", completion = "<There is a faint smell of salt and leather.>" }
WordHunterWoW_QuestEN[56815] = { title = "With A Little Help From My Friends", description = "It has been so long since we have been able to trust anyone not in our little pack of survivors.\n\nI forgot how good it feels. \n\nThank you for reminding me.\n\nAtolia should have the rest of your gift together by now. We should go check in with her!", objectives = "Visit Atolia Seapearl, in Newhome, for your gift.", completion = "You know, if everyone on the land is as great as you, maybe we should visit once we are all free.\n\nIt isn't much, but I hope you find something useful here!" }
WordHunterWoW_QuestEN[56816] = { title = "A Kelfin's Best Friend", description = "There is no better weapon in our fight than knowledge. \n\nKnowing you is proof of that!\n\nI found this thing, it lets me see better than my eyes could ever do before. \n\nWith the water gone, I can see far, too! I have been using it sometimes to see what is happening in Nazjatar.\n\nLet me show you!", objectives = "Examine Neri's Find.There is no better weapon in our fight than knowledge. \n\nKnowing you is proof of that!\n\nI found this thing, it lets me see better than my eyes could ever do before. \n\nWith the water gone, I can see far, too! I have been using it sometimes to see what is happening in Nazjatar.\n\nLet me show you!", completion = "<Etched into the scope, you see the faint words, \"No man is an island, but should you find yourself seeking one, bring this!\">" }
WordHunterWoW_QuestEN[56817] = { title = "Thank You For Being A Friend", description = "Since the waterwall appeared, so much has changed here. \n\nThere is a little spot I found, where you can feel the sea spray on your face. \n\nSometimes I just ride over there and relax.\n\nI will show it to you, if you'd like.", objectives = "Enjoy Neri's Spot.Since the waterwall appeared, so much has changed here. \n\nThere is a little spot I found, where you can feel the sea spray on your face. \n\nSometimes I just ride over there and relax.\n\nI will show it to you, if you'd like.", completion = "<When disturbed, these coral give off a scent of flowers and forests.>" }
