WordHunterWoW_QuestEN[56829] = { title = "Bottom Feeders", description = "Oh this is bad. This is really bad.\n\nEvery time one of the lads makes it down here they don't come back. Things that come down here... they sort of stay down here one way or another.\n\nLet's make a deal. You're a Maw Walker. You go find Cudgelface and the Chamberlain while I get this here carriage back in service and then we all get out of here before somethin' tries to eat us and THEN go to work on us.", objectives = "Find Cudgelface and the Lord Chamberlain.", completion = "Ah good. No one got ate.\n\nCarriage is ready to go when you are." }
WordHunterWoW_QuestEN[56830] = { title = "Summons from the Deep", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[56833] = { title = "Leaders of the Horde", description = "Saurfang has shown his true colors and now enlists the aid of the Alliance. \n\nMeet with those who have remained loyal to the Horde. They are to ready themselves for the battle against our enemies.\n\nAnd as for Eitrigg... bring him to Nathanos. A quick death is too lenient a punishment for his treachery.\n\nGo, {name}. Let us end this.", objectives = "Order the Horde leaders in Orgrimmar to prepare for battle.", progress = "There is no honor in this battle, <name>.", completion = "So be it. Our choices have been made." }
WordHunterWoW_QuestEN[56836] = { title = "The Eternal Palace: Master's Call", description = "The palace hums with the power of Azshara's master. It calls to her, pulling her closer to his power. If we could focus this energy, it would be possible to travel directly to the Wards of the Abyss.", objectives = "" }
WordHunterWoW_QuestEN[56837] = { title = "The Eternal Palace: Master's Call", description = "The palace hums with the power of Azshara's master. It calls to her, pulling her closer to his power. If we could focus this energy, it would be possible to travel directly to the Wards of the Abyss.", objectives = "" }
WordHunterWoW_QuestEN[56838] = { title = "The Eternal Palace: Master's Call", description = "The palace hums with the power of Azshara's master. It calls to her, pulling her closer to his power. If we could focus this energy, it would be possible to travel directly to the Wards of the Abyss.", objectives = "" }
WordHunterWoW_QuestEN[56839] = { title = "Killclaw the Terrible", description = "<You see a crude sign made by the ogres. It contains a warning.>\n\nBIG bear! Bad!\n\nBig bear guard big ogre treasure!\n\nKill after ritual! Get treasure, make more power!", objectives = "Defeat Killclaw the Terrible.", completion = "<You find a cache of treasure, just like the ogres' sign mentioned!>" }
WordHunterWoW_QuestEN[56842] = { title = "Lunar Preservation", description = "My staff has served me well for many years. It has stood by my side, been through many trials... and as I grow older I find myself leaning on it more and more.\n\nIts flowers bloom every Lunar Festival, basking in the Elune's might. They bring me so much joy, I wish for them to stay all year long. I know a way... but my bones are too old to make the trip.\n\nPerhaps you would take the journey for me? Empower my staff in the light of the moon at the moonwells around the world. Then my flowers can stay.", objectives = "Perform the Rite of the Moon at the moonwells scattered around the world. You can find them in Ashenvale, Felwood, Feralas, Moonglade, Stonetalon Mountains, Duskwood, and Mount Hyjal.\n\nIf you let the Blessing of the Moon expire, you will have to start over.", progress = "Flowers flourish under Elune's light. She was always known to cherish them.", completion = "You've done it! I can feel Elune's power within. Now I can enjoy the company of my flowers for the rest of my days.\n\nPerhaps I can do the same for you. If you have flowers you wish to preserve, bring them to me. I may be able to help." }
WordHunterWoW_QuestEN[56877] = { title = "An Extra Sticky Situation", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[56889] = { title = "Wounded Wastewanderers", description = "Ahh, my friend, have you returned to render additional aid?\n\nAs you can see, we are still locked in battle with these creatures, with no end to their numbers in sight.\n\nThis is a war of attrition and we find ourselves at a clear disadvantage as injuries continue to mount.\n\nPlease, assist any of our wounded that you find within the ruins.", objectives = "Heal 6 Wastewander Laborers.", progress = "Do you require additional bandages?", completion = "Your help is greatly appreciated, my friend." }
WordHunterWoW_QuestEN[56903] = { title = "Crown of Courage", description = "I see you are a fan of pink flowers. It is a shame those that make up your crown will one day come to perish.\n\nPerhaps I can help with that.\n\nThough those are ordinary blossoms, I know similar flowers that bloom only during Lunar Festival. If you retrieve them for me, I can imbue them with Elune's power so that you may enjoy them throughout the year.", objectives = "Gather blooms from Eversong Woods, the Hinterlands, and Mulgore.", progress = "Not all flowers are equal. Those that bloom during Lunar Festival have a special bond with Elune.", completion = "Such beautiful flowers! I can feel Elune's might within them.\n\nThis crown shall bring you great courage." }
WordHunterWoW_QuestEN[56904] = { title = "Crown of Prosperity", description = "Your crown is so colorful! Such beautiful pinks and yellows and blues... if only it could last.\n\nAlthough those particular flowers cannot, I know some that can!\n\nSimilar flowers to those bloom every Lunar Festival. They hold a special connection to Elune that I can empower, thanks to you. Retrieve them for me, and we can fashion a crown that you can enjoy year round!", objectives = "Gather blooms from Un'goro Crater, Stranglethorn Vale, and Northern Barrens.", progress = "Elune has a soft spot for flowers. Those that bloom during Lunar Festival are quite special.", completion = "Such a multitude of colors! These flowers will bring happiness to all who see them.\n\nThis crown shall bring you great prosperity." }
WordHunterWoW_QuestEN[56905] = { title = "Crown of Dark Blossoms", description = "Such somber flowers... but they hold a beauty of their own, don't you think? If only they could last.\n\nAllow me to lend my aid.\n\nEvery Lunar Festival, similar flowers to yours bloom around the world. They hold a special connection to Elune... one that I can empower. If you bring them to me, I can preserve them so you may enjoy them long after an ordinary flower would die.", objectives = "Gather blooms from Duskwood, Silverpine Forest, and Desolace.", progress = "The flowers that bloom during Lunar Festival have special properties. I believe it is Elune's light watching over them.", completion = "Ah, what calming flowers. I sense a solemn peace emanating from them.\n\nThis crown shall support you with a silent grace." }
WordHunterWoW_QuestEN[56906] = { title = "Crown of Good Fortune", description = "Those flowers remind me of Elune herself! I wear similar ones year round, to remind me of her watchful grace.\n\nPerhaps you would like to as well?\n\nYour crown is made of ordinary blossoms that will one day wilt and die. It is an unfortunate fate for such delicate beauties, but my crown is made of similar flowers that I made to last year round! If you bring me specific flowers that bloom only during Lunar Festival, I can bless them so that you too can enjoy your crown all year long.", objectives = "Gather blooms from Winterspring, Dun Morogh, and Hillsbrad Foothills.", progress = "Between you and me, I believe these flowers are Elune's favorite. They mirror her lunar radiance so splendidly!", completion = "Ah, flowers that match my own. I can feel Elune's presence within them.\n\nThis crown shall bring you great fortune in life." }
WordHunterWoW_QuestEN[56907] = { title = "Paint Bottle: Nukular Red", description = "<Kram Kelada could make use of this item.>", objectives = "Deliver the item to Kram Kelada.\n\nProvided item:", completion = "Good color choice!" }
WordHunterWoW_QuestEN[56908] = { title = "Paint Bottle: Goblin Green", description = "<Kram Kelada could make use of this item.>", objectives = "Deliver the item to Kram Kelada.\n\nProvided item:", completion = "Good color choice!" }
WordHunterWoW_QuestEN[56909] = { title = "Paint Bottle: Electric Blue", description = "<Kram Kelada could make use of this item.>", objectives = "Deliver the item to Kram Kelada.\n\nProvided item:", completion = "Good color choice!" }
WordHunterWoW_QuestEN[56914] = { title = "Angry Residents", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[56942] = { title = "On The Road Again", description = "Right lads! All aboard!", objectives = "Ride the Carriage.", completion = "We are not getting the carriage through that." }
WordHunterWoW_QuestEN[56955] = { title = "Rebels on the Road", description = "This is unacceptable. The stoneborn rebels have ambushed a convoy intended for the Tithelord. He is the local Harvester who rules this ward. \n\nWe need to get through this mess. The bridge on the far side of this conflict leads to Darkhaven. The Master typically keeps some of his own Stone Legion forces there. \n\nCarve us a way through, Maw Walker. Destroy any who would delay us. We must not keep Sire Denathrius waiting.", objectives = "Slay 5 Stoneborn Rebels.", completion = "Your talents in combat show promise. Perhaps with a few more centuries and a little humility we might make something of you." }
WordHunterWoW_QuestEN[56969] = { title = "Ancient Reefwalker Bark", description = "", objectives = "Yes? What is it?", progress = "Yes? What is it?", completion = "We use reefwalker bark for many things, from buildings to armor. \n\nThis one must have come from one of the elder ones, it's huge! We can make many things from it.\n\nI will distribute this bounty to the camp, thank you!" }
WordHunterWoW_QuestEN[56970] = { title = "Reefwalker Bark", description = "", objectives = "Yes? What is it?", progress = "Yes? What is it?", completion = "We use reefwalker bark for many things, from buildings to armor. \n\nI will distribute this bounty to the camp, thank you!" }
WordHunterWoW_QuestEN[56971] = { title = "Eel Filet", description = "", objectives = "Yes? What is it?", progress = "Yes? What is it?", completion = "My favorite! How did you know?\n\nI will cook it up for the camp, everyone is going to enjoy this." }
WordHunterWoW_QuestEN[56972] = { title = "Fathom Ray Wing", description = "", objectives = "Yes? What is it?", progress = "Yes? What is it?", completion = "That is a nice, juicy wing you have there. \n\nI will cook this up, there's plenty to go around." }
WordHunterWoW_QuestEN[56973] = { title = "Giant Crab Leg", description = "", objectives = "Yes? What is it?", progress = "Yes? What is it?", completion = "Wow, that is a large one. Looks delicious!\n\nI'll make some soup for tonight, the group is going to love it." }
WordHunterWoW_QuestEN[56978] = { title = "To Darkhaven", description = "Across this bridge is the hamlet of Darkhaven. It is fortified by those loyal to Sire Denathrius. These pitiful rebels would not dare approach it.\n\nHowever, getting to it may prove challenging. Here, I shall carry the anima, you make sure no one throws us back into the Endmire.", objectives = "Escort Lord Chamberlain to Darkhaven.", completion = "It may not look like it, but this rebellion is on its last leg. Those who stand against the Master are fools who will know a new form of pain and suffering." }
WordHunterWoW_QuestEN[56979] = { title = "Saving the Siege", description = "In the chaos of the rockslides, Sylvanas dispatched her saboteurs to sneak past our sentries and plant bombs on our siege weaponry. \n\nSeveral of them have already been lost. We cannot afford to lose more.", objectives = "Remove 8 Suspicious Crates.", completion = "Our people are tired and our resources are dwindling. We need every weapon and soldier at our disposal if we are to take the city." }
WordHunterWoW_QuestEN[56980] = { title = "Already Among Us", description = "While some of the Horde have joined forces with us, many within Orgrimmar remain loyal to Sylvanas. Her saboteurs have infiltrated our ranks and are posing as our technicians. Her assassins are lurking in the shadows.\n\nStop any loyalists you encounter, before they can cause any harm.", objectives = "Slay 10 Suspicious Technicians or Loyalist Assassins.", completion = "I wish this bloodshed wasn't necessary." }
WordHunterWoW_QuestEN[56981] = { title = "Strategic Deployment", description = "Saurfang maintains that the key to taking Orgrimmar is to exploit its multiple points of entry. He led the city's defenses for years, and knows its vulnerabilities better than anyone. We are spread thin as it is, but I trust his judgment in this matter.\n\nWe must also fortify Thunder Bluff in case Sylvanas plans to assault it while our forces are committed here.\n\nDeliver these deployment orders to our officers. We will assail all of Orgrimmar's gates at once while also defending Thunder Bluff.", objectives = "Deliver Anduin's deployment orders.", completion = "Our forces are in place. All that is left is to begin the battle." }
WordHunterWoW_QuestEN[56982] = { title = "Before the Gates of Orgrimmar", description = "We have prepared for this battle as best we can, {name}.\n\nI pray that we all survive what is to come.", objectives = "Begin the battle at the gates of Orgrimmar.", completion = "Saurfang... he gave his life so our soldiers wouldn't lose theirs.\n\nNone of us anticipated he would challenge Sylvanas directly. But perhaps she did.\n\n<Jaina shakes her head.> \n\nIt does us no good to debate whether this was part of her plan or if she merely took advantage of an opportunity. We must be on our guard against her schemes.\n\nSaurfang won his final battle. I do not know what will become of the Horde, but I have hope that they will find a new path to follow." }
WordHunterWoW_QuestEN[56993] = { title = "The Price of Victory", description = "Saurfang... how could this have happened....\n\n<Jaina takes a moment to compose herself.>\n\nThe Alliance has known High Overlord Saurfang as both a sworn enemy and an invaluable ally.\n\nAnduin will want to honor his memory. Recall our forces and inform them of what has happened. Genn's soldiers were dispatched to the western gate. You should be able to find him there.", objectives = "Recall the Alliance forces and inform them of what has transpired.", progress = "He died a warrior's death, as he always wanted. I suppose there is some comfort in that.", completion = "Many have lost their lives to this war. Let us hope Saurfang is the last." }
WordHunterWoW_QuestEN[57001] = { title = "Valley of Honor", description = "", objectives = "" }
WordHunterWoW_QuestEN[57002] = { title = "Old Soldier", description = "No matter what doubts he harbored, Saurfang was an honorable soldier. \n\nHe prevented both a civil war within the Horde and the potential destruction of the Alliance. He brought an end to Sylvanas's reign and saved many lives at the cost of his own. \n\nWe shall honor his sacrifice.", objectives = "Speak with Jaina in front of the gates of Orgrimmar.", progress = "Thank you for coming.", completion = "We continue to fall into old habits of mistrust and suspicion. Of hatred and war... \n\nAnd yet, we also find ourselves banding together and rising against the forces that would destroy our world.\n\nI pray that the day will come when we break the cycle for good." }
WordHunterWoW_QuestEN[57003] = { title = "Create Your Own Strength", description = "For something that has been sitting on the ocean floor, there is still power to be found in this item.\n\nTake your piece of Benthic armor to Voidbinder Zorlan. He has been eyeing it with great curiosity.\n\nGo ahead and humor the ethereal and let him have a look.\n\nMaybe he has something to offer.", objectives = "Upgrade a piece of Benthic armor through Voidbinder Zorlan.", completion = "Ancient elven magic and the ocean infusing things with her own power...\n\nI would like to say I'm surprised, but I'm really not.\n\nIt's a good thing you brought those shiny fellows to help sort it all out." }
WordHunterWoW_QuestEN[57004] = { title = "Create Your Own Strength", description = "That Benthic armor you carry has been lost beneath the tides for too long.\n\nThere is still power within it.\n\nVoidbinder Sturzah may be able to provide insight.\n\nTake your find to our intrepid ethereal friend, and see what he can do with it.", objectives = "Upgrade a piece of Benthic armor through Voidbinder Sturzah.", progress = "Were you successful?", completion = "There is bond formed between the ocean and what comes to rest beneath its waves.\n\nThe glowing man will be able to use the Prismatic Manapearls to improve the Benthic items.\n\nThis will prove most beneficial." }
WordHunterWoW_QuestEN[57005] = { title = "Becoming a Friend", description = "Some of our bravest kelfin have volunteered to join you on your adventures, should you ever need a friend.\n\nYou will find they each have their own special interests and they will mark your map with different opportunities every day.\n\nUse the conch when you're ready, choose who you would like to join you, and explore Nazjatar!\n\nChoose wisely! You may only select one friend per day.", objectives = "Use the Calling Conch, choose an ally, and complete 3 ally quests.", completion = "It is good to have you here, <name>.\n\nThat was masterfully handled. You have made the Unshackled excited and hopeful. \n\nI really couldn't ask for more." }
WordHunterWoW_QuestEN[57006] = { title = "A Worthy Ally", description = "Some of our bravest ankoan have volunteered to join you on your expedition.\n\nYou will find each have their own special interests and they will mark your map with different opportunities every day.\n\nUse the Deepflame Campfire when you are ready. Choose a noble ally to join you, and explore what remains of Nazjatar.\n\nChoose wisely! You may only select one friend per day.", objectives = "Use the Deepflame Campfire, choose an ally, and complete 3 ally quests.", completion = "My brethren reported that you were quite skilled in the field, <name>.\n\nWe are honored to have you here." }
WordHunterWoW_QuestEN[57007] = { title = "Invitation of the Master", description = "The great Sire Denathrius, Master of Revendreth, and King of the venthyr, has asked me, his loyal Chamberlain, to escort you safely to his personal gardens. This is an honor never before bestowed upon a living mortal. \n\nYou should feel honored.\n\nCome, join me in the carriage and we shall ride to the castle in style.", objectives = "Ride the Darkhaven Carriage.", completion = "Oh good, still not dead yet?\n\nYou see where the Lord Chamberlain or Cudgelface landed?" }
WordHunterWoW_QuestEN[57008] = { title = "Assault: The Warring Clans", description = "The opportunistic mogu clans seek to take the Vale while its defenders are recovering from N'Zoth's attack. \n\nThey are both cowardly and foolish.\n\nShow them the error of their ways.", objectives = "Drive back the Mogu Assault in the Vale of Eternal Blossoms.", progress = "Yes?", completion = "These pretenders will learn that they must either join the Rajani or be ground to dust.\n\nYou have done well to show them that." }
WordHunterWoW_QuestEN[57009] = { title = "Fame Waits for Gnome One", description = "Tinkmaster Overspark requests your assistance on an important research expedition. \n\nWorking with the esteemed Tinkmaster will certainly be of benefit to your career. It's done wonders for mine!", objectives = "Meet with Tinkmaster Overspark in Boralus.", completion = "Now we can begin the expedition." }
WordHunterWoW_QuestEN[57010] = { title = "Harnessing the Power", description = "Heart Forge online.\n\nInitiate final attunement sequence.\n\nAwaiting input from champion unit {name}.", objectives = "Use the Petrified Ebony Scale atop the Heart Forge to infuse its power into the Heart of Azeroth.", progress = "Standing by.", completion = "Well, well! Looks like the Heart o' Azeroth has got new capabilities, just like MOTHER said!\n\nBe on the lookout fer more o' those essences. They've got tae be all over Azeroth." }
WordHunterWoW_QuestEN[57022] = { title = "Assault: Amathet Advance", description = "", objectives = "" }
WordHunterWoW_QuestEN[57023] = { title = "Weighted Mogu Artifact", description = "", objectives = "" }
WordHunterWoW_QuestEN[57024] = { title = "Rumors of Mechagon", description = "I knew I should've taken that gig with the Greasemonkeys...\n\nGazlowe's crew always get paid, and no dumb risks. I heard they got somethin' big comin' up too...", objectives = "Meet Gazlowe outside the Great Seal in Dazar'alor.", completion = "Well, ain't this a pleasant surprise." }
WordHunterWoW_QuestEN[57025] = { title = "A Plea to Revendreth", description = "Revendreth is quite possibly the most... efficient... realm at extracting anima. Perhaps they can lend aid where others cannot. \n\nKnow that while souls sometimes return from Revendreth, they are never the same when they do. It is a dark realm, where those the Arbiter deems worthy of a chance of redemption are sent.\n\nTheir path, however, is not an easy one.\n\nKah-Sher will assist you in opening the gateway to Revendreth. Meet him in the Ring of Transference.", objectives = "Journey to Revendreth.", completion = "Sorry for the state of things. Usually a venthyr would be here to greet you. Been a while since we seen anyone come through that gate.\n\nAll good, though, as I know the welcome speech better than a good mornin' whipping." }
WordHunterWoW_QuestEN[57026] = { title = "The Sinstone", description = "Well, you ain't like the others. Usually you're supposed to be dead before you come here. Ah well. A sin is a sin and a stone is a stone, as it goes.\n\nLet's get you sorted out with your sinstone. This way, if you please.", objectives = "Take the tour.", completion = "Hopefully these wretched creatures did not bore you with their inane babble." }
WordHunterWoW_QuestEN[57037] = { title = "A Once Sweet Sound", description = "The bells! That sound!\n\nTheir song has been twisted! If their dire toll continues, we will all succumb.\n\n<Eridia presses her hammer into your hands.>\n\nFind the great vespers within the temple and strike them with my hammer. May the mallet's tonal purity restore their true voices!\n\nI will listen for their clarion call and meet you near the bridge. Go swiftly!", objectives = "Cleanse the Vesper of Purity and the Vesper of Harmony.", progress = "Such a bitter sound!", completion = "I can hear their song once more. It is a boon on my mind, but the loudest voice remains. We must silence it before it destroys all that we hold dear." }
WordHunterWoW_QuestEN[57039] = { title = "Valley of Spirits", description = "", objectives = "" }
WordHunterWoW_QuestEN[57043] = { title = "Old Friends, New Opportunities", description = "Greetings, {name}. I have a... strange message for you from a group of goblins.\n\nSomeone named Sassy Hardwrench is asking for your help for what was described as a, \"big job\". \n\nThe word \"big\" was mentioned several times, followed by murmuring about time and money. \n\nSassy is waiting for you over in Stranglethorn Vale.", objectives = "Speak with Sassy Hardwrench in Stranglethorn Vale.", completion = "<Sassy gasps loudly.>\n\nLook at what the cat dragged in! Do you know how long we've been looking for you?" }
WordHunterWoW_QuestEN[57045] = { title = "A Special Delivery", description = "I'm glad you're finally here, {name}. I've got an important delivery to make and you're the goblin I trust most.\n\nYeah, yeah. I know that's not sayin' much, but it's hard to find good help these days!\n\nThis package is for Hobart Grapplehammer. He's got a workshop in Crapopolis and I need you to deliver it to him. He's been working on somethin' big lately!\n\nDeliver the package and for the love of money... DON'T DROP IT!\n\nYou have no idea how long it took me to locate this thing!", objectives = "Deliver the package to Hobart Grapplehammer.", progress = "Gallywix sure has some nerve threatening me in my own laboratory!\n\nHe thinks he can just do whatever he wants to whoever he wants...", completion = "Sassy Hardwrench asked you to deliver this package?\n\nAh! These must be the parts I ordered last month. I can finally begin the final round of testing on my latest invention!" }
WordHunterWoW_QuestEN[57047] = { title = "A Simple Experiment", description = "Now that you've delivered the necessary parts, I can begin testing my latest prototype!\n\nI call it the X-52 Personnel Armor! It will be nearly indestructible!\n\nGallywix has always coveted my inventions and now that he knows about the X-52 I'm sure he'll be up to no good. I've gotta complete the prototype before Gallywix comes up with a way to steal it out from under me!\n\nI could really use an extra set of hands with the experiments.\n\nCan I count on you, {name}?", objectives = "Assist Hobart Grapplehammer.", progress = "We need to complete the X-52 Personnel Armor before Gallywix finds a way to steal the prototype!", completion = "Good work, <name>! The experiments were mostly successful! However, it does look like we'll need to find a new lab assistant for the explosives testing..." }
WordHunterWoW_QuestEN[57048] = { title = "Shopping For Parts", description = "I'm going to need some additional components in order to complete the next phase of testing.\n\nRight now, what we need most are thermoplugs and thermoplug adaptors! I'll explain what they're for later...\n\nCrank Greasefuse runs a shop near the entrance of the town. Go speak with Crank and get him to fork over the necessary parts.\n\nI don't care what they cost, just tell him to bill me later! I can't be bothered to negotiate right now. I need to prepare the modifications to the X-52 Personnel Armor!", objectives = "Speak with Crank Greasefuse.", completion = "Thermoplugs, eh? Yeah I got some more here... but they ain't cheap!" }
WordHunterWoW_QuestEN[57049] = { title = "Vault of Souls", description = "", objectives = "" }
WordHunterWoW_QuestEN[57051] = { title = "Debt Collection!", description = "You need thermoplugs? Well, you came to the right place, kid.\n\nBut I ain't giving 'em to you on credit. There's way too many shlubs who haven't paid me back the money they owe. I'm in over my head here, if I don't get paid fast, I'll be out of business in no time.\n\n<Crank Greasefuse thinks for a moment.>\n\nLook, I tell you what... If you can muscle those no-good goons into paying me my money, I'll give you the thermoplugs as payment.\n\nYou won't find a better deal than that!", objectives = "Collect 8 Unpaid Debts.", progress = "You got my money?", completion = "<Crank Greasefuse takes a moment to count the money.>\n\nIt's all here! Good work, kid! The thermoplugs are all yours. Send my regards to Grapplehammer and tell him to name one of his inventions after me!" }
WordHunterWoW_QuestEN[57052] = { title = "I've Got What You Need", description = "A deal's a deal, {name}. Here's the thermoplugs you ordered!\n\nBe sure to let that ol' grouch Grapplehammer know that I won't be giving out anymore handouts. If he needs more thermoplugs he'd better be ready to pay up.\n\nAnyway, it was a pleasure doing business with you...\n\nNow get lost!", objectives = "Deliver the package to Hobart Grapplehammer.", completion = "Yes! These are exactly what I need to finish the landmines for the upcoming experiment...\n\nOh, I didn't mention landmines?\n\nI thought I did... oh well! I'll explain everything later! It'll be fine!" }
WordHunterWoW_QuestEN[57053] = { title = "Blunt Force Testing", description = "Now that we have the thermoplugs we're ready for our next test of the prototype X-52 Personnel Armor!\n\nUnfortunately, my lab assistants have either quit or expired. What a pity! But their loss is your gain, {name}... now YOU get to wear the X-52 Personnel Armor!\n\nHow exciting!\n\nThe next test will be conducted by my new mechanized lab assistant. Head over to the main workshop and press the big red button to begin.\n\nDon't worry, I'll be giving you directions over the X-52's built in intercom!", objectives = "Complete Hobart Grapplehammer's experiment.", progress = "Everything depends on this experiment!", completion = "<Hobart Grapplehammer examines you closely.>\n\nThis is fantastic! You're currently suffering a moderate amount of internal bleeding, but the prototype X-52 Personnel Armor performed just as I predicted under extreme levels of repeated blunt force.\n\nThe X-52 doesn't have a scratch on it!" }
WordHunterWoW_QuestEN[57058] = { title = "Fun With Landmines", description = "The prototype X-52 Personnel Armor is ready for the final test! \n\nHow are you with loud noises and sudden bursts of concussive energy, {name}?\n\nFor the final test, we're going to strap you into the X-52 Personnel Armor and have you traverse a minefield!\n\nI have placed a refreshing coconut beverage in the center of the minefield. Consider the drink a fitting reward for reaching the oasis and surviving the inevitable explosions in the process!", objectives = "Retrieve the refreshing coconut beverage from the minefield.", progress = "Ballistic testing... IS MY FAVORITE!", completion = "These goons are demolishing my workshop! We've gotta do something fast!" }
WordHunterWoW_QuestEN[57059] = { title = "Let's Rumble!", description = "This is bad, {name}! Real bad!\n\nGallywix and his goons are destroying my workshop, but he's got another thing coming if he thinks I'm gonna hand over the X-52 Personnel Armor!\n\nYou've gotta get down there and clear out his goon squad before this place--AND ALL MY INVENTIONS--go up in flames!", objectives = "Defeat 8 Hired Scoundrels.", progress = "Hurry, <name>! Gallywix and his goons are destroying my worskshop!", completion = "Good work getting rid of Gallywix, <name>, but I've got a bad feeling about this. We need to find a buyer for the X-52 before Gallywix comes back.\n\nWho knows what he'll try next..." }
WordHunterWoW_QuestEN[57067] = { title = "Mogu at the Gates", description = "The time has come. The other mogu clans have set their sights on the Vale of Eternal Blossoms.\n\nThey will not conquer it.\n\nSome of your kind have already gone to the gate to scout out the size of their force. If you think yourself worthy for such a mission, meet them there.", objectives = "Meet Chen and Li Li Stormstout at the Gate of the August Celestials.", completion = "The mogu have not massed in numbers like this since... well I cannot remember!\n\nWe must be careful. They have overtaken the entire plains." }
WordHunterWoW_QuestEN[57068] = { title = "Kite Surveillance", description = "We heard for ourselves that there were mogu attacking, but I had no idea it would be this many!\n\nThere must be a way to stop them before they completely overrun the Vale. Quickly, let us fly over and scout out their numbers.\n\nWe just so happen to have a kite that can carry three people. Usually it's more, but I had a big lunch.", objectives = "Ride Chen's Kite to scout the Mogu armies.", completion = "Oh no, we went down hard. Uncle Chen can't get up! And there are mogu everywhere!\n\nIt's okay. It's fine. We'll think of something." }
WordHunterWoW_QuestEN[57069] = { title = "Cut Off the Heads", description = "Okay. We're stuck in the middle of three mogu armies, and Uncle Chen is too hurt to move yet.\n\nIt's not hopeless though. We have the chance to take out the leaders of these armies. Maybe that will slow them down or distract them long enough for us to get back to the gate!\n\nSee if you can get out there and take down the biggest, baddest mogu you can find. Those will be the commanders.", objectives = "Slay mogu commanders.", completion = "Good job. The mogu are not as strong without their leaders." }
WordHunterWoW_QuestEN[57070] = { title = "Mogu Massacre", description = "I think this is what my friends would call a \"target rich environment.\" As a nicer way of saying \"we're surrounded and probably doomed.\"\n\nYou know what this means. We have to kill as many of these mogu as possible! It doesn't matter how you do it, just take them out!", objectives = "Slay mogu in Kun-Lai Summit.", completion = "That's a lot of mogu down. Hopefully that will thin their ranks enough for us to get out of here." }
WordHunterWoW_QuestEN[57071] = { title = "No Brew Left Behind", description = "My head is... hurting. There can be only one solution.\n\nWe flew over an abandoned brew caravan. You must go find it, and save that brew! That should help bring me back to full strength.\n\nPlus, it would do wonders for the morale of those fighting in the Vale, if we can recover it.", objectives = "Locate the abandoned brew barrels in Kun-Lai Summit.", completion = "<These must be the brew barrels Chen spotted when flying over.\n\nThey are too heavy to carry on your own.>" }
WordHunterWoW_QuestEN[57072] = { title = "Yak of All Trades", description = "<The brew barrels are too heavy and numerous to carry alone.\n\nPerhaps you can find something, or someone, to help you.>", objectives = "Find something to help you carry the brew back to Chen in Mogujia.", completion = "What is this? You found a yak?\n\nAnd what's more, you found brew!" }
WordHunterWoW_QuestEN[57074] = { title = "Our Backs to the Gate", description = "It is most fortuitous that you found this brew, and a yak to carry it on!\n\nBut we cannot remain here. Li Li has healed me up enough to travel. We can ride the yak back to the gate and hope that the mogu do not notice our passing.\n\nLet me know when you are ready to leave.", objectives = "Ride Mobi with Chen and Li Li to the Gate of August Celestials.", completion = "We got through! Now, what are we going to do about all those mogu?" }
WordHunterWoW_QuestEN[57075] = { title = "Liquid Courage", description = "We have to do something about all these mogu. At least to thin their ranks before they invade the Vale!\n\nAs much as Uncle Chen loves his brew, I think we can put it to better use. Let's hop onto that yak and give the mogu something to fear!", objectives = "Mount Mobi and defeat the mogu armies with the power of brew.", progress = "Something must be done about all these mogu, or we will lose the Vale.", completion = "All that lovely brew... gone.\n\nBut let us look on the bright side. There are fewer mogu to contend with now. It is time for us to report back." }
WordHunterWoW_QuestEN[57076] = { title = "Return to Mistfall", description = "We have done all we can here. We know how much the mogu are a clear threat.\n\nThe forge is in great danger of falling into their hands if we lose our hold on the Vale.\n\nLet us return to Mistfall and report to the Rajani. They will want to know what we are up against.", objectives = "Return to Stormspeaker Qian in the Silent Sanctuary in the Vale of Eternal Blossoms.", completion = "So the other clans seek to invade the Vale with their armies?\n\nWe will show them what true might looks like." }
WordHunterWoW_QuestEN[57077] = { title = "Buyers Wanted!", description = "The X-52 Personnel Armor is finally complete and Gallywix has been sent packing with his tail between his legs!\n\nI've got you to thank for this, {name}!\n\nBut we're still not done... the best part is yet to come. We're going to hold an auction and sell the X-52 Personnel Armor to the highest bidder!\n\nSassy Hardwrench should have a list of interested buyers ready to go. Head over to Hardwrench Hideaway and let her know we're ready for the auction!", objectives = "Speak with Sassy Hardwrench in Stranglethorn Vale.", completion = "So the invention is complete, huh? Good work, kiddo! We'll be rolling in moolah in no time!" }
WordHunterWoW_QuestEN[57078] = { title = "The VIP List", description = "While you've been assisting Grapplehammer with his newest invention, I've been hard at work finding potential buyers!\n\nThis is going to be a private auction, so we're only inviting the best and the brightest, the cream of the crop, the creme de la creme... got it?\n\nI've narrowed the potential buyers down to an 'A' list of only the wealthiest, classiest, most connected goblins around... minus Gallywix, of course!\n\nHead out and deliver these invitations while I finish up preparations for the auction!", objectives = "Deliver the invitations to Grapplehammer's private auction.", progress = "This will be an 'A' list event. Only Kezan's finest will be in attendance!", completion = "You delivered the invitations? Good! We're going to need all the help we can get... I've got some bad news for you!\n\nDid I say bad news? I meant REALLY bad news!" }
WordHunterWoW_QuestEN[57079] = { title = "Beat The Crapopolis Outta Him!", description = "Boy am I glad to see you! We've got a bad situation on our hands...\n\nWhile you were away delivering the invitations, Gallywix and his goons took over Crapopolis! They're holding Hobart Grapplehammer hostage until he hands over the X-52 Personnel Armor!\n\nYou have to stop Gallywix before it's too late!", objectives = "Complete the Crapopolis scenario.", completion = "The X-52 Personnel Armor is ruined beyond repair... but at least Crapopolis is saved and Gallywix finally got what he deserves!" }
WordHunterWoW_QuestEN[57080] = { title = "A Fitting Reward", description = "Although the X-52 Personnel Armor's power-core was destroyed during the battle with Gallywix, the invention was a success!\n\nI doubt anyone will be interested in purchasing the rights to the X-52 without a working power-core, so why don't you hang onto the armor instead? It is quite stylish after all!\n\nNow that Crapopolis is saved and Gallywix is conveniently trapped inside of his own mechanical pummeler, I think I'm going to renegotiate that \"contract\" of his.\n\nHe is a \"captive audience\" after all!", objectives = "Thank you for everything you've done for me, <name>! You've saved Crapopolis and put that no good, double-crossing Gallywix in his place!\n\nTake the X-52 Personnel Armor along with my thanks. It looks good on you!Although the X-52 Personnel Armor's power-core was destroyed during the battle with Gallywix, the invention was a success!\n\nI doubt anyone will be interested in purchasing the rights to the X-52 without a working power-core, so why don't you hang onto the armor instead? It is quite stylish after all!\n\nNow that Crapopolis is saved and Gallywix is conveniently trapped inside of his own mechanical pummeler, I think I'm going to renegotiate that \"contract\" of his.\n\nHe is a \"captive audience\" after all!You will learn:" }
WordHunterWoW_QuestEN[57085] = { title = "Empowered War Wagon", description = "", objectives = "" }
WordHunterWoW_QuestEN[57086] = { title = "Legacy of the Mad Mage", description = "<This rather large jewel has an inscription etched on its base:\n\nProperty of Mardivas. If found please return to my laboratory. \n\nPerhaps this laboratory can still be found somewhere?>", objectives = "Investigate Mardivas's Laboratory.", progress = "<The chest appears to be simply constructed, but the locking mechanism hums with arcane energy.>", completion = "<The ancient lock clicks open, revealing the contents within.>" }
WordHunterWoW_QuestEN[57087] = { title = "Baruk Obliterator", description = "", objectives = "" }
WordHunterWoW_QuestEN[57088] = { title = "This Ain't Mine", description = "Sylvanas's loyalists have collapsed part of the canyon path to Orgrimmar. Our forces are now cut off from each other.\n\nWe need to reinforce our front line or the Banshee will pick us off at her leisure. We have come too far to be slain by a thousand cuts.\n\nGazlowe and one of the Alliance's gnomes believe they have an answer. You'd best ensure that their plan does not backfire.", objectives = "Clear the pass of boulders, mines, and other obstructions between Razor Hill and Orgrimmar.", progress = "Hmm. Maybe that goblin's gadgets have some use.", completion = "Swift action saved our soldiers' lives, but there is still more to do." }
WordHunterWoW_QuestEN[57089] = { title = "Vil'thik Hatchery", description = "", objectives = "" }
WordHunterWoW_QuestEN[57090] = { title = "Saving the Siege", description = "The Banshee's spies were able to sneak past our guards in the chaos of the rockslides. They've been planting bombs on our siege weaponry.\n\nGet rid of those bombs.", objectives = "Remove 8 Suspicious Crates.", completion = "Well done. We cannot afford to lose any more of our weaponry to Sylvanas's treachery." }
WordHunterWoW_QuestEN[57091] = { title = "Already Among Us", description = "Sylvanas still commands the loyalty of many within the Horde. The war she started has blinded them with rage and hatred. She exploits that to maintain her support.\n\n<Saurfang scowls.>\n\nThey do not yet see she will lead us to ruin, that her so-called victories are all hollow.\n\nSome of her agents have been spotted lurking within our ranks. Kill them. They will show us no mercy, and will have none in return.", objectives = "Slay 10 Suspicious Technicians or Loyalist Assassins.", completion = "We both have blood on our hands. Today, we will see that it has not been in vain." }
WordHunterWoW_QuestEN[57092] = { title = "Strategic Deployment", description = "For years, I guarded the gates of Orgrimmar. The city's greatest weakness has always been its multiple entrances. We should strike at all of them to seize victory.\n\nWrynn and I have drawn up orders for deployment. The mages will cover our flank. Greymane will close in from the west, and the elves will take the north. We will send Mayla to reinforce Thunder Bluff's defenses in case Sylvanas launches a counterattack.\n\nBring the orders to our commanders.", objectives = "Deliver Saurfang's deployment orders.", completion = "No matter what our strategy, taking Orgrimmar will be no easy task. I should know." }
WordHunterWoW_QuestEN[57093] = { title = "Before the Gates of Orgrimmar", description = "It is time.\n\nWe have done all that we can to prepare. All that remains is the battle itself.\n\nI am not one for speeches. So I will say only this.\n\nLok-tar ogar, {name}. Victory. Or death.", objectives = "Begin the battle at the gates of Orgrimmar.", completion = "Saurfang... slain by dark magic... \n\nI have known Sylvanas for years, yet I have never seen her wield such power. Why reveal it to us now? What does she gain by abandoning the Horde?\n\n<Lor'themar's eye narrows.>\n\nWhatever she has planned, it would seem that she no longer requires the Horde to achieve it. We will need to be cautious, <name>. There is no telling what her next move will be." }
WordHunterWoW_QuestEN[57094] = { title = "The Price of Victory", description = "Saurfang... I...\n\n<Lor'themar takes a moment to compose himself.>\n\n...Thrall will wish to honor Saurfang's sacrifice. And so shall the rest of us.\n\nRecall our forces. Let them know what has transpired. Tell them that the great warrior Varok Saurfang is dead and that the warchief has abandoned us.\n\nSpeak to Baine when you arrive in Thunder Bluff. You will find him on the Elder Rise. I am certain he will want to pay his respects to Saurfang as well. \n\nLet us stand as a united Horde once more.", objectives = "Inform Baine Bloodhoof of what has transpired.", progress = "He earned the warrior's death he always sought. There is honor in that.", completion = "Saurfang's death will not be in vain." }
WordHunterWoW_QuestEN[57095] = { title = "Old Soldier", description = "No matter what anyone says, he was an honorable orc. A legend in his own right, the ideal to which all warriors of the Horde aspired. \n\nHe gave his life to heal the rift in the Horde and give us the chance to forge a new path forward. His was more than a death befitting a warrior. It was the death of a hero.\n\nWe shall honor his sacrifice.", objectives = "Honor High Overlord Saurfang.", completion = "He will be buried in Nagrand, as he would have wanted.\n\nI do not know what lies ahead for the Horde, but I know we will face it together." }
WordHunterWoW_QuestEN[57098] = { title = "The Grove of Terror", description = "Ah, yes. You've done me a great favor in delivering the Accuser, Maw Walker. \n\nTo celebrate, I must insist that you take part in a sacred tradition of Revendreth: The Penitent Hunt. It is a duty we undertake to strike a humbling fear into the hearts of the most... stubborn souls.\n\nFear can be a very powerful motivator for change.\n\nMeet the Fearstalker in the Grove of Terror below. There you will prepare.", objectives = "Meet the Fearstalker in the Grove of Terror.", completion = "Welcome to the Grove of Terror.\n\nHere you will see the beginning of the process for the anima you seek." }
WordHunterWoW_QuestEN[57099] = { title = "A Dreadful Roundup", description = "Welcome to The Banewood, Maw Walker.\n\nAs Huntmaster it is my duty to lead the Fearstalk. Our first order of business is to collect the souls selected for the hunt.\n\nIn the woods behind me we have souls who have been ripening for several hundred years now. Go choose the souls who will be hunted today.", objectives = "Collect 6 Condemned Souls." }
WordHunterWoW_QuestEN[57100] = { title = "Feeding Time is Over", description = "A crucial element to a successful Fearstalk is our tool: the fangs of a terrorbeast.\n\nTheir fangs are perfect for revealing the scent of their prey once bound to a soul. There's plenty of them in the forest surrounding the ripening souls. \n\nGo and collect some from their corpses. Their population is a bit large right now anyhow.", objectives = "Kill Winged Terrorbeasts and collect 6 of their fangs." }
WordHunterWoW_QuestEN[57101] = { title = "Zan-Tien Serpent Cage", description = "", objectives = "" }
WordHunterWoW_QuestEN[57102] = { title = "Pardon Our Dust", description = "Ah yes, the Greeter.\n\nIt seems this Mnemis unit has been deactivated. Anima has been so scarce of late, and with no new souls entering our gates... I suppose it was a prudent measure. Anima is our most precious resource, after all.\n\nThere are some centurions nearby. A portion of their anima could serve our needs.\n\nAh! One of our most helpful stewards is here to lend her aid. She will guide you in the collection effort.\n\nReturn when you have sufficient anima and we will power the Greeter once more.", objectives = "Collect anima from nearby centurions.", progress = "<The centurion is unresponsive.>", completion = "<The centurion emits a soft chime.>" }
WordHunterWoW_QuestEN[57103] = { title = "Upgrade Your Vehicle (Optional)", description = "", objectives = "" }
WordHunterWoW_QuestEN[57104] = { title = "Expedition GG-118 Micro-Jetpack", description = "", objectives = "" }
WordHunterWoW_QuestEN[57105] = { title = "Upgrade Your Jetpack (Optional)", description = "", objectives = "" }
WordHunterWoW_QuestEN[57106] = { title = "Expedition A.T.O.M.I.K. Mk. II", description = "", objectives = "" }
WordHunterWoW_QuestEN[57107] = { title = "Upgrade Your A.T.O.M.I.K. Mk. II (Optional)", description = "", objectives = "" }
WordHunterWoW_QuestEN[57112] = { title = "Test Shared Quest", description = "None", objectives = "" }
WordHunterWoW_QuestEN[57113] = { title = "On Lysonia's Trail", description = "Our scouts have reported spotting Lysonia and Uther en route to the Temple of Humility.\n\nAs the de facto leader of the Forsworn, we must not allow her to stand free, twisting the minds of those around her.\n\nThe disciples of Humility have not answered our beckons. I have sent Kleia ahead to reconnoiter. Meet her outside the temple.", objectives = "Meet Kleia outside the Temple of Humility.", completion = "The entire temple is overrun with Forsworn. We must find the survivors!" }
WordHunterWoW_QuestEN[57114] = { title = "Aerial Reconnaissance", description = "The temple grounds are crawling with those loyal to the Forsworn.\n\nIf I were still an aspirant, this task would be monumental. Luckily, that is no longer the case.\n\nLet us survey the situation from the sky. We can both take stock of the challenges ahead and find any survivors we can.", objectives = "Fly with Kleia to find the survivors.", completion = "Fortunate that you both found us. \n\nThere are many wounded. I have been able to keep them alive, but it has taken all of my focus. You must help us push back against the Forsworn." }
WordHunterWoW_QuestEN[57115] = { title = "Sacred Scrolls of Humility", description = "The Forsworn are ransacking the library, looking for specific texts amongst our archives.\n\nWe cannot allow them to uncover the scrolls they are searching for. Find any set aside scrolls and return them to me for safekeeping.", objectives = "Collect 5 Sacred Scrolls.", progress = "The scrolls throughout these temples cover many topics, from information on different worlds, to training pillars, to ancient rituals.", completion = "It seems they are gathering information on performing one of our strongest rituals. But for what purpose?" }
WordHunterWoW_QuestEN[57116] = { title = "Succumbing to Pride", description = "The aspirants that spend the most time at this temple are those who must face their pride.\n\nI was one of them, once.\n\nDuring our surveillance, I saw Forsworn forcing these aspirants to fall to their vices then toss them aside as if they meant nothing.\n\nYou must stop the Forsworn. Free the aspirants from a terrible fate.", objectives = "Free 5 Burdened Aspirants by stopping Forsworn rituals.", completion = "Thank you, <name>. These aspirants will live to improve themselves and serve Bastion." }
WordHunterWoW_QuestEN[57117] = { title = "Fallen to Their Vices", description = "Lysonia's forces ransack our sacred temple... they are long gone from the Archon's embrace.\n\nIt pains me to say, but you must defeat them so they can no longer abuse our people.\n\nTake Compassion with you. You will find it more than helpful, now that its power has returned.", objectives = "Defeat 15 Forsworn forces in the Terrace of Inner Grace.", completion = "Fighting the Forsworn, our brothers and sisters... it never gets easier." }
WordHunterWoW_QuestEN[57118] = { title = "Distorted by the Maw", description = "Lysonia's forces are rerouting the anima collectors to spew Maw energy across the temple. They hamper our forces while strengthening their own.\n\nThe collectors have been tainted. Take Compassion and destroy them to halt Lysonia's boon.", objectives = "Destroy 3 Anima Collectors in the Terrace of Inner Grace.", completion = "Do not worry about the collectors. With the drought, they have been barely functioning for quite some time." }
WordHunterWoW_QuestEN[57120] = { title = "Compassion, Blade of Humility", description = "<You find a familiar sword impaled into one of the Forsworn corpses. The Paragon of Humility must have left it behind in pursuit of Lysonia.\n\nIt seems inert, as if all its anima has been used. Perhaps you could restore it to its usual glory.>", objectives = "Charge Compassion, Blade of Humility by killing manifestations.", progress = "The Paragon rarely uses his weapon. He prefers debate and reason over the use of force.", completion = "Compassion!\n\nThe Paragon chased Lysonia in such a rush, he left his sword behind. This may be key to expelling the Forsworn from the temple.\n\nTake it with you, and may it serve you well." }
WordHunterWoW_QuestEN[57121] = { title = "The Power of the Maw", description = "Lysonia flees to the Maw to enact her dark rituals. As the Maw Walker, you are the only one who can pursue her.\n\nTake Kleia and my blade. She must be stopped.", objectives = "Enter the Maw with Kleia, then meet her outside Perdition Hold.", completion = "I can feel the oppression here, as if it were a real weight on my body." }
WordHunterWoW_QuestEN[57122] = { title = "A Step Too Far", description = "My initial scouting revealed things I did not believe at first.\n\nThe Mawsworn hold Forsworn captive here, transforming them against their will.\n\nThough the Forsworn stand against the Archon, they are still kyrian. It is our duty to free them.", objectives = "Free 5 Captive Forsworn.", progress = "I cannot stand idly by while my brothers and sisters are tormented.", completion = "Exiled by the Archon... failed by Lysonia...\n\nWhere can they go?" }
WordHunterWoW_QuestEN[57123] = { title = "Kyrian No More", description = "Mawsworn kyrian... I have not seen one since that vision when we first met.\n\nI am not intimidated. They are enemies of Bastion, of the Archon, and it is our duty to defeat them.", objectives = "Kill 15 Mawsworn forces.", completion = "If my mind were ever to be twisted by the Maw... I ask that you cut me down.\n\nI cannot bear the thought." }
WordHunterWoW_QuestEN[57124] = { title = "Her Will, Inflicted", description = "I feel myself drawn across the double bridges to the west...\n\nLysonia must be there.\n\nCome, {name}. We must confront her before she can escape again. Who knows what she plans.", objectives = "Confront Lysonia in the Altar of Domination.", completion = "It seems that... I am the fool." }
WordHunterWoW_QuestEN[57125] = { title = "Time to Reflect", description = "I knew that Devos had powerful allies. I turned a blind eye. When Lysonia took her place... I was blinded by my loyalty.\n\nI have much to reflect on.\n\nWe may not be allies, but I have one request. Please, escort me from this wretched place. I will leave you be... but do not leave me here in the Maw.", objectives = "Speak to Kleia to exit the Maw, then return to Polemarch Adrestes in Elysian Hold.", completion = "It is unfortunate to hear that Lysonia has escaped us again... The revelations of both her master and her new powers are quite concerning." }
WordHunterWoW_QuestEN[57126] = { title = "...And Following Seas", description = "My brother Derek died in the Second War, only to be raised against his will by the Banshee Queen. If not for Baine Bloodhoof's courageous act of defiance, Derek would have been turned into a weapon against my family.\n\nHe's lived in torment since his awakening. I feared he would be lost to us, but he has received help from an old friend of mine who has also been recently raised--Calia Menethil. She has guided him back from the brink of despair.\n\nI am on my way to pay them a visit. Care to join me?", objectives = "Visit Derek Proudmoore and Calia Menethil.", completion = "Welcome. It's nice to have company.\n\nAh, Jaina has arrived." }
WordHunterWoW_QuestEN[57129] = { title = "Valley of Wisdom", description = "", objectives = "" }
WordHunterWoW_QuestEN[57130] = { title = "Traitors In Our Midst", description = "There is a difference between loyalty and blind obedience. I am done following the Banshee's orders!", objectives = "Deal with this traitor.", completion = "The warchief has long suspected that this traitor lacks the necessary resolve.\n\nYou, on the other hand... You understand." }
WordHunterWoW_QuestEN[57131] = { title = "Let the Hunt Begin", description = "One step remains until we may begin the Penitent Hunt.\n\nYou and the other hunters will first siphon a small amount of anima from the souls. It will come with ease. The soul's time in the Grove of Terror causes trace anima to release.\n\nThis anima helps us venthyr in tracking the prey's fear.\n\nI also ask that you do us the honor of signaling the hunt.\n\n<The Fearstalker hands you an anima stake and a hollowed dredbat fang.>\n\nUse these to complete the task.", objectives = "Complete the hunting ritual at Wanecrypt Hill.", progress = "The ceremony must continue.", completion = "Well done. Perhaps in death you will make a fine hunter.\n\nI can practically taste the fear we will inflict." }
WordHunterWoW_QuestEN[57136] = { title = "The Penitent Hunt", description = "You will descend upon these poor souls. Remember, you are helping them and Revendreth through the terror you bring. When a soul is filled with fear, their resistances to our methods falter.\n\nThe Master has requested that you hunt the Accuser yourself. But we must prey upon some of the others first.\n\nI will be able to guide you through your first hunt.", objectives = "Speak to the Fearstalker in Wanecrypt Hill and participate in the Penitent Hunt.", progress = "The souls must be hunted.", completion = "Well done. The fear we struck allowed us to extract ample anima for Revendreth.\n\nOnto our final target." }
WordHunterWoW_QuestEN[57146] = { title = "Corruption Tear", description = "", objectives = "" }
WordHunterWoW_QuestEN[57147] = { title = "Not My Warchief", description = "There is little time. Sylvanas likely knows of my intentions and sent you to deal with me accordingly. I doubt she will be pleased with your decision.\n\nWe must make our way to the wyverns and take to the skies.", objectives = "Escape with Eitrigg and meet up with Saurfang in Razor Hill.", completion = "Eitrigg told me of your escape from Orgrimmar. There may still be other dissenters within the city who are unable to leave such as you did.\n\nAll we can do for them now is end this battle before Sylvanas makes them suffer." }
WordHunterWoW_QuestEN[57148] = { title = "Siegebreakers", description = "The fools who follow Saurfang have grown bold enough to launch a direct assault. We cannot allow these pests to swarm before our gates.\n\nOur operatives are collapsing the pass between Razor Hill and Orgrimmar as we speak. Saurfang's treasonous forces will be cut in half.\n\nYour task is to sneak into their ranks and sabotage their siege engines. Wear this disguise, but know that it will not hold up under close examination. Slay anyone who discovers you.", objectives = "Covertly place Suspicious Crates and slay guards.", completion = "I weep for them. The fools.\n\n<Nathanos smirks.>" }
WordHunterWoW_QuestEN[57149] = { title = "Propaganda Takedown", description = "Recently, dissidents have been posting propaganda around the city and spreading all manner of lies.\n\nThis is no time to entertain delusion. An army of traitors and sworn enemies assembles at our gates. These ingrates would see us become pin cushions for the Alliance's archers.\n\n<Nathanos rolls his eyes.>\n\nTear down the rubbish. It can only lead to panic in the streets. \n\nAnd should you encounter any... resistance... you are hereby authorized to respond with force.", objectives = "Burn Dissident Propaganda in Orgrimmar.", completion = "Well done. I expect you faced little resistance of note." }
WordHunterWoW_QuestEN[57150] = { title = "Militia", description = "The war has proven costly and our ranks have been steadily depleted. But the Horde is nothing if not strong. Each and every citizen of Orgrimmar is worth ten Alliance weaklings on the battlefield.\n\nRally the citizens and form a militia! Remind them of their slain brothers and sisters!", objectives = "Rally the citizens of Orgrimmar.", completion = "Our armies swell while those of our enemies wither away." }
WordHunterWoW_QuestEN[57151] = { title = "A Line in the Sand", description = "Now that we have put our house in order, it is time to purge the filth before our gates.\n\nHow thoughtful of those traitors to gather themselves in one place, so that we may slay them all in one fell swoop.\n\nLet us end this pitiful rebellion.", objectives = "Speak with Nathanos.", completion = "I have orders for you from the Dark Lady. She instructed me to deliver them on her behalf, should things play out this way." }
WordHunterWoW_QuestEN[57152] = { title = "Most Loyal", description = "The Dark Lady anticipated this as a possible outcome. She has prepared a contingency plan to deal with it accordingly.\n\nYou are to rendezvous with her in the Ghostlands. Take this hearthstone. It is good for one more use. \n\nShe will meet you near Windrunner Spire.", objectives = "Speak with Sylvanas Windrunner.", completion = "You will be remembered for your loyal service." }
WordHunterWoW_QuestEN[57153] = { title = "Dwarven District", description = "", objectives = "" }
WordHunterWoW_QuestEN[57155] = { title = "Blinding the Eye", description = "Ah yes, just the {class} I wanted to see.\n\nI can still sense his touch lingering upon you. Our victory over the god of the deep will not be complete until we remove all traces of his infection.\n\nThrough my research I have learned a less painful way of removing the infection.\n\nSpeak with me, and let's put an end to this nightmare.", objectives = "Speak with Brother Pike to cleanse your \"gift\".Ah yes, just the <class> I wanted to see.\n\nI can still sense his touch lingering upon you. Our victory over the god of the deep will not be complete until we remove all traces of his infection.\n\nThrough my research I have learned a less painful way of removing the infection.\n\nSpeak with me, and let's put an end to this nightmare.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[57156] = { title = "Blinding the Eye", description = "You finally arrived {name}. Dat dark mojo on you has lingered for too long. N'Zoth be defeated and we need to cleanse all de traces of his infection from you.\n\nDis won't hurt. Much.\n\nTell me when you are ready to begin.", objectives = "Speak with Nailok to cleanse your \"gift\".You finally arrived <name>. Dat dark mojo on you has lingered for too long. N'Zoth be defeated and we need to cleanse all de traces of his infection from you.\n\nDis won't hurt. Much.\n\nTell me when you are ready to begin.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[57157] = { title = "Assault: The Black Empire", description = "It is just as the visions fortold. Dark forces have come to claim the Forge of Origination.\n\nThey must be stopped, or all of Azeroth will meet its end!", objectives = "Drive back the N'Zoth Assault in Uldum.", progress = "The madness... it consumes!", completion = "The voices have stopped. The visions show me the dawn.\n\nWe will survive this day, thanks to you." }
WordHunterWoW_QuestEN[57158] = { title = "Electric Empowerment", description = "", objectives = "" }
WordHunterWoW_QuestEN[57159] = { title = "A Reflection of Truth", description = "I sent the Fearstalker far from here with that trap--buying us some time.\n\nOn the other side of this mirror lies the depths of Castle Nathria, the fortress of Denathrius himself. There, a meeting between Denathrius and one of his lackeys is about to take place.\n\nJoin me through the mirror, {name}. You shall see the truth of this \"drought\" first hand.", objectives = "Follow the Accuser through the mirror and witness the truth of Revendreth.", completion = "We barely made it. Denathrius will surely be on our trail soon." }
WordHunterWoW_QuestEN[57161] = { title = "I Don't Get My Hands Dirty", description = "You heard Sire Denathrius. Today, I ascend to the Court of Harvesters.\n\nYou are fortunate to have the honor of witnessing my rise to power.\n\nThe traitors have barricaded the bridge ahead. Clear a path for me, so that I might cross it undisturbed.\n\nNothing can stand against me now that I have a Harvester's medallion.\n\nBut I will not waste my power on this rabble.", objectives = "Clear the bridge for Lord Chamberlain.", progress = "Clear the way for Lord Chamberlain!", completion = "<Echelon grunts.> You're late." }
WordHunterWoW_QuestEN[57164] = { title = "Devour This", description = "Though the souls are our primary target, another challenge has arisen.\n\nThe Banewood has seen an infestation of devourers: disgusting vermin who gorge themselves on the anima we need to survive. A fitting challenge for any true hunter, no?\n\nI should only thank the Master that they have remained in a few secluded pockets. I loathe to think that their numbers could multiply. Let us exterminate them before they pose a true threat.", objectives = "Eliminate the devourers in the Banewood.", progress = "Are the devourers finished?", completion = "Once you master fear, all crumble before you." }
WordHunterWoW_QuestEN[57165] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[57167] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[57171] = { title = "Goldbough Guardian", description = "", objectives = "" }
WordHunterWoW_QuestEN[57172] = { title = "Break Their Will", description = "The timing of your arrival is a sign. You are the force behind the Arbiter. The only one to walk in and out of the Maw in ages. You are the symbol that can help crush this rebellion once and for all.\n\nOnly one leader remains who is strong enough to command the Darkwing Legion. The Accuser. Defeat her, and the rebellion will fall.\n\nHere, take this medallion. Place it in the hands of my faithful Lord Chamberlain in the Grand Palisade. Together, you and he can crush this rebellion.", objectives = "" }
WordHunterWoW_QuestEN[57173] = { title = "The Accuser's Sinstone", description = "Lord Chamberlain will cross the bridge when it pleases him.\n\nBefore he arrives, you will seize the Accuser's sinstone.\n\nWise venthyr like Lord Chamberlain hide their sinstone, so that it can never be used against them.\n\nThe Accuser is too proud to hide her sinstone. Instead, she puts it on display for all to see.\n\nBoasting of the many, many sins she's overcome.\n\nProud. Arrogant. Most importantly, foolish.\n\nHer sinstone lies on the altar before us, seemingly unguarded. Retrieve it.", objectives = "Investigate the Accuser's sinstone.", completion = "Is that truly the best you have to offer?" }
WordHunterWoW_QuestEN[57174] = { title = "The Stoneborn", description = "The Stone Legion is not even here yet? This is an outrage.\n\nIf we do not do something quickly, the rebels will overrun this filthy hamlet.\n\nHere, take the anima and go activate a few of the stoneborn along the periphery of Darkhaven. Take whatever is left over to the Quartermaster and tell her to do her job.\n\nI will try to commune with the Master and see if he can send reinforcements.", objectives = "Collect the Anima Cage and then awaken 6 Stoneborn Guardians.", progress = "Darkhaven. Such a pitiful hamlet filled with unworthy supplicants.", completion = "This is all that remains of our tithe? The Tithelord is not one for excuses. We may need to gather a second tithe quickly or he will condemn us all to the Ember Ward." }
WordHunterWoW_QuestEN[57175] = { title = "Inquisitor Vilhelm's Sinstone", description = "Inquisitor Vilhelm has taken exceptional precautions to protect his sinstone.\n\nBroken into several pieces and hidden from sight, he believed his sinstone would be safe from us.\n\nBut his plan had the same weakness as most: he trusted weak-willed underlings.\n\nI \"interrogated\" several dredgers to learn where they helped the inquisitor hide the broken fragments of his sinstone.\n\nFind all the fragments and bring them to me.", objectives = "Collect the 3 Hidden Sinstone Fragments.", completion = "<As Echelon holds the sinstone fragments, anima binds draw the pieces into one another, reforming into a completed sinstone.>\n\nWe are ready to proceed." }
WordHunterWoW_QuestEN[57176] = { title = "Sinstone Delivery", description = "Lord Chamberlain has held off the Accuser to buy us the time we needed to break the ward on her sinstone.\n\nBut, thanks to your delays, our reinforcement of his position is overdue.\n\nI will collect the Accuser's sinstone and carry us to the battle.", objectives = "Fly with Echelon and deliver the Accuser's Sinstone to Lord Chamberlain.", completion = "This is, in fact, one of the larger sinstones I have seen.\n\nThis will be easy to exploit." }
WordHunterWoW_QuestEN[57177] = { title = "A Fresh Start", description = "", objectives = "" }
WordHunterWoW_QuestEN[57178] = { title = "The Master Awaits", description = "Maw Walker, I am General Kaal. Those stoneborn who remember their oaths to the Master are under my command.\n\nThe path between here and Sire Denathrius is no longer secured by my forces. I am pulling my troops from this ward to support the Master's will elsewhere. \n\nSire Denathrius has dispatched me to bring you directly to him. Myskia can carry you.", objectives = "Meet Sire Denathrius.", progress = "Mind your manners when speaking to Sire Denathrius. He is a being older than your world.", completion = "Wait! Please, Maw Walker, allow me to announce you to the Master." }
WordHunterWoW_QuestEN[57179] = { title = "The Authority of Revendreth", description = "{name}, a proud {race} {class}. I know your name and your deeds. I can taste your regrets and your shame.\n\nMore importantly, I know what you might become. You can be the beacon for the Shadowlands to rally behind. The symbol my people need to set aside these petty squabbles and help fix the problems that afflict all reality.\n\nBefore you stands the Court of Harvesters, my most loyal and trusted venthyr. Where once there were seven, only four remain. \n\nIntroduce yourself to them, for where they go, my power follows", objectives = "Accept the Master's Boon.", progress = "My eyes are everywhere.", completion = "Now, Maw Walker, arise as a weapon of ordained power within my dominion." }
WordHunterWoW_QuestEN[57180] = { title = "The Accuser's Secret", description = "Now that I possess the Accuser's sinstone, I can finally end her treasonous charade once and for all!\n\nProtect me while I study this sinstone, and you will be rewarded as first among my retainers.\n\nAfter I crush her with my incredible power, I will seize control of the Halls of Atonement and receive the Master's reward.\n\nThis feat heralds my own ascension to the Court of Harvesters!", objectives = "Help Lord Chamberlain defeat the Accuser.", completion = "<Lord Chamberlain smiles wryly.>\n\nThe Halls of Atonement are under my control." }
WordHunterWoW_QuestEN[57182] = { title = "The Accuser's Fate", description = "You now stand in the presence of a Harvester, Maw Walker.\n\n<Lord Chamberlain breathes in deeply and smiles.>\n\nI will use the Accuser's medallion to solidify my foothold over the Halls of Atonement.\n\nMeanwhile, the Master has requested that you deliver both the Accuser and the medallion that he loaned to me.\n\nMyskia will be along shortly to retrieve you. Do not keep the Master waiting.", objectives = "Ride Myskia and deliver the Accuser to Sire Denathrius.", progress = "I trust you have the medallion that I loaned to the Lord Chamberlain?", completion = "<Sire Denathrius smiles as you hand him the medallion.>\n\nI am pleased to see that you can be trusted with great power." }
WordHunterWoW_QuestEN[57185] = { title = "Dutybound", description = "Welcome to the fight, {name}. You're with us now.\n\nTake a moment and introduce yourself. I will meet you by Draven at the lodge.", objectives = "Introduce yourself to General Draven, Nadjia the Mistblade, and Rendle." }
WordHunterWoW_QuestEN[57189] = { title = "Breaking the Hopebreakers", description = "The Fearstalker has surely sent her hunters across the entirety of the Banewood in search of us, {name}. \n\nDraven informed me that some of her top hunters are scouring Dredhollow as we speak. We can use this to our advantage. Slaying them should get her attention.\n\n<The Accuser hands you a collection of bright red vials.>\n\nThrow these on her hunters. It should draw the attention of the devourers infesting this place.", objectives = "Use the Concentrated Anima Vial to defeat the hopebreakers in Dredhollow.", completion = "Sounds like it worked better than expected. \n\nPerfect. The Fearstalker stands no chance." }
WordHunterWoW_QuestEN[57190] = { title = "They Won't Know What Hit Them", description = "Luring the Fearstalker here will prove pointless unless we can tilt the odds. She will surely show up with a small army. \n\nPlant these anima containers. When the time comes, we will release their contents into the air, dousing her and her forces in a thick layer of anima.\n\nThat should get the devourers infesting this place to flock to them like moths to a flame.", objectives = "Plant 8 Rigged Anima Containers.", completion = "The devourers will rip them to shreds." }
WordHunterWoW_QuestEN[57198] = { title = "Sense of Obligation", description = "Derek is free. I have to atone for much with him.\n\nThere is a rumor of a meeting with Jaina and her brother.\n\nHead to Seabreeze Village in Stormsong Valley. I hope there you will be able to find out... well, let's just say I am trying to keep the bigger picture in focus.\n\nIf you find out anything of interest, I would be most appreciative.\n\nFor now, let's keep this between the two of us.", objectives = "Eavesdrop on Jaina Proudmoore's meeting.", completion = "Well, that is interesting...\n\nI must act quickly." }
WordHunterWoW_QuestEN[57205] = { title = "A Few Bumps Along the Way", description = "This territory is strategic to our defense, we can not allow these abominations to force our retreat!\n\nSeize control of two of the locations marked on your map. Defend them from enemy attack till the flag is planted and the location captured.Upon completion of this quest you will gain:", objectives = "Defend and capture two locations" }
WordHunterWoW_QuestEN[57207] = { title = "Lysonia's Plan", description = "Lysonia has brought the Paragon to his knees! The Maw powers she wields are far too potent.\n\nWe must stop her.", objectives = "Confront Lysonia.", progress = "<The Paragon of Humility clutches his body in pain.>", completion = "I am weakened, but I will heal.\n\nShe searched for pride that does not exist within me." }
WordHunterWoW_QuestEN[57215] = { title = "Engine of Ascension", description = "", objectives = "" }
WordHunterWoW_QuestEN[57216] = { title = "Old Town", description = "", objectives = "" }
WordHunterWoW_QuestEN[57217] = { title = "Unearthed Keeper", description = "", objectives = "" }
WordHunterWoW_QuestEN[57218] = { title = "Unearthed Keeper", description = "", objectives = "" }
WordHunterWoW_QuestEN[57219] = { title = "Unearthed Keeper", description = "", objectives = "" }
WordHunterWoW_QuestEN[57220] = { title = "Power Protocol Initiation", description = "We've come a long way, {name}.\n\nOnce the power from the auxiliary systems are brought online MOTHER will be able tae run diagnostics.\n\nAll that's left is settin' the final pieces in place.", objectives = "Relay power from the Chamber of Heart, Engine of Nalak'sha and Forge of Origination auxiliary systems, then speak with MOTHER to power up the Forge of Origination.", progress = "Quite the journey so far.", completion = "Best get tae it 'fore things get out of hand." }
WordHunterWoW_QuestEN[57221] = { title = "Re-Origination", description = "If the Ramkahen haven't reached out tae sound any alarms then the anomaly must be contained within the Halls of Origination.\n\nWe best get back tae investigate, {name}.", objectives = "Meet Magni Bronzebeard outside the Halls of Origination in Uldum.", completion = "We won't be findin' any answers out here." }
WordHunterWoW_QuestEN[57222] = { title = "Investigating the Halls", description = "Whatever's happenin' has tae be comin' from deep within the inner chamber. If we can get tae the forge maybe we'll find some answers.\n\nBest check yer gear 'fore headin' in, {name}. Who knows what's waitin' fer us in there.", objectives = "Investigate the anomaly in the Halls of Origination.", completion = "If N'Zoth were to gain access to the forge and leverage its power the results would be... catastrophic.\n\nI'm afraid we're short on time, <name>. If you're going to continue these investigations, you'll need protection.\n\nAnd I know just the place." }
WordHunterWoW_QuestEN[57223] = { title = "Unearthed Keeper", description = "", objectives = "" }
WordHunterWoW_QuestEN[57225] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[57226] = { title = "Short-Supply Reward", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[57228] = { title = "The Assault on Dredhollow", description = "The time is upon us, Maw Walker. The Fearstalker's hunters are descending upon us.\n\nWe have done all we can do to prepare for their assault. Here.\n\n<The Accuser gives you an ornate staff.>\n\nI fashioned this out of the supplies you brought me. Use it to destroy the Fearstalker's forces.\n\nThe fight begins.", objectives = "Defeat 12 of the Fearstalker's Forces." }
WordHunterWoW_QuestEN[57234] = { title = "Solar Collector", description = "", objectives = "" }
WordHunterWoW_QuestEN[57235] = { title = "Solar Collector", description = "", objectives = "" }
WordHunterWoW_QuestEN[57240] = { title = "Where is Prince Renathal?", description = "This is not victory, {name}. If Prince Renathal does not return, we've merely delayed defeat.\n\nThe Prince was last seen during an assault on the Master's keep alongside Duke Theotar.\n\nWe don't know the Prince's fate, but we've learned that Duke Theotar was banished to the Ember Ward.\n\nThe Ember Ward is a land of madness and torture. Blighted by the Light, the Master sends his most hated enemies there to suffer unending agony.\n\nEnter the Ember Ward, find Theotar, and discover the Prince's fate.", objectives = "Speak with Stonehead, gatekeeper of the Ember Ward.", completion = "You no go here. Here for bad buds!" }
WordHunterWoW_QuestEN[57243] = { title = "Amathet Slave Camp", description = "", objectives = "" }
WordHunterWoW_QuestEN[57245] = { title = "Ani-Matter Animator", description = "This area is rich with the remains of fallen soldiers... some of which still carry a spark of potential.\n\nI've created what I call the \"Ani-Matter Orb,\" with which you can reanimate the skeletal matter littered throughout the foundry. \n\nLet us see how many of the new animates would join our cause.\n\nAs for those who don't... well, they should be quite accustomed to being slain by now.", objectives = "Recruit 15 animates.", progress = "Do we have enough animates?", completion = "These reanimated troops will be put to good use." }
WordHunterWoW_QuestEN[57246] = { title = "Eel Filet", description = "", objectives = "Yes? What is it?", progress = "Yes? What is it?", completion = "My favorite! How did you know?\n\nI will cook it up for the camp, everyone is going to enjoy this." }
WordHunterWoW_QuestEN[57247] = { title = "Fathom Ray Wing", description = "", objectives = "Yes? What is it?", progress = "Yes? What is it?", completion = "That is a nice, juicy wing you have there. \n\nI will cook this up, there's plenty to go around." }
WordHunterWoW_QuestEN[57248] = { title = "Giant Crab Leg", description = "", objectives = "Yes? What is it?", progress = "Yes? What is it?", completion = "Wow, that is a large one. Looks delicious!\n\nI'll make some soup for tonight, the group is going to love it." }
WordHunterWoW_QuestEN[57249] = { title = "A Timely Invitation", description = "The time has arrived to remember the past and celebrate our adventures across Azeroth and Beyond. \n\nTo commemorate the occasion the Bronze Dragonflight is throwing a celebration and you are invited! \n\nCome to the Caverns of Time and present this ticket to gain entry to the party!", objectives = "Bring the Invitation from the Timewalkers to Chromie within the Caverns of Time.", completion = "Welcome! It's that special time of year when the bronze dragonflight celebrates all that has happened over the years and you, <name>, are the guest of honor!\nCome celebrate at the grand feast, get down at the \"Disco of Time\", or accept a quest to fend off some of Azeroth's greatest threats." }
WordHunterWoW_QuestEN[57251] = { title = "Conquest's Reward", description = "", objectives = "Your prowess on the field of battle is without peer." }
WordHunterWoW_QuestEN[57252] = { title = "Conquest's Reward", description = "", objectives = "Your prowess on the field of battle is without peer." }
WordHunterWoW_QuestEN[57253] = { title = "Conquest's Reward", description = "", objectives = "Your prowess on the field of battle is without peer." }
