WordHunterWoW_QuestEN[57255] = { title = "Conquest's Reward", description = "", objectives = "Your prowess on the field of battle is without peer." }
WordHunterWoW_QuestEN[57256] = { title = "Stormchosen Arena", description = "", objectives = "" }
WordHunterWoW_QuestEN[57261] = { title = "Walk the Path, Aspirant", description = "If you wish to stand before the Archon, there is a path you must walk. Thankfully, it is well worn and serviceable even in these dire times.\n\nThough you are not destined to become kyrian, our ways may be of interest to you. Learn well, learn fast, and perhaps the Archon will take notice and grant you this audience you seek.\n\nAspirant Kleia will show you the way. Archon's eyes upon you.", objectives = "Travel with Kleia.", completion = "Your journey is just beginning, <name>. I hope you can help us, and I hope we can help you." }
WordHunterWoW_QuestEN[57263] = { title = "The Cycle of Anima: Etherwyrms", description = "Forge is cold, yes? Need LOTS of anima to light.\n\n<Sika references her scroll.>\n\nTimes before now, anima is everywhere, yes? Now it hides. Small bits, weird places.\n\nWe know that etherwyrms -- flappy scale-things that are blue -- eat anima. They are not dead, so they are finding anima to eat still, yes?\n\nMaybe if we take what they have eaten, we can use it to light the forge. This will probably kill them.\n\nSad, yes. But! We will not take too much. Just a little.", objectives = "Slay Etherwyrms to collect 25 Glowing Viscera.", progress = "Did you find anima? Small pieces, even?", completion = "<Sika pokes the squishy substance.>\n\nIt glows. This means anima. Forgelite will be pleased." }
WordHunterWoW_QuestEN[57264] = { title = "On the Edge of a Revelation", description = "Ah! Good. You answered the call.\n\nAs you can see, there are many aspirants who require our aid. Myself and the other disciples are hard pressed to deal with all of them. Some are in greater need than others.\n\nAspirants are most at risk when they are on the precipice of a revelation. It is a critical moment that we cannot allow to pass without intervention.\n\nYou must push them, one way or another.\n\nFind the most vulnerable among your peers and do what you can to help them find the path forward.", objectives = "Inspire 11 Vulnerable Aspirants to action.", progress = "My disciples will be grateful for your aid, <name>.", completion = "Your service is noted. Thank you." }
WordHunterWoW_QuestEN[57265] = { title = "The Cycle of Anima: Drought Conditions", description = "In days past, keeping a forge burning was a trivial task. The anima extractors could run constantly without ever running dry.\n\nNow, even turning an extractor on is a risk. Etherwyrms, without the anima streams to feed on, are attracted to any source of anima. They are a frequent nuisance.\n\nI am going to ask that you risk their attentions. Activate the extractor and guard it until it can accumulate what little anima remains.\n\nBring me the product it collects. Let us hope it is enough.", objectives = "Collect a Condensed Anima Mote from the Anima Extractor.", progress = "Is the extractor functional? How much were you able to acquire?", completion = "That is... somehow more and less than I expected. It will have to do." }
WordHunterWoW_QuestEN[57266] = { title = "The First Cleansing", description = "This situation may feel familiar, {name}.\n\nWhen you found Pelagos, he was undergoing a similar rite. As you saw, it can end in violence.\n\nThis will be the first time you are asked to draw out the burdens that held you to a mortal life. It may be a painful process. It is for many.\n\nFor you, this is the path you must walk to attain your goals. To earn the right to stand among us, to be heard. So we may carry your message to the Archon herself.\n\nCenter yourself. When you are prepared, we will begin.", objectives = "Undergo your first cleansing.", completion = "This is a moment worthy of celebration, <name>.\n\n\n\nYou have done it. They have come." }
WordHunterWoW_QuestEN[57267] = { title = "The Cycle of Anima: Flower Power", description = "For forge to light, need more anima. Always more. Never too much, for forge!\n\n<Sika consults her scroll and nods vigorously as she reads.>\n\nOut in fields, there is a glowy flower. The round thing inside. Bulb? It glows. So, has anima. From the ground, we think.\n\nAccording to scrolls, it is called Adrima's Lily. We do not know who Adrima is. But the lily is good.\n\nGet flowers, too. Not just bulbs. Petals make stewards happy, too. \n\nThank you!", objectives = "Collect 6 Adrima's Lily.", progress = "Do you have flower bulb things?", completion = "Oh. They smell nice! And they glow lots.\n\nThis is good. Yes." }
WordHunterWoW_QuestEN[57269] = { title = "The Hand of Doubt", description = "Quickly! We have no time to lose. Lysonia has weakened Eridia to the point that she may fall. Our Paragon will do what she can, but we must intervene.\n\nWe will challenge Lysonia, and perhaps buy Eridia more time. \n\nThis so-called Hand of Doubt will make no easy foe. Stand ready, {name}.", objectives = "Defeat Lysonia, Hand of Doubt.", completion = "That you should join us now, on the precipice of this treachery, is curious.\n\n<The Paragon of Purity studies you with a piercing gaze.>\n\nYou have done well. The Archon will know of your contributions this day." }
WordHunterWoW_QuestEN[57270] = { title = "The Temple of Purity", description = "Greetings.\n\nI am Kosmas, Disciple to the Temple of Purity.\n\nThe temple is a place of cleansing. Its sole purpose is to free aspirants of the burdens they carry with them from life. It is a place of quiet reflection even for those who have shed their burdens.\n\nOf late, those who look to us for purification have grown numerous. My fellow disciples are stretched terribly thin. I have come to ask the aid of all able-minded aspirants.\n\nYour help is needed. Please report to the Hand of Purity at once.", objectives = "Meet the Hand of Purity at the Temple of Purity.", completion = "Thank you for volunteering." }
WordHunterWoW_QuestEN[57271] = { title = "Trade District", description = "", objectives = "" }
WordHunterWoW_QuestEN[57272] = { title = "Bloodbound Effigy", description = "", objectives = "" }
WordHunterWoW_QuestEN[57274] = { title = "Quartermaster's Bounty", description = "To defeat the enemy, you will need to keep your equipment in peak condition. If you have been unable to acquire more powerful arms, I can requisition from the quartermaster on your behalf.", objectives = "To defeat the enemy, you will need to keep your equipment in peak condition. If you have been unable to acquire more powerful arms, I can requisition from the quartermaster on your behalf.", progress = "To defeat the enemy, you will need to keep your equipment in peak condition. If you have been unable to acquire more powerful arms, I can requisition from the quartermaster on your behalf.", completion = "Victory at any cost." }
WordHunterWoW_QuestEN[57275] = { title = "Something in Your Mind", description = "<Looking into the crystal, the light around you is slowly drowned in inky smoke. An imposing presence crushes down on you, whispering unintelligibly in your ear. Looking for the source, you see nothing, but the sensation grows. Your head begins to swim as the darkness deepens and the noise becomes deafening.\n\nSummoning all your willpower to steel your resolve...\n\nThe light has returned, the noise silenced, and you stand with a humble crystal in your hand.\n\nPerhaps Wrathion knows more about it...>", objectives = "Bring the Void Focus to Wrathion in the Chamber of Heart.\n\nProvided item:", completion = "<Wrathion's brow furrows when he sees the crystal.>\n\nIt is fortunate you brought this to me. Impressive that you were able to handle it while retaining your sanity. In fact... this may provide us with an opportunity.\n\n<Wrathion strokes his chin, lost in thought.>\n\nI will not mince words, <name>. This will certainly prove dangerous. However, I have full confidence that you are up to the task. Now, let us wield N'Zoth's own power against him." }
WordHunterWoW_QuestEN[57276] = { title = "Maintaining Focus", description = "At present, the focus holds but a fraction of N'Zoth's true power. If we further empower it, we could craft even more effective weapons to wield against him.\n\nN'Zoth's influence is everywhere, {name}, and is most concentrated within powerful foes. Vanquish them and claim whatever vestiges of the Old God's power remain.", objectives = "Acquire 20 Shred of Insanity. These can be looted from bosses in Ny'alotha and World Bosses, obtained by winning Battlegrounds and Arenas, or from Honorable Kills.", progress = "We are embarking upon a dangerous gambit, <name>. Caution is of the utmost importance.", completion = "Excellent. These should provide just what we need.\n\nI will draw out the corruption from these physical vessels and infuse it into the focus. Then you will be able to use it to create more powerful items." }
WordHunterWoW_QuestEN[57277] = { title = "Vignette - Muminah the Incandescent", description = "", objectives = "" }
WordHunterWoW_QuestEN[57278] = { title = "Bring Me Their Heads", description = "I swore to the grave of Vistara the Fallen that I would bring him the head of the one who betrayed him. \n\nThough that was eons ago, it is an oath I must fulfill. Whatever fate ultimately befell the traitor, it is likely that his head can still be found nearby.\n\nSlaughter everyone here. Surely one of them must be the traitor... or be in possession of his head.", objectives = "Collect 10 Traitor's Heads.", progress = "Do you have the traitor's head?", completion = "I have asked many others to collect heads as well! So even if none of these are the traitor's head, we shall find it eventually!" }
WordHunterWoW_QuestEN[57282] = { title = "Mage Quarter", description = "", objectives = "" }
WordHunterWoW_QuestEN[57284] = { title = "Blade of Blades", description = "The finest sword in existence has been lost!\n\nNever in your pitiful adventures have you encountered such a blade, mortal. Foe Cleaver was forged to strike down the titans themselves!\n\nI have wielded it against countless adversaries. Emissaries of the Light, minions of the Void, meddlers from the Gardens of Life... all have fallen before me! Soon the very planes of reality will kneel to my greatness!\n\nOnce I find my weapon, that is.\n\nI insist you help me reclaim it. I know it's here somewhere!", objectives = "Find Foe Cleaver amongst the forgotten weapons.", progress = "Have you found Foe Cleaver? Well? HAVE YOU?!", completion = "Foe Cleaver! Now my crusade of conquest begins!\n\nYou... you act as if you've seen finer swords, mortal. How dare you!\n\nJust you wait. You'll kneel before me just like all the rest!\n\n<The animate mutters and grunts.>" }
WordHunterWoW_QuestEN[57288] = { title = "Assessing Your Strength", description = "The trial to come will test you in ways you can likely only imagine.\n\nI can see both from your past and from your demeanor that you are no stranger to combat. I would like to know where your strengths lie so we may address any weaknesses we find before your trial.\n\nYou will find three praetorian soldiers created for this purpose, each stronger than the last.\n\nDefeat them all and I will consider your strength sufficient to continue at this time.", objectives = "Defeat the 3 Praetorian Sparring Assistants.", progress = "How fares the combat?", completion = "Impressive. I see I have little enough to teach you." }
WordHunterWoW_QuestEN[57290] = { title = "Beginning the Descent", description = "Protecting one's mind against the old gods requires an object of pure corruption. Unbeknownst to many, one such object exists--dormant beneath the molten pits of Blackwing Descent.\n\nUntil recently, one of my agents stood watch over the area, keeping detailed records of suspicious activities. Unfortunately, this agent has gone silent. It is now clear we are not the only ones with this knowledge.\n\nIf we are to find answers, there is one place to look.\n\nOur journey continues, {name}. Blackrock awaits.", objectives = "Retrieve the Corrupt Black Dragonscale from Blackwing Descent atop Blackrock Mountain in Burning Steppes.", progress = "Have you recovered what we discussed?", completion = "The scales of corruption now serve as protection for those who stand against it.\n\nHow fitting.\n\nNow, let's see what a <class> of your caliber is capable of when dressed for the occasion." }
WordHunterWoW_QuestEN[57291] = { title = "The Chamber of First Reflection", description = "Ah, Athanos. It remains undefeated, as intended.\n\nStill, you have exceeded any expectation I might have had. You are stronger than many that have come before you.\n\nYou have come here for a purpose, and Kleia has illuminated a path that she believes you can walk. I agree. I have opened the way to the Crucible's final rite.\n\nFollow the path to the south and east. There you will find the entrance to the Chamber of First Reflection.\n\nKleia will instruct you further. Go in service, {name}.", objectives = "Speak to Kleia in the Chamber of First Reflection.", completion = "Gather yourself. This is how you will find your way before the Archon. I am certain of it." }
WordHunterWoW_QuestEN[57298] = { title = "How Things \"Really\" Happened...", description = "You've come a long way over the years, {name}.\n\nFrom humble beginnings doing odd jobs to saving Azeroth's very existence, you've done so much to ensure the safety of our world.\n\nBut why should we just stand around trying to remember things? Let's just go back in time and relive all of the exciting bits again! \n\nDon't worry, in all of the millions upon millions of timeways I'm sure I'll find one where you never die.", objectives = "Embark from the Caverns of Time with Chromie to defeat villains of the past.", progress = "Hey, did we win yet? Or have we begun? I'm maybe not yet sure. Keeping the timelines straight gets a bit difficult.", completion = "Yay! Wasn't that fun? And absolutely NOTHING bad happened to you, ever!\n\n<Chromie gives you a playful wink.>" }
WordHunterWoW_QuestEN[57299] = { title = "Mysterious Sarcophagus", description = "", objectives = "" }
WordHunterWoW_QuestEN[57300] = { title = "Soldier of Time", description = "Long ago, the land of Alterac Valley was peaceful. However, when the Frostwolves moved in it became highly contested real estate between them and the Stormpikes. Battles used to rage for days. \n\nWell, actually the battle is still ongoing, the bronze dragons have figured out a way for you to revisit those early days.", objectives = "Earn 500 honor in Korrak's Revenge.", progress = "Did you have fun exploring Alterac Valley as it used to be?", completion = "The battles for Alterac were bloody affairs, I'm glad they're done. Oh wait, the battles are still ongoing! The cycle of strife is never ending." }
WordHunterWoW_QuestEN[57301] = { title = "Callous Concoctions", description = "I witnessed your success with the Pool of Potions and I think you could be of help. Within this larger pool, we create more dangerous mixtures!\n\nThere are three different oozing ingredients we mix together in different combinations to create violent creatures. When enough ingredients have been added to the pool, the mixture takes shape and a creature will emerge!\n\nBring any combination of these ingredients, Mephitic Goo, Viscous Oil, or Miscible Ooze to the Pool of Mixed Monstrosities.", objectives = "Deliver any combination of Mephitic Goo, Viscous Oil, or Miscible Ooze to the Pool of Mixed Monstrosities.", progress = "Have you completed the mixture?", completion = "You may continue to add as many ingredients as you wish. The more we add, the more we create!" }
WordHunterWoW_QuestEN[57302] = { title = "Alterac Valley Graveyards", description = "The graveyards in Alterac Valley are prized territories.  Both the Horde and the Alliance fight savagely for these sacred grounds.  Are you, {name}, ready to join that fight?\n\nI want you to assault an enemy graveyard.  Find a graveyard with a Horde banner in its midst, and pull it from the ground!  Do that, and your task will be complete....\n\nBut if you can also hold the graveyard for a few minutes, then our troops will soon come to relieve you.", objectives = "Assault a graveyard, then return to Sergeant Durgen Stormpike in Dun Baldar.", completion = "Well done!  Graveyards are vital to our control of Alterac Valley.  When you capture one, you help ensure the Alliance's sovereignty here.\n\nGo now, <name>.  Reenter the battle, and if you see a graveyard under the Horde's control... you know what to do!" }
WordHunterWoW_QuestEN[57303] = { title = "The Quartermaster", description = "{name}, our quartermaster charged me to direct new recruits to him.  He needs supplies from caches stored in the mines of Alterac, and he'll probably send you to get them.\n\nFollow the road.  You'll find our quartermaster to the west.", objectives = "Speak with the Stormpike Quartermaster.", completion = "It's good to see fresh troops here, <name>, but with a little luck you'll get into some action and won't be fresh for long!\n\nSpeak with me again.  I have tasks I must discuss with you...." }
WordHunterWoW_QuestEN[57304] = { title = "Capture a Mine", description = "The mines in Alterac Valley hold more than just minerals.  Both the Frostwolf and Stormpike have cached excess supplies in the Irondeep and Coldtooth mines... that's not a bad idea, if we could only maintain control of them!\n\nCapture a mine, then return to me.  To capture a mine, enter one that we do not control and kill its leader.  When you do that, the mine will be ours, and we'll send troops to protect it!", objectives = "Capture a mine that the Stormpike does not control, then return to Sergeant Durgen Stormpike in the Alterac Mountains.", completion = "You did it!  Well done, <name>!\n\nWhen we control a mine and have troops stationed there, it's much easier to gather minerals and supplies from it." }
WordHunterWoW_QuestEN[57305] = { title = "Armor Scraps", description = "Battles rage constantly in Alterac Valley, and the supplies we get from Ironforge are not enough to outfit our experienced troops.\n\nIf you find armor scraps from the battlefield, aid the war effort and bring those scraps to me!", objectives = "Bring 20 Armor Scraps to Murgot Deepforge in Dun Baldar.", progress = "Did you bring any armor scraps, <name>?", completion = "These are some good pieces, <name>.  I can use them to fashion new equipment for our troops.\n\nIf my supply level gets high enough, then maybe our seasoned fighting units will enter the field!" }
WordHunterWoW_QuestEN[57306] = { title = "More Armor Scraps", description = "", objectives = "<name>, we need more armor scraps to supply our troops!", progress = "<name>, we need more armor scraps to supply our troops!", completion = "These are some good pieces, <name>.  I can use them to fashion new equipment for our troops.\n\nIf my supply level gets high enough, then maybe our seasoned fighting units will enter the field!" }
WordHunterWoW_QuestEN[57307] = { title = "Towers and Bunkers", description = "Towers and bunkers are key defensive positions, and so we must hold as many as possible!  I want you to attack a tower or a bunker in Alterac Valley.\n\nTo do that, enter a tower with a Horde banner atop it.  You will see another enemy banner inside.  Pull out that banner, and a white Alliance banner will appear in its place.  Well done!\n\nAt that point your mission for me will be complete, but hold the area long enough, and if the Horde doesn't take it back, then it will be destroyed!", objectives = "Destroy the banner at an enemy tower or bunker, then return to Sergeant Durgen Stormpike in the Dun Baldar.", completion = "I received a field report stating you helped secure an enemy banner.  Well done, <name>!  With their ranged troops out of position we can move the line of battle forward!" }
WordHunterWoW_QuestEN[57308] = { title = "The Battle of Alterac", description = "The Explorers' League believes there are artifacts in Alterac Valley, but the Frostwolf orcs won't let us explore.  We can't allow the Horde to stop our scholarly pursuits!  Defeat the Frostwolf general, Drek'Thar.  With him dead, the orcs will lose their edge.\n\nDrek'Thar is in Frostwolf Keep, in the south of Alterac Valley.  Vanquish him, and then return to me.", objectives = "Enter Alterac Valley, defeat the Horde general Drek'thar, and then return to Prospector Stonehewer in the Dun Baldar." }
WordHunterWoW_QuestEN[57309] = { title = "Begin the Attack!", description = "", objectives = "My troops are supplied and ready to assault.  We just need orders from Noreg Stormpike and I'll send them into the fray!", progress = "My troops are supplied and ready to assault.  We just need orders from Noreg Stormpike and I'll send them into the fray!", completion = "Ah, the orders!  They say I'm to assault at will, and my will says... now!" }
WordHunterWoW_QuestEN[57310] = { title = "Irondeep Supplies", description = "Before the fighting started, we stored supplies for Dun Baldar in the Irondeep mine.  The troggs that surfaced there weren't much of a problem when we had spare troops to guard the mine, but now that we're fighting with the Horde we can't maintain control of Irondeep.\n\nWe need the supplies in Irondeep, <name>.  Enter the mine and bring me a load of them.", objectives = "Bring 10 Irondeep Supplies to the Alliance Quartermaster in Dun Baldar.", progress = "Do you have the supplies, <name>?  We can never have enough!", completion = "Well done!  I'll put these supplies to good use!  Thanks, <name>!" }
WordHunterWoW_QuestEN[57311] = { title = "Coldtooth Supplies", description = "The Coldtooth mine is a storage depot for the Horde.  I can't stomach the food they give their troops, and the state of their arms and armor is atrocious!  But... in times like these when supplies are so important, we can use what they have.\n\nEnter the Coldtooth mine and bring me back their supplies.  That will help keep the Alliance in fighting shape, and remove much needed equipment from the Horde's warriors.\n\nGood luck, <name>.  The mine is to the distant south, deep in Horde territory.", objectives = "Bring 10 Coldtooth Supplies to the Alliance Quartermaster in Dun Baldar.", progress = "Did you enter the Coldtooth mine in Horde territory, <name>?  Did you raid their supplies?", completion = "You got them!  Well done, <name>!  I'll go through these supplies and get them ready for our own troops!" }
WordHunterWoW_QuestEN[57312] = { title = "The Graveyards of Alterac", description = "The battle lines of Alterac Valley are ever shifting.  Territories swing back and forth as we meet our opponents in deadly combat.  And graveyards, {name}, are where battles rage most fierce.\n\nI want you to attack an Alliance held graveyard!  Find a graveyard with an Alliance banner in its midst and pull it from the ground.\n\nDo that and your task for me will be complete, but... if you hold the graveyard for a few minutes, then it will be ours and troops will come and relieve you.", objectives = "Assault a graveyard, then return to Corporal Teeka Bloodsnarl in Frostwolf Village.", completion = "Well done, <name>!  With each graveyard under our control, the spirits of our enemies will wander more lost and aimless." }
WordHunterWoW_QuestEN[57313] = { title = "Speak with our Quartermaster", description = "{name}, the Frostwolf Quartermaster is looking for recruits, for tasks that lead into the mines of Alterac Valley.  Speak with him; he will tell you more.\n\nFollow the road west into the bunker, then take the west exit and you'll find our quartermaster.", objectives = "Speak with the Frostwolf Quartermaster.", completion = "Hail, <name>!  It is good to see a <class> like yourself, eager to do his part for the Horde.  Speak with me again, for I have vital tasks for you..." }
WordHunterWoW_QuestEN[57314] = { title = "Capture a Mine", description = "As battle rages over the landscape of Alterac Valley, so too does it rage through the Coldtooth and Irondeep mines.  Both are rich sources of minerals and both are used to store supplies; it's no wonder they are so highly valued!\n\nHelp our war effort, {name}!  Capture one of the mines for the Horde!  To capture a mine, enter one that we do not control and kill its leader.  When that is done, the mine will be ours and we'll send troops to protect it!", objectives = "Capture a mine, then return to Corporal Teeka Bloodsnarl in Frostwolf Village.", progress = "You haven't yet captured a mine, <name>!  Find one that we do not control and defeat it's leader!", completion = "You captured a mine!  With our own warriors protecting it, it will be much simpler to extract minerals from its depths, or gather supplies that have been cached there.\n\nWell done, <name>.  The deed you have done is a great boon to our battle efforts." }
WordHunterWoW_QuestEN[57315] = { title = "Towers and Bunkers", description = "Towers and bunkers are important positions, and we must capture and hold them all!  So to that end, I want you to attack a bunker that is controlled by the enemy.\n\nTo do that, enter one with an Alliance banner.  You will see another banner inside.  Pull out that banner, and a white Horde banner will appear in its place.  Well done!\n\nAt that point your task for me will be complete, but if you hold the place long enough, and if the Alliance doesn't take it back, then it will be destroyed!", objectives = "Capture an enemy tower or bunker, then return to Corporal Teeka Bloodsnarl in Frostwolf Village.", completion = "I heard of your mission's success!  That pleases me...\n\nOur troops can now charge forward with impunity, and show the Alliance that Alterac Valley is no place for them!" }
WordHunterWoW_QuestEN[57316] = { title = "The Ladder", description = "Within the Theater of Pain, brother, legends rise like cream to the top.\n\nListen to me, brother. If you have the courage to step into that sacred arena, you're going to face the greatest threats in all of existence! The cards will be stacked against you, but only those who can work together will emerge as champions.\n\nGather your team and meet this challenge head on! Enter the Theater of Pain and defeat the opponents within! Prove that you can rise to the top!", objectives = "Defeat 3 opponents within the Theater of Pain.", progress = "Greetings, brother. Have you faced the madness of the arena?", completion = "Well fought, brother! You've begun your rise to the top!\n\nBut keep up with your training and stay ready. In Maldraxxus, there is always a challenger waiting to take your place." }
WordHunterWoW_QuestEN[57317] = { title = "Enemy Booty", description = "When you fight the enemy, gather the scraps of their armor and bring them to me.  I'll use those scraps to make armor for our own troops!", objectives = "Bring 20 Armor Scraps to Smith Regzar in Frostwolf Village.", progress = "How goes the hunting, <name>.  Do you have any armor scraps for me?", completion = "These will do nicely.  I'll melt them down and patch them up and you'll never know they came from those Stormpike cowards!\n\nThanks, <name>.  And let me polish up that armor of yours..." }
WordHunterWoW_QuestEN[57318] = { title = "More Booty!", description = "", objectives = "I need more armor scraps, <name>!  Do you have any?", progress = "I need more armor scraps, <name>!  Do you have any?", completion = "Thanks again, <name>.  You do the Horde proud..." }
WordHunterWoW_QuestEN[57319] = { title = "The Battle for Alterac", description = "The Stormpike dwarves and their allies have invaded Alterac Valley, and we must drive them out!  To win the battle for Alterac, we must defeat their general, Vanndar Stormpike!\n\nYou will find Vanndar in Dun Baldar, in the north of Alterac Valley.\n\nDestroy him, {name}, and then return to me.", objectives = "Enter Alterac Valley and defeat the dwarven general, Vanndar Stormpike. Then, return to Voggah Deathgrip in Frostwolf Village." }
WordHunterWoW_QuestEN[57320] = { title = "Launch the Attack!", description = "", objectives = "My warriors are eager to attack!  All I need are the assault orders...", progress = "My warriors are eager to attack!  All I need are the assault orders...", completion = "It's about time!  Now we can show the Alliance their folly in coming to Alterac Valley!" }
WordHunterWoW_QuestEN[57321] = { title = "Coldtooth Supplies", description = "The Coldtooth mine to the north was once an ideal place to store extra supplies, but now that the fighting with the Stormpikes grows fierce, we do not always have the spare warriors to station at the mine and protect it.  And so, control of the mine often falls to the Alliance, or to underground denizens...\n\nBut we still need our supplies, <name>!  Go to the Coldtooth mine and bring me a load of them.  And be wary of enemies as you go; the tides of battle shift quickly in that place...", objectives = "Bring 10 Coldtooth Supplies to the Horde Quartermaster in Frostwolf Keep.", progress = "Have you been to the Coldtooth mine, <name>?  Do you have the supplies I asked for?", completion = "Ah, you got  them.  Good work, <name>!  These supplies are a little musty from sitting in that dark mine for so long, but we'll make use of them nonetheless.\n\nThank you, <name>.  Your deeds are vital to the maintenance of our fighting forces." }
WordHunterWoW_QuestEN[57322] = { title = "Irondeep Supplies", description = "The Stormpike dwarves are using the Irondeep mine as a storage depot.  I want you to raid that mine and bring me its supplies.  This will curtail the Stormpikes' efforts in Alterac Valley, and will provide us with needed equipment!\n\nBe wary, <name>.  The Irondeep mine is deep in Alliance territory, and control of the mine is as shifting as the snows of Alterac.", objectives = "Bring 10 Irondeep Supplies to the Horde Quartermaster in Frostwolf Keep.", progress = "Did you enter the Irondeep mine, <name>?  Did you raid its supplies?", completion = "You got them!  Nicely done, <name>!  And I hope you saw a few dwarves during your raid, and shed their blood for the Frostwolves!" }
WordHunterWoW_QuestEN[57323] = { title = "Serpent Binding", description = "", objectives = "" }
WordHunterWoW_QuestEN[57324] = { title = "Sail With the Tide", description = "Hello, {name}.\n\nI have received word from Calia asking that we meet with her once again. \n\nShe has so much to offer those who feel lost, those seeking a better way. Once she is free of doubt, she will know what must be done.\n\nWill you join me?", objectives = "Meet with Calia Menethil and Derek Proudmoore.", completion = "My death seems to have given me a new purpose." }
WordHunterWoW_QuestEN[57326] = { title = "Prototypes for Profit", description = "<Gazlowe pulls you in close and whispers.>\n\nLookit here, {name}. I gotta keep my nose clean here in front of the prince.\n\nBut I trust you know what's gotta be done outside of town, yeah?\n\nOutside of town... where all the tech is...\n\nTech that Alliance grubs are tryin' to get their clumsy mitts on...\nwhich we could use for the Horde...\nto build big weapons...\nand scary robots...\nand other lucrative products...?\n\nI don't gotta spell this out for you, right?", objectives = "Collect 150 Prototype Implants in Mechagon, while in War Mode.", progress = "This place is teemin' with tech. Betcha can find prototypes anywhere.", completion = "<Gazlowe flicks through the prototypes you brought.>\n\nSome good stuff in here, <name>... We'll get a lotta use outta these..." }
WordHunterWoW_QuestEN[57327] = { title = "Prototypes for Inspiration", description = "<Overspark pulls you in close and whispers.>\n\nAs the leader of this momentous expedition, I must stay with Prince Erazmin to ensure he's not swindled by this Horde hooligan.\n\nBut I cannot stop my research, or the Horde will gain the advantage!\n\nUnderlings like yourself must collect the technology samples required to fuel my legendary brainstorms.\n\nBring me prototypes from the island, and I will turn them into groundbreaking new innovations for the Alliance!", objectives = "Collect 150 Prototype Implants in Mechagon, while in War Mode.", progress = "I don't care where you get the prototypes from. Take them from Gazlowe's thugs if you have to.", completion = "<Tinkmaster flicks through the prototypes you brought.>\n\nInteresting... provocative... inspiring! I can certainly turn these into something useful." }
WordHunterWoW_QuestEN[57328] = { title = "Trashin' the Camp", description = "", objectives = "" }
WordHunterWoW_QuestEN[57330] = { title = "Time for Revenge", description = "", objectives = "" }
WordHunterWoW_QuestEN[57331] = { title = "Salvage Operations", description = "", objectives = "" }
WordHunterWoW_QuestEN[57333] = { title = "Terrace Terrors", description = "", objectives = "" }
WordHunterWoW_QuestEN[57334] = { title = "Cave of Murlocs", description = "", objectives = "" }
WordHunterWoW_QuestEN[57335] = { title = "Murloc Mayhem", description = "", objectives = "" }
WordHunterWoW_QuestEN[57336] = { title = "Putting the Past to Rest", description = "", objectives = "" }
WordHunterWoW_QuestEN[57338] = { title = "Depopulation Effort", description = "", objectives = "" }
WordHunterWoW_QuestEN[57339] = { title = "Construction Ritual", description = "", objectives = "" }
WordHunterWoW_QuestEN[57340] = { title = "Fathom Ray Feast", description = "", objectives = "" }
WordHunterWoW_QuestEN[57353] = { title = "Deepcoil Cleansing", description = "", objectives = "" }
WordHunterWoW_QuestEN[57354] = { title = "Overdue", description = "", objectives = "" }
WordHunterWoW_QuestEN[57359] = { title = "Summoning Ritual", description = "", objectives = "" }
WordHunterWoW_QuestEN[57362] = { title = "Deeper Into the Darkness", description = "This recent change of events allows us to continue our journey to discover what darkness lies beyond the sands.\n\nIt will not be easy, {name}. We stand on the precipice of the unknown, but now the tables have turned.\n\n<Wrathion glances at your new attire.>\n\nYou do dress the part. \n\nLet's see what insights your return to the Halls of Origination bring to light.", objectives = "Speak with MOTHER to return to the Halls of Origination in Uldum to discover the source behind the anomaly.", progress = "I await your return.", completion = "Removing the corruption from the Halls of Origination has shifted N'Zoth's attention elsewhere. The attacks on Uldum and Vale of Eternal Blossoms continue to grow." }
WordHunterWoW_QuestEN[57370] = { title = "Assault: The Black Empire", description = "", objectives = "" }
WordHunterWoW_QuestEN[57371] = { title = "Assault: Aqir Unearthed", description = "", objectives = "" }
WordHunterWoW_QuestEN[57372] = { title = "The Drag", description = "", objectives = "" }
WordHunterWoW_QuestEN[57373] = { title = "Descending Into Madness", description = "As unfortunate as the spreading corruption may seem, I believe it provides us the opportunity to prepare for what lies ahead.\n\nLocate one of these incursions and see what happens when you peer beyond the dark veil.", objectives = "Seek out a Vision of N'Zoth amidst the corruption in Vale of Eternal Blossoms or Uldum to discover what the future holds for Azeroth.", completion = "I believe it is time we put this new knowledge to good use." }
WordHunterWoW_QuestEN[57374] = { title = "Into the Darkest Depths", description = "With our connection secured, it is time for us to breach the veil and discover what lies beyond.\n\nWhat you find may provide us the key to unlocking our success.", objectives = "Enter a Horrific Vision to discover what dark manifestations await in a world ruled by N'Zoth.", progress = "Your expertise in these matters are invaluable.", completion = "You've done well, but do not let what you've just seen play you for a fool. Even the safety of this chamber can create a false sense of security.\n\nThe mind is easily manipulated." }
WordHunterWoW_QuestEN[57375] = { title = "Pulsating Mound", description = "", objectives = "" }
WordHunterWoW_QuestEN[57376] = { title = "The Hidden Need", description = "Because of Sylvanas, some members of the Horde are skeptical of the Forsaken. We must regain their trust. \n\nWe cannot do that without accepting ourselves. So many feel lost, alone... abandoned.\n\nI have arranged a meeting. It could be a big step... or all go horribly wrong. Either way, you should bear witness.\n\nMeet me in Tirisfal Glades, at the Calston Estate.", objectives = "Meet Lilian Voss in Tirisfal Glades.", completion = "Calia Menethil and Derek Proudmoore have come a long way to speak with us. Let's not keep them waiting any longer." }
WordHunterWoW_QuestEN[57377] = { title = "A Hand Offered", description = "Here begins the calia intro", objectives = "Here begins the calia intro" }
WordHunterWoW_QuestEN[57378] = { title = "Remnants of a Shattered World", description = "The knowledge gained from these visions affords us a unique opportunity to further protect one's mind from corruption. To continue our research, we must investigate the deeper mysteries of these experiences.\n\nSeek out those of power within these visions. Should you come across anything of interest do not hesitate to share your findings.\n\nIn the meantime, MOTHER and I shall continue our research here in the chamber. \n\nWe await your return, {name}.", objectives = "Recover a copy of \"The Curse of Stone\" from a Horrific Vision for Wrathion in the Chamber of Heart.", progress = "Find anything of interest?", completion = "Fascinating. It appears we have our work cut out for us." }
WordHunterWoW_QuestEN[57379] = { title = "Infested Jade Statue", description = "", objectives = "" }
WordHunterWoW_QuestEN[57380] = { title = "Sign Your Own Death Warrant", description = "Ember Ward only for bad buds!\n\n<Stonehead squints at you and shakes head.>\n\nYou not look like other bad buds!\n\nBad buds come with bad paper!", objectives = "Forge official documents condemning you to the Ember Ward.", progress = "Bad buds come with bad paper!", completion = "This bad paper look very bad..." }
WordHunterWoW_QuestEN[57381] = { title = "The Greatest Duelist", description = "A mortal in Revendreth. Well, well, well... you are primed to be at the head of high adventure.\n\nThe name you may call me is Nadjia the Mistblade, and, if I might be so humble as to say, I am the finest duelist that has ever wielded a sword.\n\nThis trap you found me in was a lesson learned in getting paid in advance. Release me and my blade is yours to command for as long as I find you interesting.\n\nDo we have an accord?", objectives = "Release Nadjia the Mistblade.", progress = "That consecrated iron really leaves one feeling stiff afterward.", completion = "That was FUN! I have not felt so alive in centuries. Everything about you is just... different, and invigorating.\n\nI can continue to assist you until you are ready to leave the Endmire but then we will need to part ways for a time. I have some unfinished business regarding someone who put me in a cage." }
WordHunterWoW_QuestEN[57384] = { title = "Mending Monstrosity", description = "", objectives = "" }
WordHunterWoW_QuestEN[57386] = { title = "If You Want Peace...", description = "Maldraxxus is a land which revels in strife and conflict. But they should also be bound by honor.\n\nIf their honor has been tossed aside, then they may move their forces beyond just Bastion.\n\nTake care, danger lies beyond that gate. It is a realm of heroes as well as a realm of villains.", objectives = "Enter Maldraxxus.", completion = "Well? Why aren't you out there fighting?" }
WordHunterWoW_QuestEN[57390] = { title = "To Die By the Sword", description = "What's this? You fly no colors! Where is the pride in your house, gladiator?\n\nBah, this drought has left us with slim pickings indeed, if this is the best Maldraxxus can muster!\n\nI remember the old days. The strongest souls arriving, then being divided among the five houses...\n\nNo matter. The tournament beckons. Enter the arena! Fight for glory!\n\nBy the look of you, it's likely you won't last long. Try to make a name for yourself in the time you have left.", objectives = "Defeat 30 contenders in the Theater of Pain.", progress = "What are you waiting for? Put on a show!", completion = "You survived? Really...\n\nI admit, that was unexpected." }
WordHunterWoW_QuestEN[57391] = { title = "Reconstructing \"The Curse of Stone\"", description = "I came across several references to this book in my research of Ny'alotha. Penned by a neophyte cultist, it documents the \"lies of the Titans\" and the \"injustices\" they inflicted upon the denizens of Azeroth.\n\nMad ravings, intended to erode the reader's acceptance of reality.\n\nStill, by studying this work, we can gain a better understanding of the Old God's power, and thus tailor the cloak to offer better protection against it.\n\nBring as many pages from this tome as you can find.", objectives = "Collect Torn Pages of \"The Curse of Stone\" from Horrific Visions for Wrathion in the Chamber of Heart.", progress = "What have you been able to find?", completion = "Excellent work. This tome should prove quite enlightening." }
WordHunterWoW_QuestEN[57392] = { title = "Reconstructing \"The Curse of Stone\"", description = "Thus far, the contents of this book are unsettling to say the least. Nevertheless, I have been able to glean valuable information on the nature of N'Zoth's power, and have made alterations to your cloak accordingly.\n\nThere remains much to learn, however. Continue your search for additional pages as you delve into the visions.", objectives = "Collect Torn Pages of \"The Curse of Stone\" from Horrific Visions for Wrathion in the Chamber of Heart.", progress = "Urgent matters require a great deal of attention. Unless it is of the utmost importance, I must see to my work.", completion = "Fine work, indeed." }
WordHunterWoW_QuestEN[57393] = { title = "Stepping Through the Darkness", description = "By now you've noticed the protection of your cloak wavering the deeper you delve into these visions. \n\nTo further bolster your resistance to N'Zoth's influence, we will need to gain an even deeper understanding of his nefarious power.\n\nSeek out knowledge from manifestations deeper within the visions, and we shall have our answers soon enough.", objectives = "Recover a copy of \"Fear and Flesh\" from the depths of a Horrific Vision for Wrathion in the Chamber of Heart.", progress = "Dark and deep are the shadows.", completion = "How curious. \n\nGive me a moment. I will examine this closely." }
WordHunterWoW_QuestEN[57394] = { title = "Reconstructing \"Fear and Flesh\"", description = "Another tome written by one lost to N'Zoth's madness. I dread to think of what vile words await us within it.\n\nBut if we are to strengthen your cloak, then we must know more of that which it was meant to resist. See if you can find the remaining pages so that we can complete this tome and make use of the knowledge it holds.", objectives = "Collect Torn Pages of \"Fear and Flesh\" from Corrupted or Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart.", progress = "The missing pages must reside deeper within these visions. \n\nAs dark and difficult these times may seem, we mustn't forget the possibility remains of a time of great success and discovery.", completion = "Perseverance in the face of darkness.\n\nOur work continues..." }
WordHunterWoW_QuestEN[57395] = { title = "Reconstructing \"Fear and Flesh\"", description = "Adherents of the Old Gods maintain that flesh is a gift, not a curse. This tome reflects on the Old Gods' supposed benevolence in granting us such a generous blessing.\n\nNaturally, it omits any mention of what occurs when their corruption is allowed to run unfettered.\n\nGather more of these pages for me. As wretched as these words might be, studying them will allow us to increase the efficacy of your cloak.", objectives = "Collect Torn Pages of \"Fear and Flesh\" from Corrupted or Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart.", progress = "Anything to share?", completion = "I see you have found more pages from the book. Well done." }
WordHunterWoW_QuestEN[57396] = { title = "Reconstructing \"Fear and Flesh\"", description = "Adherents of the Old Gods maintain that flesh is a gift, not a curse. This tome reflects on the Old Gods' supposed benevolence in granting us such a generous blessing.\n\nNaturally, it omits any mention of what occurs when their corruption is allowed to run unfettered.\n\nGather more of these pages for me. As wretched as these words might be, studying them will allow us to increase the efficacy of your cloak.", objectives = "Collect Torn Pages of \"Fear and Flesh\" from Corrupted or Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart.", progress = "Nearly halfway there, <name>.\n\nHave you found anything new?", completion = "Magnificent. Our work is coming together nicely." }
WordHunterWoW_QuestEN[57397] = { title = "Reconstructing \"Fear and Flesh\"", description = "Perhaps the most insidious element of the Old Gods' whispers is that they contain within them the smallest kernel of truth. There is something to be said for the joy that comes with feeling the sun on one's skin and the wind in one's hair.\n\nBut you have braved N'Zoth's visions. You have seen where their designs are ultimately meant to lead. The curse of flesh has nothing to do with bringing us joy.\n\nContinue to collect the pages of this book. We have nearly finished piecing it back together.", objectives = "Collect Torn Pages of \"Fear and Flesh\" from Corrupted or Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart.", progress = "The darkness lingers.\n\nNever hurried. Never sleeping. Patiently waiting...", completion = "Ah, the final pages.\n\nI believe we're ready to advance our efforts yet again, dear <name>." }
WordHunterWoW_QuestEN[57398] = { title = "Walking in the Darkness", description = "The end nears. The darkest corners of these visions await.\n\nOur work has ensured you are well equipped to seek out the most horrific manifestations these visions have to offer. The final answers lie just beyond. Our preparations for Ny'alotha are nearly complete.", objectives = "Recover a copy of \"The Final Truth\" from Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart.", progress = "I await your return.", completion = "Be grateful your eyes needn't stare upon these pages.\n\nWith the final pieces falling into place, we begin our preparations for Ny'alotha." }
WordHunterWoW_QuestEN[57399] = { title = "Reconstructing \"The Final Truth\"", description = "I know of this book. It is a sacred tome to those who worship the Old Gods, containing the deepest secrets and most incomprehensible mysteries of the Void. Only the most devout cultists are allowed to gaze upon its pages.\n\nEven incomplete, holding it makes my skin crawl. I must take care not to read too much of it in a single sitting.\n\nThat being said, we must find its missing pages in order to continue our research. Retrieve them from the darkest corners of N'Zoth's visions.", objectives = "Collect Torn Pages of \"The Final Truth\" from Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart.", progress = "I often find my own thoughts wandering, weary of what lies ahead.\n\nHow are you faring, <name>? Have you any news?", completion = "Another piece falls into place. We are so very close, <name>." }
WordHunterWoW_QuestEN[57400] = { title = "Reconstructing \"The Final Truth\"", description = "I dare not repeat aloud the horrors that are recorded in these pages. The words themselves seem to shift and morph as I read them, as if the book itself is attempting to induce a descent into madness.\n\nThis is taxing work, but it is necessary if we are to fully prepare you for the dangers of Ny'alotha. For as disturbing as its descriptions might be, setting foot within it will prove more challenging by an order of magnitude.\n\nKeep looking for pages from the book, {name}. But... leave the reading to me.", objectives = "Collect Torn Pages of \"The Final Truth\" from Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart.", progress = "Your success has brought us this far, <name>. Perhaps you have something to share?", completion = "Our journey's end approaches. The darkness gathers." }
WordHunterWoW_QuestEN[57401] = { title = "Reconstructing \"The Final Truth\"", description = "Long have I studied the secrets of the Old Gods. I have traversed the whole of Azeroth in search of esoteric texts, lost archives, and forbidden knowledge, all in the name of preparing for the horror to come.\n\nNo amount of research could have prepared me for the depths of the insanity I would find within this book. A madness so absolute that only the Shath'yar language can convey it.\n\nFind me the final pages of this accursed tome, {name}. I wish to learn what I need from it and be done with it forever.", objectives = "Collect Torn Pages of \"The Final Truth\" from Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart.", progress = "The whispers of Ny'alotha surround us. I believe you are ready for the final task, are you not?", completion = "The works are complete. Together, they tell the tale of a descent into complete madness. How one deception leads to another, until reality itself is held in contempt. There is no \"truth\" to be found here.\n\nNo longer should you feel the need to run from the whispers, <name>. You are ready to silence them." }
WordHunterWoW_QuestEN[57402] = { title = "Reconstructing \"The Curse of Stone\"", description = "N'Zoth is nothing if not subtle and insidious. I can see how an impressionable mind could be turned against the Titans by reading these words. Thankfully, we are not so susceptible to such manipulation, are we?\n\nThe book is nearly complete. Continue retrieving its pages from within the visions.", objectives = "Collect Torn Pages of \"The Curse of Stone\" from Horrific Visions for Wrathion in the Chamber of Heart.", progress = "I believe we are on the precipice of a something grand.", completion = "A job well done, <name>.\n\nIt's time we advanced our efforts." }
WordHunterWoW_QuestEN[57403] = { title = "Reconstructing \"Fear and Flesh\"", description = "Perhaps the most insidious element of the Old Gods' whispers is that they contain within them the smallest kernel of truth. There is something to be said for the joy that comes with feeling the sun on one's skin and the wind in one's hair.\n\nBut you have braved N'Zoth's visions. You have seen where their designs are ultimately meant to lead. The curse of flesh has nothing to do with bringing us joy.\n\nContinue to collect the pages of this book. We have nearly finished piecing it back together.", objectives = "Collect Torn Pages of \"Fear and Flesh\" from Corrupted or Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart.", progress = "Making progress?", completion = "The words in this tome build and expand on the writings from the one we completed previously.\n\nStay the course, <name>. I expect we shall have answers soon enough." }
WordHunterWoW_QuestEN[57404] = { title = "Ravager Hive", description = "", objectives = "" }
WordHunterWoW_QuestEN[57405] = { title = "Chasing Madness", description = "<This wretched shamble of a venthyr mumbles uncontrollably as it claws at the ground.\n\nIt looks up suddenly and points its finger at you.>\n\nAn adversary with no ferry cannot be merry unless it is wary!\n\n<It seems to be waiting for a response from you.>", objectives = "Discover what Lost Sybille wants to show you.", completion = "Well, aren't you an unexpected windfall?\n\nI'm afraid I've no tea to offer you at the present. Forgive my poor manners." }
WordHunterWoW_QuestEN[57414] = { title = "Mount Up Test", description = "", objectives = "" }
WordHunterWoW_QuestEN[57425] = { title = "Land of Opportunity", description = "<The grandmaster's voice rings out over the roaring crowd.>\n\nThis is it! The final event of the tournament!\n\nThese two Maldraxxi gladiators have cut down challenger after challenger. Now the only thing left...\n\nIs for one to slay the other!", objectives = "Defeat High Champion Meskal.", completion = "In ages past, the Primus founded that tournament to showcase the might of Maldraxxus. \n\nToday, it has sparked an all-out war." }
WordHunterWoW_QuestEN[57426] = { title = "My Terrible Morning", description = "You simply won't believe what happened to me!\n\nI was out for my daily stroll when Marquis Pummeler and his band of ruffians assailed me!\n\nAmongst the many unfortunate and ungentlemanly behaviors they displayed was destroying my parasol.\n\nA tragedy of the highest order!\n\nWithout it, I'm afraid I'm left quite vulnerable to the oppressive Light that curses this land.\n\nThe Marquis controls a coveted shaded hideout nearby. Will you avenge my parasol and teach this ruffian some manners?", objectives = "Kill Marquis Pummeler.", progress = "The Marquis and his ruffians must be taught some manners!", completion = "<Exposure to the Light is clearly causing Theotar to lose control of himself.>\n\nJustice... for parasols... everywhere..." }
WordHunterWoW_QuestEN[57427] = { title = "Unbearable Light", description = "Have you encountered an ash ghoul yet? Wretches crawling on the ground. Jump on everything. Terrible table manners.\n\nThat is the unfortunate fate awaiting all venthyr exposed to the Light for too long. The overwhelming pain it causes us breaks our willpower, our mind, and finally our body.\n\nWith the right skills, it is possible to reverse the Light's desecration if it is treated quickly.\n\nBut the ash ghouls in this Light-burned crater are beyond redemption. There is only one mercy left.", objectives = "Kill 12 ash ghouls.", progress = "If only I'd been able to help them earlier...", completion = "<Exposure to the Light is clearly causing Theotar to lose control of himself.>\n\nMy... sincerest apologies..." }
WordHunterWoW_QuestEN[57428] = { title = "Theotar's Mission", description = "Oh the Accuser sent you? How keen!\n\nI do, in fact, know the fate of Prince Renathal... at least part of it.\n\nWhen our assault on the Master's keep failed, we were both captured. I was banished to the Ember Ward, but the Prince was dragged off to Sinfall.\n\nI'm cultivating an escape from this Light-blighted land to follow after him, but the Light here... it makes it hard to think.\n\nMy parasol once protected me, but the ruffians destroyed it. Help me rebuild it, and we'll find the Prince together.", objectives = "Collect 8 Scorched Planks and 8 Regal Cloth Scraps.", progress = "My preferred colors are pink and white, if you can find it.", completion = "<Exposure to the Light is clearly causing Theotar to lose control of himself.>\n\nGubbins... Where are you?" }
WordHunterWoW_QuestEN[57429] = { title = "Pyre of the Amalgamated One", description = "", objectives = "" }
WordHunterWoW_QuestEN[57442] = { title = "Lost in the Desiccation", description = "<Exposure to the Light has rendered Theotar incapable of forming coherent sentences.\n\nInstead of telling you how to get to his hideout, he mumbles incoherently while pointing in random directions.>\n\nLost... Syb... Tubbins... Late for tea...\n\n<You'll have to find Theotar's hideout a different way.>", objectives = "Discover the way to Theotar's hideout.", completion = "<Gubbins and Tubbins speak in unison.>\n\nDis not good." }
WordHunterWoW_QuestEN[57443] = { title = "Dirty Job: Demolition Detail", description = "", objectives = "" }
WordHunterWoW_QuestEN[57444] = { title = "An Inspired Moral Inventory", description = "{name}! You are well! I am glad of it.\n\nMany of the ascended who once served this place have betrayed us. To turn so wholly against all that the kyrian stand for is... unimaginable.\n\n<The acolyte places a heavy spear in your hands.>\n\nThis is a tool that has seen little use before today. Its sole purpose is to inspire a moment of reflection in those it touches. It will show them the error of their ways.\n\nIf they remain unrepentant, then there is no hope for them. They must die.", objectives = "Slay 3 Forsworn ascended.", progress = "They betrayed us.", completion = "I saw them perish. It is more than they deserved." }
WordHunterWoW_QuestEN[57445] = { title = "Chin's Noodle Cart", description = "", objectives = "" }
WordHunterWoW_QuestEN[57446] = { title = "The Enemy You Know", description = "My heart is filled with dread. If it truly is Lysonia who leads them now...\n\nNo. What is important is that we restore the great vespers. So long as their mighty voices are corrupted, all who hear them will suffer as this temple does. It is only a matter of time before all of Bastion succumbs.\n\nThey will no doubt try to stop you. I will hold their leader's attention as long as I can.\n\nIf I do not survive... my disciple will see you safely from this place. Go in service.", objectives = "Confront Lysonia and cleanse the great Vespers.", completion = "Our fight is not yet over, <name>." }
WordHunterWoW_QuestEN[57447] = { title = "Purity's Prerogative", description = "Do you feel it, {name}?\n\nThat cold hand that grips your throat? That chill settled in the pit of your stomach? That is the touch of the Maw, as certain as the Archon's will.\n\nI do not know how Lysonia came to possess this power, but we must act quickly.\n\nI will inform the Archon of what transpired here. You will act where my Hand could not. I will explain as we fly.\n\nSpeak to me when you are prepared to leave the temple.", objectives = "Fly with Vesiphone to Purity's Reflection.", completion = "We will see not a moment's rest today, will we?\n\n<Kleia eyes the fragment warily.>" }
WordHunterWoW_QuestEN[57448] = { title = "New Allies Among Us", description = "Even in times of peace, the Horde is not without its problems.   \n\nAlthough they can be overwhelming at times, our struggles should never stop us from remembering what it means to be a part of the Horde. \n\nWe don't turn people away when times get tough; we band together and endure. \n\nFor a moment I forgot this. Burdened by the troubles facing our new allies, I hastily dismissed the vulpera. \n\nMy only hope is that they still see as much value in the Horde as I see in them.", objectives = "Witness Baine welcome the vulpera into the Horde.", completion = "Vulpera within the Horde. A practical partnership, don't you agree? One that would not have been possible without your help. \n\nThanks to you, <name>, we now have a home beyond the dunes." }
WordHunterWoW_QuestEN[57449] = { title = "Executor of N'Zoth", description = "", objectives = "" }
WordHunterWoW_QuestEN[57453] = { title = "Swarm Caller", description = "", objectives = "" }
WordHunterWoW_QuestEN[57454] = { title = "Silence in the Stalks", description = "Hmm. Well that's not... great. But no cause for alarm, yet!\n\nIt has been a long time since our ring withdrew from here, and we probably need to go to its source to get it to return!\n\nUnfortunately, I haven't heard from the Chief Mushroomancer, Cortinarius, since the crisis began.\n\nPlease, find him and help us rejoin the rings! Head west of Dreamsong Fenn to the Stalks. You can't miss them... just follow the mushrooms!", objectives = "Speak to Cortinarius outside the Stalks.", completion = "Finally, a friendly face! Are you with the Hunt? You don't look like you're from around here...." }
WordHunterWoW_QuestEN[57455] = { title = "Mushroom For Improvement", description = "The mushrooms are under attack! I need your help, or we risk losing it all!\n\nSome fae wearing strange masks came in and demanded to gain access to the rings. When I told them they were closed due to the drought, they attacked me!\n\nI'm too weak to fight back now, and I'm cut off from the center ring. These fae have destroyed so much, but there is something we can do.\n\nSprinkle some of these spores on their corpses so we can regrow the rings. Even when slain, our enemies can still serve Ardenweald.", objectives = "Use the Pouch of Spores to plant mushrooms on 15 masked fae in the Stalks.", progress = "They'd be feeding the mushrooms anyway, so you might as well accelerate the process.", completion = "Their bodies will nourish the growth and restoration of the fae rings. It is a worthy end for them." }
WordHunterWoW_QuestEN[57456] = { title = "Spirit Drinker", description = "", objectives = "" }
WordHunterWoW_QuestEN[57457] = { title = "Shaking 'Shrooms", description = "The mushrooms in there need your help, {class}!\n\nSome of the larger mushrooms become laden with spores. It is one of my duties to help disperse them and grow the grove, but it is too dangerous for me in there.\n\nIf you're going to go in, do you mind giving any particularly full mushrooms a good shake for me? That should get most of the spores loose until we can secure the grove.", objectives = "Shake 8 Swollen Mushroom Stalks." }
WordHunterWoW_QuestEN[57458] = { title = "Ring Repairs", description = "The damage wrought here is severe, but it can be reversed.\n\nMy master is weakened by all this destruction, but mushrooms are difficult to completely eradicate. By restoring power to the rings throughout the grove, we can strengthen them once again.\n\nTake this beacon. Use it near a damaged mushroom in a ring, and watch how quickly nature can heal its wounds.", objectives = "Use the Fungal Beacon to repair 6 Damaged Mushrooms.", completion = "Together we are strong." }
WordHunterWoW_QuestEN[57459] = { title = "Fighting For Fungus", description = "Behold, Marasmius!\n\nThis is his home, his heart. Every mushroom in Ardenweald, maybe even all of the Shadowlands, stems from here. And the masked fae want to take him for their own purposes. As chief mushroomancer, I cannot abide this.\n\nOur foes may look mindless, but they are clever. They will have tracked my position by now.\n\nI shall make my final stand here, and hope that Marasmius is strong enough to lend his aid.\n\nWill you stand with me, {class}?", objectives = "Help Cortinarius defend Marasmius.", completion = "<About time you showed up! Good thing I took care of all those young ones, eh?>" }
WordHunterWoW_QuestEN[57460] = { title = "Tubbins's Tea", description = "Theotar teach Tubbins special tea that make Light go away!\n\nTubbins good tea maker!\n\nWatch Tubbins make Theotar feel good!\n\nThen Tubbins feel good!", objectives = "Help Tubbins make the special tea to heal Theotar.", progress = "Tubbins make tea!", completion = "Tea ready! Tubbins give to Theotar!" }
WordHunterWoW_QuestEN[57461] = { title = "An Uneventful Stroll", description = "I hope I wasn't too unpleasant while under the Light's influence. I do try to restrain myself, but the pain it causes is... maddening.\n\nAnyway, that tea picked me right up!\n\nWhen I last saw Prince Renathal, the Master was dragging him off to that big tower looming over the Ember Ward.\n\nMyself and a few others have been working to gain access to that tower from below, but there are... obstacles.\n\nWhen you're ready to depart, I will lead you to our headquarters of sorts, the Sanctuary of the Mad.", objectives = "Escort Theotar to the Sanctuary of the Mad.", completion = "<Theotar takes a slow sip from his tea cup.>\n\nWhat a delightful stroll!" }
WordHunterWoW_QuestEN[57462] = { title = "Dream Catcher", description = "It appears that the focus remains stable, and its containment field remains intact. I daresay we can empower it even further.\n\nHunt down and defeat formidable enemies to acquire additional remnants of N'Zoth's influence. This time, we will infuse the focus with even greater amounts of the Old God's power. I am confident that the containment field will continue to hold.", objectives = "Acquire 200 Shred of Insanity. These can be looted from bosses in Ny'alotha and World Bosses, obtained by winning Battlegrounds and Arenas, or from Honorable Kills.", progress = "Fortune favors the bold, <name>. And few acts are as bold as wielding the power of an Old God.", completion = "Well done, <name>.\n\nOnce we have imbued the focus with the power we now hold, you will be able to create the most devious items of which N'Zoth's twisted mind can conceive." }
WordHunterWoW_QuestEN[57463] = { title = "My Way or the Hyphae", description = "<An old, booming voice fills your mind.>\n\nHmph. More are coming.\n\nI would rather not lose more of myself, and I don't want you to think I'm not appreciative of the work you and Cort here have done.\n\nHow about you take a ride on the rings and give those oafs a good thrashing? We'll teach them not to mess with Marasmius and his fae rings!", objectives = "Ride the fae rings with Marasmius and defeat 30 invaders.", completion = "Hah! I haven't felt that young in ages!" }
WordHunterWoW_QuestEN[57464] = { title = "Maintaining Focus", description = "At present, the focus holds but a fraction of N'Zoth's true power. If we further empower it, we could craft even more effective weapons to wield against him.\n\nN'Zoth's influence is everywhere, {name}, and is most concentrated within powerful foes. Vanquish them and claim whatever vestiges of the Old God's power remain.", objectives = "Acquire 20 Shred of Insanity. These can be looted from bosses in Ny'alotha and World Bosses, obtained by winning Battlegrounds and Arenas, or from Honorable Kills.", progress = "We are embarking on a dangerous gambit, <name>. Caution is of the utmost importance.", completion = "Excellent. These should provide just what we need.\n\nI will draw out the corruption from these physical vessels and infuse it into the focus. Then you will be able to use it to create more powerful items." }
WordHunterWoW_QuestEN[57465] = { title = "Dirty Job: Wood Work", description = "", objectives = "" }
WordHunterWoW_QuestEN[57466] = { title = "[REUSE]", description = "I like you, youngling. You are not like the others, sitting in their fancy court, leaving old Marasmius to keep the network running.\n\nI'll open up the ring by the celestial tree nearby as a thank for all your help. You can use it to come back and visit me whenever you like.\n\nYou come back now! There will always be plenty for you to do here. Might even be something special in it for you.", objectives = "" }
WordHunterWoW_QuestEN[57470] = { title = "An Abominable Discovery", description = "{name}. Come with me. I could explain, but it's easier to understand if you see it for yourself.", objectives = "Follow Draka to Gharmal's Tower.", completion = "Gharmal's gluttony knew no bounds." }
WordHunterWoW_QuestEN[57471] = { title = "It's a Dirty Job", description = "This muck pool is all out of order. The anima shortage has taken its toll here for sure. \n\nYou see, the pools require filth and fiber to grow dredgers effectively. The problem is every time I try to treat the pool, the dang devourers are on my back!\n\nNow the untreated muck is starting to coagulate into these elementals! Can you go and toss some of the filthy rubble into the pool to restore it?", objectives = "Throw Filthy Rubble into the muck pool.", completion = "I can smell it from here. Thanks for that, <name>." }
WordHunterWoW_QuestEN[57473] = { title = "Prized Possession", description = "This chest is different. It's larger than the others... but more importantly, it's locked.\n\n<Mograine bashes the lock apart.>\n\nNow, let's see what's inside.", objectives = "Open the ornate chest.", progress = "How did they acquire that?", completion = "The Mantle of the Primus... \n\nFate favors us today." }
WordHunterWoW_QuestEN[57474] = { title = "Dredger Duty", description = "You fixed up the muck pool so we can make some dredgers, but them devourers are gonna keep causin' trouble.\n\nWe're gonna need a Gem of Binding so we can dredge up a biggun to protect the pool.\n\nI'll show you how to dredge up some disposable dredgers to work with for now.\n\nGet 'em digging in the rubble to find us a Gem of Binding, and then we'll reshape 'em all into a biggun to kick them devourers outta here!", objectives = "Dredge a dredger and bring it to the pile of rubble. Wait for it to dig through the pile and collect the Gem of Binding.", progress = "You got the gem?", completion = "Got a bit of devourer gunk on it, but it will have to do." }
WordHunterWoW_QuestEN[57475] = { title = "The Mantle Returned", description = "The Mantle of the Primus...\n\nI can hardly believe it. That Gharmal possessed it. That they did not use it against us. That we reclaimed it.\n\nThis could prove vital toward our efforts to restore Maldraxxus. We must return it to Baroness Draka at the Seat of the Primus immediately.", objectives = "Return to Draka at the Seat of the Primus.", completion = "I'll send scouts to continue the search, but this... this is a huge boon for us." }
WordHunterWoW_QuestEN[57476] = { title = "Vil'thik Feeding Grounds", description = "", objectives = "" }
WordHunterWoW_QuestEN[57477] = { title = "We're Gonna Need a Bigger Dredger", description = "Thanks for getting the stone, {name}. While you were out I went ahead and dredged up a few more folks.\n\nNow we just need to re-shape these dredgers into a biggun.", objectives = "Witness the ritual.", progress = "What do you want?", completion = "Bootus ready." }
WordHunterWoW_QuestEN[57481] = { title = "Running a Muck", description = "Bootus ready to smash devourer skulls.\n\nHop on.", objectives = "Board Bootus and quell the devourer incursion.", progress = "Enders smashed?", completion = "Nice work, <name>. \n\nBigguns can be... a bit much sometimes." }
WordHunterWoW_QuestEN[57484] = { title = "Ritual of Wakening", description = "", objectives = "" }
WordHunterWoW_QuestEN[57486] = { title = "Waning Energy", description = "Mekkatorque's pod is powering down. \n\nWe are no longer able to hear him speak. \n\nHis pulse has slowed, in spite of the best efforts of Kul Tiran healers.\n\nI have an idea, but I am going to need your help.\n\nMeet me at Proudmoore Keep. We must go soon.", objectives = "Meet Kelsey Steelspark at Proudmoore Keep.", completion = "What we're about to do may not be... uh... an approved plan. \n\nWe will just ask for forgiveness later." }
WordHunterWoW_QuestEN[57487] = { title = "Someone Who Can Help", description = "I believe there is a way to help Mekkatorque, but some may not be a hundred percent on board... \n\nThe mechagnomes have advanced techniques in biomechanical repair and improvements.\n\nIf there is even a chance they can help him, we have to try! There are some mechagnomes sending supplies out to the island from a dock in Hook Point. No one will notice one more piece of cargo. We need to reroute one of their homing copters.\n\nWill you please help me get Mekkatorque's Pod to Mechagon?", objectives = "Help Kelsey move Mekkatorque's Escape Pod to Mechagon.", progress = "How can I help?", completion = "It would be my pleasure to give aid to the most esteemed High Tinker Mekkatorque!" }
WordHunterWoW_QuestEN[57488] = { title = "The Current Schematic", description = "I think I can modify one of our existing devices to give us access to Gelbin Mekkatorque without disturbing his life preserving functions.\n\nThere are some items I will need you to procure. \n\nFrom the nearby vector of the Heaps, you will find scrapbots and scraphounds. These would be a fine source of spare parts for my construction project.\n\nThe Outflow is home to some particularly slimy friends. From them, you will find excellent ingredients for the heat resistant lubricant we need.", objectives = "Collect 4 Heat Tolerant Ooze and 6 Acquisitioned Machine Parts.", progress = "Were all assets found?", completion = "Yes, yes, these will do.\n\nExcellent work, <name>!" }
WordHunterWoW_QuestEN[57490] = { title = "Voyage to Safety", description = "One of our defenders saw the troggs take out the homing copter carrying Mekkatorque's pod. \n\nSince we started bringing goods in from Tiragarde, they have been a real thorn in our side. \n\nPiston, a very promising young inventor, has a vehicle able to handle this task. Meet his crew down in Bondo's yard.\n\nPlease hurry and retrieve the pod! I am not sure what will happen to Gelbin, if they break it open.\n\nAhem, we would not be upset if you did a little beach clean-up while you were there...", objectives = "Defeat the scavenging troggs and retrieve Mekkatorque's Escape Pod.", progress = "Did everyone make it back in one piece?", completion = "I hope the poor guy didn't get shaken around too much in there." }
WordHunterWoW_QuestEN[57491] = { title = "Better... Stronger... Less Dead", description = "King Mechagon may have been crazy, but his minions did have exemplary robotic creation capabilities. \n\nThere are a few residual creations wandering Mechagon. Refusing to accept King Mechagon's dethroning.\n\nThe logical conclusion to defeat is withdrawal, if one remains operational. Some do not excel at logic.\n\nThey currently bear the latest in technical advancement. I believe retrieving specific pieces from these units would greatly benefit our recovery endeavor.", objectives = "Collect the Neural Accelerator, Omni Electromagnetic Amplifier, and Flux Energized Servos from the erratic units.", progress = "Did you acquire the parts we need?", completion = "Barely a scratch on them!\n\nA couple of upgrades and you could do that in half the time, you know." }
WordHunterWoW_QuestEN[57492] = { title = "Him?", description = "Speak to some of the gnomes in Mechagon, enhanced or otherwise. Of my people, ask what they hope for in a leader of our kind. Of our new friends, ask what they appreciate most about their current leader.\n\nFrom what I have learned thus far, the High Tinker has always led his people by necessity, he never sought or desired the crown. I believe the gnomes should be united once again. \n\nI seek a solution that will be most amenable to all. Will you gather the information I need?", objectives = "Gather data from gnomes and mechagnomes in Mechagon.", progress = "Have your communications been productive?", completion = "Excellent, excellent, these are the results I was hoping for. You have strengthened my theory." }
WordHunterWoW_QuestEN[57493] = { title = "Mental Attunement", description = "We now have a baseline of who Mekkatorque is, looks like there could be some room for improvement. \n\nYour assistance is needed to get him stabilized and synchronized before removing him from his pod.\n\nPlease position yourself by the Synchroscope. I will make adjustments, you will need to fire the machine when I call.", objectives = "Activate the Synchroscope when Christy tells you to fire.", progress = "Did you successfully push the button?", completion = "Your button pushing skills are commendable. \n\nWe are fortunate you were here." }
WordHunterWoW_QuestEN[57494] = { title = "A Strong Heart", description = "We saw a flare near Junkwatt Depot. \n\nThe retrieval team has made it out with the power source. We are now forever safe from King Mechagon's Annihilo-tron, its heart will serve a new purpose.\n\nThis is great news!\n\nHowever, the flare means they have company. Your help will be needed to extricate the team and retrieve the Spark Reactor.\n\nPlease move with haste, we are so close to completion.", objectives = "Retrieve the Spark Reactor and complete Mekkatorque's procedure.", progress = "Are you ready?", completion = "I am quite pleased.\n\nWith a 40% chance of success, I was not sure the variables would reconcile in our favor.\n\nIt was a serendipitous sequence of events." }
WordHunterWoW_QuestEN[57495] = { title = "The Future of Mechagon", description = "Now that Mechagon City has been cleared of its remaining dangers, it may once again be a place of peace and prosperity for gnomes and mechagnomes alike.\n\nIt is time for me to speak with Prince Erazmin regarding the future of our peoples. It is my sincere hope that we will forge an alliance that will last for generations to come!\n\nWhen you are ready, please join us at the High Tinkertory for a special address.", objectives = "Travel to the High Tinkertory in Mechagon City.", progress = "When you are ready, please join us at the High Tinkertory for a special address.", completion = "This has truly been a glorious day for both gnomes and mechagnomes! We could not have done it without you, <name>!" }
WordHunterWoW_QuestEN[57496] = { title = "Ascension", description = "After everything the mechagnomes have done for us today, it is our duty to return the favor.\n\nLet us clear out the rogue creations that remain in Mechagon. \n\nWith their home returned, Prince Erazmin and his people will have a brilliant path forward.\n\nWith this team, we will make short work of the remaining King Mechagon loyalists.\n\nLet me know when you are ready to roll out!", objectives = "Clear the remaining Mechagon defenders.", completion = "That was exciting! \n\nThe world just got a little bigger, my friend!" }
WordHunterWoW_QuestEN[57497] = { title = "Propagate the News", description = "We wanted to save a life and we have accomplished so much more!\n\nWe really couldn't have done it without you, {name}. I am so excited about the future of all gnomekind.\n\nHead back to Stormwind and share the good news!", objectives = "Update Aysa Cloudsinger in Stormwind.", completion = "Outstanding results, <name>! \n\nI will share your news with the leaders of the Alliance.\n\nI look forward to collecting some new toys..." }
WordHunterWoW_QuestEN[57506] = { title = "Light Lost", description = "Some of our aspirants foolishly believed they could enter the Maw and make a difference in that dark abyss.\n\nSadly, they are mistaken. To enter the Maw is to invite eternal damnation.\n\nBut not for you.\n\nPlease investigate their fate. If you can find them, their souls might once again be free.", objectives = "Find Kyrian Aspirants within the Maw and return with their souls to Elysian Hold." }
WordHunterWoW_QuestEN[57508] = { title = "Zara'thik War Banner", description = "", objectives = "" }
WordHunterWoW_QuestEN[57510] = { title = "Darklord Taraxis", description = "", objectives = "" }
WordHunterWoW_QuestEN[57511] = { title = "Arms for the Poor", description = "This trench is strewn with the remnants of countless attacks upon the Seat of the Primus by forces which threatened the Shadowlands.\n\nEach time, Maldraxxus claimed victory.\n\nNow scavengers pick at scraps in hopes of buying their way into one of the three remaining houses. In these desperate times, we must gain every advantage possible over our rivals.\n\nIf we arm these scavengers and offer them a second chance at glory, we can bolster the ranks of the Chosen.", objectives = "Arm 8 Displaced Scavengers with weaponry scattered around the Iron Trench.", progress = "There should be plenty of weapons found on this old battlefield.", completion = "And now we test them." }
WordHunterWoW_QuestEN[57512] = { title = "Walk Among Death", description = "This trench echoes with necromantic energies unleashed in the countless battles waged here. That power has coalesced into chaotic entities we call deathwalkers.\n\nIn simpler times, we would have sent troops out to subdue them to serve the House of the Chosen. But with war brewing, there is no time for that.\n\nEliminate this potential threat, before our enemies turn them against us.", objectives = "Kill 8 Unbound Deathwalkers.", completion = "Everything in this land is dangerous. There is no room for weakness." }
WordHunterWoW_QuestEN[57513] = { title = "Enemy of My Enemy", description = "I have no doubt you have questions. Know that we share enemies in this land.\n\nFor now, we must move. I will get you to a safer location and then we can speak.", objectives = "Escape from the Theater of Pain." }
WordHunterWoW_QuestEN[57514] = { title = "The First Act of War", description = "Look around you, {name}. This army is all that remains to defy the treachery of the other two houses.\n\nI must regroup with the margrave and discuss strategy. War will soon be upon us.\n\nI would ask that you prepare for the coming battle alongside the rest of our forces. We cannot afford for a single soldier to falter.\n\nSeek out Baron Vyraz. He has earned countless victories for Maldraxxus. I fear his blades must soon be turned upon our former allies.", objectives = "Report to Baron Vyraz.", progress = "What are you waiting for?", completion = "Mark my words, recruit. We will crush the other houses for their acts of treason." }
WordHunterWoW_QuestEN[57515] = { title = "The House of the Chosen", description = "<Draka gestures to the sky.>\n\nLook there, mortal. That is the necropolis of Margrave Krexus, who leads the House of the Chosen. It is my honor to serve as his baroness.\n\nLet us ride to our fortress. There we can gather our strength and make ready for the battle to come.", objectives = "Head to the House of the Chosen with Draka.", progress = "Yes?", completion = "The Chosen are all that remains of what the Primus stood for.\n\nWe are the last hope of this realm." }
WordHunterWoW_QuestEN[57516] = { title = "Through the Fire and Flames", description = "Margrave Krexus was pleased to hear of your service to our house. He senses great potential within you.\n\nPotential that must be tested.\n\nA stone stands at the center of our citadel, surrounded by magma. Reaching the stone is a challenge of endurance and fortitude.\n\nThis trial is usually attempted only by our most renowned soldiers, but Margrave Krexus commands you to attempt the rite at once.\n\nGo on, then. Prove your worth.", objectives = "Reach the Standing Stone.", progress = "What happened?", completion = "This blade was inside the stone all this time... \n\nMargrave Krexus was right about your potential." }
WordHunterWoW_QuestEN[57517] = { title = "Swarm Caller", description = "", objectives = "" }
WordHunterWoW_QuestEN[57519] = { title = "Swarm Caller", description = "", objectives = "" }
WordHunterWoW_QuestEN[57521] = { title = "Empowered War Wagon", description = "", objectives = "" }
WordHunterWoW_QuestEN[57522] = { title = "Call of the Void", description = "", objectives = "" }
WordHunterWoW_QuestEN[57524] = { title = "Accessing the Archives", description = "The information you've gathered has allowed us to better understand these manifestations.\n\nI believe MOTHER is waiting to share some of her findings with you.", objectives = "Speak with MOTHER to activate the Titanic Research Archive, then examine the archives.", progress = "Do you require assistance?", completion = "Archival database now available." }
WordHunterWoW_QuestEN[57529] = { title = "Garden in Turmoil", description = "Please excuse me for not standing. I would rather not disturb these creatures.\n\nIf you have a desire to help the creatures of Bastion, Zosime needs aid to regain control of our garden. You will find her just down this path.\n\nGo in service.", objectives = "Speak with Zosime downhill in the Garden of Respite.", completion = "Oh, you're here to lend a hand? Wonderful!" }
WordHunterWoW_QuestEN[57530] = { title = "Gharmal's Tower", description = "Gharmal collected anything they believed to be an item of power.\n\nWe'll need to search the tower. There is almost certainly something here of value to us.", objectives = "Search Gharmal's Tower.", completion = "That is definitely something. Let's open it and find out." }
WordHunterWoW_QuestEN[57531] = { title = "An Unfortunate Situation", description = "Laurent, mirror maker to the Master. Pleasure to meet you. Excuse my disheveled appearance. It appears I've found myself in a most unfortunate situation.\n\nI was attempting to travel on royal business when my mirror sent me to this wasteland instead.\n\nNot a moment after I arrived, a band of exiles ripped the clothes right from my back, making it impossible for me to traverse this unforgiving terrain.\n\nAssist me and I will endeavor to create a mirror which will allow us to escape this wretched place.", objectives = "Defeat Costel and recover Laurent's belongings.", progress = "Have you recovered my belongings?", completion = "This is it? Are you sure there wasn't more?" }
WordHunterWoW_QuestEN[57532] = { title = "Foraging for Fragments", description = "Forgive me. I don't mean to appear ungrateful, but my mirror fragments are missing.\n\nI shouldn't be surprised, really. They're quite powerful and I'm sure the miscreants out here would be happy to get their hands on them.\n\nNonetheless, I will not let this deter me.\n\nThe Master sends his stone servants to smash any mirrors erected in this ward, so we should have no trouble finding fragments nearby.", objectives = "Follow Laurent and collect Mirror Fragments.", progress = "Simone shouldn't be here!", completion = "This must be some sort of mistake!" }
WordHunterWoW_QuestEN[57533] = { title = "Light Punishment", description = "The reasons we were banished here differ, but our goal once we arrive is always the same--to avoid becoming ash.\n\nThe Shrouded control the areas shaded from Light. Those that trespass within their stronghold are made to suffer. Our flesh blisters and burns, yet we do not die. Instead, our minds descend into madness from the pain.\n\nI do not claim to know the crimes of those trapped within the Light, but I know this is not the Maw. It is not our role to punish.\n\nFree the others as you have freed me.", objectives = "Free 5 Blistering Outcasts.", progress = "Penance, not punishment. It seems the Master has forgotten the difference.", completion = "You freed them, yes? Let us hope they found some small sliver of respite, where the Light cannot reach." }
WordHunterWoW_QuestEN[57534] = { title = "When Only Ash Remains", description = "Is this really what becomes of the exiled? Are they left here to burn to ash?\n\nHow could the Master allow such a thing? It is cruel. Heartless, even.\n\nNo venthyr would want to continue on like this. \n\nYou must end their suffering.", objectives = "Kill 10 Ashen Ravagers.", completion = "I thought I knew our sire, but anyone who would do this to his subjects is not worth following." }
WordHunterWoW_QuestEN[57535] = { title = "Escaping the Master", description = "Now more than ever I wish to escape this place, but I cannot go back to serve the Master. Not after seeing what goes on here.\n\nSimone and I are in agreement. With your assistance, I will craft a mirror that connects to a sanctuary controlled by the prince. We will leave this place and pledge our support to Renathal. \n\nBut first, I'll need fragments of glass. The Shrouded seem to have plenty, and the fewer they have to make traps, the better.", objectives = "Collect 10 Mirror Fragments.", progress = "Have you collected the fragments?", completion = "<Laurent carefully examines the fragments before speaking.>\n\nYes, these should work. I'm almost certain." }
WordHunterWoW_QuestEN[57536] = { title = "Mirror Making, Not Breaking", description = "Denathrius does not allow mirrors to be erected within the ember ward. His stone servants shatter anything that so much as glints. \n\nI need you to remain vigilant as I make this mirror. I have no doubt that the Master's minions will try to stop us. \n\nAre you ready?", objectives = "Defend Laurent and Simone from Stone Legion attackers.", completion = "Simone is right. We don't have time for idle chatter. Not here, at least.\n\nThe mirror we've repaired will take you to safety." }
WordHunterWoW_QuestEN[57537] = { title = "Covering our Tracks", description = "I belong to the House of the Chosen. We have a stronghold to the south, it should be safe there.\n\nWe'll fly the rest of the way. Approach my flayedwing when you are prepared.", objectives = "Ride with Draka to the House of the Chosen." }
WordHunterWoW_QuestEN[57538] = { title = "Disturbing the Peace", description = "This anima drought isn't hard on just the kyrian. The wildlife of Bastion are suffering too!\n\nMany creatures are becoming aggressive and menacing, wyrms and cloudfeathers especially. They are hurting the other wildlife and long beyond saving.\n\nIf someone doesn't clear this garden of these starved creatures, we can no longer meditate here. And if we can no longer meditate, that will make the anima shortage even worse!", objectives = "Kill 10 Anima-Starved creatures.", progress = "We must deal with the anima-starved creatures so this place can return to a state of tranquility.", completion = "We can now better fulfill our duties here. I look forward to resuming my meditations. Thank you." }
WordHunterWoW_QuestEN[57540] = { title = "Kunchong Incubator", description = "", objectives = "" }
WordHunterWoW_QuestEN[57541] = { title = "Call of the Void", description = "", objectives = "" }
WordHunterWoW_QuestEN[57542] = { title = "Swarm Caller", description = "", objectives = "" }
WordHunterWoW_QuestEN[57543] = { title = "Executor of N'Zoth", description = "", objectives = "" }
WordHunterWoW_QuestEN[57545] = { title = "Distractions for Kala", description = "When the animals became aggravated, we left in a hurry. However, all of Kala's toys are still inside the garden.\n\nSince you are going to be there, would you please collect them? Kala may be very large, but she is still young. She can be a bit of a troublemaker as well.\n\nHopefully the return of her toys will help keep her distracted.", objectives = "Collect Kala's playthings.", progress = "Do you have her playthings? She's becoming quite the handful!", completion = "Kala! Look! <name> brought back your favorite things!" }
WordHunterWoW_QuestEN[57547] = { title = "A Test of Courage", description = "I'm still new and haven't passed all of my Aspirant tests. But, I have an idea.\n\nThere is an artifact called Korinna's Allaying Crook. Korinna was a powerful Ascended who tamed the creatures of Bastion eons ago. Her staff has the power to prevent more creatures from succumbing to a savage, anima-starved state.\n\nHowever, the artifact is protected and only one with great courage can retrieve it. I bet you could, {name}.\n\nGo on ahead. The staff is in the reliquary to the north. I'll join you there shortly.", objectives = "Help Zosime retrieve Korinna's Allaying Crook.", progress = "Were you able to retrieve the crook?", completion = "I told you she can be quite the troublemaker. Ugh, Kala!" }
WordHunterWoW_QuestEN[57549] = { title = "In Agthia's Memory", description = "Greetings, mortal!\n\nAre you here to learn about the legacy of Agthia, Paragon of Courage?\n\nI welcome you to walk the grounds of this ancient battleground to learn of the battle that occurred here, and the heroic Paragon who saved all of Bastion and the Shadowlands.", objectives = "Read the Scrolls of Remembrance around Agthia's Repose.", progress = "Agthia did not only live a life of courage, but one of service to all of the Shadowlands.", completion = "It is an eternal tug of war between the cosmic forces of existence. \n\nThey constantly vie for power over each other but if one fell, all worlds would fall into chaos." }
WordHunterWoW_QuestEN[57551] = { title = "Agthia's Path", description = "Now that you have familiarized yourself with the events leading to the battle that took place here eons ago, it is time to experience it for yourself.\n\nRing the bell, take a deep breath, and walk in Agthia's steps.", objectives = "Ring the Vesper of History.", completion = "To arms, kyrian! We must stand strong before the forces of the Void!" }
WordHunterWoW_QuestEN[57552] = { title = "Warriors of the Void", description = "These Void invaders are wiping our forces from existence!\n\nMy disciples fall, returning their anima to the lands.\n\nIf we fail to drive them from our lands, more than kyrian will be lost. First Bastion, then the Shadowlands as a whole.", objectives = "Kill 15 Void forces.", completion = "Wherever you step, you leave a wake of vanquished Void forces in your path.\n\nYou give your peers time to breathe." }
WordHunterWoW_QuestEN[57553] = { title = "On Wounded Wings", description = "I see my peers fall in pain, their wounds from the Void overtaking them.\n\nWe cannot allow ourselves, or each other, to give up hope.\n\nShare your anima with our wounded brothers and sisters. Help them stand tall for another fight!", objectives = "Heal 5 Wounded Defenders.", completion = "My disciples resolve, standing to fight another day.\n\nI will not take that in vain." }
WordHunterWoW_QuestEN[57554] = { title = "Wicked Gateways", description = "The forces of the Void are infinite.\n\nThey travel through the Great Beyond by creating portals, twisting gateways between our planes.\n\nQuickly, move to close these portals. Cripple the swell of their forces for as long as we can hold.", objectives = "Destroy 3 Void Portals.", progress = "New portals shall open, but we can prevent the swell for a time.", completion = "Do not revel in our victory. More shall break through.\n\nWe must use this opportunity to strike." }
WordHunterWoW_QuestEN[57555] = { title = "Shadow's Fall", description = "Despite our efforts, the Void stands strong. All of the forces of Bastion fight, and fall one by one...\n\nThe Void cannot destroy us!\n\nThey are led by Tezulat the Annihilator, scourge of a thousand realms. This day, his reign of terror will end!", objectives = "Kill Tezulat the Annihilator.", progress = "We shall sing the songs of Agthia, hero of Bastion, for eternities to come.", completion = "Now you have bore witness to Agthia's great sacrifice." }
WordHunterWoW_QuestEN[57558] = { title = "Vil'thik Hatchery", description = "", objectives = "" }
WordHunterWoW_QuestEN[57562] = { title = "Amathet Assault Tracker", description = "", objectives = "" }
WordHunterWoW_QuestEN[57563] = { title = "Mogu Assault Tracker", description = "", objectives = "" }
WordHunterWoW_QuestEN[57564] = { title = "Mantid Assault Tracker", description = "", objectives = "" }
WordHunterWoW_QuestEN[57565] = { title = "Aqir Assault Tracker", description = "", objectives = "" }
WordHunterWoW_QuestEN[57566] = { title = "N'Zoth Assault Tracker (Uldum)", description = "", objectives = "" }
WordHunterWoW_QuestEN[57567] = { title = "N'Zoth Assault Tracker (Vale)", description = "", objectives = "" }
WordHunterWoW_QuestEN[57568] = { title = "Tough Love", description = "Heavens! Kala has flown off with Korinna's Allaying Crook!\n\nI saw her fly into her den to the west. I must warn you, she can become very protective when she's in there. Please be careful, but do not be afraid to give her some tough love. She is exceptionally resilient.\n\nHere, take her slobber ball. It's her favorite and may help to distract her.", objectives = "Retrieve Korinna's Allaying Crook from Kala inside her den.", progress = "Do you have the crook?", completion = "With the crook and Korinna's guidance, I can begin to bring this place and its creatures back to their former state of respite. Thank you, <name>." }
WordHunterWoW_QuestEN[57571] = { title = "Moving Mirrors", description = "What sort of horrific trap is this? The Light is being reflected directly on her! \n\nSimone's a dear friend of mine! Free her from that thing, please!", objectives = "Redirect the mirror fragments to free Simone.", completion = "Denathrius may not have set the mirrors, but it's his fault I am here.\n\nThose that rouse his suspicion are sent here to suffer, even once loyal servants like myself." }
WordHunterWoW_QuestEN[57580] = { title = "Executor of N'Zoth", description = "", objectives = "" }
WordHunterWoW_QuestEN[57581] = { title = "Plucking Plumes", description = "", objectives = "Skettis's lapdogs still keeps a close watch over us, outcasts. The moment any of us sets foot outside Shattrath we'll be as good as dead.\n\nContinue to bring me more feathers as proof of your victory over them.", progress = "Skettis's lapdogs still keeps a close watch over us, outcasts. The moment any of us sets foot outside Shattrath we'll be as good as dead.\n\nContinue to bring me more feathers as proof of your victory over them.", completion = "<Vekax squawks in glee as you present him with proof of his enemies' demise.>\n\nYes, yes, continue to show Skettis that we outcasts will not take their punishment lying down. I can arrange for more, should you provide me with additional feathers." }
WordHunterWoW_QuestEN[57582] = { title = "Executor of N'Zoth", description = "", objectives = "" }
WordHunterWoW_QuestEN[57583] = { title = "Through the Veil", description = "I like you, youngling. You put in the work while the others sit in their fancy court, leaving old Marasmius to keep the fae rings thriving.\n\nHere, take one of my spores back with you to the Heart of the Forest. Find somewhere nice and cozy for me to rest, will you?\n\nCome back and visit me whenever you like. Cort and I can keep an eye on things for now, but there will always be plenty for you to do here. Might even be something special in it for you.", objectives = "Find somewhere to plant Marasmius in the Heart of the Forest.", completion = "Ahh, it's nice to stretch out again. I've missed this place, you know.\n\n<Marasmius pauses for a moment.>\n\nDon't tell anyone here I said that, all right?" }
WordHunterWoW_QuestEN[57584] = { title = "A Fate Most Noble", description = "Welcome, Worthy One!\n\nI am Greeter Mnemis. It is my duty and pleasure to assist you on this, your first day among the kyrian.\n\nAllow me to congratulate you. Your fate is reserved for the most noble of souls. Only those who lived a life of service may call Bastion home.\n\nI am certain you have many questions- all new aspirants do! Please allow me the honor of introducing you to the next chapter of your existence.\n\nWe will begin when you are ready.", objectives = "Learn more about the kyrian.", progress = "Please alert me to your needs and concerns, Worthy One.", completion = "I hope that was informative and relaxing." }
