WordHunterWoW_QuestEN[57621] = { title = "Summoning Ritual", description = "", objectives = "" }
WordHunterWoW_QuestEN[57634] = { title = "Bring Your Own", description = "Scunner, a roiling mass of flesh and slime, has crawled out of the ruins of the House of Plagues. \n\nHe emits a toxic vapor that impairs the functions of those who attempt to fight him. You can try it, Maw Walker, but it's doubtful you could hurt him on your own.\n\nConstructs are built to fight creatures like Scunner. So gather a force of them and eliminate the threat.", objectives = "Defeat Scunner.", completion = "Very fine work, Maw Walker." }
WordHunterWoW_QuestEN[57636] = { title = "Pride of Place", description = "The Mantle of the Primus. It belongs on his statue.\n\nYou were the one to recover it, so you will have the honor of returning it to its proper place.", objectives = "Place the Mantle of the Primus.", progress = "Each answer leads to another question. Each enemy defeated reveals another secret.", completion = "We must find the source of Gharmal's stockpiled anima. But for now, let us enjoy our victory." }
WordHunterWoW_QuestEN[57637] = { title = "Disturbance Detected: Firelands", description = "You're early {name}, I hadn't even sent for you yet.\n\nAnother temporal disturbance has flared up, this time in the Firelands. If Ragnaros hadn't been dealt with when he was, well, you've already seen one way the end time could turn out.\n\nSome intricate time weaving is required to be sure you catch Ragnaros early, but still after whatever is causing the disturbance. Whoever is doing this isn't messing around any more.", objectives = "Relive the siege of the Firelands.", progress = "Bring me the temporal anomaly as soon as you can, so we can get back to yesterday's problems tomorrow.", completion = "Oh no, time-locking?! Who knows how long this had been there before we were able to detect it! This is far worse than I had imagined..." }
WordHunterWoW_QuestEN[57638] = { title = "Korrak the Bloodrager", description = "The indigenous Winterax trolls of the region are ruthless savages that would love nothing more than to have our bones added to their foul stew.\n\nWe must show them our might!\n\nWe have recovered tomes from their caves that detail their leadership hierarchy. The artifacts indicate that their leader, Korrak the Bloodrager, tends to remain hidden until given a reason to make his presence known.\n\nDeath to Korrak would mean death to Winterax Clan! Slay him and return.", objectives = "According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley.\n\nShould Korrak make himself known, destroy him and return to Lieutenant Haggerdin in the Dun Baldar.", progress = "Be warned, soldier: The Frostwolf also hunt for Korrak.", completion = "Well done. With Korrak dead, our full attention can be focused upon purging the Frostwolf filth from the region." }
WordHunterWoW_QuestEN[57639] = { title = "The Legend of Korrak", description = "The invading Stormpike are not the only threat in the region, soldier. The war in the Valley is waged on two fronts. The cannibal Winterax trolls also vie for power.\n\nThey are lead by Korrak the Bloodrager - a cruel and cunning beast.\n\nA strike against Korrak could prove to be a crushing blow to the Winterax clan. Slay the beast and be rewarded!", objectives = "According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley.\n\nShould Korrak make himself known, destroy him and return to Warmaster Laggrond.", progress = "Be warned, soldier, the Stormpike also hunt for Korrak.", completion = "Only the invading Stormpike armies remain, soldier. Well done!" }
WordHunterWoW_QuestEN[57640] = { title = "Master Ryson's All Seeing Eye", description = "Your war in the heart of Alterac means nothing to the Syndicate, <class>. We will do as we have always done: Wait until a clear victor rises from the ashes and rubble of this madness and then strike.\n\nThat, however, is not why we are here now. The All Seeing Eye has been lost - taken by the Winterax trolls of the region.\n\nRecover the Eye and our services shall be yours - for whatever time remains for your side.\n\nReturn to me once you acquire the eye so that I may examine you.\n\n<Master Ryson grins.>", objectives = "Recover Master Ryson's All Seeing Eye from the Winterax caves and return it to Master Ryson.\n\nBe warned, it is said that Master Ryson's All Seeing Eye carries with it a terrible curse!", completion = "<Master Ryson examines the Eye.>\n\nNow you shall be witness to the awesome power of the All Seeing Eye!" }
WordHunterWoW_QuestEN[57641] = { title = "Master Ryson's All Seeing Eye", description = "Your war in the heart of Alterac means nothing to the Syndicate, <class>. We will do as we have always done: Wait until a clear victor rises from the ashes and rubble of this madness and then strike.\n\nThat, however, is not why we are here now. The All Seeing Eye has been lost - taken by the Winterax trolls of the region.\n\nRecover the Eye and our services shall be yours - for whatever time remains for your side.\n\nReturn to me once you acquire the eye so that I may examine you.\n\n<Master Ryson grins.>", objectives = "Recover Master Ryson's All Seeing Eye from the Winterax caves and return it to Master Ryson.\n\nBe warned, it is said that Master Ryson's All Seeing Eye carries with it a terrible curse!", completion = "<Master Ryson examines the Eye.>\n\nNow you shall be witness to the awesome power of the All Seeing Eye!" }
WordHunterWoW_QuestEN[57642] = { title = "A Winter Veil Gift", description = "", objectives = "A small tag on this present reads:\n\nHappy holidays, <name>!" }
WordHunterWoW_QuestEN[57643] = { title = "A Gently Shaken Gift", description = "", objectives = "This present looks like it has been shaken a few times. The tag on it reads:\n\nTo a very special <race> <class>." }
WordHunterWoW_QuestEN[57644] = { title = "No Friend Left Behind", description = "I would care for nothing more than to serve as navigator again, but my dearest friend suffers. I cannot stand to abandon him.\n\nI can feel Twigin now. He struggles against the binding web of the spiders who once served us. More victims of this senseless conflict...\n\nThough it pains me to say it, you must slay our spiders and gather their caustic venom. You can then use it to free Twigin.\n\nIf not out of empathy, rescue him for the sake of your plans. My skills will be useless without his direction.", objectives = "Rescue Twigin.", progress = "Please spare him this pain.", completion = "Thank you for returning me to my sister." }
